INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0001','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 4. 요양개시일','A. 4. 요양개시일','요양개시일 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','A. 4. 요양개시일\n1. 최초 입원 월인 경우 입원일을 기재함.\n2. 계속 입원으로 월초에 작성된 경우 해당 월의 1일을 기재함.\n3. 특정기간 종료 후인 경우 특정기간 종료 다음 날짜(또는 정액수가 적용개시일)를 기재함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 297쪽',297,10,1);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0002','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 5. 평가구분','A. 5. 평가구분','평가구분 치매 인지기능 MMSE 인지 환자평가표 평가표 작성 입원평가 계속입원 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','A. 5. 평가구분\n이번 평가가 최초 입원평가인지 계속 입원중인 환자 평가인지를 기재함.\n1. 입원평가：입원하여 제 1~10일 사이에 작성된 경우\n2. 계속 입원 중인 환자평가：입원평가가 아닌 경우\n3. 이전 환자평가표를 적용하는 경우：전월 환자평가표 작성일로부터 전월 마지막 날 까지의 잔여일수가 7일 이하로 당월의 평가를 생략한 경우 또는 당월에 적용할 환자 평가표가 없어 최근 3개월 이내의 환자평가표 중 가장 최근 평가표를 적용하는 경우\n▸ 유의사항\n· 입원 초기 특정기간이 적용되어 이후에 환자평가표가 작성된 경우 ‘2. 계속 입원 중인 환자 평가’로 기재함\n· 월말 입원 등으로 인하여 익월에 환자평가표가 작성된 경우 동 환자평가표는 당월 및 익월의 정액수가 기간에 적용하는 것이므로 이 경우 환자평가표는 월별로 각각 제출하며, 요양개시일은 해당 월의 요양개시일을 기재하고 평가구분은 동일하게 ‘1. 입원평가’ 또는 ‘2. 계속 입원 중인 환자 평가’로 기재한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 297쪽',297,10,2);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0003','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 6. 작성일','A. 6. 작성일','작성일 환자평가표 평가표 작성','A. 6. 작성일\n환자평가표 작성일(관찰기간의 마지막날)을 기재함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 297쪽',297,10,3);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0004','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 7. 입원 직전 있던 곳','A. 7. 입원 직전 있던 곳','입원 직전 있던 평가구분 입원평가 계속입원','A. 7. 입원 직전 있던 곳\n요양병원에 입원하기 직전 있던 곳을 체크함\n- 집에 거주한 경우이면서 재가서비스 수혜 여부를 확인할 수 없는 경우에는 재가 서비스를 받지 않은 것으로 판단하여 ‘2. 집에 거주(재가장기요양서비스/가정간호/ 방문간호를 받지 않으면서)’에 체크함\n- ‘4. 급성기병원’이란 요양병원을 제외한 종합병원 등을 말함\n- 입원 직전 있던 곳을 확인할 수 없는 경우에는 ‘7. 기타’에 체크함\n▸ 유의사항\n· ‘A. 5. 평가구분’이 ‘1. 입원 평가’인 경우만 기재함\n※ 참고사항\n· 재가장기요양서비스의 예\n   - 노인장기요양보험법에 따른 재가급여(방문요양, 방문목욕, 방문간호, 주･야간보호, 단기보호 등)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 298쪽',298,10,4);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0005','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 9. 혈압','A. 9. 혈압','혈압 ','A. 9. 혈압*\n관찰기간 동안 측정한 혈압 중 가장 최근 기록을 기재함.\n▸ 유의사항\n· 수축기 혈압과 이완기 혈압을 각각 기재함\n· 혈압측정이 불가능한 경우 혈압은 999/999로 기재함\n· 사망한 환자의 혈압은 ‘0’이 아닌 마지막으로 측정한 혈압을 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 298쪽',298,10,5);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0006','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 10. 건강생활습관','A. 10. 건강생활습관','10 건강생활습관 평가구분 입원평가 계속입원','A. 10. 건강생활습관\n- ‘흡연’은 작성일 기준으로 흡연하고 있는 경우에만 ‘예’로 기재함\n- ‘음주’는 입원하기 전 과거 1개월간의 음주습관을 기재하되, 술의 종류와 양에 관계 없이 일주일에 3회 이상 음주하는 경우 ‘예’로 기재함\n- ‘규칙적 운동 및 식사’는 입원하기 전 과거 1개월간의 운동 및 식사습관을 평가하여 기재함\n▸ 유의사항\n· ‘A. 5. 평가구분’이 ‘1. 입원 평가’인 경우만 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 298쪽',298,10,6);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0007','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 11. 장기요양등급 및 신청','A. 11. 장기요양등급 및 신청','11 장기요양등급 신청 치매 인지기능 MMSE 인지 평가구분 입원평가 계속입원','A. 11. 장기요양등급 및 신청\n- ‘해당사항 없음’은 65세 미만이거나, 노인성 질환자가 아니어서 장기요양등급신청 자격이 아닌 경우 기재함\n- ‘신청하였으나 인정 못 받음’은 장기요양등급 신청결과 ‘기각’ 또는 ‘각하’를 의미함\n- ‘등급 내 자’는 장기요양 인정조사 후 등급을 받은 경우(1등급~5등급, 인지지원등급)를 의미함\n- ‘등급 외 자’는 장기요양 등급신청 하였으나, 등급 내 자가 아닌 경우(등급 외 자 A~C)를 말함\n▸ 유의사항\n· ‘A. 5. 평가구분’이 ‘1. 입원 평가’인 경우만 기재함\n※ 참고사항\n· 노인장기요양보험법 시행령 [별표 1] <개정 2016. 11. 8.>\n      노인성 질병의 종류(제2조 관련)\n    구분 질병명 질병코드\n      가. 알츠하이머병에서의 치매 F00*\n      나. 혈관성 치매 F01\n      다. 달리 분류된 기타 질환에서의 치매 F02*\n      라. 상세불명의 치매 F03\n      마. 알츠하이머병 G30\n      바. 지주막하출혈 I60\n      사. 뇌내출혈 I61\n      아. 기타 비외상성 두개내출혈 I62\n      자. 뇌경색증 I63\n   한국표준질병･ 차. 출혈 또는 경색증으로 명시되지 않은 뇌졸중 I64 사인분류 카. 뇌경색증을 유발하지 않은 뇌전동맥의 폐쇄 및 협착 I65\n      타. 뇌경색증을 유발하지 않은 대뇌동맥의 폐쇄 및 협착 I66\n      파. 기타 뇌혈관질환 I67\n      하. 달리 분류된 질환에서의 뇌혈관장애 I68*\n      거. 뇌혈관질환의 후유증 I69\n      너. 파킨슨병 G20\n      더. 이차성 파킨슨증 G21\n      러. 달리 분류된 질환에서의 파킨슨증 G22*\n      머. 기저핵의 기타 퇴행성 질환 G23\n      버. 중풍후유증 U23.4\n      서. 진전(震顫) R25.1\n비고\n1. 질병명 및 질병코드는 「통계법」 제22조에 따라 고시된 한국표준질병･사인분류에 따른다.\n2. 진전은 보건복지부장관이 정하여 고시하는 범위로 한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 299쪽',299,10,7);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0008','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 12. 장기요양등급 및 이용 서비스','A. 12. 장기요양등급 및 이용 서비스','12 장기요양등급 이용 서비스 평가구분 입원평가 계속입원','A. 12. 장기요양등급 및 이용 서비스\n- ‘a. 등급’은 장기요양등급 ‘등급 내 자’에 한해서 평가하여 기재하며 환자가 기억을 잘 못할 경우 ‘확인불가’로 기재함\n- ‘b. 이용 중인 또는 이용하였던 서비스’는 장기요양등급 ‘등급 내 자’에 한해서 평가 하여 기재하며 환자가 기억을 잘 못하거나, 자신이 받는 서비스의 내용을 모를 경우, 특별현금급여, 가족요양비를 받는 경우는 ‘기타’로 기재함\n▸ 유의사항\n· ‘A. 5. 평가구분’이 ‘1. 입원 평가’인 경우만 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 300쪽',300,10,8);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0009','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 13. 장기요양서비스를 받고 싶은 의향이 있습니까?','A. 13. 장기요양서비스를 받고 싶은 의향이 있습니까?','13 장기요양서비스 받고 의향 있습니까 평가구분 입원평가 계속입원','A. 13. 장기요양서비스를 받고 싶은 의향이 있습니까?\n- 65세 이상이거나 노인성질환을 갖고 있으면서, 등급 판정이 없는 경우에만 평가하여 기재함\n▸ 유의사항\n· ‘A. 5. 평가구분’이 ‘1. 입원 평가’인 경우만 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 300쪽',300,10,9);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0010','PDF_PVAL','PDF_PVAL_01','PDF','ITEM','A. 14. 사회환경 선별조사','A. 14. 사회환경 선별조사','14 사회환경 선별조사 평가구분 입원평가 계속입원','A. 14. 사회환경 선별조사\n- a. 사회환경 선별조사 각 항목(b~g)에 답변 거부일 경우 ‘응답거부’ 기재함\n- b. 가족, 친지 등의 보호자 또는 유･무급 형태의 돌봄 고용인력 모두 포함하여 식사 준비 등의 수발을 해줄 수 있는 사람이 없는 경우 ‘예’로 기재함\n- d. 기차역, 공원, 차량 등에서의 노숙 또는 안정적으로 거주할 곳이 없어 찜질방, PC방 등을 떠돌며 (방랑)생활을 한 적 있는 경우 ‘예’로 기재함\n- f. 교통수단 부족은 교통수단 자체가 없거나, 혼자서는 대중교통을 이용하기 힘들어, 타인의 도움이 필요한데 도움을 받지 못하는 경우 ‘예’로 기재함\n▸ 유의사항\n· ‘A. 5. 평가구분’이 ‘1. 입원 평가’인 경우만 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 300쪽',300,10,10);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0011','PDF_PVAL','PDF_PVAL_02','PDF','ITEM','B. 1. 혼수','B. 1. 혼수','혼수 치매 인지기능 MMSE 인지','B. 1. 혼수*\n진료기록부에 담당의사가 ‘혼수’, ‘반혼수’ 또는 ‘지속적인 식물인간 상태’ 등에 대한 의식상태를 기록한 경우 해당함.\n▸ 유의사항\n· ‘B. 1. 혼수*’에 “예”라고 기재한 경우 ‘B. 2. 섬망’과 ‘C. 인지기능’ 항목을 기재하지 않고, ‘D. 신체기능’으로 넘어감\n※ 참고사항\n· 의식수준\n   - 노인 환자들은 신경계 손상 등에 의해 의식수준이 저하된 경우가 있다. 의식수준은 주로 다음 5단계로 구분할 수 있다.\n      의식수준 상태\n      명료(alert) 정상적인 의식상태로 자발적으로 모든 자극에 대해 움직이는 상태 집중력이 감소하나, 외부의 자극에 대해 바로 반응할 수 있는 상태로 기면(drowsiness) 자극이 주어질 때에만 의사소통이 가능함\n      혼미(stupor) 통증을 유발하는 강력한 자극에 대해 반응함\n      반혼수(semicoma) 통증을 유발하는 자극에 대해 신체부분을 회피하는 반응을 보임\n      혼수(coma) 자발적인 움직임도 없고 통증을 유발하는 강력한 자극에도 반응이 없음\n· 식물인간(vegetative status)\n   - 대뇌의 기능은 정지되었어도 뇌간 끝 부분에 있는 연수의 생명 중추 기능은 유지되어, 인공호흡기를 부착하지 않고서도 생명이 지속되는 상태이다. 운동, 감각, 기억, 사고 등 사람의 동물적 기능은 상실하였으나, 호흡, 순환, 대사, 체온 조절 등 식물적 기능은 유지 되고 있는 상태이며 의식이 없고 전신이 경직되어 있다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 301쪽',301,10,11);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0012','PDF_PVAL','PDF_PVAL_02','PDF','ITEM','B. 2. 섬망','B. 2. 섬망','섬망 치매 인지기능 MMSE 인지 환자평가표 평가표 작성','B. 2. 섬망*\n진료기록부에 담당의사가 ‘섬망’에 대한 의식상태를 기록한 경우 해당함.\n▸ 유의사항\n· 평가기준 중 ‘지난 7일 이내’는 환자평가표 작성일을 기준으로 작성일을 포함하여 7일 이전 까지를 의미함\n※ 참고사항\n· 섬망\n   가. 섬망이란：급성 또는 아급성의 다양한 정신기능 이상(대개 의식 및 인지기능의 손상)으로 나타나는 가역적인 뇌 대사의 장애를 말함. 대개는 일시적으로 나타나며 가역적임\n   나. 원인：중추신경계 질환, 전신질환, 수술, 약물중독이나 금단 등\n   다. 증상\n   – 급성적인 의식장애, 집중력 장애, 안절부절 못함, 진전(tremor) 등\n   – 혈압의 변동, 빈맥, 발한, facial flushing 등의 자율신경 증상이 동반되기도 함\n   라. 섬망과 치매증상의 감별\n      구분 섬망(delirium) 치매증상(dementia)\n      발생 급성 완만하고 잠행성\n      경과 보통 단기간 여러 해에 걸쳐 진행됨\n      기분 공포, 불안, 흥분성 불안정한 감정이나 성격성향 지각 환청, 환시, 환촉, 착각 환각은 두드러진 특징 아님 기억 단기기억 손상 단기기억 손상 후 장기기억 손상 의사소통 더듬거리는 의사표현, 작화증 점진적인 실어증과 작화증','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 302쪽',302,10,12);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0013','PDF_PVAL','PDF_PVAL_03','PDF','ITEM','C. 1. 단기기억력','C. 1. 단기기억력','단기기억력 ','C. 1. 단기기억력\n알고 있거나 배운 것을 5분 후에도 동일하게 기억하는지 여부를 측정하여 기재하는 것으로 평가기준은 다음과 같음.\n      -다 음-\n0. 정상：세 낱말 모두를 기억하는 경우\n1. 이상 있음：두 낱말 이하를 기억하는 경우\n2. 확인 불가：혼수는 아니지만 단기기억력을 평가할 수 없는 경우\n▸ 유의사항\n· 구두표현이 어려운 환자는 글로 쓰게 하여 평가함\n· 혼수는 아니지만 단기기억력을 평가할 수 없는 경우는 ‘2. 확인 불가’로 기재함\n   - (예시) 혼수는 아니지만 심한 구음장애(dysarthria)가 있으면서 cachexia상태로 단기기억력 평가를 위한 낱말을 발음할 수 없으며 글로써 표현하는 것도 불가능한 상태 등\n▸ 평가방법 예시\n· 먼저 환자에게 “제가 지금부터 낱말을 세 개 불러 드릴테니, 제가 다 말한 다음 따라하세요.”\n   라고 하고, 서로 관계없는 세 단어(예：“비행기, 연필, 소나무” 또는 “나무, 자동차, 모자”\n   등)를 일 초에 하나씩 불러준다. 환자가 말한 뒤 내용을 정확히 알아들었는지 확인한 다음, 잠시 다른 화제로 이야기를 나눈 뒤, 5분 후에 환자가 세 낱말을 기억해 내는지 평가한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 304쪽',304,10,13);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0014','PDF_PVAL','PDF_PVAL_03','PDF','ITEM','C. 2. 일상 생활사에 관한 의사결정을 할 수 있는 인식기술','C. 2. 일상 생활사에 관한 의사결정을 할 수 있는 인식기술','일상 생활사 관한 의사결정 인식기술 치매 인지기능 MMSE 인지','C. 2. 일상 생활사에 관한 의사결정을 할 수 있는 인식기술 일상적인 생활(언제 식사해야 하는지, 휠체어의 용도를 알고 필요시 이용할 줄 아는지, 요의 또는 변의를 느낄 때 화장실을 가려하는지, 도움이 필요한 경우 보조인력 등 다른 사람에게 도움을 요청할 수 있는지 등)과 관련하여 스스로 의사결정이 가능한 정도를 측정하여 기재하는 것으로 평가기준은 다음과 같음.\n      -다 음-\n1. 새로운 상황(평소와 다른 상황을 의미)에서만 의사결정의 어려움이 있는 경우\n2. 인식기술이 다소 손상됨：의사결정 능력이 부족하여 지도나 감독을 요하는 경우\n3. 인식기술이 심하게 손상됨：거의 또는 전혀 의사결정을 하지 못하는 경우 또는 어떤 방법으로도 의사표현이 안 되는 경우\n▸ 유의사항\n· 구두표현이 어려운 환자나 치매환자의 경우 의사결정 능력을 환자의 몸짓이나 행동 등을 통해 평가함\n· 일상적이거나 자주 반복되는 상황에서는 의사결정을 잘 할 수 있으나, 외부 손님이 방문했을 때 또는 새로운 프로그램을 수행할 때 등 어쩌다 발생하는 새로운 상황에서 의사결정에 어려움이 있는 경우에는 ‘1. 새로운 상황에서만 의사결정의 어려움이 있음’으로 기재함\n· 의식수준이 심하게 저하되어 있거나, 침상에만 누워있고 의사소통이 불가능한 상태 등 어떤 방법으로도 의사표현이 안 되어 일상생활에 관한 의사결정 능력을 평가할 수 없는 경우에는 ‘3. 인식기술이 심하게 손상됨’으로 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 304쪽',304,10,14);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0015','PDF_PVAL','PDF_PVAL_03','PDF','ITEM','C. 3. 이해시키는 능력','C. 3. 이해시키는 능력','이해시키 능력 ','C. 3. 이해시키는 능력\n말이나 글 등으로 의사소통을 할 때 자신의 의견이나 요구사항을 표현할 수 있는 정도를 측정하여 기재하는 것으로 평가기준은 다음과 같음.\n      -다 음-\n1. 대부분 이해시킴：단어를 찾거나 생각을 마무리하는데 어려움이 있는 경우\n2. 가끔 이해시킴：구체적인 요청을 하는 데 제한이 있는 경우\n▸ 유의사항\n· 구두표현이 어려운 경우에는 글을 쓰거나 몸짓 등을 이용하여 남에게 의사표현을 할 수 있으므로 말 뿐 아니라 동작, 신체적 표현 등의 방법을 모두 포함하여 환자의 능력을 평가함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 305쪽',305,10,15);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0016','PDF_PVAL','PDF_PVAL_03','PDF','ITEM','C. 4. 말로 의사표현을 할 수 있음','C. 4. 말로 의사표현을 할 수 있음','의사표현 있음 ','C. 4. 말로 의사표현을 할 수 있음\n환자의 말을 경청하여 말하기의 명료함을 평가함\n0. 아니오：불분명하고 웅얼거리는 단어로 말하거나, 말을 할 수 없는 경우 (예：구음장애가 있거나, 의식이 drowsy하여 말을 할 수 없는 상태 등)\n1. 예：분명하고 명료하게 말하는 경우\n▸ 유의사항\n· 환자가 하는 말에 대하여 내용의 적절성을 평가하는 것이 아니라, 말(words spoken)의 명료함과 명확성을 평가함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 305쪽',305,10,16);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0017','PDF_PVAL','PDF_PVAL_03','PDF','ITEM','C. 5. 행동심리증상의 빈도','C. 5. 행동심리증상의 빈도','행동심리증상 ','C. 5. 행동심리증상의 빈도*\n행동심리증상의 경감을 위한 약제를 복용중인 경우에는 그 상태에서 동일 기준으로 평가함.\n지난 7일 간의 상태를 기준으로 평가하되, 지난 4주간의 상태를 종합적으로 관찰하여 평가 하는 것도 가능함. 관찰기간은 이전 관찰기간과 중복되지 않도록 함. 평가기준은 다음과 같음.\n      -다 음-\n0. 없음：지난 7일(4주) 동안 행동심리증상이 전혀 나타나지 않은 경우\n1. 가끔：지난 7일(4주) 동안 1일(1~7일) 정도 행동심리증상이 나타난 경우\n2. 자주：지난 7일(4주) 동안 2일(8일) 이상 나타나나, 매일은 아닌 경우\n3. 매우자주：지난 7일(4주) 동안 매일 하루에 한 번 이상 행동심리증상이 나타난 경우\n※ 행동심리증상의 정의\na. 망상은 사실이 아닌 것을 사실이라고 믿거나, 남들이 자기를 해치려 하거나 무엇을 훔쳐갔다고 주장하는 것을 의미함.\nb. 환각은 헛것을 보거나 듣는 등 현재에 없는 것을 실제로 보거나 듣거나 경험하는 것을 의미함.\nc. 초조 또는 공격성은 소리를 지르거나 욕을 하거나, 다른 사람을 때리거나 밀치는 것, 안절부절 못하는 행동 등을 보이는 것을 의미함.\nd. 우울 또는 낙담은 슬퍼 보이거나 우울해 보이는 것, 환자 스스로 슬프거나 우울하다고 말하는 것을 의미함.\ne. 불안은 특별한 이유 없이 신경이 매우 예민해 보이거나, 걱정하거나 무서워하는 것을 의미함.\nf. 들뜬 기분 또는 다행감은 특별한 이유 없이 비정상적으로 기분 좋아하거나 재미있어 하는 것을 의미함.\ng. 무감동 또는 무관심은 주변에 관심과 흥미를 잃거나, 새로운 일을 시작하려는 의욕이 감소하는 것을 의미함.\nh. 탈억제는 충동적 행동, 사회적으로 부적당한 행동 등을 보이는 것을 의미함.\nI. 과민 또는 불안정은 평소에 비해 비정상적으로 화를 내거나 성급해졌거나 감정이 급격하게 변하는 것을 의미함.\nj. 이상 운동증상 또는 반복적 행동은 반복적으로 왔다 갔다 하거나 같은 일을 계속 해서 반복하는 것을 의미함.\nk. 수면 또는 야간행동은 밤에 자지 않고 깨어 있거나 서성거리거나 돌아다녀 다른 사람의 수면을 방해하는 것을 의미함.\nC. 5. 행동심리증상의 빈도*\nl. 식욕 또는 식습관의 변화는 식욕, 식습관, 음식의 선호가 바뀌는 것을 의미함.\nm. 케어에 대한 저항은 복약, 주사, 일상생활수행을 위한 도움, 식사 등에 대해 거부 하는 것을 의미함.\nn. 배회는 납득할만한 목적 없이 돌아다니며, 필요사항이나 안전에는 신경 쓰지 않는 것\n    같이 보이는 것을 의미함.\n▸ 유의사항\n· ‘l. 식욕/식습관의 변화’ 평가시 Levin-tube를 삽입한 환자의 경우 식욕/식습관의 변화를 평가할 수 없으므로 ‘없음’에 체크함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 306쪽',306,10,17);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0018','PDF_PVAL','PDF_PVAL_03','PDF','ITEM','C. 6. K-MMSE(또는 MMSE-K) 검사','C. 6. K-MMSE(또는 MMSE-K) 검사','MMSE 검사 치매 인지기능 인지 환자평가표 평가표 작성','C. 6. K-MMSE(또는 MMSE-K) 검사* 평가표 작성일로부터 6개월 이내의 검사 결과를 의미함.\n▸ 유의사항\n· 6개월 이내에 2회 이상 검사를 실시했다면 가장 최근 시행한 검사 결과를 기재함\n· 다른 요양기관에서 시행한 경우에도 기록(검사일, 검사결과 등)이 확인되면 기재 가능함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 307쪽',307,10,18);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0019','PDF_PVAL','PDF_PVAL_03','PDF','ITEM','C. 7. 치매 척도 검사','C. 7. 치매 척도 검사','치매 검사 인지기능 MMSE 인지 환자평가표 평가표 작성','C. 7. 치매 척도 검사*\n평가표 작성일로부터 12개월 이내의 검사 결과를 의미함.\n▸ 유의사항\n· 12개월 이내에 2회 이상 검사를 실시했다면 가장 최근 시행한 검사 결과를 기재함\n· 다른 요양기관에서 시행한 경우에도 기록(검사일, 검사결과 등)이 확인되면 기재 가능함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 307쪽',307,10,19);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0020','PDF_PVAL','PDF_PVAL_04','PDF','ITEM','D. 1. ~10. 일상생활수행능력(ADL)','D. 1. ~10. 일상생활수행능력(ADL)','10 일상생활수행능력 ADL 일상생활','D. 1.~10. 일상생활수행능력(ADL)\n일상생활을 하는데 필요한 기본 동작들을 수행하는 능력을 종합적으로 판단하여 평가함.\n일시적 변동이나 예외적 상황은 제외하고 반복적이고 통상적인 수행능력의 수준(빈도가 높은 것)을 평가함. 일상적인 보장구 및 보조구 등의 기구를 사용(착용)하고 있는 경우는 그 상태에서 판단하며 평가기준은 다음과 같음.\n      -다 음-\n1. 완전자립：대부분의 경우 도움이나 감독 없이 스스로 수행할 수 있음.\n2. 감독필요：대부분의 경우 감독이나 격려가 필요함.\n3. 약간의 도움：대부분의 경우 환자가 스스로 행위를 수행하나 무게를 지탱하지 않는 정도의 도움이 필요함.\n4. 상당한 도움：대부분의 경우 무게를 지탱하는 도움을 제공하거나, 해당 활동의 일 부분(전체가 아님)을 다른 사람이 전적으로 수행함.\n5. 전적인 도움：대부분의 경우 다른 사람의 전적인 도움을 받아 일상생활을 수행함.\n6. 행위발생 안함：일주일 동안 해당 행위가 전혀 발생하지 않음.\nD. 1.~10. 일상생활수행능력(ADL)\n※ ADL 항목별 정의 및 측정 시 유의사항\n1. 옷벗고 입기는 일상적인 옷 벗고 입는 일련의 행위를 의미함.\n2. 세수하기는 수건 준비, 수도꼭지 돌리기, 물 받기, 얼굴 씻기, 옷이 젖는지 확인, 수건으로 닦기 등의 행위를 의미함.\n3. 양치질하기는 칫솔에 치약 바르기, 칫솔질하기, 헹굼용 물 준비하기, 가글하기 등의 행위(틀니를 빼고, 씻고, 헹구는 등의 행위도 포함)를 의미함.\n4. 목욕하기는 목욕이나 샤워를 할 때 비누칠하기, 헹구기 등의 행위를 의미함.\n5. 식사하기는 투여 경로[경구, 비경구]를 불문하고 환자의 영양섭취와 관련된 일련의 동작을 의미함. 일반적인 식사의 경우 음식이 차려졌을 때 도구를 사용하여 스스로 섭취가 가능한 정도와 일반적인 식사[경관영양, 정맥영양(TPN 등)]가 아닌 경우 그에 상응하는 식사활동을 스스로 수행 가능한 정도를 평가함.\n    신체적 기능이 있다하더라도 치매환자 등에서 인지적인 문제로 인하여 식사하기 동작 수행이 되지 않아 다른 사람(보조인력 등)이 먹여줘야 하는 경우는 다른 사람 (보조인력 등)이 먹여준 것을 기준으로 측정함. 그러나 환자의 식욕, 기분 등으로 인해 식사하지 않으려 해서 다른 사람(보조인력 등)이 먹여주는 경우 환자의 실제 ‘식사하기’ 동작의 수행능력 정도를 측정함.\n    식사하기에서 ‘행위발생 안함’은 경구 또는 비경구 모두로 체내에 영양이 투여되지 않는 경우를 의미함. 그러므로 금식(NPO)을 하는 환자라도 비경구적으로 영양물질을 공급하고 있는 경우에는 ‘행위발생 안함’에 기재해서는 안 됨.\n6. 체위변경하기는 제대로 돌아눕기, 엎드리기, 옆으로 눕기 등의 행위를 의미함.\n7. 일어나 앉기는 누운 상태에서 상반신을 일으켜 앉는 행위를 의미함.\n8. 옮겨앉기는 「침상에서 휠체어로」, 「의자에서 휠체어로」, 「휠체어에서 침상으로」, 「휠체어 에서 의자로」 이동하는 행위를 의미함.\n9. 방밖으로 나오기는 환자가 자신의 방에서 복도 등으로 이동하는 행위를 말하며, 휠 체어를 사용하는 경우는 일단 휠체어를 탄 상태에서 이동하는 능력을 평가함.\n10. 화장실 사용하기는 배뇨･배변과 관련된 일련의 동작으로 하의 벗기, 배설 후 닦기, 옷 입기, 변기에 물 내리기, 휴대용 변기 비우기, 사용한 카테터 뒤처리 등의 행위를 의미함. 화장실 또는 실내변기가 있는 곳까지 이동하는 능력은 측정대상에 포함되지 않음. 실내변기, 침상용 변기, 소변기를 사용하는 경우와 인공항문, 인공요루 등을 한 환자의 경우에도 그 상태에서의 수행정도를 판단함. 화장실 사용하기에서 ‘행위발생 안함’은 어떤 형태로든 배설 행위가 전혀 일어나지 않은 경우를 의미함.\n▸ 유의사항\n· 기분 등의 이유로 스스로 해당 동작을 할 수 있음에도 불구하고 수행하지 않는 경우는 수행 능력과는 무관한 것이므로 이를 기준으로 판단하지 않으며, 실제 환자의 해당 동작의 수행 능력이 어느 정도인가를 평가함\n· ‘식사하기’를 평가할 때 치매환자의 경우, 식사시간, 식사의 필요성, 식사방법 등에 대한 인지부족으로 인해 식사시간이 되어도 식사를 하지 않는 경우에는 환자가 식사를 할 수 있는 신체적 기능이 있다하더라도 인지 문제로 인해 스스로 식사하기 동작을 수행하지 못 하고 다른 사람(보조인력 등)이 먹여주고 있으므로 다른 사람(보조인력 등)이 먹여준 것을 기준으로 평가하나, 환자의 식욕, 기분 등으로 인해 식사하지 않으려 해서 다른 사람(보조 인력 등)이 먹여주는 경우 다른 사람(보조인력 등)의 도움은 환자의 식사하기 수행능력과는 무관한 것이므로 이를 반영해서 도움정도를 체크해서는 안됨\n   ‘일상생활수행능력 평가를 위한 구체적 사례’ 참고 (요양기관업무포탈 심사기준 종합서비스의 공지사항 게재)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 308쪽',308,10,20);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0021','PDF_PVAL','PDF_PVAL_04','PDF','ITEM','D. 11. 와상상태 여부','D. 11. 와상상태 여부','11 와상상태 ','D. 11. 와상상태 여부\n일주일에 적어도 4일 이상 하루 22시간 이상을 자리에 누워 있는 상태를 말함.\n▸ 유의사항\n· 의식 및 기능상태 저하, 고관절 골절(hip fracture)로 인해 의사가 ABR(Absolutely Bed Rest)하도록 지시하여 환자가 24시간 내내 침대에 누워있는 상태 등 의학적인 문제 또는 의료적인 필요에 의해 침대에서 주로 지내는 것뿐만 아니라, 휠체어 등을 이용하여 침대 밖으로 벗어날 수는 있으나 환자의 의지도 없고, 간병인 등도 거의 운동을 시키지 않는 등 자극의 부족으로 인해 침대에서 주로 생활하는 것도 포함함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 310쪽',310,10,21);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0022','PDF_PVAL','PDF_PVAL_05','PDF','ITEM','E. 1. 대변조절 상태','E. 1. 대변조절 상태','대변조절 상태 배뇨 실금 배뇨일지 도뇨 소변','E. 1. 대변조절 상태*\n환자의 배변 주기를 고려하여 판단하며 평가기준은 다음과 같음.\n      -다 음-\n0. 조절할 수 있음：전혀 실금하지 않는 경우\n1. 가끔 실금함：평균적인 배변 횟수를 고려하여 실금하는 경우보다 조절하는 경우가 더 많거나 같은 경우\n2. 자주 실금함：평균적인 배변 횟수를 고려하여 조절하는 경우보다 실금하는 경우가 더 많은 경우\n3. 조절 못함：배변을 보는 주기에 관계없이 배변할 때마다 실금하는 경우\n▸ 유의사항\n· 관장을 하고 난 후 하루 정도 변실금을 하는 경우 실금으로 판단함\n· 인공항문(ostomy)을 가지고 있는 환자의 경우, 실수로 한 번 정도 인공항문 주변으로 leakage가 있고 이후 바로 적절히 관리해 주었다면 이는 환자의 예외적인 상황이므로 반영하지 아니함.\n   그러나 이와 같은 현상이 반복적으로 나타난다면 이는 통상적인 상황으로 간주하여 실금으로 판단함\n· 환자의 배변 주기를 고려하여, 대변을 조절하는 횟수와 실금하는 횟수를 비교하여 해당 정도를 평가하는 것으로 소변과 달리 대변은 매일 보지 않는 경우가 많으므로, 실제 7일 동안 대변을 2~3회 보았는데, 실금을 1회만 한 경우라면, ‘1. 가끔 실금함’으로 기재함\n· 전신쇠약 등으로 화장실에 가지 못하고 대변기를 대어주는 것도 거부하여 평가기간 동안 매번 기저귀에 대변을 보았다면 ‘조절 못함’으로 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 311쪽',311,10,22);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0023','PDF_PVAL','PDF_PVAL_05','PDF','ITEM','E. 2. 소변조절 상태','E. 2. 소변조절 상태','소변조절 상태 배뇨 실금 배뇨일지 도뇨 소변 유치도뇨관 도뇨관 폴리 카테터 foley','E. 2. 소변조절 상태*\n환자의 소변 주기를 고려하여 판단하며 평가기준은 다음과 같음.\n      -다 음-\n0. 조절할 수 있음：전혀 실금하지 않는 경우\n1. 가끔 실금함：실금하는 경우보다 조절하는 경우가 더 많거나 같은 경우\n2. 자주 실금함：조절하는 경우보다 실금하는 경우가 더 많은 경우\n▸ 유의사항\n· 기저귀를 차고 있더라도 환자가 요의를 느껴 의료진에게 이를 알리고, 소변기 등을 대어 주어 소변을 본다면 이는 실금이 아님\n· 유치도뇨관 등 배뇨관련 기구(device)를 가지고 있는 환자의 경우 그 상태를 기준으로 판단함\n   - 조절이 잘 되고 있어 침상이 젖지 않는다면 ‘0. 조절할 수 있음’으로 기재함\n   - 그러나, 기구 주변으로 반복적인 leakage가 있다면 실금하는 것으로 판단함\n   - 다만, 실수로 한 번 정도 leakage가 있고 이후 바로 적절히 관리해 주었다면 이는 환자의 예외적인 상황이므로 반영하지 않음\n· 소변조절을 잘 하던 환자가 이뇨제 복용 등으로 평가기간 7일 중 2일 동안 매일 한 번씩 실금을 한 경우 실금한 횟수보다 조절한 횟수가 더 많으므로 ‘1. 가끔 실금함’으로 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 312쪽',312,10,23);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0024','PDF_PVAL','PDF_PVAL_05','PDF','ITEM','E. 3. 환자에게 실시하는 배변조절 기구 및 프로그램','E. 3. 환자에게 실시하는 배변조절 기구 및 프로그램','환자에게 실시하 배변조절 기구 프로그램 배뇨 실금 배뇨일지 도뇨 소변 치매 인지기능 MMSE 인지','E. 3. 환자에게 실시하는 배변조절 기구 및 프로그램*\na. 일정하게 짜여진 배뇨계획(Scheduled toileting plan)\n      방광이 차는 것과 관계없이 정해진 시간에 다른 사람(보조인력 등)이 환자를 화장실에 데리고 가거나, 소변기를 주거나, 화장실에 가도록 상기시켜 주는 것을 말함.\nb. 방광 훈련 프로그램(Bladder training program)\n      인지기능 손상이 없는 환자에게 방광근 및 요도괄약근 재훈련을 위하여 의식적으로 배설 하는 것을 지연시키도록 하거나 긴박하게 소변이 나오는 것을 참도록 교육시키는 것을 말함.\nc. 규칙적인 도뇨수행\n      (CIC, Clean Intermittent Catheterization)\n      일정한 간격(3-6시간)으로 방광 내에 고여 있는 소변을 배출시키는 것을 말함.\nd. 외부(콘돔형) 카테터\n      남성환자에게 유치도뇨관 삽입 없이 배뇨를 하기 위한 도구를 말함.\nf. 인공루\n      요루(urostomy), 장루(colostomy) 등을 말함.\n▸ 유의사항\n· ‘일정하게 짜여진 배뇨계획’은 인지장애로 인하여 스스로 화장실을 가야하는 것을 인식하지 못하여 배뇨관리를 잘 못하는 환자에게 규칙적으로 정해진 시간에 화장실을 가도록 알려주거나 유도하는 습관훈련(habit training)이나 배설자극 등이 포함됨\n· ‘방광 훈련 프로그램’은 배뇨 간격이 짧은 긴박성 요실금 환자에게 일정 시간 소변을 참게 하여 점차로 그 시간 간격을 늘려가도록 하는 경우, 바이오피드백(Biofeedback) 기구 등을 사용하여 골반근육능력을 향상시키는 경우, 유치도뇨관 제거 후 자가도뇨를 하기 전 방광근 및 요도괄약근 훈련을 위하여 일정시간 간격으로 유치도뇨관을 잠궜다가 풀어 요의를 느낄 수 있도록 하는 훈련(clamp and release) 등이 포함됨\n· 유치도뇨관이 삽입되어 있는 경우 ‘g. 유치도뇨관 삽입’에 체크하고 삽입일자 또는 교체일자를 기재함\n   - 입원 시부터 유치도뇨관이 삽입되어 있는 경우 삽입일자를 확인하여 기재하거나 교체 시 교체일자를 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 313쪽',313,10,24);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0025','PDF_PVAL','PDF_PVAL_05','PDF','ITEM','E. 4. 배뇨일지 작성 여부','E. 4. 배뇨일지 작성 여부','배뇨일지 작성 배뇨 실금 도뇨 소변','E. 4. 배뇨일지 작성 여부*\n작성일을 기준으로 7일 이상 지속적으로 작성한 경우 “예”로 기재함.\n▸ 유의사항\n· “예”로 기재 시 배뇨일지 작성일수는 “7일”로 기재함\n· 작성일을 기준으로 지난 7일 동안 7일 미만 작성한 경우 “아니오”로 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 314쪽',314,10,25);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0026','PDF_PVAL','PDF_PVAL_06','PDF','ITEM','F. 1. 질병','F. 1. 질병','질병 HbA1c 당화혈색소 당뇨','F. 1. 질병*\nc. 요로감염은 지난 30일 이내에 요로감염으로 인해 연속해서 1주일 이상 비경구 항생제가 투여된 경우에 해당함.\n▸ 유의사항\n· a. 당뇨에 기재한 경우 ‘1일 3회 이상 혈당검사 매일 실시 여부’와 ‘최근 3개월 이내에 헤모글로빈A1c(HbA1c) 검사 실시여부’를 기재해야 하며 헤모글로빈A1c(HbA1c)는 다른 요양기관에서 시행한 경우에도 기록(검사일, 검사결과 등)이 확인되면 기재 가능함\n· f. 사지마비(Quadriplegia)\n   - 척수신경이 손상을 받아서 신경증세가 발생하여 양쪽 팔과 다리의 움직임이 약하거나 전혀 못 움직이는 상태를 의미하는 것으로 사지 불완전마비(Quadriparesis)는 해당하지 않음\n· k. 척수손상(Cord injury)\n   - 외상(trauma)에 의한 척수손상 뿐만 아니라, 질환에 의한 척수손상도 포함하는 것으로 원인과 상관없이 모든 척수손상을 말함\n· 최근의 일상생활수행능력, 인지기능, 정서, 행동, 의학적 치료, 간호 감시, 사망의 위험과 직접적인 상관이 있는 질병에만 기재하는 것이므로 10년 전 고혈압으로 진단받아 5년 정도 혈압약을 먹으면서 적극적인 식이요법과 운동요법으로 혈압수치가 적절히 조절되어 현재는 혈압약을 먹지 않고 있는 경우 ‘b. 고혈압’에 기재하지 않음','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 316쪽',316,10,26);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0027','PDF_PVAL','PDF_PVAL_07','PDF','ITEM','G. 1. 문제상황','G. 1. 문제상황','문제상황 영양 경관영양 섭취 수분','G. 1. 문제상황*\na. 열은 37.2℃(직장 체온은 37.5℃) 이상의 체온이 3일 이상 있는 경우를 말함.\nb. 탈수는 다음 중 2가지 이상에 해당되는 경우(①, ③은 I/O sheet에 근거해야 함)를 말함.\n      -다 음-\n① 1일 섭취하는 수분량이 1500㎖ 미만인 경우\n② 탈수의 임상적 증상[건조한 구강점막, 피부탄력도 저하, 색이 짙은 소변, 새로 발병한 또는 악화된 혼돈, 비정상적인 임상검사 결과(헤모글로빈, 헤마토크리트, 칼륨, 혈액 요소질소, 요비중 증가 등)]등을 보이는 경우\n③ 구토, 열, 설사 등으로 섭취한 수분량 보다 수분 소실량이 많은 경우\nc. 구토는 약물독성, 독감, 심인성 문제 등 원인에 상관없는 구토를 말함.\n▸ 유의사항\n· a. 열\n   - 작성일을 기준으로 지난 7일 동안 열이 3일 이상 있는 경우 기재하며, 3일 미만 있는 경우 기재하지 않음\n   - ‘a. 열’에 기재한 경우 ‘체온’과 ‘발열 원인을 찾는 검사와 처치 시행 여부’와 ‘발열 일수’를 기재해야 하며 ‘발열 원인을 찾는 검사와 처치 시행 여부’는 발열상태의 환자에게 발열 원인을 찾기 위한 검사와 해열을 위한 처치를 모두 시행한 경우 “예”로 기재하고, ‘발열 일수’는 최대 7일 기재함\n· d. 수술 3개월 이내 루 관리\n   - 환자평가표 작성일을 기준으로 루(위루, 요루, 장루) 수술일로부터 3개월 이내이면서 루 관리를 시행하고 있는 경우 기재함\n· e. 출혈･감염 등의 문제로 인한 루 관리\n   - 환자평가표 작성일을 기준으로 루(위루, 요루, 장루) 수술일로부터 3개월 이후라도 출혈･ 감염 등의 문제가 있어 지속적으로 루 관리를 시행하고 있는 경우 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 317쪽',317,10,27);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0028','PDF_PVAL','PDF_PVAL_07','PDF','ITEM','G. 2. 통증','G. 2. 통증','통증 ','G. 2. 통증*\n통증은 통증 유발요인 혹은 완화요인(provocation/palliation), 통증의 양상(quality), 통증부위(region/radiation), 통증강도(severity), 통증 지속시간(timing) 등을 평가하여 진료기록부 등에 기록함.\n통증강도는 통증 사정도구(VAS 등)를 이용하여 판단하며, 여러 부위에 통증이 있고 각 부위별 통증강도가 다를 경우에도 환자상태별 통증점수와 빈도 등을 통합적으로 고려하여 통증의 빈도와 강도를 기재함.\n▸ 유의사항\n· 통증 발생 빈도가 ‘1. 통증 있으나 매일은 아님’ 또는 ‘2. 매일 통증이 있음’인 경우 통증 강도는 VAS, NRS, FPS 중 하나를 기재함\n· 암성통증이라도 격렬하거나 참을 수 없는 통증이 매일 있어 통증치료를 받고 있는 경우에는 의료고도로, 그 외 암성통증이 있어 마약성 진통제 등으로 적절한 치료를 받고 있는 경우에는 의료중도로 산정 가능함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 318쪽',318,10,28);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0029','PDF_PVAL','PDF_PVAL_07','PDF','ITEM','G. 3. 낙상 여부','G. 3. 낙상 여부','낙상 평가구분 입원평가 계속입원','G. 3. 낙상 여부*\n작성일을 기준으로 지난 30일 이내 또는 31일에서 180일 사이의 낙상존재여부를 말함.\n▸ 유의사항\n· 낙상으로 인해 별다른 손상이 없었더라도 낙상이 있었다면 “예”로 기재함\n· ‘A. 5. 평가구분’이 ‘1. 입원 평가’인 경우(또는 입원 초기 환자의 경우) 지난 30일 이내 또는 31일에서 180일 사이의 낙상존재여부를 환자 및 가족에게 확인하여 기재함\n   - 다만, 환자 및 가족에게 확인할 수 없는 경우 ‘2. 확인불가’에 기재함\n※ 참고사항\n· 낙상이란 비의도적인 자세변화로 인해 높은 곳에서 낮은 곳으로 넘어지거나 바닥에 눕게 되는 것을 말한다. 낙상은 높은 곳에서 떨어지는 것, 넘어지는 것, 미끄러지는 것 등을 모두 포함\n   하며 주로 질병, 기능상태 저하, 약물투여, 위험한 환경 등이 원인이 되어 발생한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 319쪽',319,10,29);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0030','PDF_PVAL','PDF_PVAL_07','PDF','ITEM','G. 4. 말기질환','G. 4. 말기질환','말기질환 ','G. 4. 말기질환*\n진료기록부에 ‘말기질환 또는 end-stage disease’ 등 의사의 기록이 있어야 하며, 질환의 종류를 불문하고 기대여명이 얼마 남지 않아 의사가 말기상태로 진단한 것을 의미함.\n▸ 유의사항\n· 진료기록부에 DNR(Do Not Resuscitate) 등의 기록이 있다 하더라도, ‘말기질환 end-stage disease’ 등의 의사의 기록이 있어야 함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 319쪽',319,10,30);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0031','PDF_PVAL','PDF_PVAL_08','PDF','ITEM','H. 1. 물이나 음식을 삼키기가 어렵습니까?','H. 1. 물이나 음식을 삼키기가 어렵습니까?','물이나 음식 삼키기 어렵습니까 영양 경관영양 섭취 수분','H. 1. 물이나 음식을 삼키기가 어렵습니까?\n정맥 또는 경관영양 등을 하고 있어 입으로 물이나 음식을 삼키지 않는 경우에는 연하곤란 증상이 없는 것으로 평가함.\n▸ 유의사항\n· 금식 상태에서 정맥 또는 경관영양을 하고 있거나 수술 또는 검사를 위한 금식 상태인 경우 “아니오”로 기재함\n▸ 평가방법 예시\n· 환자가 주로 먹거나 마실 때 자주 사레가 들거나, 기침을 하는 증상, 오랫동안 음식을 입에 계속 머금고 있거나 과도하게 침을 흘리는 증상 등을 보이는 경우 연하장애가 있다고 판단함\n※ 참고사항\n· 연하곤란(swallowing problem, dysphagia)이란 음식물을 씹고 삼키는 구강, 인두, 식도 등의 구조에 결함이 있거나 기능장애가 있어서 씹고 삼키는 능력이 손실 또는 손상된 것을 말한다. 연하곤란은 원인에 따라 기계적 연하곤란(Mechanical dysphagia), 운동성 연하 곤란(Motor dysphagia)으로 나뉠 수 있다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 320쪽',320,10,31);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0032','PDF_PVAL','PDF_PVAL_08','PDF','ITEM','H. 2. 체중 등','H. 2. 체중 등','체중 ','H. 2. 체중 등*\n관찰기간 내에 체중을 측정한 경우 기재함. 체중감소란 지난 31일 이내에 5% 이상 감소 또는 184일 이내에 10% 이상 감소한 경우에 한함.\n   계산식1> [지난달 체중(㎏) - 이번달 체중(㎏)]/[지난달 체중(㎏)] ≥ 0.05 계산식2> [6개월전 체중(㎏) - 이번달 체중(㎏)]/[6개월전 체중(㎏)] ≥ 0.1\n   ※ 체중감소율은 소수 셋째자리에서 절사\n▸ 유의사항\n· 기간 내에 여러 번 체중을 측정한 경우 모두 비교대상이 됨\n· 이번달 체중과 비교하는 지난달(또는 6개월전) 체중은 관찰기간에 측정한 체중이 아니어도 됨\n· 2-3. 키(신장)*\n   - 관찰기간 내에 키를 측정한 경우 기재함\n   - 관찰기간 내에 키를 측정하지 않은 경우 입원기간 중 측정한 키를 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 321쪽',321,10,32);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0033','PDF_PVAL','PDF_PVAL_08','PDF','ITEM','H. 3. 영양섭취 방법','H. 3. 영양섭취 방법','영양섭취 영양 경관영양 섭취 수분','H. 3. 영양섭취 방법*\na. 정맥영양(parenteral/IV)은 영양섭취를 목적으로 지속적 또는 간헐적으로 정맥내 영양공급(TPN 등)을 하는 것을 말함.\nb. 경관영양은 비위관 또는 위루 등을 통해 영양공급을 하는 것을 말하며 경구를 통한 수분 또는 영양섭취가 곤란한 상태에서 지난 7일 이상 지속적으로 경관영양을 한 경우 “예”로 기재함\n▸ 유의사항\n· 정맥영양\n   - 진단 혹은 수술 전 처치를 위해 일시적으로 IV fluid를 주입하는 것은 정맥영양에 해당하지 않음\n· 경관영양\n   - “예”로 기재 시 경관영양 실시일수는 “7일”로 기재함\n   - 작성일을 기준으로 지난 7일 동안 7일 미만 경관영양을 한 경우 “아니오”로 기재함\n· ‘H. 3. 영양섭취 방법*’에 모두 “아니오”로 기재한 경우 ‘H. 4. 정맥 또는 경관을 통한 섭취*’ 항목을 기재하지 않음','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 321쪽',321,10,33);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0034','PDF_PVAL','PDF_PVAL_08','PDF','ITEM','H. 4. 정맥 또는 경관을 통한 섭취','H. 4. 정맥 또는 경관을 통한 섭취','정맥 경관 통한 섭취 영양 경관영양 수분','H. 4. 정맥 또는 경관을 통한 섭취*\nI/O sheet 등에 근거하며 실제 환자가 섭취한 열량 및 수분량을 기준으로 계산함.\na. 섭취한 칼로리 비율\n    지난 6일 동안 환자가 섭취(구강섭취 포함)한 총 칼로리 중 정맥 또는 경관을 통해 섭취한 칼로리의 비율(1일 평균)\n      지난 6일 동안 정맥･경관영양으로 섭취한 열량 × 100 지난 6일 동안 총 섭취 열량\nb. 수분 섭취량\n    지난 6일 동안 정맥 또는 경관을 통해 섭취한 1일 평균 수분량 지난 6일 동안 정맥･경관영양으로 섭취한 수분의 총량 / 6\n▸ 유의사항\n· a. 지난 6일 동안 정맥 또는 경관으로 섭취한 칼로리의 비율 (1일 평균)\n   - 1일 24시간을 기준으로 지난 6일 동안 구강섭취를 포함하여 실제 환자가 섭취한 총 칼로리 중 정맥 또는 경관을 통해 섭취한 칼로리의 비율을 계산함\n· b. 지난 6일 동안 정맥 또는 경관으로 섭취한 수분량 (1일 평균)\n   - 1일 24시간을 기준으로 지난 6일 동안 정맥 또는 경관을 통해 섭취한 1일 평균 수분량을 계산함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 322쪽',322,10,34);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0035','PDF_PVAL','PDF_PVAL_09','PDF','ITEM','I. 1. 피부궤양 수 기재','I. 1. 피부궤양 수 기재','피부궤양 욕창 압창 드레싱','I. 1. 피부궤양 수 기재*\n진료기록부에 담당의사가 피부궤양에 대한 근거 등을 기록한 경우에 해당하며 피부궤양 (skin ulcer)의 종류에는 욕창(압박성 궤양), 울혈성 궤양, 허혈성 궤양, 말초신경병증 궤양이 있음.\n압박성 궤양(pressure ulcer)은 일정한 부위에 지속적 압력이 가해졌을 때 모세혈관의 순환장애로 인해 조직의 궤사가 일어나는 것, 울혈성 궤양(stasis ulcer)은 하지의 부적절한 정맥순환으로 인해 발생하는 정맥성 궤양(venous ulcer) 또는 말초정맥질환 (PVD, Peripheral Vascular Disease)으로 인한 궤양, 허혈성 궤양(ischemic ulcer)은 동맥관류부전으로 인하여 주로 하지에 나타나는 동맥성 궤양(arterial ulcer), 말초신경병증 궤양(neuropathic ulcer)은 당뇨병 환자에서 흔히 나타나는 궤양을 말함.\nI. 1. 피부궤양 수 기재*\n딱지(necrotic eschar)로 뒤덮여 있어 단계를 알 수 없다면 변연절제(Debridement)를 수행할 때까지 4단계로 기재하고, 낫고 있는(healing) 궤양의 단계를 평가할 경우 현재 보이는 양상대로 평가함. 예를 들어 3단계 욕창이 낫는 과정에서 현재 2단계 궤양의 양상을 보인다면 2단계로 기재함. 평가기준은 다음과 같음.\n      -다 음-\n   1단계：압박을 제거한 후에도 지속적으로 피부 발적은 있으나, 피부 균열은 없는 경우 2단계：피부가 벗겨지거나 수포모양을 보이는 부분적인 피부층의 소실 있는 경우 3단계：피부가 전층 소실되거나 피하층이 나타나고 깊은 분화구가 생긴 경우 4단계：피부와 피부층이 전부 소실되고 근육이나 뼈가 노출된 경우\n▸ 유의사항\n· 피부궤양을 평가하는 항목으로 화상 등은 ‘I. 4. 피부의 기타 문제*’에서 평가함\n· 신체의 여러 부위에 종류가 다른 궤양이 각각 있는 경우 각각의 피부궤양을 모두 기재해야 하므로 예를 들어 엉덩이에 2단계의 압박성 궤양 2개와 발가락에 당뇨로 인한 3단계의 말초신경병증 궤양 1개가 있는 경우 ‘2단계 욕창(압박성궤양)’에 ‘2’로 기재하고 ‘3단계 울혈성 또는 허혈성 궤양 등’에 ‘1’로 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 323쪽',323,10,35);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0036','PDF_PVAL','PDF_PVAL_09','PDF','ITEM','I. 2. 새로 발생한 욕창','I. 2. 새로 발생한 욕창','발생한 욕창 피부궤양 압창 드레싱 평가구분 입원평가 계속입원','I. 2. 새로 발생한 욕창*\n이전 평가 이후 새로 발생한 욕창(압박성 궤양) 존재 여부를 의미함.\n▸ 유의사항\n· ‘A. 5. 평가구분’이 ‘1. 입원 평가’인 경우 “없음”으로 기재함\n· 욕창(압박성 궤양)을 평가하는 항목으로 울혈성 궤양, 허혈성 궤양, 말초신경병증 궤양은 해당하지 않음','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 324쪽',324,10,36);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0037','PDF_PVAL','PDF_PVAL_09','PDF','ITEM','I. 3. 지난 1년 사이의 욕창 과거력','I. 3. 지난 1년 사이의 욕창 과거력','지난 1년 사이 욕창 과거력 피부궤양 압창 드레싱','I. 3. 지난 1년 사이의 욕창 과거력*\n욕창(압박성 궤양)이 지난 1년 이내에 발생했다가 치유된 적이 있는지를 확인함. 현재의 압박성 궤양, 울혈성 궤양 등의 과거력은 제외함.\n▸ 유의사항\n· 욕창(압박성 궤양)을 평가하는 항목으로 울혈성 궤양, 허혈성 궤양, 말초신경병증 궤양은 해당하지 않음','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 324쪽',324,10,37);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0038','PDF_PVAL','PDF_PVAL_09','PDF','ITEM','I. 4. 피부의 기타 문제','I. 4. 피부의 기타 문제','피부 문제 욕창 피부궤양 압창 드레싱','I. 4. 피부의 기타 문제*\na. 2도 이상의 화상은 진료기록부에 담당의사가 ‘2도 이상의 화상’에 대한 피부상태를 기록한 경우 해당함.\nb. 개방성 피부병변은 매독이나 피부암 등으로 인하여 발생한 개방성 피부질환을 의미함\n    (피부궤양, 자상, 발적은 제외).\nc. 수술창상은 수술 후 회복되지 않은 상처\nd. 발의 감염은 봉소염, 화농성 배출물이 있는 경우에 해당함.\n▸ 유의사항\n· d. 발의 감염\n- 하지를 절단(amputation)하여 발이 없는 경우는 말단 부위를 발로 판단하여 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 325쪽',325,10,38);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0039','PDF_PVAL','PDF_PVAL_09','PDF','ITEM','I. 5. 피부문제에 대한 처치','I. 5. 피부문제에 대한 처치','피부문제 처치 영양 경관영양 섭취 수분','I. 5. 피부문제에 대한 처치*\na. 압력을 줄여주는 도구에는 젤, 공기 또는 다른 쿠션을 포함한 의자나 휠체어, 공기 방석, 물침대, 에어매트리스, 거품침대 등을 말함(도넛모양의 쿠션은 포함하지 않음).\nb. 체위변경은 두 시간마다 지속적으로 환자의 체위를 변경시켜주는 것을 말함.\nc. 피부문제를 해결하기 위한 영양은 적절한 열량공급(30㎉/㎏ 이상)이나 고단백 치료 (1.25g/㎏ 이상)만 해당함.\nf. 수술창상 치료는 수술창상을 보호하거나 치료하기 위한 중재를 말함. 예를 들어 국소 청결(topical cleansing), 창상세척(wound irrigation), 항생제연고 등을 발라줌, 드레싱 실시, 봉합사 제거, 침수 또는 열 요법을 적용한 경우임. 흉관(Chest-tube)\n    등의 드레싱도 포함함.\ng. 화상관련 처치는 2도 이상 화상으로 입원이 필요한 환자에게 화상 관련 직접 처치를 제공한 경우 해당함.\n▸ 유의사항\n· b. 체위변경\n- 간호인력이 직접 실시한 경우 기재함\n· c. 피부문제를 해결하기 위한 영양공급\n- 정맥주사를 통해 공급된 경우 기재 가능함\n· d. 피부궤양(욕창 및 울혈성궤양 등) 드레싱\n- 욕창(압박성 궤양), 울혈성 궤양, 허혈성 궤양, 말초신경병증 궤양에 대한 드레싱을 시행한 경우 기재하며, 드레싱 부위를 ‘1. 발’과 ‘2. 발 이외’로 구분하여 기재함\n· e. 피부궤양(욕창 및 울혈성궤양 등) 이외의 드레싱\n   - ‘I. 4. 피부의 기타문제’ 중 개방성 피부병변, 발의 감염에 대한 드레싱을 시행한 경우 기재하며, 드레싱 부위를 ‘1. 발’과 ‘2. 발 이외’로 구분하여 기재함\n· f. 수술창상 치료\n   - ‘I. 4. 피부의 기타문제’ 중 ‘c. 수술창상’에 대한 드레싱을 시행한 경우 기재함\n   - 장루관련 치료 및 드레싱은 포함하지 않음\n· g. 화상관련 처치\n   - 자2-1 단순처치･염증성 처치, 자-18 피부과 처치만 시행하는 경우 또는 항생제 진통제 투여, 연고 도포 등 약제만 투여하는 경우는 해당하지 않음','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 325쪽',325,10,39);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0040','PDF_PVAL','PDF_PVAL_10','PDF','ITEM','J. 1. 인슐린 주사제 투여 일수','J. 1. 인슐린 주사제 투여 일수','인슐린 주사제 투여 일수 ','J. 1. 인슐린 주사제 투여 일수*\n▸ 유의사항\n· 지난 7일(관찰기간) 동안 정맥주사, 피하주사 등으로 인슐린 주사제가 투여된 해당란에 체크함\n· 펜형 인슐린 주사기의 경우 의사의 처방에 의해 혈당검사 결과에 따라 인슐린 주사제가 투여 되는 경우 기재 가능함\nJ. 2. 망상, 환각, 초조･공격성, 탈억제, 케어에 대한 저항, 배회에 대한 약물 치료 여부*\n▸ 유의사항\n· 망상, 환각, 초조･공격성, 탈억제, 케어에 대한 저항, 배회 중 하나 이상에 해당하는 증상으로 약물 치료를 하는 경우 “예”로 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 327쪽',327,10,40);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0041','PDF_PVAL','PDF_PVAL_10','PDF','ITEM','J. 3. 치매관련 약제 투여 여부','J. 3. 치매관련 약제 투여 여부','치매관련 약제 투여 치매 인지기능 MMSE 인지 약사 약사인력 재직일수 영양 경관영양 섭취 수분','J. 3. 치매관련 약제 투여 여부*\n▸ 유의사항\n· 약사법령에 의하여 허가 또는 신고된 사항(효능･효과 및 용법･용량 등)을 고려하여 치매상병과 관련된 약제(아리셉트 등)를 투여한 경우 기재함\n※ 참고사항\n· 국민건강보험 요양급여의 기준에 관한 규칙 [별표 1] 요양급여의 적용기준 및 방법(제5조 제1항관련)\n   3. 약제의 지급\n   가. 처방･조제\n      (1) 영양공급･안정･운동 그 밖에 요양상 주의를 함으로써 치료효과를 얻을 수 있다고 인정되는 경우에는 의약품을 처방･투여하여서는 아니되며, 이에 관하여 적절하게 설명하고 지도하여야 한다.\n      (2) 의약품은 약사법령에 의하여 허가 또는 신고된 사항(효능･효과 및 용법･용량 등)의 범위 안에서 환자의 증상 등에 따라 필요･적절하게 처방･투여하여야 한다. 다만, 안전성･유효성 등에 관한 사항이 정하여져 있는 의약품 중 진료상 반드시 필요\n      하다고 보건복지부장관이 정하여 고시하는 의약품의 경우에는 허가 또는 신고된 사항의 범위를 초과하여 처방･투여할 수 있으며, 중증환자에게 처방･투여하는 약제로서 보건복지부장관이 정하여 고시하는 약제의 경우에는 건강보험심사평가 원장이 공고한 범위 안에서 처방･투여할 수 있다.\n      (3) 요양기관은 중증환자에 대한 약제의 처방･투여시 해당약제 및 처방･투여의 범위가 (2)의 허용범위에는 해당하지 아니하나 해당환자의 치료를 위하여 특히 필요한 인정하는 범위 안에서 처방･투여할 수 있다.\n      (4) 제10조의2제2항에 따라 식품의약품안전처장이 긴급한 도입이 필요하다고 인정한 품목의 경우에는 식품의약품안전처장이 인정한 범위 안에서 처방･투여하여야 한다.\n      (5) 항생제･스테로이드제제 등 오남용의 폐해가 우려되는 의약품은 환자의 병력･투약력 등을 고려하여 신중하게 처방･투여하여야 한다.\n      (6) 진료상 2품목 이상의 의약품을 병용하여 처방･투여하는 경우에는 1품목의 처방･ 투여로는 치료효과를 기대하기 어렵다고 의학적으로 인정되는 경우에 한한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 327쪽',327,10,41);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0042','PDF_PVAL','PDF_PVAL_10','PDF','ITEM','J. 4. 지난 7일 동안 매일 복용한 의약품 수(제품명 기준)','J. 4. 지난 7일 동안 매일 복용한 의약품 수(제품명 기준)','지난 7일 동안 매일 복용한 의약품 제품명 기준 ','J. 4. 지난 7일 동안 매일 복용한 의약품 수(제품명 기준)\n▸ 유의사항\n· 지난 7일 동안 매일 복용한 전문･일반 의약품에 해당하는 약의 종류 수를 기재함\n· 약의 제품명을 기준으로 기재하는 것으로 성분, 용량까지 같은 경우 한 종류의 약물로 간주 하여 기재함\n· 제품명이 같은 약(약제의 성분, 용량이 동일)을 2알 복용 시 1개로 기재함\n· 약제의 성분은 같으나 제품명 또는 제형이 다른 약물을 복용 시 2개로 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 328쪽',328,10,42);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0043','PDF_PVAL','PDF_PVAL_11','PDF','ITEM','K. 1. 특수처치','K. 1. 특수처치','특수처치 영양 경관영양 섭취 수분','K. 1. 특수처치*\na. 정맥주사에 의한 투약\n주사 투여기준 범위 내에서 연속 또는 간헐적으로 3일 이상 정맥주사로 치료약제가 투여된 경우를 말함. 영양물질, 투석, 진단 혹은 수술 전 처치에 수반되는 일시적 약물만 투여된 경우는 제외함.\n▸ 유의사항\n· 항생제, 혈압강하제 등의 약제를 치료적 목적으로 정맥주사한 경우 기재함\n· 작성일을 포함하여 지난 7일(관찰기간) 동안 3일 미만으로 정맥주사를 시행한 경우이거나 투석, 진단 혹은 수술 전 처치를 위해 일시적으로 약물을 투여한 경우 기재하지 않음\n· 탈수환자에게 생리식염수에 전해질을 mix하여 투여하고 ‘정맥주사에 의한 투약’으로 적용할 수 있는 탈수의 기준은 아래 중 2가지 이상에 해당하는 경우(①, ③은 I/O sheet에 근거해야 함)에 적용함.\n   ① 하루에 섭취하는 수분량이 1500㎖ 미만인 경우\n   ② 탈수의 임상적 증상이 있음\n    예：새로 발병된 또는 악화된 혼돈(confusion), 비정상적인 임상결과(헤모글로빈, 헤마 토크리트, 칼륨, 혈액요소질소, 요비중 증가 등)\n   ③ 구토, 열, 설사 등으로 섭취한 수분량보다 수분 소실량이 많은 경우\n      (보험급여과-502호, 2008. 4. 29.)\n※ 참고사항\n· 주사 투여기준\n   - 국민건강보험 요양급여의 기준에 관한 규칙 [별표 1] 요양급여의 적용기준 및 방법(제5조 제1항관련) <개정 2019. 6. 12.>\n   3. 약제의 지급\n      나. 주사\n      (1) 주사는 경구투약을 할 수 없는 경우, 경구투약시 위장장애 등의 부작용을 일으킬 염려가 있는 경우, 경구투약으로 치료효과를 기대할 수 없는 경우 또는 응급환자 에게 신속한 치료효과를 기대할 필요가 있는 경우에 한한다.\n      (2) 동일 효능의 먹는 약과 주사제는 병용하여 처방･투여하여서는 아니된다. 다만, 경구투약만으로는 치료효과를 기대할 수 없는 불가피한 경우에 한하여 병용하여 처방･투여할 수 있다.\n      (3) 혼합주사는 치료효과를 높일 수 있다고 의학적으로 인정되는 경우에 한한다.\n      (4) 당류제제･전해질제제･복합아미노산제제･혈액대용제･혈액 및 혈액성분제제의 주사는 의학적으로 특히 필요하다고 인정되는 경우에 한한다.\nK. 1. 특수처치*\nb. 배뇨관련 루 관리\n방광루, 요루 등의 관리를 말함.\n▸ 유의사항\n· 유치도뇨관은 배뇨관련 루(stoma)에 해당하지 않으며, ‘E. 3. 환자에게 실시하는 배변조절 기구 및 프로그램*’에서 평가함\nK. 1. 특수처치*\nc. 배변관련 루 관리\n장루 등의 관리를 말함.\nK. 1. 특수처치*\nd. 영양관련 루 관리\n위루 등의 관리를 말함.\n▸ 유의사항\n· 비위관은 영양관련 루(stoma)에 해당하지 않음\nK. 1. 특수처치*\ne. 산소요법\n마스크, 캐뉼라 등 투여경로를 불문하고 작성일을 기준으로 지난 14일 중 7일 이상 산소를 투여하되, 산소포화도(SaO2 또는 SpO2)가 90% 이하인 상태에서 산소 투여를 시작한 경우를 말함. 날을 달리하여 비연속적으로 산소를 투여하는 경우에도 산소포화도 (SaO2 또는 SpO2)가 90% 이하로 재시작한 경우만 해당하고, 산소를 투여하는 하루 중에는 지속적 또는 간헐적으로 투여할 수 있음. 관찰기간은 이전 관찰기간과 중복되지 않도록 함. 관찰기간이 14일 미만인 경우에도 7일 이상 연속적으로 산소를 투여하거나 산소 투여일수의 합이 7일 이상이어야 함.\n▸ 유의사항\n· 관찰기간은 이전 관찰기관과 중복되지 않아야 함\n· 산소포화도는 산소를 투여하기 전 SaO2 또는 SpO2를 기재함\n· 산소투여일수는 관찰기간 중 산소를 투여한 일수를 기재하며 산소요법에 대한 관찰기간은 최대 14일로 산소투여일수를 14일을 초과하여 기재하지 않음\nK. 1. 특수처치*\nf. 하기도 증기흡입치료\n자4-1 하기도 증기흡입치료의 급여기준에 적합하게 시행한 경우를 말함.\n▸ 유의사항\n· 자4-1 하기도 증기흡입치료의 급여기준 외 시행하는 경우 기재하지 않음\n※ 참고사항\n· 자4-1 하기도증기흡입치료 급여기준(고시 제2017-152호, 2017.9.1.시행)\n   1. 자4-1 하기도 증기흡입치료(Nebulizer Treatment of Lower Airway)는 천식이나 만성 폐쇄성 폐질환의 급성악화기, 급성세기관지염의 호흡곤란치료에 실시함을 원칙으로 함.\n   2. 상기 1. 기준 이외에도 다음과 같은 경우에 요양급여 함.\n      -다 음-\n   가. 응급실 또는 입원진료 중인 환자\n   1) 정량식(또는 분말)흡입기를 사용할 수 없는 경우로 “기도 폐쇄에 의한 호흡곤란(PaO2\n      < 60mmHg 등)”이 있거나 “하기도 경련에 의한 천명(Wheezing)”이 확인되는 경우에는 급성기 일주일 이내 인정함.\n   2) 객담배출이 곤란하여 전신 투여(경구 또는 주사)를 실시하였음에도 불구하고 치료효과를 기대할 수 없어 직접 하기도에 국소 투여가 필요한 경우에는 급성기에 사례별로 인정함.\n   나. Pentamidine isethionate 주사제의 「요양급여의 적용기준 및 방법에 관한 세부사항」에 따라 증기흡입치료하는 경우\nK. 1. 특수처치*\ng. 흡인\n흡인(suction)으로 상기도 및 기관지내의 분비물을 배출시키는 경우에 한함. 구강내 및 비강내 흡인만 하는 경우는 제외함.\nK. 1. 특수처치*\nh. 기관절개관 관리\n기관절개관 교환 및 기관절개구와 캐뉼라의 세정 등을 시행한 경우 해당함.\n▸ 유의사항\n· 기관절개관의 교환, 캐뉼라의 세정 또는 기관절개관 주변 드레싱 등을 시행하는 경우 기재함\n· Tracheostomy tube가 제거된 경우는 해당하지 않음\nK. 1. 특수처치*\ni. 인공호흡기\n지난 7일 동안 1일 8시간 이상 지속적으로 인공호흡기를 사용한 경우를 말하며 인공 호흡기를 떼는 과정(weaning)도 포함함. 간헐적 양압/음압호흡치료(IPPB/INPB), 지속적 양압호흡치료(CPAP), 양위양압호흡치료(BIPAP) 등과 같은 호흡치료는 제외함.\nK. 1. 특수처치*\nj. 중심정맥영양\n중심정맥관을 통하여 영양물질을 공급한 경우에 해당함.\n▸ 유의사항\n· 중심정맥관을 통하여 일반적인 수액제(5% 또는 10% D/W 등)를 투여한 경우에는 말초정 맥을 통하여 수액제를 투여하여야 하나 route확보 등이 어려워 말초정맥투여를 하지 못하는 경우에 해당하므로 말초정맥영양을 실시한 것으로 보아야 하며, 중심정맥영양의 경우는 반드시 중심정맥관을 통하여 TPN요법을 실시한 경우에만 해당됨.\n      (보험급여과-502호, 2008. 4. 29.)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 329쪽',329,10,43);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0044','PDF_PVAL','PDF_PVAL_11','PDF','ITEM','K. 2. 지난 7일 동안 전문재활치료를 실시한 날 수','K. 2. 지난 7일 동안 전문재활치료를 실시한 날 수','지난 7일 동안 전문재활치료 실시한 재활 물리치료','K. 2. 지난 7일 동안 전문재활치료를 실시한 날 수* 지난 7일 동안 건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수 제3편 (별표1)\n특정항목에 해당하는 재활치료를 실시한 날 수를 기재함. 재활치료 인정기준은 건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수 제1편에 의함.\n▸ 유의사항\n· 지난 7일 동안 재활치료 실시 횟수가 아니라 실시 일수(days)를 기재함\n· 제3편 (별표1) 특정항목\n   3. 전문재활치료\n   - 제1편 제2부 제7장 이학요법료 중 제2절의 사116 운동치료와 제3절 전문재활치료료\n※ 참고사항\n· 건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수 제1편 제2부 제7장 이학요법료 중 제2절의 사116 운동치료와 제3절 전문재활치료료 구분 분류번호 분류 제2절 사116 가. 운동치료-복합운동치료 단순재활치료료 나. 운동치료-등속성운동치료 사121 가. 풀치료-보행풀치료\n      나. 풀치료-전신풀치료\n      사122 중추신경계발달재활치료\n      가. 작업치료-단순작업치료\n      사123 나. 작업치료-복합작업치료\n      다. 작업치료-특수작업치료\n      사124 일상생활동작훈련치료\n      사125 신경인성방광훈련치료\n      제3절 사126 기능적전기자극치료\n   전문재활치료료 사127 근막동통유발점 주사자극치료\n      가. 재활사회사업-개인력조사\n      사128 나. 재활사회사업-사회사업상담\n      다. 재활사회사업-가정방문\n      사129 호흡재활치료\n      사130 가. 재활기능치료-매트및이동치료\n      나. 재활기능치료-보행치료\n      사131 연하재활 기능적전기자극치료\n      서141 연하장애재활치료','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 333쪽',333,10,44);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0045','PDF_CLS','PDF_CLS_01','PDF','ITEM','요1 의료최고도 급여기준','요1 의료최고도 급여기준','요1 의료최고 급여기준 ADL 일상생활수행능력 일상생활 영양 경관영양 섭취 수분','요1 의료최고도 급여기준 일상생활수행능력이 11점 이상이면서 다음 중 하나 이상에 의료최고도 해당하는 경우에 산정함\n      -다 음-\n      가. 인공호흡기\n      나. 혼수\n      다. 중심정맥영양','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 83쪽',83,9,45);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0046','PDF_CLS','PDF_CLS_01','PDF','ITEM','요2 의료고도 급여기준','요2 의료고도 급여기준','요2 의료고 급여기준 ADL 일상생활수행능력 일상생활','요2 의료고도 급여기준 다음 중 하나 이상에 해당하는 경우에 산정함\n의료고도\n      -다 음-\n      가. 뇌성마비, 척수손상에 의한 마비, 사지마비, 편마비, 파킨슨병, 신경성 희귀난치성질환, 후천성면역결핍증, 다발경화증을 가진 환자가 일상생활수행능력이 18점 이상인 경우 ：위 “가”의 ‘신경성 희귀난치성질환’이란 중증근무력증 및 기타 근신경장애(G70), 근육의 원발성 장애(G71), 헌팅톤병(G10), 유전성 운동실조(G11), 척수성 근위축 및 관련 증후군(G12), 달리 분류된 질환에서의 일차적 으로 중추신경계통에 영향을 주는 계통성 위축(G13), 진행성 핵상안근마비[스틸-리차드슨-올스제위스키]\n      (G23.1), 중추신경계통의 비정형바이러스감염(A81), 아급성 괴사성 뇌병증[리이](G31.81)을 말함\n      나. 3단계 이상의 욕창(울혈성･허혈성 궤양 등 포함)으로 2가지 이상의 피부궤양 치료를 받고 있는 경우 ：위 “나”의 ‘피부궤양 치료’는 압력을 줄여주는 도구 사용, 체위변경, 피부문제를 해결하기 위한 영양공급, 피부궤양 드레싱을 의미함\n      다. 발열(탈수･구토･체중감소 중 하나 이상을 동반한 경우에 한함)이 최소 3일 이상 있고, 발열 원인을 찾는 검사와 처치를 받고 있는 경우\n라. 2도 이상 화상으로 처치를 받고 있는 경우\n      마. 매일 있는 격렬하거나 참을 수 없는 통증으로 통증관련 치료를 받고 있는 경우 ：위 “마”의 ‘격렬하거나 참을 수 없는 통증’은 VAS (Visual Analogue Scale) 또는 NRS(Numeric Rating Scale) 10점 중 7점 이상이거나 FPS(Faces Pain Scale) 5단계 중 4단계 이상인 경우에 해당함\n      바. 7일 이상의 지속적 경관영양\n      ：위 “바”의 ‘경관영양’은 경관영양을 하고 있으면서 경관 또는 말초정맥을 통해 섭취하는 칼로리가 총 섭취 칼로리의 51% 이상인 경우 또는 경관 영양을 하고 있으면서 경관 또는 말초정맥을 통해 섭취하는 칼로리가 총 섭취 칼로리의 26-50%이면서 1일 섭취 수분양이 501ml 이상인 경우에 해당함\n      사. 기관절개관 관리를 매일 받고 있는 경우\n      아. 당뇨환자가 합병증으로 발의 감염이 있어 주기적으로 드레싱을 받고 있는 경우(일상생활수행능력 4~8점인 경우는 제외)\n      자. 산소포화도(SaO2 또는 SpO2)가 90% 이하인 상태에서 산소 투여를 시작하여 7일 이상 산소를 투여 받고 있는 경우\n      차. 일상생활수행능력이 10점 이하이면서 의료최고도 조건에 해당하는 경우','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 83쪽',83,9,46);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0047','PDF_CLS','PDF_CLS_01','PDF','ITEM','요3 의료고도 급여기준','요3 의료고도 급여기준','요3 의료고 급여기준 배뇨 실금 배뇨일지 도뇨 소변 ADL 일상생활수행능력 일상생활 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 9인이상 병실 감산','요3 일상생활수행능력 요양병원 환자군 중 의료중도에서 산정하는 일상생활수행 의료중도 향상 활동 인정기준 능력 향상 활동은 다음과 같이 실시하고 진료기록부 등에 기록한 경우 1일당 1회 요양급여를 인정함\n      -다 음-\n      가. 일상생활수행능력 향상 활동은 환자가 기저귀를 하지 않고 하루 일정시간 보조를 받아 보행이나 탈기저귀 훈련 등의 활동을 시행하는 경우에 산정함\n※ 탈기저귀 훈련：기저귀 사용을 줄이고 배뇨조절을 위해 규칙적인 화장실 이용 및 보행을 독려하는 활동을 말함\n      나. 대상\n      일상생활 활동 시(화장실 이동, 병실 밖 이동 등)\n      스스로 보행이 어려워 보조인력의 도움이 필요한 환자 (ADL 9점 이상)\n      ※ ADL 측정항목：식사하기, 체위변경하기, 옮겨앉기, 화장실 사용하기\n      다. 실시인력 및 실시횟수 등\n      판단･감독하에\n      (1) 실시인력：의사의 당해 기관의 간호 인력 및 기타 보조인력 등 1명 이상\n      (2) 실시횟수：1일 4회 이상\n      (3) 소요시간：1회당 최소 15분 이상 의료중도 급여기준 다음 중 하나 이상에 해당하는 경우에 산정함\n      -다 음-\n      가. 뇌성마비, 척수손상에 의한 마비, 사지마비, 편마비, 파킨슨병, 신경성 희귀난치성질환, 후천성면역결핍증, 다발경화증을 가진 환자가 일상생활수행능력이 11-17 점인 경우 ：위 “가”의 ‘신경성 희귀난치성질환’이란 중증근무력증 및 기타 근신경장애(G70), 근육의 원발성 장애(G71), 헌팅톤병(G10), 유전성 운동실조(G11), 척수성 근위축 및 관련 증후군(G12), 달리 분류된 질환에서의 일차적 으로 중추신경계통에 영향을 주는 계통성 위축(G13), 진행성 핵상안근마비[스틸-리차드슨-올스제위스키]\n      (G23.1), 중추신경계통의 비정형바이러스감염(A81), 아급성 괴사성 뇌병증[리이](G31.81)을 말함\n나. 2단계 욕창(울혈성･허혈성 궤양 등 포함)으로 2가지 이상의 피부궤양 치료를 받고 있는 경우 ：위 “나”의 ‘피부궤양 치료’는 압력을 줄여주는 도구 사용, 체위변경, 피부문제를 해결하기 위한 영양공급, 피부궤양 드레싱을 의미함\n      다. 당뇨병을 진단받은 환자 중 매일 3회 이상 혈당검사를 시행하고, 매일 2회 이상 인슐린 주사제를 투여 받고 있는 경우\n      라. 매일 있는 중등도의 통증으로 통증관련 치료를 받고 있거나 암성통증으로 통증관련 치료(마약성 진통제 등)를 받고 있는 경우 ：위 “라”의 ‘중등도의 통증’은 VAS(Visual Analogue Scale) 또는 NRS(Numeric Rating Scale) 10점 중 4점 이상이거나 FPS(Faces Pain Scale) 5단계 중 3단계 이상인 경우에 해당함\n      마. 연속 또는 간헐적으로 3일 이상 정맥주사로 치료약제 (항생제, 혈압강하제 등)를 투여 받고 있는 경우\n      바. 하기도 증기흡입치료\n      사. 수술창상 치료 및 이에 준하는 치료를 받고 있는 경우\n      아. 3개월 이내 루(위루, 요루, 장루) 수술로 루 관리를 받고 있는 경우이거나, 출혈이나 감염 등의 문제로 지속적인 루 관리를 받고 있는 경우\n      자. 배뇨장애로 일정하게 짜여진 배뇨계획, 방광훈련 프로 그램, 규칙적 도뇨 중 하나 이상의 배뇨훈련을 받고 있으면서 7일 이상 배뇨일지가 작성된 경우\n      차. 치매진단을 받은 환자가 망상, 환각, 초조･공격성, 탈억제, 케어에 대한 저항, 배회 중 하나 이상의 증상을 1주에 2일 이상 또는 4주에 8일 이상 보여 이에 대한 약물 치료를 받고 있는 경우','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 84쪽',84,9,47);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0048','PDF_CLS','PDF_CLS_01','PDF','ITEM','요6 의료경도 급여기준','요6 의료경도 급여기준','요6 의료경 급여기준 ADL 일상생활수행능력 일상생활 치매 인지기능 MMSE 인지 전문재활치료 재활 물리치료','요6 의료경도 급여기준 다음 중 하나 이상에 해당하는 경우에 산정함\n의료경도\n      -다 음-\n      가. 치매진단을 받은 환자가 우울･낙담, 불안, 이상 운동 증상 또는 반복적 행동, 수면･야간행동 중 하나 이상의 증상을 1주에 2일 이상 또는 4주에 8일 이상 보이며 치매관련 약제를 투여 받고 있는 경우\n      나. 요-1 의료최고도 내지 요-3 의료중도에 해당하지 않는 환자로서 루(위루, 요루, 장루) 관리를 받고 있는 경우\n      다. 일상생활수행능력이 6점 이상이면서 특정항목에 해당 하는 전문재활치료 중 적어도 한 가지 이상을 주 2일 이상 받고 있으며, 지속적으로 입원 치료가 필요한 경우','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 87쪽',87,9,48);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0049','PDF_CLS','PDF_CLS_01','PDF','ITEM','요7 선택입원군 급여기준','요7 선택입원군 급여기준','요7 선택입원군 급여기준 ADL 일상생활수행능력 일상생활 환자평가표 평가표 작성','요7 선택입원군 급여기준 국민건강보험법 시행령 제19조제1항 [별표2]의 1.가.2)의 선택입원군 규정을 적용 받는 경우로서, 일정기간 입원치료가 필요하나\n      「건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수」\n      제3편 제2부 요-1 의료최고도, 요-2 의료고도, 요-3 의료 중도, 요-6 의료경도에 해당하지 않는 환자에게 산정함\n비고 1. 위 ‘일상생활수행능력’은 환자평가표[별지 제25호 서식]의 일상생활수행능력(Activities of Daily Living, ADL)에 따라 산정함\n    2. ADL 점수계산：환자평가표의 ADL 측정항목 중 4항목(식사하기, 체위변경하기, 옮겨앉기, 화장실 사용하기)의 점수를 모두 합하여 산정함\n환자평가표 A. 일반사항의 입원일* 이번 입원의 최초 입원일을 기재함.\n      A. 일반사항의 1. 최초 입원 월인 경우 입원일을 기재함.\n      요양개시일 2. 계속 입원으로 월초에 작성된 경우 해당 월의 1일을 기재함.\n      3. 특정기간 종료 후인 경우 특정기간 종료 다음 날짜(또는 정액수가 적용개시일)를 기재함.\nA. 일반사항의 이번 평가가 최초 입원평가인지 계속 입원중인 환자 평가 평가구분 인지를 기재함.\n      1. 입원평가：입원하여 제 1~10일 사이에 작성된 경우\n      2. 계속 입원중인 환자평가：입원평가가 아닌 경우\n      3. 이전 환자평가표를 적용하는 경우：전월 환자평가표 작성일로부터 전월 마지막 날까지의 잔여일수가 7일 이하로 당월의 평가를 생략한 경우 또는 당월에 적용할 환자평가표가 없어 최근 3개월 이내의 환자평가표 중 가장 최근 평가표를 적용하는 경우\n      A. 일반사항의 작성일 환자평가표 작성일(관찰기간의 마지막날)을 기재함.\n      A. 일반사항의 혈압* 관찰기간 동안 측정한 혈압 중 가장 최근 기록을 기재함.\n      B. 의식상태의 혼수* 진료기록부에 담당의사가 ‘혼수’, ‘반혼수’ 또는 ‘지속적인 식물인간 상태’ 등에 대한 의식상태를 기록한 경우 해당함.\n      B. 의식상태의 섬망* 진료기록부에 담당의사가 ‘섬망’에 대한 의식상태를 기록한 경우 해당함.\n      C. 인지기능의 단기 알고 있거나 배운 것을 5분 후에도 동일하게 기억하는지 기억력 여부를 측정하여 기재하는 것으로 평가기준은 다음과 같음.\n      -다 음-\n      0. 정상：세 낱말 모두를 기억하는 경우\n      1. 이상 있음：두 낱말 이하를 기억하는 경우\n      2. 확인 불가：혼수는 아니지만 단기기억력을 평가할 수 없는 경우\n      C. 인지기능의 일상 일상적인 생활(언제 식사해야 하는지, 휠체어의 용도를 생활사에 관한 알고 필요시 이용할 줄 아는지, 요의 또는 변의를 느낄 때 의사결정을 할 수 화장실을 가려하는지, 도움이 필요한 경우 보조인력 등 있는 인식기술 다른 사람에게 도움을 요청할 수 있는지 등)과 관련하여 스스로 의사결정이 가능한 정도를 측정하여 기재하는 것\n      으로 평가기준은 다음과 같음.\n-다 음-\n      1. 새로운 상황(평소와 다른 상황을 의미)에서만 의사 결정의 어려움이 있는 경우\n      2. 인식기술이 다소 손상됨：의사결정 능력이 부족하여 지도나 감독을 요하는 경우\n      3. 인식기술이 심하게 손상됨：거의 또는 전혀 의사결정을 하지 못하는 경우 또는 어떤 방법으로도 의사표현이 안 되는 경우\n    C. 인지기능의 이해 말이나 글 등으로 의사소통을 할 때 자신의 의견이나 요구 시키는 능력 사항을 표현할 수 있는 정도를 측정하여 기재하는 것으로 평가기준은 다음과 같음.\n      -다 음-\n      1. 대부분 이해시킴：단어를 찾거나 생각을 마무리하는데 어려움이 있는 경우\n      2. 가끔 이해시킴：구체적인 요청을 하는 데 제한이 있는 경우\n    C. 인지기능의 행동 행동심리증상의 경감을 위한 약제를 복용중인 경우에는 심리증상의 빈도* 그 상태에서 동일 기준으로 평가함.\n      지난 7일 간의 상태를 기준으로 평가하되, 지난 4주간의 상태를 종합적으로 관찰하여 평가하는 것도 가능함. 관찰 기간은 이전 관찰기간과 중복되지 않도록 함. 평가기준은 다음과 같음.\n      -다 음-\n      0. 없음：지난 7일(4주) 동안 행동심리증상이 전혀 나타 나지 않은 경우\n      1. 가끔：지난 7일(4주) 동안 1일(1~7일) 정도 행동심리 증상이 나타난 경우\n2. 자주：지난 7일(4주) 동안 2일(8일) 이상 나타나나, 매일은 아닌 경우\n      3. 매우자주：지난 7일(4주) 동안 매일 하루에 한 번 이상 행동심리증상이 나타난 경우\n      ※ 행동심리증상의 정의\n      a. 망상은 사실이 아닌 것을 사실이라고 믿거나, 남들이 자기를 해치려 하거나 무엇을 훔쳐갔다고 주장하는 것을 의미함.\n      b. 환각은 헛것을 보거나 듣는 등 현재에 없는 것을 실제로 보거나 듣거나 경험하는 것을 의미함.\n      c. 초조 또는 공격성은 소리를 지르거나 욕을 하거나, 다른 사람을 때리거나 밀치는 것, 안절부절 못하는 행동 등을 보이는 것을 의미함.\n      d. 우울 또는 낙담은 슬퍼 보이거나 우울해 보이는 것, 환자 스스로 슬프거나 우울하다고 말하는 것을 의미함.\n      e. 불안은 특별한 이유 없이 신경이 매우 예민해 보이거나, 걱정하거나 무서워하는 것을 의미함.\n      f. 들뜬 기분 또는 다행감은 특별한 이유 없이 비정상적 으로 기분 좋아하거나 재미있어하는 것을 의미함.\n      g. 무감동 또는 무관심은 주변에 관심과 흥미를 잃거나, 새로운 일을 시작하려는 의욕이 감소하는 것을 의미함.\n      h. 탈억제는 충동적 행동, 사회적으로 부적당한 행동 등을 보이는 것을 의미함.\n      I. 과민 또는 불안정은 평소에 비해 비정상적으로 화를 내거나 성급해졌거나 감정이 급격하게 변하는 것을 의미함.\n      j. 이상 운동증상 또는 반복적 행동은 반복적으로 왔다\n      갔다 하거나 같은 일을 계속해서 반복하는 것을 의미함.\n      k. 수면 또는 야간행동은 밤에 자지 않고 깨어 있거나 서성거리거나 돌아다녀 다른 사람의 수면을 방해하는 것을 의미함.\nl. 식욕 또는 식습관의 변화는 식욕, 식습관, 음식의 선호가 바뀌는 것을 의미함.\n      m.케어에 대한 저항은 복약, 주사, 일상생활수행을 위한 도움, 식사 등에 대해 거부하는 것을 의미함.\n      n. 배회는 납득할만한 목적 없이 돌아다니며, 필요사항 이나 안전에는 신경 쓰지 않는 것 같이 보이는 것을 의미함.\n    C. 인지기능의 평가표 작성일로부터 6개월 이내의 검사 결과를 의미함.\n    K-MMSE(또는\n    MMSE-K) 검사*\n    D. 신체기능의 일상 일상생활을 하는데 필요한 기본 동작들을 수행하는 능력을 생활수행능력(ADL) 종합적으로 판단하여 평가함. 일시적 변동이나 예외적 상황은 제외하고 반복적이고 통상적인 수행능력의 수준 (빈도가 높은 것)을 평가함. 일상적인 보장구 및 보조구 등의 기구를 사용(착용)하고 있는 경우는 그 상태에서 판단하며 평가기준은 다음과 같음.\n      -다 음-\n      1. 완전자립：대부분의 경우 도움이나 감독 없이 스스로 수행할 수 있음.\n      2. 감독필요：대부분의 경우 감독이나 격려가 필요함.\n      3. 약간의 도움：대부분의 경우 환자가 스스로 행위를 수행 하나 무게를 지탱하지 않는 정도의 도움이 필요함.\n      4. 상당한 도움：대부분의 경우 무게를 지탱하는 도움을 제공하거나, 해당 활동의 일부분(전체가 아님)을 다른 사람이 전적으로 수행함.\n      5. 전적인 도움：대부분의 경우 다른 사람의 전적인 도움을 받아 일상생활을 수행함.\n      6. 행위발생 안함：일주일 동안 해당 행위가 전혀 발생하지 않음.\n※ ADL 항목별 정의 및 측정 시 유의사항\n      1. 옷벗고 입기는 일상적인 옷 벗고 입는 일련의 행위를 의미함.\n      2. 세수하기는 수건 준비, 수도꼭지 돌리기, 물 받기, 얼굴 씻기, 옷이 젖는지 확인, 수건으로 닦기 등의 행위를 의미함.\n      3. 양치질하기는 칫솔에 치약 바르기, 칫솔질하기, 헹굼용 물 준비하기, 가글하기 등의 행위(틀니를 빼고, 씻고, 헹구는 등의 행위도 포함)를 의미함.\n      4. 목욕하기는 목욕이나 샤워를 할 때 비누칠하기, 헹구기 등의 행위를 의미함.\n      5. 식사하기는 투여 경로[경구, 비경구]를 불문하고 환자의 영양섭취와 관련된 일련의 동작을 의미함. 일반적인 식사의 경우 음식이 차려졌을 때 도구를 사용하여 스스로 섭취가 가능한 정도와 일반적인 식사[경관영양, 정맥영양(TPN 등)] 가 아닌 경우 그에 상응하는 식사 활동을 스스로 수행 가능한 정도를 평가함.\n      신체적 기능이 있다하더라도 치매환자 등에서 인지적인 문제로 인하여 식사하기 동작 수행이 되지 않아 다른 사람(보조인력 등)이 먹여줘야 하는 경우는 다른 사람 (보조인력 등)이 먹여준 것을 기준으로 측정함. 그러나 환자의 식욕, 기분 등으로 인해 식사하지 않으려 해서 다른 사람(보조인력 등)이 먹여주는 경우 환자의 실제 ‘식사하기’ 동작의 수행능력 정도를 측정함.\n      식사하기에서 ‘행위발생 안함’은 경구 또는 비경구 모두로 체내에 영양이 투여되지 않는 경우를 의미함.\n      그러므로 금식(NPO)을 하는 환자라도 비경구적으로 영양물질을 공급하고 있는 경우에는 ‘행위발생 안함’에 기재해서는 안 됨.\n      6. 체위변경하기는 제대로 돌아눕기, 엎드리기, 옆으로 눕기 등의 행위를 의미함.\n7. 일어나 앉기는 누운 상태에서 상반신을 일으켜 앉는 행위를 의미함.\n      8. 옮겨앉기는 「침상에서 휠체어로」, 「의자에서 휠체어로」,\n      「휠체어에서 침상으로」, 「휠체어에서 의자로」 이동하는 행위를 의미함.\n      9. 방밖으로 나오기는 환자가 자신의 방에서 복도 등으로 이동하는 행위를 말하며, 휠체어를 사용하는 경우는 일단 휠체어를 탄 상태에서 이동하는 능력을 평가함.\n      10. 화장실 사용하기는 배뇨･배변과 관련된 일련의 동작 으로 하의 벗기, 배설 후 닦기, 옷 입기, 변기에 물 내리기, 휴대용 변기 비우기, 사용한 카테터 뒤처리 등의 행위를 의미함. 화장실 또는 실내변기가 있는 곳까지 이동하는 능력은 측정대상에 포함되지 않음.\n      실내변기, 침상용 변기, 소변기를 사용하는 경우와 인공항문, 인공요루 등을 한 환자의 경우에도 그 상태 에서의 수행정도를 판단함. 화장실 사용하기에서 ‘행위발생 안함’은 어떤 형태로든 배설 행위가 전혀 일어나지 않은 경우를 의미함.\n    D. 신체기능의 와상 일주일에 적어도 4일 이상 하루 22시간 이상을 자리에 상태 여부 누워 있는 상태를 말함.\n    E. 배설기능의 일반 원인에 관계없이 발생하는 모든 실금현상의 존재 여부와 사항 그 정도를 평가함. 실금의 정도는 하루 24시간을 기준으로 기재함. 낮에는 대소변 조절이 가능하나, 밤에 예방적 차원으로 기저귀를 채우고 그 기저귀에 실금을 하였다면 이는 실금이 있는 것으로 봄.\n    E. 배설기능의 대변 환자의 배변 주기를 고려하여 판단하며 평가기준은 다음과 조절 상태* 같음.\n      -다 음-\n      0. 조절할 수 있음：전혀 실금하지 않는 경우\n1. 가끔 실금함：평균적인 배변 횟수를 고려하여 실금하는 경우보다 조절하는 경우가 더 많거나 같은 경우\n      2. 자주 실금함：평균적인 배변 횟수를 고려하여 조절하는 경우보다 실금하는 경우가 더 많은 경우\n      3. 조절 못함：배변을 보는 주기에 관계없이 배변할 때마다\n      실금하는 경우\n      E. 배설기능의 소변 환자의 소변 주기를 고려하여 판단하며 평가기준은 다음과 조절 상태* 같음.\n      -다 음-\n      0. 조절할 수 있음：전혀 실금하지 않는 경우\n      1. 가끔 실금함：실금하는 경우보다 조절하는 경우가 더 많거나 같은 경우\n      2. 자주 실금함：조절하는 경우보다 실금하는 경우가 더 많은 경우\n      E. 배설기능의 배변 a. 일정하게 짜여진 배뇨계획 조절 기구 및 (Scheduled toileting plan)\n      프로그램* 방광이 차는 것과 관계없이 \n…(이하 원문 참조)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 87쪽',87,9,49);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0050','PDF_CLS','PDF_CLS_02','PDF','ITEM','요51 간호인력 확보수준에 따른 입원료 차등제','요51 간호인력 확보수준에 따른 입원료 차등제','요51 간호인력 확보수준 입원료 차등제 간호사 간호조무사 간호등급','요­51 간호인력 확보수준에 적정수준의 간호인력을 확보하지 못한 요양병원에서 요양병원 입원료 따른 요양병원 입원료 간호서비스의 일부를 보호자나 간병인에게 위임하는 등 차등적용 관련 기준 입원 진료시 간호서비스의 질이 저하되는 바람직하지 않은 현상을 해소하기 위해서 시행하고 있는 [간호인력 확보수준에 따른 요양병원 입원료 차등제] 관련 기준은 다음과 같이 함.\n      -다 음-\n      가. 환자 산정기준\n      간호인력 확보수준에 따른 입원료 차등제의 기준이 병원 입원료 차등제 산정현황 통보서상의 입원 환자 수로 「건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수」 제3편 제3부[산정지침] 4.바(3)을 말함.\n      나. 간호인력 산정기준\n      1) 간호인력은 입원환자 간호업무를 전담하는 간호사와 이에 대한 간호업무를 보조하는 간호조무사를 의미함.\n      2) (입원)병동에 근무하지만 입원환자 간호를 전담하지 않는 간호인력(간호감독, 전임노조, 가정간호사, 호스 피스 간호사 등), 일반병상과 특수병상을 순환 또는 파견(PRN 포함) 근무하는 간호인력, 특수병상 중 중환자실, 격리실, 인공신장실, 물리치료실에서 근무 하는 간호인력, 외래 근무자는 산정대상에서 제외 하며, 연속적 부재기간이 16일 이상인 경우에는 동 기간 동안 간호인력 산정대상에서 제외함.\n      3) 계약직 및 단시간 근무 간호인력은 「기간제 및 단시간근로자 보호 등에 관한 법률」 제17조(근로 조건의 서면명시)를 준수하고, 계약직의 경우에는 3개월 이상 고용계약을 체결한 경우에 산정함.\n4) 단시간 근무 간호사로 1주간의 근로시간이 휴게 시간을 제외하고 월평균 40시간 미만인 근무자에 대하여 16(이상)~20시간(미만) 근무자의 경우 0.4인, 20(이상)~24시간(미만) 근무자는 0.5인, 24(이상)~ 28시간(미만) 근무자는 0.6인, 28(이상)~32시간(미만)\n      근무자는 0.7인, 32(이상)~36시간(미만) 근무자는 0.8인, 36(이상)~40시간(미만) 근무자는 0.9인으로 산정하며, 「소득세법」 시행규칙 제7조 제4호에 의한 의료취약지역 소재 요양기관은 각각 0.5인, 0.6인, 0.7인, 0.8인, 0.9인, 1인으로 산정함. 다만, 계약직 간호사를 고용하는 경우, 정규직 간호사 의무고용 비율은 100분의 80으로 함.\n      5) 전일제 근무 간호인력으로 1주간의 근로시간이 휴게 시간을 제외하고 월평균 40시간 이상인 근무자는 1인으로 산정함. 다만, 계약직 간호조무사는 전일 제인 경우에만 3인을 2인으로 산정함.\n      6) 출산휴가자를 대체하는 간호사는 1주간의 근로 시간이 휴게시간을 제외하고 월평균 40시간 이상인 근무자의 경우 1인으로 산정함.\n      다. 간호인력 확보수준에 따른 등급산정 및 신청방법\n      1) 환자수는 전전분기 마지막 월 15일부터 전분기 마지막 월 14일까지 환자수 평균으로, 간호인력수는 전전분기 마지막 월 15일부터 전분기 마지막 월 14일까지 재직 일수 평균으로 산정하되, 평균 환자수와 평균 간호인력 수는 각각 소수점 셋째자리에서 반올림하여 계산함.\n      2) 요양기관은 [별지 제6호 서식]에 의한 요양병원 입원료 매분기말 16일부터 20일까지 제출하여야 하며, 미제출 기관은 6등급으로 산정함. 다만, 제출기간을 도과하더 라도 적용분기 전일까지 부득이한 사유를 소명하여 제출하는 경우에 한하여 확인된 간호등급을 적용하며, 통보서 내용 중 간호인력 현황에 변경사항 발생 시는 즉시 제출하여야 함.\n      (고시 제2019-183호, ’20.1.1. 시행)\n    의사인력 확보수준에 적정수준의 의사인력을 확보하지 못한 요양병원에서 입원 따른 요양병원 입원료 환자에 대한 의료서비스의 질이 저하되는 현상을 방지하기 차등적용 관련 기준 위하여 시행하는 [의사인력 확보수준에 따른 요양병원 입원료 차등제] 관련 기준은 다음과 같이 함.\n      -다 음-\n      가. 환자 산정기준\n      의사인력 확보수준에 따른 입원료 차등제의 기준이 병원 입원료 차등제 산정현황 통보서상의 입원환자 수로 「건강보험 행위 급여·비급여 목록표 및 급여 상대가치점수」 제3편제3부[산정지침] 4.마.(3)을 말함.\n      나. 의사인력 산정기준\n      1) 의사는 요양병원 입원료 차등제 산정현황 통보서 상의 상근자를 의미하며, 연속적 부재기간이 16일 이상인 경우에는 동 기간 동안 의사인력 산정대상에서 제외함.\n      2) 시간제 또는 격일제 의사는 주3일 이상이면서 주 20시간 이상인 경우 0.5인으로 인정하며, 기간제 의사는 근무시간 등 근무조건이 정규직 근무자와 동일하면서 3개월 이상 고용계약을 체결한 경우는 1인으로 인정함.\n      다. 의사인력 확보수준에 따른 등급산정 및 신청방법\n      1) 환자수는 전전분기 마지막 월 15일부터 전분기 마지막 월 14일까지 환자수 평균으로, 의사수는 전전분기 마지막 월 15일부터 전분기 마지막 월 14일까지 재직일수 평균으로 산정하되, 평균 환자 수와 평균 의사수는 각각 소수점 셋째자리에서 반 올림하여 계산함.\n      2) 요양기관은 [별지 제6호 서식]에 의한 요양병원 입원료 차등제 산정현황 통보서를 건강보험심사 평가원에 매분기말 16일부터 20일까지 제출하여야 하며, 미제출 기관은 4등급으로 산정함. 다만, 제출 기간을 도과하더라도 적용분기 전일까지 부득이한 사유를 소명하여 제출하는 경우에 한하여 확인된 의사등급을 적용하며, 통보서 내용 중 의사인력 현황에 변경사항 발생 시는 즉시 제출하여야 함.\n      (고시 제2019-302호, ’21.1.1. 시행)\n      필요인력 확보에 따른 요양병원의 입원환자에게 질 높은 의료서비스를 제공 별도 보상제 관련 기준 토록 하기 위해 시행하는 [필요인력 확보에 따른 별도 보상제] 관련 기준은 다음과 같이 함.\n      -다 음-\n      가. 환자 산정기준\n      산정현황 통보서상의 입원환자수를 말함.\n      나. 약사 산정기준\n      환자수가 200명 이상인 경우 요양병원 입원료 차등제 산정현황 통보서상의 상근자를 의미하며, 연속적 부재 기간이 16일 이상인 경우에는 동 기간 동안 산정대상 에서 제외함.\n      다. 의무기록사, 방사선사, 임상병리사, 물리치료사, 사회 복지사 산정기준 산정현황 통보서상의 상근자를 의미하며, 연속적 부재 기간이 16일 이상인 경우에는 동 기간 동안 산정대상 에서 제외함.\n      라. 필요인력 산정 및 신청방법\n      1) 환자수는 전전분기 마지막 월 15일부터 전분기 마지막 월 14일까지 환자수 평균으로 산정하되, 소수점 셋째자리에서 반올림하여 계산하며, 약사 및 의무기록사, 방사선사, 임상병리사, 물리치료사, 사회 복지사는 전전분기 마지막 월 15일부터 전분기 마지막 월 14일까지 재직일수로 산정함.\n      2) 요양기관은 [별지 제6호 서식]에 의한 요양병원 입원료 차등제 산정현황 통보서를 건강보험심사 평가원에 매분기말 16일부터 20일까지 제출하여야 하며, 미제출 기관은 별도 산정할 수 없음. 다만, 제출기간을 도과하더라도 적용분기 전일까지 부득 이한 사유를 소명하여 제출하는 경우에 한하여 확인된 필요인력 현황을 적용함. 통보서 내용 중 필요인력 현황에 변경사항 발생 시는 즉시 제출 하여야 함.\n      (고시 제2019-302호, ’21.1.1. 시행)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 101쪽',101,9,50);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0051','PDF_CLS','PDF_CLS_02','PDF','ITEM','요54 요양병원 격리실 입원료','요54 요양병원 격리실 입원료','요54 요양병원 격리실 입원료 격리','요54 요양병원 격리실 요양병원 격리실 입원료는 전파경로별 격리지침을 준수 격리실 입원료 입원료 급여기준 하여야 하며 의료법 시행규칙 제34조 [별표 4] 제1호 사목을 준수한 경우(병상이 300개 미만 요양병원 포함)\n      다음과 같이 요양급여함\n      –다 음–\n      가. 급여대상\n      의료법 시행규칙 제36조제2항에 의한 「감염병의 예방 및 관리에 관한 법률」 제41조제1항에 따라 제1급감염병 및 질병관리청장이 고시한 감염병에 걸린 같은 법 제2조제13호부터 제15호까지에 따른 감염병환자, 감염병의사환자 또는 병원체보유자(이하 “감염병환자등”이라 한다) 및 같은 법 제42조제1항 각 호의 어느 하나에 해당하는 감염병환자등이 아닌 경우\n      나. 인정기준\n      상기 가.의 경우 「요양급여의 적용기준 및 방법에 관한 세부사항」 Ⅰ. 행위 제1장 기본진료료 가10 격리실 입원료에 의함\n      (고시 제2021-135호, ’21.5.4. 시행)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 105쪽',105,9,51);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0052','PDF_CLS','PDF_CLS_02','PDF','ITEM','요55 요양병원 입원환자 안전관리료','요55 요양병원 입원환자 안전관리료','요55 요양병원 입원환자 안전관리료 환자안전 전담인력 인증 의료기관인증 인증조사 가산','요55 요양병원 입원환자 요양병원 입원환자 안전관리료는 다음의 요건을 모두 요양병원 입원 안전관리료 산정기준 충족하는 경우 요양급여하며, 입원환자 입원 1일당 1회 환자 안전관리료 산정함.\n      -다 음-\n      가. 대상기관\n      「환자안전법」 제11조･제12조를 준수하고 「의료법」\n      제58조･제58조의3에 따라 ‘인증’ 또는 ‘조건부인증’\n      등급을 받은 200병상 이상 요양 병원\n      나. 산정기준\n      1) 환자안전위원회는 「환자안전법」 제11조제3항 및 같은 법 시행규칙 제8조에 명시된 업무를 시행하여야 하며, 위원회 구성은 같은 법 시행규칙 제6조를 따름.\n      2) 전담인력은 「환자안전법」 제12조제3항 및 같은 법 시행규칙 제9조제5항에 따른 업무를 시행하여야 하며, 환자안전 활동에 대한 연간 계획을 수립하고 관리하여야 함.\n      3) 「환자안전법」 제9조 및 같은 법 시행령 제6조에 따른 환자안전기준 준수를 위해 아래의 가), 나)를 포함한 체계적인 활동을 시행하여야 함.\n가) 입원환자 병문안 관리 규정을 자체적으로 수립 하고 이를 시행하여야 함.\n      나) 입원기간 동안 낙상, 욕창 예방 및 관리 등을 시행 하여야 함.\n      4) 인력기준 및 병문안 관리기준은 「요양급여의 적용 기준 및 방법에 관한 세부사항」 Ⅰ. 행위 제1장 기본진료료 가29 입원환자 안전관리료의 기준을 동일하게 적용함.\n      5) 6인 이하 병실에 입원한 경우에만 산정함. (’22.1.1.\n      부터 적용)\n      (고시 제2021-135호, ’21.5.4. 시행)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 106쪽',106,9,52);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0053','PDF_CLS','PDF_CLS_02','PDF','ITEM','요56 요양병원 지역사회 연계료','요56 요양병원 지역사회 연계료','요56 요양병원 지역사회 연계료 퇴원지원 복귀','요56 요양병원 지역사회 요양병원 입원환자의 퇴원 후 원활한 지역사회 복귀를 요양병원 지역 연계료 산정기준 지원하기 위한 요양병원 지역사회 연계료의 산정기준을 사회 연계료 다음과 같이 함.\n      -다 음-\n      가. 적용대상\n      입원일로부터 120일 경과 후 퇴원이 예정되어 있고 지역연계가 필요한 환자\n      나. 산정방법\n      1) 요양병원 지역사회 연계 평가료는 환자지원팀이 환자 (또는 보호자)를 대상으로 [별지 제17호 서식]에 따라 환자지원 심층평가를 실시하고 작성한 경우 산정함.\n      상담･평가를 수 회 실시하더라도 입원기간 중 1회 산정하며, 평가완료 후 환자 상태의 급격한 변화 등 불가피한 경우 진료기록부에 이를 기록하고 입원기간 중 최대 2회까지 산정함.\n      2) 요양병원 지역사회 연계 관리료는 환자지원팀이 환자 (또는 보호자)를 대상으로 [별지 제18호 서식]에 따라 퇴원지원 표준계획을 수립･작성하고 지역사회 자원 연계 계획에 따라 연계가 이루어진 경우 산정함. 환자 지원팀이 환자(또는 보호자)와 함께 지역 행정기관 등을 방문하여 연계가 이루어진 경우 요양병원 지역사회 연계 관리료 Ⅱ를 산정하고, 이 외에는 요양병원 지역 사회 연계 관리료 Ⅰ을 산정하며 종류 및 횟수를 불문 하고 퇴원 시 1회만 산정\n      다. 기타\n      1) 환자지원팀은 요양병원 환자지원 심층평가표[별지 제17호 서식], 요양병원 퇴원지원 표준계획서[별지 제18호 서식] 및 연계내역(연계기관, 연계 서비스 등)을 요양기관정보마당으로 제출하여야 하며 관련 사항을 진료기록부에 기록･보관하여야 함.\n      2) 환자지원팀(상근하는 의사, 간호사, 사회복지사) 중 1인 이상은 요양병원 퇴원환자 지원 기본교육을 매년 이수 하여야 함. (’21.1.1.부터 적용)\n      (고시 제2019-183호, ’19.11.1. 시행)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 107쪽',107,9,53);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0054','PDF_QNA','PDF_QNA_01','PDF','QA','개정되는 요양병원 의사인력확보수준에 따른 입원료 차등제를 반영한 의사등급이 적용되는 시점은?','개정되는 요양병원 의사인력확보수준에 따른 입원료 차등제를 반영한 의사등급이 적용…','개정되 요양병원 의사인력확보수준 입원료 차등제 반영한 의사등급 적용되 시점 의사인력 의사수 적정성평가 질지원금 우수기관 향상기관','○ ’23년 7월 1일 진료분부터 적용되며, ’23년 3사분기 요양병원 입원료 차등제 적용을 위해 ’23년 3월 15일부터 6월 14일까지의 요양병원 입원료 차등제 산정현황 통보서를 ’23년 6월 16일부터 20일까지 제출하여야 함\n   요양병원 입원급여 적정성평가 결과 연계 질지원금 신설','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 198쪽',198,8,54);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0055','PDF_QNA','PDF_QNA_01','PDF','QA','“요양병원 입원급여 적정성평가 결과 연계 질 지원금”은 모든 요양병원에서 산정할 수 있는지?','“요양병원 입원급여 적정성평가 결과 연계 질 지원금”은 모든 요양병원에서 산정할…','요양병원 입원급여 적정성평 연계 지원금 모든 산정할 있는지 인증 의료기관인증 인증조사 가산 적정성평가 질지원금 우수기관 향상기관','○ 의료법 제3조제2항제3호에 의한 요양병원(단, 「장애인복지법」 제58조제1항제4호에 따른 의료재활시설은 제외) 중 요양병원 입원급여 적정성 평가 결과 우수기관(종합 점수 상위 10%이하, 상위 10%초과하고 상위 30%이하) 및 향상기관(적정성평가 결과 4등급이면서, 종합점수가 직전 평가 대비 5점 이상 향상)에서 산정할 수 있음\n   - 다만, 「의료법」 제58조･제58조의3에 따라 의료기관평가인증원에서 실시하는 의료 기관 인증결과 ‘인증’ 또는 ‘조건부인증’ 등급을 획득한 기관에 한함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 198쪽',198,8,55);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0056','PDF_QNA','PDF_QNA_01','PDF','QA','신설되는 “요양병원 입원급여 적정성 평가결과 연계 질 지원금”이 적용되는 적정성 평가의 시점은?','신설되는 “요양병원 입원급여 적정성 평가결과 연계 질 지원금”이 적용되는 적정성…','신설되 요양병원 입원급여 적정성 평가결 연계 지원금 적용되 평가 시점 적정성평가 질지원금 우수기관 향상기관','○ ’23년 7월 1일 진료분부터 적용되는 적정성 평가는 2주기 3차 평가 결과임\n- 질지원금은 ‘요양병원 입원급여 적정성 평가’ 결과 발표 익월부터 다음 차수 평가 결과 발표월까지 적용됨\n      ※ (예시) 2주기 3차 평가결과 발표 ’23. 6.\n      ･ 질지원금 산정 ’23. 7.∼다음 평가결과 발표월\n○ 평가결과 발표 직후 청구실적이 없거나 지연되는 경우에도 동일하게 평가결과 발표 익월부터 다음 차수 평가 결과 발표월 진료분 기준으로 적용되며, 관리 기간은 청구 소멸시효를 감안하여 3년으로 함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 198쪽',198,8,56);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0057','PDF_QNA','PDF_QNA_01','PDF','QA','의료기관 평가 인증의 유효기간이 만료된 경우 “요양병원 입원급여 적정성 평가결과 연계 질 지원금” 수가 산정이 가능한지?','의료기관 평가 인증의 유효기간이 만료된 경우 “요양병원 입원급여 적정성 평가결과…','의료기관 인증 유효기간 만료된 요양병원 입원급여 적정성 평가결 연계 지원금 의료기관인증 인증조사 가산 적정성평가 질지원금 우수기관 향상기관','○ 수가산정을 위한 진료일에 인증 결과가 유효한(‘인증’ 및 ‘조건부 인증’) 기관에 한하여 산정\n   - ‘인증’ 또는 ‘조건부 인증’ 유효기간 만료일 이후에는 산정불가\n   - ‘조건부 인증’을 받은 요양병원은 유효기간(1년) 만료 전 재 인증을 받아야 하며, 재인증 결과 ‘불인증’ 획득 시 조건부 인증의 유효기간 이후에는 수가 적용 불가','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 199쪽',199,8,57);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0058','PDF_QNA','PDF_QNA_01','PDF','QA','“요양병원 입원급여 적정성 평가결과 연계 질 지원금” 청구 시 명세서 진료내역의 항, 목 구분은?','“요양병원 입원급여 적정성 평가결과 연계 질 지원금” 청구 시 명세서 진료내역의…','요양병원 입원급여 적정성 평가결 연계 지원금 청구 명세서 진료내역 구분 적정성평가 질지원금 우수기관 향상기관','○ 요양병원 입원급여 적정성 평가결과 연계 질 지원금은 1항 03목으로 청구함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 199쪽',199,8,58);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0059','PDF_QNA','PDF_QNA_01','PDF','QA','“요양병원 입원급여 적정성 평가결과 연계 질 지원금” 산정횟수는?','“요양병원 입원급여 적정성 평가결과 연계 질 지원금” 산정횟수는?','요양병원 입원급여 적정성 평가결 연계 지원금 산정횟수 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 적정성평가 질지원금 우수기관 향상기관','○ 요양병원 입원급여 적정성 평가결과 연계 질지원금은 1일당* 1회 산정 * 1일당은 정액수가 및 입원료 산정기준의 1일당으로 입원료 산정 횟수와 동일하게 산정\n※ (예시) 4박 5일 입원한 경우 4회 산정','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 199쪽',199,8,59);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0060','PDF_QNA','PDF_QNA_01','PDF','QA','요양병원 입원 중 산정특례 대상 상병으로 타병원 진료 의뢰한 경우 청구방법은?','요양병원 입원 중 산정특례 대상 상병으로 타병원 진료 의뢰한 경우 청구방법은?','요양병원 입원 산정특례 대상 상병 타병원 진료 의뢰한 청구방법 적정성평가 질지원금 우수기관 향상기관','○ “요양병원 입원급여 적정성 평가결과 연계 질지원금” 산정 대상 요양병원이더라도, 산정특례 대상 상병*으로 타병원 진료의뢰 당일에는 수가 산정 불가 * (보건복지부 고시 제2019-302호) 「본인일부부담금 산정특례에 관한 기준」 [별표3], [별표4]\n      및 [별표4의2]에 따른 산정특례 대상 상병','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 200쪽',200,8,60);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0061','PDF_QNA','PDF_QNA_01','PDF','QA','“요양병원 입원급여 적정성 평가결과 연계 질 지원금”과 전문병원(병원･요양병원･ 한방병원) 의료질평가지원금과 동시산정 가능한지?','“요양병원 입원급여 적정성 평가결과 연계 질 지원금”과 전문병원(병원･요양병원･…','요양병원 입원급여 적정성 평가결 연계 지원금 전문병원 병원 한방병원 의료질평가지원금 동시산정 적정성평가 질지원금 우수기관 향상기관','○ 동시산정 가능함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 200쪽',200,8,61);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0062','PDF_QNA','PDF_QNA_01','PDF','QA','요양병원이 우수기관 및 향상기관 기준 모두 해당되는 경우는?','요양병원이 우수기관 및 향상기관 기준 모두 해당되는 경우는?','요양병원 우수기관 향상기관 기준 해당되 ','○ 우수기관 및 향상기관 기준이 모두 해당되는 경우 높은 보상률 1개만 적용','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 200쪽',200,8,62);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0063','PDF_QNA','PDF_QNA_01','PDF','QA','요양병원 입원급여 적정성 평가 이후 설립구분을 변경하거나 공동대표자 중 주개설자가 변경된 경우 평가결과를 연계하여 수가 산정이 가능한지?','요양병원 입원급여 적정성 평가 이후 설립구분을 변경하거나 공동대표자 중 주개설자…','요양병원 입원급여 적정성 이후 설립구분 변경하거나 공동대표자 주개설자 변경된 평가결과 연계하여 적정성평가 질지원금 우수기관 향상기관','○ 요양기관의 설립구분만 변경되었을 뿐 변경 전･후가 실질적으로 동일(시설, 인력, 운영 등)하다면 평가결과 연계하여 수가 산정이 가능함\n      요양병원 입원급여 적정성 평가 이후, 양도･양수가 이루어진 경우 양도한','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 200쪽',200,8,63);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0064','PDF_QNA','PDF_QNA_01','PDF','QA','요양병원의 평가 결과를 양수받은 대표자의 요양병원에 연계하여 수가 산정이 가능한지?','요양병원의 평가 결과를 양수받은 대표자의 요양병원에 연계하여 수가 산정이 가능한지?','요양병원 결과 양수받 대표자 연계하여 ','○ 타 요양병원을 양도･양수받아 재개설한 경우 기관의 대표자의 변경이 있었을 뿐 신규로 개설한 기관이 아니므로 양수받은 요양병원이 평가대상 요양병원이고, 대표자 변경 전･후가 실질적으로 동일(시설, 인력, 운영 등)하다면 평가결과 연계','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 200쪽',200,8,64);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0065','PDF_QNA','PDF_QNA_01','PDF','QA','“요양병원 입원급여 적정성 평가결과 연계 질 지원금”의 대상 기관임을 확인하는 방법은?','“요양병원 입원급여 적정성 평가결과 연계 질 지원금”의 대상 기관임을 확인하는 …','요양병원 입원급여 적정성 평가결 연계 지원금 대상 기관임 확인하 인증 의료기관인증 인증조사 가산 적정성평가 질지원금 우수기관 향상기관','○ E-평가자료제출시스템을 통해 적정성 평가 결과 우수기관 및 향상기관을 확인할 수 있음\n   - 다만, 의료기관평가인증원에서 실시하는 의료기관 인증결과 ‘인증’ 또는 ‘조건부인증’\n    등급 유효기간 내 산정 가능\n   요양병원 입원급여 적정성 평가 환류 개정\n    변경되는 요양병원 입원급여 적정성 평가결과 환류 기준이 적용되는 적정성 평가의 시점은?\n○ ’23년 7월 1일 진료분부터 적용되는 적정성 평가는 2주기 3차 평가 결과임\n   - 환류는 ‘요양병원 입원급여 적정성 평가’의 결과 발표 직후 2분기 동안 적용됨\n    ※ (예시) 2주기 3차 평가결과 발표 ’23. 6.\n      ･ 환류적용 ’23. 7.∼ 12.(3/4, 4/4분기)\n○ 평가결과 발표 직후 청구실적이 없거나 지연되는 경우에도 동일하게 결과발표 직후 2분기 진료분 기준으로 적용되며, 관리 기간은 청구소멸시효를 감안하여 3년으로 함\n    요양병원 입원급여 적정성평가결과 환류인 경우, 간호인력 확보수준에 따른','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 201쪽',201,8,65);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0066','PDF_QNA','PDF_QNA_01','PDF','QA','입원료 차등제의 입원료 가산 중 ‘간호사 비율이 간호인력의 3분의 2이상인 경우에 1일당 2,000원을 별도 산정’하는 규정도 환류 적용 범주에 포함되는지?','입원료 차등제의 입원료 가산 중 ‘간호사 비율이 간호인력의 3분의 2이상인 경우…','입원료 차등제 가산 간호사 비율 간호인력 3분 2이상인 1일당 000원 규정 환류 적용 범주 포함되는지 간호조무사 간호등급 적정성평가 질지원금 우수기관 향상기관','○ ‘간호사 비율이 간호인력의 3분의 2 이상인 경우에 1일당 2,000원을 별도 산정’하는 규정도 요양병원 입원급여 적정성평가결과 환류의 적용을 받는 입원료 가산의 범주에 포함됨','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 201쪽',201,8,66);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0067','PDF_QNA','PDF_QNA_02','PDF','QA','일상생활수행능력(Activities of Daily Living, ADL)에 따른 중분류가 삭제되었는데 일상생활 수행능력 평가를 해야 하는지?','일상생활수행능력(Activities of Daily Living, ADL)에 따…','일상생활수행능력 Activities of Daily Living ADL 중분류 삭제되었는데 일상생활 수행능력 평가 해야 하는지 환자평가표 평가표 작성 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 일상생활수행능력(ADL) 중분류는 삭제 되었지만, 환자군별 기준은 남아있어 환자 평가표의 ADL 평가는 해야 합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 202쪽',202,8,67);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0068','PDF_QNA','PDF_QNA_02','PDF','QA','치매진단은 상급종합병원에서만 받아야 하는지?','치매진단은 상급종합병원에서만 받아야 하는지?','치매진단 상급종합병원에서 받아야 하는지 치매 인지기능 MMSE 인지','○ 의료중도 또는 의료경도의 ‘치매진단을 받은 환자’는 치매 진단이 관련 검사결과 등을 통해 객관적으로 확인되는 경우 산정 가능합니다. 다만 해당 검사나 진단 등이 반드시 상급종합병원에서 이루어질 필요는 없습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 202쪽',202,8,68);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0069','PDF_QNA','PDF_QNA_02','PDF','QA','새로 신설된 선택입원군은 어떤 환자인지?','새로 신설된 선택입원군은 어떤 환자인지?','신설된 선택입원군 어떤 환자 치매 인지기능 MMSE 인지','○ 일정기간 입원치료가 필요하나 의료최고도, 의료고도, 의료중도, 의료경도에 해당하지 않는 환자입니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 202쪽',202,8,69);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0070','PDF_QNA','PDF_QNA_02','PDF','QA','이번 개정고시에서 정액수가에 포함되지 않는 항목 중 ‘제1편 제3부 행위 비급여 목록과 치료 재료 급여･비급여 목록 및 급여 상한금액표의 비급여 목록 중 ’19년 1월 이후 급여로 변경 고시 된 항목’은 어떻게 산정하는지?','이번 개정고시에서 정액수가에 포함되지 않는 항목 중 ‘제1편 제3부 행위 비급여…','이번 개정고시 정액수가 포함되지 항목 제1편 제3부 행위 비급여 목록 치료 재료 급여 상한금액표 19년 1월 이후 변경 고시 어떻게 산정하는지 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 특정항목으로 별도 산정합니다. 또한, ’19년 11월 1일 진료분부터는 제1편 제3부 행위 비급여 목록과 치료재료 급여･비급여 목록 및 급여 상한금액표의 비급여 목록 중 ’18년 12월 31일까지 급여로 변경 고시된 항목은 별도 산정할 수 없습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 202쪽',202,8,70);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0071','PDF_QNA','PDF_QNA_02','PDF','QA','‘수혈’을 시행한 경우에는 어떻게 산정하는지?','‘수혈’을 시행한 경우에는 어떻게 산정하는지?','수혈 시행한 경우에 어떻게 산정하는지 ','○ ‘수혈’을 시행하는 경우 건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수\n제1편 파-1 전혈, 파-2 혈액성분제제를 별도 산정합니다.\n※ 개정 전 ‘수혈’을 시행하는 경우에는 의료 고도로 산정하였으나, 개정 후 ‘수혈’을 시행하는 경우에는 혈액에 대하여 별도 산정토록 변경함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 203쪽',203,8,71);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0072','PDF_QNA','PDF_QNA_02','PDF','QA','환자평가표의 ‘건강생활습관’의 작성기준은 어떻게 되는지?','환자평가표의 ‘건강생활습관’의 작성기준은 어떻게 되는지?','환자평가표 건강생활습관 작성기준 어떻게 되는지 평가표 작성','○ 입원 평가인 경우에만 작성하는 것을 원칙 으로 합니다.\n- ‘흡연’은 작성일 기준으로 흡연하고 있는 경우에만 ‘예’로 기재함\n- ‘음주’는 입원하기 전 과거 1개월간의 음주습관을 기재하되, 술의 종류와 양에 관계없이 일주일에 3회 이상 음주하는 경우 ‘예’로 기재함\n- ‘규칙적 운동 및 식사’는 입원하기 전\n과거 1개월간의 운동 및 식사습관을 평가\n하여 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 203쪽',203,8,72);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0073','PDF_QNA','PDF_QNA_02','PDF','QA','환자평가표의 ‘장기요양등급’의 작성기준은 어떻게 되는지?','환자평가표의 ‘장기요양등급’의 작성기준은 어떻게 되는지?','환자평가표 장기요양등급 작성기준 어떻게 되는지 치매 인지기능 MMSE 인지 평가표 작성','○ 입원 평가인 경우에만 작성하는 것을 원칙 으로 합니다.\n환자평가표 A. 일반사항 중\n◈ 11번. 장기요양등급 및 신청 관련\n- ‘해당사항 없음’은 65세 미만이거나, 노인성 질환자가 아니어서 장기요양등급신청 자격이 아닌 경우 기재함\n- ‘신청하였으나 인정 못 받음’은 장기요양 등급 신청결과 ‘기각’ 또는 ‘각하’를 의미함\n- ‘등급 내 자’는 장기요양 인정조사 후\n등급을 받은 경우(1등급~5등급, 인지지원 등급)를 의미함 & ASSESSMENT SERV\n- ‘등급 외 자’는 장기요양 등급신청 하였 으나, 등급 내 자가 아닌 경우(등급 외 자 A~C)를 말함\n◈ 12번. 장기요양등급 및 이용 서비스 관련\n- ‘a. 등급’은 장기요양등급 ‘등급 내 자’에 한해서 평가하여 기재하며 환자가 기억을 잘 못할 경우 ‘확인불가’로 기재함\n- ‘b. 이용 중인 또는 이용하였던 서비스’는 장기요양등급 ‘등급 내 자’에 한해서 평가 하여 기재하며 환자가 기억을 잘 못하거나, 자신이 받는 서비스의 내용을 모를 경우, 특별현금급여, 가족요양비를 받는 경우는 ‘기타’로 기재함\n◈ 13번. 장기요양서비스 욕구의향 관련\n- 65세 이상이거나 노인성질환을 갖고 있으 면서, 등급 판정이 없는 경우에만 평가 하여 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 203쪽',203,8,73);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0074','PDF_QNA','PDF_QNA_02','PDF','QA','‘사회환경 선별조사’의 작성기준은 어떻게 되는지?','‘사회환경 선별조사’의 작성기준은 어떻게 되는지?','사회환경 선별조사 작성기준 어떻게 되는지 환자평가표 평가표 작성','○ 환자평가표 A. 일반사항 중\n◈ 14. 사회환경 선별조사 관련\n- a. 사회환경 선별조사 각 항목(b~g)에 답변 거부일 경우 ‘응답거부’ 기재함\n- b. 가족, 친지 등의 보호자 또는 유･무급 형태의 돌봄 고용인력 모두 포함하여 식사 준비 등의 수발을 해줄 수 있는 사람이 없는 경우 ‘예’로 기재함\n- d. 기차역, 공원, 차량 등에서의 노숙 또는 안정적으로 거주할 곳이 없어 찜질방, PC방 등을 떠돌며 (방랑)생활을 한 적 있는 경우 ‘예’로 기재함\n- f. 교통수단 부족은 교통수단 자체가 없거나, 혼자서는 대중교통을 이용하기 힘들어, 타인의 도움이 필요한데 도움을 받지 못하는 경우 ‘예’로 기재함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 204쪽',204,8,74);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0075','PDF_QNA','PDF_QNA_02','PDF','QA','환자평가표는 누가 작성하는지?','환자평가표는 누가 작성하는지?','환자평가표 작성하는지 간호인력 간호사 간호조무사 간호등급 평가표 작성','○ 환자평가표는 당해 환자를 담당하는 의사 및 간호사가 의무기록을 근거로 작성해야 하며, 의무기록에 비치합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 205쪽',205,8,75);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0076','PDF_QNA','PDF_QNA_02','PDF','QA','일상생활수행능력 향상 활동은 어떤 활동을 말하며 수가 산정 방법은?','일상생활수행능력 향상 활동은 어떤 활동을 말하며 수가 산정 방법은?','일상생활수행능력 향상 활동 어떤 말하며 ADL 일상생활 간호인력 간호사 간호조무사 간호등급 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 9인이상 병실 감산','소 등 보 <예시> 1. 탈기 1) 화장 2) 환자 3) 화장 하 4) 화장 후 하 보 하 5) 실시 여 기 2. 보행 1) 병실 본 2) 환자 3) 안 하 4) 환자 잔 으 인 필 5) 실시 여 기\n○ 일상생활수행능력 향상 활동은 환자의\n잔존능력을 활용하여 탈기저귀나 독립적\n보행 능력을 향상시키는 활동으로, 1일\n4회 이상 시행해야 합니다.\n※ 자발적으로 보행이 가능한 환자에게는 산정 불가하며, 보조 인력*의 도움을 받아 시행한 경우는 산정 가능함\n* 의사, 간호인력, 물리치료사, 작업치료사 중 1인 이상이 일상생활수행능력향상 활동을 한 경우를 말하며, 간병인력, 자원 봉사자, 실습인력 등은 보조인력에 해당 하지 않음\n※ 의료중도 환자군에서 의사의 판단 하에\n환자의 상태에 적합한 활동을 수행하는\n경우 산정하며, 의료중도 불인정 시 동\n수가도 불인정 함\n○ 입원료의 일당(1박) 개념으로 산정하며, 외박 수가 또는 입원료의 50%를 별도 산정하는 경우*에는 산정할 수 없습니다.\n* 0~6시 사이에 입원하거나, 18~24시 사이에 퇴원하여 입원료의 50%를 별도 산정한 경우\n○ 또한, 특정항목의 전문재활치료와는 다른 별개의 행위로 동 행위의 급여기준을 충족 했다면 산정가능합니다.\n○ 일상생활수행능력 향상 활동을 시행한\n경우에는 실시목적, 시간, 방법, 활동내역, & ASSESSMENT SER 요시간, 환자의 수행 정도(개선경과)\n을 구체적으로 진료기록부 등에 기록･\n관해야 합니다.\n저귀 활동\n실 이동을 원하는지 물어본다.\n가 배뇨욕구를 표현한다.\n실 지물을 활용하여 화장실을 안전\n게 이용하는 방법을 알려준다.\n실까지 환자의 잔존능력으로 이동한\n배뇨와 관련된 활동을 수행하고 안전\n게 침상으로 복귀하는 활동을 수행하되,\n조인력은 이 과정을 감독, 격려, 지지\n며 필요 시 도움을 준다.\n시마다 활동 내용 및 환자상태 개선\n부 등 관련 내용을 진료기록부에 자세히\n록한다.\n활동\n밖 공간으로 이동을 원하는지 물어\n다.\n가 병실 밖 이동 욕구를 표현한다.\n전바 등 주변 지물을 활용하여 안전\n게 이동하는 방법을 알려준다.\n가 원하는 병실 밖 공간까지 환자의\n존능력으로 이동한 후 안전하게 침상\n로 복귀하는 활동을 수행하되, 보조\n력은 이 과정을 감독, 격려, 지지하며\n요 시 도움을 준다.\n시마다 활동 내용 및 환자상태 개선\n부 등 관련 내용을 진료기록부에 자세히\n록한다.\n요양병원 행정해석 등','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 205쪽',205,8,76);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0077','PDF_QNA','PDF_QNA_02','PDF','QA','의료최고도의 ‘체내출혈’은 어떻게 산정해야 하는지?','의료최고도의 ‘체내출혈’은 어떻게 산정해야 하는지?','의료최고도 체내출혈 어떻게 산정해야 하는지 정액수가 환자군 분류체계 의료고도 의료중도 의료경도 선택입원군','○ 의료최고도의 ‘체내출혈’은 임상적으로 문제가 되는 체내출혈 소견이 있으면서 지혈을 위한 처치 또는 수술을 시행한 경우 폐렴, 패혈증 등과 같이 ‘특정기간’\n으로 산정합니다.\n※ 개정 전 ‘체내출혈’을 시행하는 경우에는 정액수가로 산정하였으나, 개정 후 ‘체내 출혈’을 시행하는 경우에는 특정기간으로 산정토록 변경함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 207쪽',207,8,77);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0078','PDF_QNA','PDF_QNA_02','PDF','QA','인공호흡기 사용 환자가 개인용 또는 병원용을 사용하는 경우 모두 의료최고도로 산정 가능한지요?','인공호흡기 사용 환자가 개인용 또는 병원용을 사용하는 경우 모두 의료최고도로 산…','인공호흡기 사용 환자 개인용 병원용 사용하 의료최고도 가능한지요 환자평가표 평가표 작성 전문재활치료 재활 물리치료','○ 개인용 또는 병원용을 사용하는 경우 모두 의료최고도 산정이 가능하나, 요양급여의 적용기준 및 방법에 관한 세부사항 고시의 ‘환자평가표’ 중 「K. 특수처치 및 전문 재활치료의 인공호흡기」의 세부인정사항에 따라 인공호흡기를 사용한 경우 산정합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 207쪽',207,8,78);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0079','PDF_QNA','PDF_QNA_02','PDF','QA','1일 3회 이상 혈당검사 매일 실시 여부{F,1,a,(1)} 인슐린 주사제 투여 일수(J,1)','1일 3회 이상 혈당검사 매일 실시 여부{F,1,a,(1)} 인슐린 주사제 투여…','1일 3회 혈당검사 매일 실시 인슐린 주사제 투여 일수 HbA1c 당화혈색소 당뇨','○ 입원 중인 요양병원의 의료자원(인력･치료 재료･장비)으로 의료서비스(혈당검사 및 인슐린주사 투여)가 제공되는 경우 체크 ( 합니다.\n○ 다만, 연속혈당측정검사 등 비급여 진료 비용의 일부 또는 전부를 별도 징수하는 경우 또는 목표혈당을 설정하여 인슐린을 자동 점적 주입하는 경우 등은 체크할 수 없습니다.\n○ 또한, 타 의료기관으로 의뢰하여 혈당 및 인슐린 용량 등을 조절하는 경우는 당뇨병 관리를 위해 요양병원에 입원하였다고 보기 어려우므로 산정할 수 없습니다. & ASSESSMENT SERV','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 207쪽',207,8,79);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0080','PDF_QNA','PDF_QNA_02','PDF','QA','암성통증의 경우 어떻게 산정해야 하는지?','암성통증의 경우 어떻게 산정해야 하는지?','암성통증 어떻게 산정해야 하는지 ','○ 암성통증이라도 격렬하거나 참을 수 없는 통증이 매일 있어 통증치료를 받고 있는 경우에는 의료고도로, 그 외 암성통증이 있어 마약성 진통제 등으로 적절한 치료를 받고 있는 경우에는 의료중도로 산정 합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 208쪽',208,8,80);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0081','PDF_QNA','PDF_QNA_02','PDF','QA','의료중도의 ‘네블라이저 요법’은 어떻게 변경되었는지?','의료중도의 ‘네블라이저 요법’은 어떻게 변경되었는지?','의료중도 네블라이저 요법 어떻게 변경되었는지 ','○ 의료중도에서 ‘네블라이저 요법’은 삭제 되었습니다. 다만, ‘하기도 증기흡입치료’가 의료중도에 신설되어 「건강보험 행위 급여･ 비급여 목록표 및 급여 상대가치점수」\n제1편 자4-1 하기도 증기흡입치료의 급여 기준에 따라 적정하게 시행되는 경우 의료 중도로 산정할 수 있습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 208쪽',208,8,81);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0082','PDF_QNA','PDF_QNA_02','PDF','QA','당뇨환자가 합병증으로 발의 궤양이 발생하여 치료받는 경우 어떻게 산정하는지?','당뇨환자가 합병증으로 발의 궤양이 발생하여 치료받는 경우 어떻게 산정하는지?','당뇨환자 합병증 궤양 발생하여 치료받 어떻게 산정하는지 욕창 피부궤양 압창 드레싱 환자평가표 평가표 작성 영양 경관영양 섭취 수분 HbA1c 당화혈색소 당뇨','○ 당뇨병성 궤양이 있는 경우에는 궤양의 보험 상태(단계)와 치료에 따라 의료고도와 의료 급여과- 중도로 나누어 산정합니다. 3929호\n○ 환자평가표의 ‘피부궤양’에서 ‘울혈성 또는 허혈성 궤양 등’ 항목에 발 궤양의 단계별 수를 기재하고 피부문제에 대한 처치항목 중 압력을 줄여주는 도구 사용, 체위변경, 피부문제를 해결하기 위한 영양공급, 피부 궤양 드레싱 중 2가지 이상에 해당하는 경우 의료중도로 산정합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 208쪽',208,8,82);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0083','PDF_QNA','PDF_QNA_02','PDF','QA','타 요양기관에서 루 관련 진료를 받은 경우는 어떻게 하는지?','타 요양기관에서 루 관련 진료를 받은 경우는 어떻게 하는지?','요양기관 진료 어떻게 하는지 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 의료중도 및 의료경도의 ‘루 관리를 받고 보험 있는 경우’란 당해 요양기관에서 루 관리를 급여과- 받는 경우를 말합니다. 3929호\n○ 다만, 요양병원 환자군 급여목록･상대가치 점수 및 산정지침에서 정한 바와 같이, 환자를 진료하는 중에 당해 요양기관에 요양병원 행정해석 인력･시설 또는 장비가 갖추어져 있지 아니하거나 기타 부득이한 사유로 해당 진료가 가능한 다른 요양기관으로 적정 하게 의뢰하는 경우에도 관련 치료재료는 정액수가에 포함되므로 별도산정 할 수 없습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 208쪽',208,8,83);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0084','PDF_QNA','PDF_QNA_02','PDF','QA','발열 열(G,1,a) 탈수(G,1,b) 구토(G,1,c) 체중감소(H,2-2)','발열 열(G,1,a) 탈수(G,1,b) 구토(G,1,c) 체중감소(H,2-2)','발열 탈수 구토 체중감소 영양 경관영양 섭취 수분','○ 탈수･구토･체중감소 중 하나 이상을 동반한 37.2℃(직장 체온은 37.5℃) 이상의 발열이 3일 이상 있고, 이를 확인하기 위해 1일 3회 이상, 적정 간격(6~8시간)으로 체온을 측정하며, 발열의 원인을 찾는 검사와 처치를 시행한 경우에 해당합니다.\n○ 아래 중 2가지 이상에 해당하는 경우를\n말합니다.\n- 하루에 섭취하는 수분량이 1500ml 미만인 경우\n- 탈수의 임상적 증상이 있는 경우\n예) 새로 발병된 또는 악화된 혼돈\n(confusion), 비정상적인 임상결과 (헤모글로빈, 헤마토크리트, 칼륨, 혈액요소질소, 요비중 증가 등) 등\n- 구토, 열, 설사 등으로, 섭취한 수분량 보다 수분 소실량이 많은 경우\n○ 발열 증상과 함께 심한 반복적 구토 증상이 동반되어 섭취량 및 배설량의 불균형이 발생하는 경우를 말합니다.\n○ 지난 31일 이내에 5% 이상 감소 또는\n184일 이내에 10% 이상 감소한 경우를 말합니다. & ASSESSMENT SER','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 209쪽',209,8,84);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0085','PDF_QNA','PDF_QNA_02','PDF','QA','통증 (G,2)','통증 (G,2)','통증 ','○ 매일 통증이 있는 경우란, 매일 통증이 보험 있고 그에 따른 통증 관련 치료를 매일 급여과- 받고 있는 경우에 해당합니다. 3929호\n○ ‘매일 있는 격렬하거나 참을 수 없는 통증’에 ‘통증 관련 치료’ 중 주사제를 투여 받고 있는 경우 ‘주사제’는 마약성 진통제를 투여 받는 경우를 말합니다.\n○ 통증 관련 치료 중 경구제 또는 패치제로\n통증 조절이 가능한 경우는 외래 통원\n치료가 가능하므로 입원 대상에 해당하지\n않습니다.\n○ 담당의사는 통증의 원인, 부위, 정도, 지속 시간, 치료 및 관리 등에 대한 지속적인 경과를 진료기록부 등에 기록･보관하여야 합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 210쪽',210,8,85);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0086','PDF_QNA','PDF_QNA_02','PDF','QA','I. 피부상태 피부의 기타 문제 중 개방성 피부병변(4,b) 피부의 기타 문제 중 수술 창상(4,c) 피부문제에 대한 처치 중 피부궤양(욕창 및 울혈성 궤양 등) 드레싱 (5,d)','I. 피부상태 피부의 기타 문제 중 개방성 피부병변(4,b) 피부의 기타 문제 …','피부상태 피부 문제 개방성 피부병변 수술 창상 피부문제 처치 피부궤양 욕창 울혈성 궤양 드레싱 압창','○ 개방성 피부병변은 매독이나 피부암 등 보험 으로 인하여 발생한 개방성 피부병변을 급여과- 의미합니다(피부궤양, 자상, 발적은 제외) 3929호\n○ 수술창상은 수술 후 회복되지 않은 상처로서 수술 후 Stitch Out 까지를 말합니다.\n○ 피부궤양(욕창 및 울혈성궤양 등)의 상태에 따른 적절한 드레싱으로서 단순처치는 해당 하지 않습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 210쪽',210,8,86);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0087','PDF_QNA','PDF_QNA_02','PDF','QA','피부문제에 대한 처치 중, 피부궤양 (욕창 및 울혈성궤양 등) 드레싱･ 피부궤양(욕창 및 울혈성 궤양 등) 이외의 드레싱･수술창상 치료 (I,5,d･e･f)','피부문제에 대한 처치 중, 피부궤양 (욕창 및 울혈성궤양 등) 드레싱･ 피부궤양…','피부문제 처치 피부궤양 욕창 울혈성궤양 드레싱 울혈성 궤양 이외 수술창상 치료 압창','○ △피부궤양(욕창 및 울혈성궤양 등) 드레싱 보험 △피부궤양(욕창 및 울혈성 궤양 등) 이외의 급여과- 드레싱 △수술창상 치료는, 피부상태(사이즈, 3929호 깊이, 색깔, 양상 등) 및 병변변화(사진, 그림, 의무기록 등), 2가지 이상의 피부궤양 치료에 대한 담당의사의 지속적 관리 내역 등을 매일 진료기록부 등에 기록･보관 하여야 합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 210쪽',210,8,87);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0088','PDF_QNA','PDF_QNA_02','PDF','QA','J. 투약 치매진단을 받은 환자가 망상, 환각, 초조･공격, 탈억제, 케어에 대한 저항, 배회에 대한 약물 치료 여부(2) 치매 관련 약제 투여 여부(3)','J. 투약 치매진단을 받은 환자가 망상, 환각, 초조･공격, 탈억제, 케어에 대…','투약 치매진단 환자 망상 환각 초조 공격 탈억제 케어 저항 배회 약물 치료 치매 약제 투여 인지기능 MMSE 인지','○ 항정신병 약물(Haloperidol, Risperidone, 보 Olanzapine, Aripiprazole, Quetiapine, 급 Perphenazine, Clozapine, Paliperidone, 3 Chlorpromazine, Sulpiride, Amisulpride)\n을 투여하는 경우에 해당합니다.\n○ 치매 치료 약제(Donepezil, Galantamine, Rivastigmine, Memantine)를 투여 하는 경우에 해당합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 211쪽',211,8,88);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0089','PDF_QNA','PDF_QNA_02','PDF','QA','정맥주사에 의한 투약 (K,1,a)','정맥주사에 의한 투약 (K,1,a)','정맥주사 의한 투약 ','○ 「국민건강보험 요양급여의 기준에 관한 규칙」 보\n[별표1] 요양급여의 적용기준 및 방법 3. 급 약제의 지급 나. 주사의 요양급여의 기준에 3 부합하는 대상이어야 합니다.\n○ 또한, 치료약제(항생제, 혈압강하제 등)를 투여한 경우에 해당하며, 단순 수액제, 비타민제, 해열･진통･소염제, 일시적 증상 완화를 위한 소화기관용제 등은 해당하지 않습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 211쪽',211,8,89);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0090','PDF_QNA','PDF_QNA_02','PDF','QA','산소요법 (K,1,e)','산소요법 (K,1,e)','산소요법 ','○ ‘의료고도’에 상응하는 환자 중증도를 고려 보 하여, 호흡곤란 혹은 저산소증이 지속적 급 으로 동반되는 상병(예：만성 폐쇄성 폐 3 질환)과 이에 대한 적극적인 중재 및 기록이 확인되어야 합니다.\n<예시>\n산소투여 이외에 호흡곤란 혹은 저산소증의 원인과 경과를 확인하기 위한 방사선 또는 혈액검사나 호흡곤란 혹은 저산소증 개선을 위한 약제 투여 등 관련 의료서비스를 제공 하고 기록이 확인되는 경우 & ASSESSMENT SERV','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 211쪽',211,8,90);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0091','PDF_QNA','PDF_QNA_02','PDF','QA','중심정맥영양 (K,1,j)','중심정맥영양 (K,1,j)','중심정맥영양 영양 경관영양 섭취 수분','○ 중심정맥영양은 경구 또는 위장관으로 수분 보완 및 영양섭취가 불가능하여 관찰기간 동안 (환자평가 중심정맥관을 통하여 매일 영양물질을 표의 K,1,k 공급한 경우에 해당하며 영양물질은 TPN K,1,j 요법을 말합니다. 변경.\n질의응답\n- 따라서, 경구로 영양섭취가 가능하여 식이와 내용 동시 청구되는 경우는 산정할 수 없습니다. 동일.)\n(’21.\n적용)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 212쪽',212,8,91);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0092','PDF_QNA','PDF_QNA_02','PDF','QA','일정하게 짜여진 배뇨계획(E,3,a)','일정하게 짜여진 배뇨계획(E,3,a)','일정하게 짜여진 배뇨계획 배뇨 실금 배뇨일지 도뇨 소변','○ 일정하게 짜여진 배뇨계획(Scheduled 신설 toileting plan)은 고시 제2019-125호 (’21.\n(’19.11.1.시행)에 의거, 방광이 차는 것과 적용)\n관계없이 정해진 시간에 다른 사람(보조\n인력 등)이 환자를 화장실에 데리고 가거나, 소변기를 주거나, 화장실에 가도록 상기시켜 주는 등 배설 기능 회복을 위한 계획과 더불어 활동이 수행된 경우 체크합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 212쪽',212,8,92);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0093','PDF_QNA','PDF_QNA_02','PDF','QA','피부문제에 대한 처치 중 화상 관련 처치(I,5,g)','피부문제에 대한 처치 중 화상 관련 처치(I,5,g)','피부문제 처치 화상 환자평가표 평가표 작성 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 2도 이상 화상으로 입원이 필요한 환자 신설 에게 화상 관련 직접 처치(예：화상처치)를 (’21.\n제공한 경우 체크합니다. 적용)\n- 의료고도 환자군 중증도를 고려하여 자- 2-1 단순처치･염증성처치, 자-18 피부과 처치만 시행하는 경우 또는 항생제, 진통제 투여, 연고 도포 등 약제만 투여한 경우는 해당하지 않습니다.\n○ 화상 관련 처치를 체크 한 경우, 피부상태 (사이즈, 깊이, 색깔, 양상 등), 병변변화 (사진, 그림, 의무기록 등) 및 화상 관련 처치에 대한 담당의사의 지속적 관리 내역 등을 매일 진료기록부 등에 기록･보관 하여야 합니다.\n○ 다만, 의료고도의 화상 관련 직접 처치\n종료 후 지속 치료가 필요하여 피부병변\n치료를 시행한 경우 등은 환자평가표 작성\n결과에 따라 해당 환자군으로 분류됩니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 212쪽',212,8,93);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0094','PDF_QNA','PDF_QNA_03','PDF','QA','2021년 4월의 환자평가표 작성일로부터 4월 마지막 날까지의 잔여일수가 7일 이하인 경우 2021년 5월의 환자평가표를 생략할 수 있나요?','2021년 4월의 환자평가표 작성일로부터 4월 마지막 날까지의 잔여일수가 7일 …','2021년 4월 환자평가표 작성일로 마지막 날까지 잔여일수 7일 이하인 5월 생략할 평가표 작성','○ 2021년 5월 1일 이후 진료분은 관찰기간 7일을 확보하여 ‘계속 입원중인 환자 평가’로 5월 1일부터 5월 10일사이에 ‘091’ 서식에 작성해야합니다.\n○ 단, 2021년 5월 환자평가표 작성일로부터 마지막 날까지의 잔여일수가 7일 이하인 경우 2021년 6월의 환자평가표는 생략 가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 214쪽',214,8,94);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0095','PDF_QNA','PDF_QNA_03','PDF','QA','계속 입원 중인 환자가 2021년 5월 3일에 퇴원예정인 경우 환자평가표는 퇴원일에 단축하여 작성해야 하나요?','계속 입원 중인 환자가 2021년 5월 3일에 퇴원예정인 경우 환자평가표는 퇴원…','계속 입원 중인 환자 2021년 5월 3일 퇴원예정인 환자평가표 퇴원일 단축하여 작성해야 평가표 작성','○ 환자평가표는 매월 1~10일에 작성함이 원칙이므로, 계속 입원 중인 환자의 경우 2021년 5월 1~3일 사이에 관찰기간 7일을 확보하여 작성 가능합니다. (단, 관찰 기간은 이전 관찰기간과 중복 불가)\n   ※ 계속 입원중인 환자의 환자평가표 작성일 및 관찰기간 관찰기간 작성일 4/25~5/1 5월 1일 4/26~5/2 5월 2일 4/27~5/3 5월 3일','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 214쪽',214,8,95);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0096','PDF_QNA','PDF_QNA_04','PDF','QA','동 고시에서 ‘최초 진료’의 의미는 무엇인가요?','동 고시에서 ‘최초 진료’의 의미는 무엇인가요?','고시 최초 진료 의미 무엇 ','○ 요양병원 입원 기간 동안에 다른 의료기관으로 진료 의뢰되어 해당 상병으로 최초 진료를 받는 경우를 말함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 215쪽',215,8,96);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0097','PDF_QNA','PDF_QNA_04','PDF','QA','요양병원 입원기간 중 진료 의뢰하는 상병이 달라지는 경우 추가 산정 가능한가요?','요양병원 입원기간 중 진료 의뢰하는 상병이 달라지는 경우 추가 산정 가능한가요?','요양병원 입원기간 진료 의뢰하 상병 달라지 가능한가요 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 요양병원 입원기간 중 다른 상병으로 진료 의뢰하였을 경우, 해당 상병 진료가 최초 진료인 경우 추가 산정 가능함\n      요양병원에서 퇴원 후 재입원한 경우 추가 산정 가능한가요?\n○ 재입원한 경우 추가산정 가능함. 다만, 90일 이내 재입원한 경우는 동일 입원기간으로 적용되어 추가산정 안됨.\n   ※ 「제2부 요양병원 환자군 급여목록·상대가치점수 및 산정지침 4-라-(4) 정액수가 입원료 산정 방법」에 따라 90일 이내 동일 요양병원에 재입원 하는 경우에는 동일 입원기간으로 적용 ‘1회 14일 이내 한하여 별도 산정’ 관련','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 215쪽',215,8,97);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0098','PDF_QNA','PDF_QNA_04','PDF','QA','약제를 1회 14일 까지만 처방해야 한다는 것인가요?','약제를 1회 14일 까지만 처방해야 한다는 것인가요?','약제 1회 14일 까지 처방해야 한다 ','○ 동 고시는 14일을 초과한 약제 처방 자체를 금지하는 규정이 아님. 다만, 진료 의뢰한 요양병원에서 별도청구 가능한 범위를 정한 것임\n○ 따라서, 다른 의료기관으로 의뢰한 경우 발생한 약제에 대해 요양병원에서 14일까지 별도 청구가 가능하다는것임','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 216쪽',216,8,98);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0099','PDF_QNA','PDF_QNA_04','PDF','QA','약제처방은 1회 14일만 가능하다는 의미는 무엇인가요?','약제처방은 1회 14일만 가능하다는 의미는 무엇인가요?','약제처방 1회 14일 가능하다 의미 무엇 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 약제 처방기간은 14일 이내에 한해서만 별도 산정함이 원칙임\n   - 약제* 14일 처방 초과분에 대해서는 별도 산정할 수 없으며, 이 경우 환자 본인 부담금은 발생하지 않음\n      * 요양병원 환자군 급여목록･상대가치점수 및 산정지침 3.의 항목은 적용대상에서 제외\n○ 단, 동일요양기관에서 해당상병으로 1회 14일 처방 후, 의･약학적 사유로 다시(변경)\n   처방한 경우 진료기록부나 의사소견서 등을 고려하여 사례별로 인정 가능함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 216쪽',216,8,99);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0100','PDF_QNA','PDF_QNA_04','PDF','QA','동 고시에서 적용되는 약제는 어떻게 되나요?','동 고시에서 적용되는 약제는 어떻게 되나요?','고시 적용되 약제 어떻게 ','○ 약제를 구분하여 적용하지 않으며, 의뢰받은 요양기관에서 해당상병 진료를 위해 처방한 약제는 모두 14일 이내 별도 산정 가능함. 다만, [산정지침] 3-가-(5)전문의약품은 동 고시 적용에서 제외됨)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 216쪽',216,8,100);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0101','PDF_QNA','PDF_QNA_04','PDF','QA','동 고시에 따라 [산정지침] 3-가-(5) ‘전문의약품’도 14일까지만 산정 가능한가요?','동 고시에 따라 [산정지침] 3-가-(5) ‘전문의약품’도 14일까지만 산정 가…','고시 따라 산정지침 전문의약품 14일까지 가능한가요 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 아래에 명시된 전문의약품은 정액수가에 포함되지 않은 항목으로 별도 산정토록 되어 있음\n○ 따라서, 동 고시의 적용범위에 해당되지 않으며, 14일 초과 산정 가능함\n      ※ [산정지침] 3-가-(5) 다음의 전문의약품 ㈎ Erythropoietin 주사제(품명：에포론주 등), Darbepoetin Alpha 주사제(품명：네스 프프리필드주 등), Methoxy polyethylene glycol - epoetin β 주사제(품명∶미쎄라 프리필드주)\n      ㈏ Recombinant Human Epidermal Growth Factor(품명：이지에프외용액)\n      ㈐ Riluzole(품명：리루텍정 등)\n      ㈑ Interferon β - 1a(품명：레비프프리필드주 등)\n   기타사항','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 217쪽',217,8,101);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0102','PDF_QNA','PDF_QNA_04','PDF','QA','고시 개정으로, 요양병원과 의뢰받은 의료기관이 달라진 점은 무엇인가요?','고시 개정으로, 요양병원과 의뢰받은 의료기관이 달라진 점은 무엇인가요?','고시 개정 요양병원 의뢰받 의료기관 달라진 무엇 ','○ 요양병원(의뢰한 기관)\n   - 동 고시의 취지를 감안할 때 요양병원에 입원중인 환자의 진료 상 필요한 약제는 가능한 요양병원에서 직접 구입하여 투약함이 원칙임\n○ 의료기관(의뢰받은 기관)\n   - 약제 처방에 대한 제한이 아니므로 고시 개정 이전과 동일함\n   - 따라서, 기존과 동일하게 원내처방 하며, 요양병원에서 입원환자에게 필요한 투약이 이루어 질 수 있도록 해당 정보(처방내역 등)를 요양병원에 제공 바람','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 217쪽',217,8,102);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0103','PDF_QNA','PDF_QNA_04','PDF','QA','외용약은 어떻게 청구하나요?','외용약은 어떻게 청구하나요?','외용약 어떻게 청구하 ','○ 외용약(패취제, 흡입제, 연고, 가글 용제, 안약 등)의 경우 식약처 허가사항(용량)을 참조하여 14일 이내 사용량 인정을 원칙으로 함. 다만, 포장 단위 특성을 고려하여 분할할 수 없는 경우는 14일을 초과하더라도 포장 단위로 인정 가능함\n○ 단, 가글 용제, 패취제 등과 같이 별도로 사용량을 정하고 있는 경우 해당 고시에서 정한 기준을 따름','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 217쪽',217,8,103);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0104','PDF_QNA','PDF_QNA_04','PDF','QA','임상적 소견은 어떻게 확인하나요?','임상적 소견은 어떻게 확인하나요?','임상적 소견 어떻게 확인하 ','○ 진료기록부나 의사소견서 등에서 의･약학적 사유(환자상태 변화, 약물 순응도 등)로 인해 처방 약제 및 용량 변경 등이 필요한 경우가 확인되어야 함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 218쪽',218,8,104);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0105','PDF_QNA','PDF_QNA_04','PDF','QA','‘기타 부득이한 사유’는 무엇인가요?','‘기타 부득이한 사유’는 무엇인가요?','부득이한 사유 무엇 ','○ 당해 요양병원에서 진료할 수 없는 객관적 사유나 타 기관 진료가 필요한 경우 이에 대한 의학적 타당성이 인정되는 경우를 원칙으로 하며,\n○ 환자･보호자의 요구에 의한 경우, 요양병원의 사정(약제 재고 부족 등)은 인정하지 않음','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 218쪽',218,8,105);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0106','PDF_QNA','PDF_QNA_04','PDF','QA','본인일부부담금 산정특례 대상자의 경우에도 동 기준이 적용되는가요?','본인일부부담금 산정특례 대상자의 경우에도 동 기준이 적용되는가요?','본인일부부담금 산정특례 대상자 경우에 기준 적용되는가요 ','○ 본인일부부담금 산정특례 대상자의 경우에는 보건복지부 고시 제2019-302호 「요양 병원 입원중인 산정특례 대상자를 타병원 진료의뢰시 수가 산정방법」에 따라 적용 되므로 동 고시 적용 대상에서 제외됨','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 218쪽',218,8,106);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0107','PDF_QNA','PDF_QNA_05','PDF','QA','산정특례 대상 해당 상병으로 의뢰 받은 요양기관에서 발생한 진료비 산정방법은?','산정특례 대상 해당 상병으로 의뢰 받은 요양기관에서 발생한 진료비 산정방법은?','산정특례 대상 상병 의뢰 요양기관 발생한 진료비 산정방법 ','○ 산정특례 대상 상병명에 대한 진료의뢰시 진료비는 「건강보험 행위 급여·비급여 목록표 및 급여 상대가치점수」 제1편 및 관련 급여기준(「요양급여의 적용기준 및 방법에 관한 세부사항」), 「본인일부부담금 산정특례에 관한 기준」에 따라 의뢰받은 요양기관에서 직접 청구(약국 약제비는 약국에서 청구)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 219쪽',219,8,107);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0108','PDF_QNA','PDF_QNA_05','PDF','QA','요양병원에 입원 중인 환자를 다른 요양기관으로 진료 의뢰 시 진료비 산정방법은?','요양병원에 입원 중인 환자를 다른 요양기관으로 진료 의뢰 시 진료비 산정방법은?','요양병원 입원 중인 환자 다른 요양기관 진료 의뢰 진료비 산정방법 ','○ 환자가 입원 중인 요양병원에서 청구하되, 특정내역 구분코드(JS008) 기재하여 청구함\n   (예시) A요양병원(12345678)에 입원중인 환자를 2021년 7월 15일 B병원 (23456789)으로 진료의뢰한 경우 특정내역 특정내역 구분코드 JS008 23456789/20210715\n○ 산정특례 적용 대상 상병으로 진료의뢰 시 의뢰받은 요양기관에서 청구하고,\n- 의뢰한 요양병원은 의뢰 당일 가산 등을 적용하지 않은 입원료만 청구하되, 위 기관 모두 특정내역 구분코드(MT063) 기재하여 청구함\n   (예시) A요양병원(12345678)에 입원중인 환자를 2021년 7월 15일 B병원 (23456789)으로 진료의뢰한 경우\n<의뢰한 A요양병원>\n      특정내역 특정내역\n      구분코드 의뢰한 기관 (A요양병원)\n      MT063 23456789/20210715\n      <의뢰받은 B병원>\n      특정내역 특정내역\n      구분코드 의뢰받은 기관 (B병원)\n      MT063 12345678/20210715\n○ 산정특례 적용 대상 진료 의뢰 당일에 산정특례 외 타 상병 진료가 동시에 이루어진 경우, 타 상병 진료내역은 산정특례 제외 대상이므로 환자가 입원 중인 요양병원에서 청구','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 219쪽',219,8,108);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0109','PDF_QNA','PDF_QNA_05','PDF','QA','「본인일부부담금 산정특례에 관한 기준」 [별표4의2] 중증난치질환자 산정특례 대상자 중 만성신부전증 환자의 진료의뢰 시 요양급여비용 청구방법은?','「본인일부부담금 산정특례에 관한 기준」 [별표4의2] 중증난치질환자 산정특례 대…','본인일부부담금 산정특례 관한 기준 별표4의2 중증난치질환자 대상자 만성신부전증 환자 진료의뢰 요양급여비용 청구방법 ','○ 질의·응답 연번2에 따라 청구함\n- 다만, 보건복지부 고시 제2010-18호(’10.2.1.시행)에 근거하여, 인공신장투석 또는 계속적 복막관류술 실시 당일에 타 상병을 외래로 병행치료한 경우 타 상병 진료 내역도 「본인일부부담금 산정특례에 관한 기준」에 의한 본인부담률을 적용하여 의뢰받은 요양기관에서 일괄 청구함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 220쪽',220,8,109);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0110','PDF_QNA','PDF_QNA_05','PDF','QA','요양병원 입원중인 산정특례 대상자의 진료의뢰 당일 가산을 적용하지 않은 요양병원의 일당 정액수가 산정방법은?','요양병원 입원중인 산정특례 대상자의 진료의뢰 당일 가산을 적용하지 않은 요양병원…','요양병원 입원중인 산정특례 대상자 진료의뢰 당일 가산 적용하지 일당 정액수 산정방법 의사인력 의사수 의사등급 차등제 간호인력 간호사 간호조무사 간호등급 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 의사 및 간호인력 확보수준에 따른 입원료 차등제 적용 시 요양병원 입원료 소정점수 가산을 적용받는 기관은 기본등급으로 산정하고 감산을 적용 받는 기관은 감산등급을 적용하여 산정 예1) 인력 가산을 적용받는 요양병원은 가산 배제 의사인력 1등급(단, ’20.7월부터는 의사인력 2등급 포함), 간호인력 1~4등급의 경우 요양병원입원료 소정점수로 산정(기본코드 네 번째, 다섯 번째 자리에 0으로 적용)\n   예2) 인력 감산을 적용받는 요양병원은 감산 적용 의사인력 3~5등급, 간호인력 6등급의 경우 해당등급 적용(기본코드 네 번째 자리에 3, 4, 5로, 다섯 번째 자리에 8로 기재)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 220쪽',220,8,110);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0111','PDF_QNA','PDF_QNA_05','PDF','QA','요양병원 입원중인 산정특례 대상자가 제외환자 및 특정기간으로 입원 중 타 기관 진료의뢰를 한 경우 요양병원 입원료 차등제 등 수가산정방법은?','요양병원 입원중인 산정특례 대상자가 제외환자 및 특정기간으로 입원 중 타 기관 …','요양병원 입원중인 산정특례 대상자 제외환자 특정기간 입원 기관 진료의뢰 입원료 차등제 수가산정방법 ','○ 연번 4와 같이 적용함\n   산정특례 대상이 아닌 타 상병으로 진료의뢰 시 청구방법은?\n○ 기존의 행정해석을 적용\n- 「요양병원 입원환자를 다른 요양기관에 진료의뢰 시 수가산정방법 등」 (보험급여팀-4048호, 2007.12.31.)\n- 「요양병원에 입원중인 환자에게 원외처방전 발행 시 수가산정방법」 (보험급여팀-4048호, 2007.12.31.)\n- 「요양병원에 입원중인 환자를 타 요양기관으로 진료의뢰 하여 의뢰받은 요양기관에서 진료 후 발생한 약제비 산정방법」(보험급여팀-204호, 2008.1.24.)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 221쪽',221,8,111);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0112','PDF_QNA','PDF_QNA_06','PDF','QA','개정되는 요양병원 의사인력확보수준에 따른 입원료 차등제를 반영한 의사등급이 적용되는 시점은?','개정되는 요양병원 의사인력확보수준에 따른 입원료 차등제를 반영한 의사등급이 적용…','개정되 요양병원 의사인력확보수준 입원료 차등제 반영한 의사등급 적용되 시점 의사인력 의사수','○ ’20년 7월 1일 진료분부터 적용되며, ’20년 3사분기 요양병원 입원료 차등제 적용을 위해 ’20년 3월 15일부터 6월 14일까지의 요양병원 입원료 차등제 산정현황 통보서를 ’20년 6월 16일부터 20일까지 제출하여야 함\n   * 요양병원 관련 고시(의사인력확보수준에 따른 입원료 차등제) 시행 안내 (보험급여과-3421호, ’20.8.2.) 에 따라 ‘21.1.1. 시행','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 222쪽',222,8,112);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0113','PDF_QNA','PDF_QNA_06','PDF','QA','환자 수 대 의사 수의 비가 35:1 이하이면서 전문의 비율에 다른 등급 구분 시 해당되는 전문의의 전문과목은?','환자 수 대 의사 수의 비가 35:1 이하이면서 전문의 비율에 다른 등급 구분 …','환자 의사 35 이하이면서 전문 비율 다른 등급 구분 해당되 전문의 전문과목 ','○ 「전문의의 수련 및 자격 인정 등에 관한 규정」 제3조에 따른 전문의의 전문과목인 내과, 신경과, 정신건강의학과, 외과, 정형외과, 신경외과, 흉부외과, 성형외과, 마취 통증의학과, 산부인과, 소아청소년과, 안과, 이비인후과, 피부과, 비뇨의학과, 영상 의학과, 방사선종양학과, 병리과, 진단검사의학과, 결핵과, 재활의학과, 예방의학과, 가정의학과, 응급의학과, 핵의학 및 직업환경의학과를 말함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 222쪽',222,8,113);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0114','PDF_QNA','PDF_QNA_06','PDF','QA','의사 1등급 또는 2등급 가산 적용을 위한 ‘상근 의사 1인’과 ‘의사 수 2인(소수점은 반올림)’의 산정방법은?','의사 1등급 또는 2등급 가산 적용을 위한 ‘상근 의사 1인’과 ‘의사 수 2인…','의사 1등급 2등급 가산 적용 상근 1인 2인 소수점 반올림 산정방법 의사인력 의사수 의사등급 차등제','○ 의사인력 산정기준은 「요양급여의 적용기준 및 방법에 관한 세부사항」에서 정한 바에 따름\n○ 다만, 의사 수 2인 이상 여부는 소수점 첫째자리에서 반올림하여 적용함\n      ※ (예시) 상근 의사 1인과 격일제 의사 1인이 근무할 경우 시간제 또는 격일제 의사는 주3일 이상이면서 주20시간인 경우 0.5인으로 인정하는 산정기준에 따라 의사 수는 1.5인이므로 소수점 첫째자리에서 반올림하여 2인으로 산정함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 222쪽',222,8,114);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0115','PDF_QNA','PDF_QNA_06','PDF','QA','의사 1등급 또는 2등급인 요양병원의 상근 의사가 1인 이상이나 의사 수가 2인 미만인 경우 가산 적용이 가능한지?','의사 1등급 또는 2등급인 요양병원의 상근 의사가 1인 이상이나 의사 수가 2인…','의사 1등급 2등급인 요양병원 상근 1인 이상이나 2인 미만인 가산 적용 ','○ “상근하는 의사 1인 이상을 포함한 의사 수 2인 이상”을 충족하지 않으므로 가산을 적용할 수 없으며, 의사 3등급을 적용함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 223쪽',223,8,115);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0116','PDF_QNA','PDF_QNA_06','PDF','QA','의사 1등급 또는 2등급인 요양병원의 의사 수가 2인 이상이나 상근 의사가 1인 미만인 경우 가산 적용이 가능한지?','의사 1등급 또는 2등급인 요양병원의 의사 수가 2인 이상이나 상근 의사가 1인…','의사 1등급 2등급인 요양병원 2인 이상이나 상근 1인 미만인 가산 적용 의사인력 의사수 의사등급 차등제','○ “상근하는 의사 1인 이상을 포함한 의사 수 2인 이상”을 충족하지 않으므로 가산을 적용할 수 없으며, 의사 3등급을 적용함\n      신규개설 요양병원의 의사인력확보수준에 따른 입원료 차등제 등급 적용기준은?\n○ 분기 마지막 월 14일 이전 신규개설한 경우, 해당 분기는 기본등급으로 적용하고, 다음\n   분기 적용을 위한 등급은 아래의 기준에 따라 산정함\n   - 입원환자수는 개설 당일부터 해당 분기의 마지막 월 14일까지의 입원환자를 평균 하여 산정함\n   - 의사는 개설 당일부터 해당 분기의 마지막 월 14일까지의 재직일수를 평균하여 산정함\n○ 분기 마지막 월 15일 이후 신규개설한 경우, 해당 분기 및 다음 분기의 의사등급은 기본등급을 적용함\n      신규개설 요양병원도 요양병원 입원료 차등제 산정현황 통보서를 제출해야 하는지?\n○ 분기 마지막 월 14일 이전 신규개설한 경우 분기 마지막 월 20일까지 제출함\n○ 분기 마지막 월 15일 이후 신규개설한 경우 분기 마지막 일까지 제출함\n○ 단, 신규개설분기의 통보서 제출 후에 다음분기의 통보서를 순차적으로 제출하여야 하며 기한 내 미제출 기관의 경우에는 4등급을 적용함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 223쪽',223,8,116);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0117','PDF_QNA','PDF_QNA_07','PDF','QA','요양병원 입원진료 현황 고지는 무엇인지?','요양병원 입원진료 현황 고지는 무엇인지?','요양병원 입원진료 현황 고지 무엇 치매 인지기능 MMSE 인지','○ 요양병원 입원진료 현황 고지는 요양병원이 입원진료 현황(수진자 주민번호, 수진자 성명, 수진자의 입원･퇴원 유형 및 일시, 요양기관기호)을 국민건강보험공단요양기관 정보마당(https://medicare. nhis.or.kr/portal/index.do)에 입력하는 것을 말함\n   * 자세한 사항은 국민건강보험공단 안내 참조','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 224쪽',224,8,117);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0118','PDF_QNA','PDF_QNA_07','PDF','QA','요양병원 입원진료 현황은 언제부터 고지하는지?','요양병원 입원진료 현황은 언제부터 고지하는지?','요양병원 입원진료 현황 언제 고지하는지 장기입원 체감제 입원기간','○ 「국민건강보험 요양급여의 기준에 관한 규칙」 제3조의2에 따라\n   - ’19.11.1. 현재 입원진료를 받고 있거나, ’19.11.1. 이후 입원･퇴원하는 건강보험 가입자 또는 피부양자 등에 대해 ’19.11.1부터 입력\n○ ’20.1.1. 진료분부터는 입원진료 현황을 고지하고, 입원진료에 대한 요양급여를 실시한 경우(입력된 입원진료 현황과 청구 내역이 일치한 경우)에 요양급여 적용이 가능하므로,\n   - 입원･퇴원, 건강보험 적용 또는 미적용 등 발생 시마다 즉시 입력하여야 하며, 계속 입원중인 환자의 경우에도 ’19.12.31.까지 입력하여야 함.\n요양병원 입원료 체감제 관련','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 224쪽',224,8,118);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0119','PDF_QNA','PDF_QNA_07','PDF','QA','계속 입원중인 환자의 입원 기간에 따른 체감률 적용 방법은?','계속 입원중인 환자의 입원 기간에 따른 체감률 적용 방법은?','계속 입원중인 환자 입원 기간 체감률 적용 ','○ ’19.12.31까지는 종전 고시를, ’20.1.1 진료분부터는 개정된 고시에 따라 입원 기간에 따른 체감률을 적용함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 225쪽',225,8,119);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0120','PDF_QNA','PDF_QNA_07','PDF','QA','요양병원 퇴원 후 재입원시 입원료 체감제 산정 방법은?','요양병원 퇴원 후 재입원시 입원료 체감제 산정 방법은?','요양병원 퇴원 재입원시 입원료 체감제 장기입원 입원기간','○ 퇴원 후 90일 이내(퇴원 익일부터 계산, 이하 같음)에 재입원 하는 경우에는 이전 요양 병원 입원기간을 합산하여 입원료 체감제 수가를 적용함. (’20.1.1 퇴원환자부터 적용)\n   ’20년 1월 1일 이후 입원한 환자가 퇴원 후 90일 이내 재입원하는 경우 이전 요양병원의 입원기간을 합산하는 방법은?\n○ ’20년 12월 31일까지는 퇴원 후 90일 이내 동일 요양병원으로 재입원 하는 경우에만 이전 요양병원의 입원기간을 합산하여 적용함.\n○ ’21년 1월 1일 이후 입원한 환자는, 입원 전 90일 이내에 퇴원이 발생한 당해 요양 병원 및 다른 요양병원의 누적 입원일수를 합산하여 산정함\n   - 다만, ’20년 12월 31일 이전에 퇴원이 이루어진 요양병원이 당해 병원을 제외하고 2개 이상인 경우에는, 최종으로 퇴원한 1개 기관의 누적 입원일수만 합산함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 225쪽',225,8,120);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0121','PDF_QNA','PDF_QNA_07','PDF','QA','퇴원 후 90일 이내 재입원시 입원기간 합산적용은 요양병원 이외 요양기관 (상급종합병원, 병원 등)에도 적용하는지?','퇴원 후 90일 이내 재입원시 입원기간 합산적용은 요양병원 이외 요양기관 (상급…','퇴원 90일 이내 재입원시 입원기간 합산적용 요양병원 이외 요양기관 상급종합병원 병원 적용하는지 ','○ 90일 이내 재입원시 이전 입원기간의 합산적용은, 요양병원의 입원기간만 합산하며 요양병원 이외 요양기관의 입원기간은 합산하지 않음.\n[예시]\n❍ ‘퇴원 후 90일 이내 다른 요양병원으로 재입원 시 이전 요양병원의 입원기간을 합산’\n하는 것에 대한 적용 방법\n* 예시로 제시되어 있는 입원일수는 입원료 산정방법에 따라 계산된 일수임\n      (예：1박2일 입원 시：1일)\n- (예시 1) A기관에 2020.9.1. 입원 후 9.30.퇴원 A기관에 2021.1.1. 입원 했다면, 입원 시 누적입원일수：1일 2020년 2021년\n[A기관] [A기관]\n9.1. 9.30. 1.1~\n      ⇓ ⇓\n      입원일수：29일 누적입원일수：1일~\n- (예시 2) A기관에 2020.9.1. 입원 후 9.30.퇴원 A기관에 2020.11.1. 입원 후 11.30퇴원 A기관에 2021.1.1. 입원 했다면, 입원 시 누적입원일수：59일 2020년 2021년\n[A기관] [A기관]\n9.1. 9.30. 11.1 11.30. 1.1~\n      ⇓ ⇓ ⇓\n      입원일수：29일 입원일수：29일 누적입원일수：59일~ 누적입원일수：58일\n- (예시 3) A기관에 2020.11.1. 입원 후 11.30.퇴원 B기관에 2021.1.1. 입원 했다면, 입원 시 누적입원일수：30일 2020년 2021년\n[A기관] [B기관]\n11.1. 11.30. 1.1~\n      ⇓ ⇓\n      입원일수：29일 누적입원일수：30일~\n- (예시 4) A기관에 2020.11.1. 입원 후 11.30.퇴원 B기관에 2020.12.1. 입원 후 12.15.퇴원 A기관에 2021.1.1. 입원 했다면, 입원 시 누적입원일수：44일 2020년 2021년\n[A기관] [B기관] [A기관]\n11.1. 11.30. 12.1. 12.15. 1.1~\n      ⇓ ⇓ ⇓\n      입원일수：29일 입원일수：14일 누적입원일수：44일~\n- (예시 5) A기관에 2020.11.1.입원 후 11.15.퇴원 B기관에 2020.12.1.입원 후 2021.1.15.퇴원 A기관에 2021.2.1.입원 했다면, 입원 시 누적입원일수：60일 2020년 2021년\n[A기관] [B기관] [A기관]\n11.1. 11.15. 12.1. 1.1 1.15. 2.1.\n      ⇓ ⇓ ⇓\n      입원일수：14일 입원일수：45일 누적입원일수：60일~\n- (예시 6) A기관에 2020.11.1.입원 후 11.15.퇴원 A기관에 2020.12.1.입원 후 2021.1.15.퇴원 B기관에 2021.2.1.입원 했다면, 입원 시 누적입원일수：60일 2020년 2021년\n[A기관] [A기관] [B기관]\n11.1. 11.15. 12.1. 1.1 1.15. 2.1.\n      ⇓ ⇓ ⇓\n      입원일수：14일 입원일수：45일 누적입원일수：60일~\n- (예시 7) A기관에 2020.11.1. 입원 후 11.10.퇴원 B기관에 2020.11.15. 입원 후 11.30.퇴원 C기관에 2020.12.1. 입원 후 12.15.퇴원 B기관에 2021.1.1. 입원 후 1.10.퇴원 A기관에 2021.1.11.입원 했다면, 입원 시 누적입원일수：48일 2020년 2021년\n[A기관] [B기관] [C기관] [B기관] [A기관]\n11.1. 11.10. 11.15. 11.30. 12.1. 12.15. 1.1. 1.10. 1.11.\n      ⇓ ⇓ ⇓ ⇓ ⇓\n입원일수：9일 입원일수：15일 입원일수：14일 입원일수：9일 누적입원일수：48일~ 누적입원일수：38일 ※ A기관 90일 이내 재입원\n- (예시 8) A기관에 2021.1.1. 입원 후 1.15.퇴원 B기관에 2021.1.20. 입원 후 1.31.퇴원 A기관에 2021.5.15. 입원 했다면, 입원 시 누적입원일수：1일 2021년\n[A기관] [B기관] [A기관]\n1.1. 1.15. 1.20. 1.31. 5.15.~\n      ⇓ ⇓ ⇓\n      입원일수：14일 입원일수：11일 누적입원일수：1일~ 누적입원일수：25일\n- (예시 9) A기관에 2020.10.1.입원 후 10.31.퇴원 B기관에 2020.11.1.입원 후 11.15.퇴원 A기관에 2020.11.20.입원 후 11.30.퇴원 C기관에 2020.12.1.입원 후 12.15.퇴원 A기관에 2021.1.1.입원 했다면, 입원 시 누적입원일수：55일 2020년 2021년\n[A기관] [B기관] [A기관] [C기관] [A기관]\n10.1. 10.31. 11.1. 11.15. 11.20. 11.30. 12.1. 12.15. 1.1.\n      ⇓ ⇓ ⇓ ⇓ ⇓\n입원일수：30일 입원일수：14일 입원일수：10일 입원일수：14일 누적입원일수：55일~ 누적입원일수：40일\n- (예시 10) A기관에 2020.10.1.입원 후 10.31.퇴원 A기관에 2020.11.1.입원 후 11.15.퇴원 C기관에 2020.11.16.입원 후 11.30.퇴원 B기관에 2020.12.5.입원 후 12.20.퇴원 C기관에 2020.12.25.입원 후 12.31.퇴원 A기관에 2021.1.1.입원 했다면, 입원 시 누적입원일수：65일 2020년 2021년\n   [A기관] [A기관] [C기관] [B기관] [C기관] [A기관]\n   10.1. 10.31. 11.1. 11.15. 1 1 . 1 6 . 12.5. 12.20. 1 2 . 2 5 . 1.1\n      11.30. 12.31.\n      ⇓ ⇓ ⇓ ⇓ ⇓ ⇓\n   입원일수：30일 입원일수：14일 입원일수：14일 입원일수：15일 입원일수：6일 누적입원일수：65 누적입원일수：44일 누적입원일수：20일 일~\n- (예시 11) A기관에 2020.12.1. 입원 후 2021.1.15.퇴원 B기관에 2021.2.1. 입원 후 2.15.퇴원 C기관에 2021.3.1. 입원 후 3.15.퇴원 D기관에 2021.4.1. 입원 후 4.30.퇴원 E기관에 2021.5.1. 입원 했다면, 입원 시 누적입원일수：103일 2020년 2021년\n[A기관] [B기관] [C기관] [D기관] [E기관]\n12.1. 1.15. 2.1 2.15. 3.1 3.15 4.1 4.30. 5.1.\n      ⇓ ⇓ ⇓ ⇓ ⇓\n      입원일수：45일 입원일수：14일 입원일수：14일 입원일수：29일 누적입원일수：\n      누적입원일수：59일 누적입원일수：73일 누적입원일수：102일 103일~','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 225쪽',225,8,121);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0122','PDF_QNA','PDF_QNA_08','PDF','QA','요양병원 9인 이상 병실 입원료 감산 적용 시 해당 병실의 기준은?','요양병원 9인 이상 병실 입원료 감산 적용 시 해당 병실의 기준은?','요양병원 9인 병실 입원료 감산 적용 기준 9인이상','○ 국민건강보험법 시행규칙 제12조에 따라 제출된 ‘요양병원 6인 이상 병실･병상 운영현황[신규변경]통보서’상 9인 이상 병실을 의미함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 230쪽',230,8,122);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0123','PDF_QNA','PDF_QNA_08','PDF','QA','정액수가 산정 시 요양병원 9인 이상 병실 입원료 감산 적용방법은?','정액수가 산정 시 요양병원 9인 이상 병실 입원료 감산 적용방법은?','정액수 요양병원 9인 병실 입원료 감산 적용방법 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 9인이상','○ 정액수가 소정점수에서 요양병원 입원료(요-51) 소정점수의 30%를 감산하여 산정함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 230쪽',230,8,123);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0124','PDF_QNA','PDF_QNA_08','PDF','QA','0~6시 사이에 입원하거나, 18~24시 사이에 퇴원하여 입원료의 50%를 별도 산정한 경우 요양병원 9인 이상 병실 입원료 감산을 적용하는지?','0~6시 사이에 입원하거나, 18~24시 사이에 퇴원하여 입원료의 50%를 별도…','6시 사이 입원하거나 18 24시 퇴원하여 입원료 50 산정한 요양병원 9인 병실 감산 적용하는지 9인이상','○ 입원료의 50%를 별도 산정한 경우에도 요양병원 9인 이상 병실 입원료 감산을 적용함.\n   ※ 산정코드 두 번째 자리에 9로 기재','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 230쪽',230,8,124);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0125','PDF_QNA','PDF_QNA_08','PDF','QA','요양병원 9인 이상 병실에 입원 중인 환자가 외박 시 입원료 감산 적용방법은?','요양병원 9인 이상 병실에 입원 중인 환자가 외박 시 입원료 감산 적용방법은?','요양병원 9인 병실 입원 중인 환자 외박 입원료 감산 적용방법 9인이상','○ 외박수가 산정 시(또는 입원료 중 병원관리료만을 산정하는 경우)에도 요양병원 9인 이상 병실 입원료 감산을 적용함.\n   ※ 산정코드 두 번째 자리에 9로 기재','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 230쪽',230,8,125);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0126','PDF_QNA','PDF_QNA_08','PDF','QA','’22년 1월 1일부터 ‘요양병원 9인 이상 병실 입원료(산정코드 두 번째 자리에 9기재)’ 산정 시, 요양급여비용 청구명세서 특정내역 기재방법은?','’22년 1월 1일부터 ‘요양병원 9인 이상 병실 입원료(산정코드 두 번째 자리…','22년 1월 1일 요양병원 9인 병실 입원료 산정코드 번째 자리 9기재 요양급여비용 청구명세서 특정내역 기재방법 9인이상 감산','○ ’22년 1월 1일 진료분부터 요양병원 9인 이상 병실에 입원한 경우 줄번호 단위 특정 내역 구분코드 “JX999(기타내역)”란에 9인 이상 병실 재원기간의 날짜(From/To)를 기재하여 청구함\n      < JX999(기타내역) 작성요령 >\n▶ 기재형식: ccyymmdd/ccyymmdd\n▶ (예시 1) 2022.1.1. 9인실에 입원하여 2022.1.30.에 퇴원한 경우\n      ☞ JX999 20220101/20220130\n   (예시 2) 2022.1.1. 9인실 입원하여 2022.1.10. 6인실로 전실하였다가 2022.1.20.\n      다시 12인실로 전실 후 2022.1.30. 퇴원 한 경우\n      ☞ 9인 이상 병실 입원료에 줄번호단위 특정내역 “JX999(기타내역)”를 줄을 달리하여 9인 이상 병실 입원기간만 기재함\n      JX999 20220101/20220110 JX999 20220120/20220130\n      ※ 전실하는 당일은 수진자가 더 오랫동안 체류한 병실의 기준에 따라 산정함\n      9인 이상 병실 입원료 감산 유예병실의 요양급여비용 청구시 특정내역 기재 방법은?\n○ 보험급여과-6531(2021.12.24.) “요양병원 9인 이상 병실 입원료 감산(고시 제2019- 182호, ’22.1.1.적용) 관련 안내”에 따른 9인 이상 입원료 감산유예병실에 입원한 경우,\n- 9인 이상 입원료 감산유예병실 입원기간 날짜와 “감산유예병실”을 띄어쓰기 없이 붙여서 기재함\n▶ (예시 1) 9인 이상 감산유예병실에 2022.1.1.부터 2022.1.15.까지 입원 후 9인 이상 일반병실로 전실하여 1.30.까지 입원한 경우\n      ☞ JX999 20220101/20220115/감산유예병실 JX999 20220116/20220130','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 231쪽',231,8,126);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0127','PDF_QNA','PDF_QNA_08','PDF','QA','월을 달리하여 계속 입원 중인 환자의 요양급여비용 청구명세서 작성 시, ‘요양병원 9인 이상 병실 입원료’ 산정을 위한 줄번호 특정내역 기재 방법은?','월을 달리하여 계속 입원 중인 환자의 요양급여비용 청구명세서 작성 시, ‘요양병…','달리하여 계속 입원 중인 환자 요양급여비용 청구명세서 작성 요양병원 9인 병실 입원료 줄번호 특정내역 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 9인이상 감산','○ 명세서마다 ‘요양병원 9인 이상 병실 입원료(산정코드 두 번째 자리에 9기재)’에 줄번호 단위 특정내역 구분코드 “JX999(기타내역)”란을 기재하며, 해당 명세서의 요양개시일자 및 마지막날짜를 입실일/퇴실일로 간주하여 특정내역을 작성함\n▶ (예시) 2022.1.1.에 9인실에 입원한 환자가 22.2.13.에 퇴원 한 경우\n   ☞ (1월명세서) JX999 20220101/20220131 (2월명세서) JX999 20220201/20220213\n      ※ 명세서를 분리청구 해야 하는 경우(ex. 정액수가 기간 중 특정기간이 발생하는 등)에도 동일 적용함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 232쪽',232,8,127);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0128','PDF_QNA','PDF_QNA_09','PDF','QA','격리실 입원료에 의사 및 간호인력 확보수준에 따른 입원료 차등제, 필요인력 확보에 따른 별도 보상제가 적용되는지?','격리실 입원료에 의사 및 간호인력 확보수준에 따른 입원료 차등제, 필요인력 확보…','격리실 입원료 의사 간호인력 확보수준 차등제 필요인력 확보 보상제 적용되는지 간호사 간호조무사 간호등급 격리','○ 격리실 입원료에는 산정할 수 없음\n      격리실 입원환자수와 간호인력수 산정 시 적용방법은?\n○ 건강보험 행위 급여･비급여 목록표 및 급여상대가치점수 제1편 제2부 제1장 기본 진료료 [산정지침] 제2호 마목(2)에 따라 별도의 병동으로 구분 운영하지 않는 격리실에 입원한 환자수와 간호인력수는 모두 포함하여 산정함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 233쪽',233,8,128);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0129','PDF_QNA','PDF_QNA_09','PDF','QA','요양병원 격리실 입원료 체감제 적용방법은?','요양병원 격리실 입원료 체감제 적용방법은?','요양병원 격리실 입원료 체감제 적용방법 격리 장기입원 입원기간 9인이상 병실 감산','○ 요양병원 입원기간 중 일반병실 등과 격리병실을 전실한 경우 격리병실 입실 시점마다\n   1일로 기산하여 격리실 입원료를 산정함\n   ※ 요양병원 입원료 체감제 적용 기산점은 최초 입원일부터 적용\n   ▸ (예시 1) 일반병실(165일) → 격리병실(15일) → 일반병실(30일) → 격리병실(5일)\n      ☞ 격리실 입원료 100%*15일, 100%*5일 요양병원 입원료 100%*165일, 95%*30일\n      (예시 2) 일반병실(165일) → 격리병실(20일) → 일반병실(30일)\n      ☞ 격리실 입원료 100%*15일, 90%*5일 요양병원 입원료 100%*165일, 95%*30일','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 233쪽',233,8,129);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0130','PDF_QNA','PDF_QNA_09','PDF','QA','격리실 입원료 본인부담률 적용은?','격리실 입원료 본인부담률 적용은?','격리실 입원료 본인부담률 적용 격리','○ 국민건강보험법 시행령 제19조제1항 [별표2]에 따라 요양병원 입원환자의 본인일부 부담률을 적용함\n   신고･청구방법','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 234쪽',234,8,130);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0131','PDF_QNA','PDF_QNA_09','PDF','QA','격리병상으로만 운영하는 격리병실의 현황신고는?','격리병상으로만 운영하는 격리병실의 현황신고는?','격리병상으로 운영하 격리병실 현황신고 9인이상 병실 감산','○ 국민건강보험법 시행규칙 [별지 제14호 서식] ‘요양기관 현황신고서’의 ‘입원병실’란의 ‘격리병실’ 중 해당병실(비음압 등)로 신고하여야 함\n   ※ 하나의 병상을 격리병실 또는 일반병실 병상으로 이용할 경우에는 일반입원실 병상으로 신고','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 234쪽',234,8,131);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0132','PDF_QNA','PDF_QNA_09','PDF','QA','‘보건의료자원통합신고포털’의 운영병상 신고방법은?','‘보건의료자원통합신고포털’의 운영병상 신고방법은?','보건의료자원통합신고포털 운영병상 신고방법 격리실 격리 입원료 9인이상 병실 감산','○ 별도의 병동으로 구분 운영하는 경우에는 병동구분 ‘특수’, 병동코드 ‘격리병실’ 선택하여 운영병상수 신고\n○ 별도의 병동으로 구분 운영하지 않는 경우에는 격리실이 속한 일반병동에 포함하여 운영병상수 신고','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 234쪽',234,8,132);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0133','PDF_QNA','PDF_QNA_09','PDF','QA','요양병원 격리실에 입원한 경우 특정내역 기재란에 어떻게 기재하는지?','요양병원 격리실에 입원한 경우 특정내역 기재란에 어떻게 기재하는지?','요양병원 격리실 입원한 특정내역 기재란 어떻게 기재하는지 격리 입원료 9인이상 병실 감산','○ 요양병원 격리실에 입원한 경우 줄번호 단위 특정내역 구분코드 “JX999(기타내역)”란에 격리실 입원기간 From/To/인실 구분코드 기재\n   <병실 구분코드>\n   코드 병실 코드 병실','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 235쪽',235,8,133);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0134','PDF_QNA','PDF_QNA_09','PDF','QA','3인실 6 6인실 ▸ 기재형식：ccyymmdd/ccyymmdd/X(1) ▸ (예시 1) 요양병원 1인 격리실에 2019.1.1. 입실하여 2019.1.5.에 퇴실한 경우','3인실 6 6인실 ▸ 기재형식：ccyymmdd/ccyymmdd/X(1) ▸ (예…','3인실 6인실 기재형식 ccyymmdd 예시 요양병원 1인 격리실 2019 입실하여 퇴실한 격리 입원료','☞ 작성：JX999 20190101/20190105/1\n   (예시 2) 요양병원 1인 격리실에 2019.1.1.부터 2019.1.5.까지 입원 후 6인 격리실에 2019.1.5.부터 2019.1.10까지 입원한 경우\n      ☞ 작성：수가코드별 각각 특정내역 기재\n      JX999 20190101/20190105/1 JX999 20190105/20190110/6','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 235쪽',235,8,134);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0135','PDF_QNA','PDF_QNA_10','PDF','QA','간호인력 산정기준 개정 내용(재직일수 등)을 반영한 간호등급 적용 시점은?','간호인력 산정기준 개정 내용(재직일수 등)을 반영한 간호등급 적용 시점은?','간호인력 산정기준 개정 내용 재직일수 반영한 간호등급 적용 시점 간호사 간호조무사','○ 2019년 9월 15일부터 12월 14일까지의 인력현황을 적용하여 산출된 간호등급을 2020.1.1.입원 진료분부터 반영함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 236쪽',236,8,135);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0136','PDF_QNA','PDF_QNA_10','PDF','QA','1주간의 근로시간에 대한 기준은 근로계약서상 근로시간 기준인지?','1주간의 근로시간에 대한 기준은 근로계약서상 근로시간 기준인지?','1주간 근로시간 기준 근로계약서상 치매 인지기능 MMSE 인지','또는 실제 근로시간 기준인지?\n○ 근로계약서상의 근로시간과 실제 근로시간 두 가지를 모두 충족하여야 함. 요양기관의 사정상 주당 근무시간을 변경하여 주기적으로 반복되는 경우 월 평균 주당 근무시간을 기준으로 해당 기준을 적용함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 236쪽',236,8,136);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0137','PDF_QNA','PDF_QNA_10','PDF','QA','계약직 간호인력 및 단시간 근무 간호사가 2개 이상의 요양기관에서 동시에 인력 현황으로 신고 될 수 있는지?','계약직 간호인력 및 단시간 근무 간호사가 2개 이상의 요양기관에서 동시에 인력 …','계약직 간호인력 단시간 근무 간호사 2개 요양기관 동시 인력 현황 신고 있는지 간호조무사 간호등급','○ 2개 이상 요양기관에 중복 등재 할 수 없음.\n   간호인력 산정 시 2,000원 가산 구간에서 간호사 20명 및 간호조무사 10명 근무시','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 236쪽',236,8,137);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0138','PDF_QNA','PDF_QNA_10','PDF','QA','간호인력 대비 간호사 비율이 0.66(소수점 셋째자리에서 절사)일 경우 가산구간 포함여부?','간호인력 대비 간호사 비율이 0.66(소수점 셋째자리에서 절사)일 경우 가산구간…','간호인력 대비 간호사 비율 66 소수점 셋째자리 절사 가산구간 포함여부 간호조무사 간호등급','○ 「요양병원 입원료 차등제 산정현황 통보서 작성요령」에 따르면, 간호사수 및 간호 조무사수는 전전분기 마지막월 15일부터 전분기 마지막월 14일까지 간호인력별 재직 일수의 합을 해당 분기일수로 나누어 적용(소수점 3자리에서 반올림)하며, 간호사수 대 간호인력수는 소수점 3자리 이하 절사하여 기재함.\n○ 위에 따라 3개월 평균 간호사 20명, 간호조무사 10명이 근무하는 경우 간호사비율이 간호인력의 3분의2 이상인 경우에 해당하므로 1일당 2,000원 가산이 가능함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 236쪽',236,8,138);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0139','PDF_QNA','PDF_QNA_10','PDF','QA','신규개설기관의 환자수, 간호인력 산정기준 및 등급 적용기준은?','신규개설기관의 환자수, 간호인력 산정기준 및 등급 적용기준은?','신규개설기관 환자수 간호인력 산정기준 등급 적용기준 간호사 간호조무사 간호등급','○ 분기 마지막 월 14일 이전 개설기관의 해당 분기의 기관등급은 기본등급으로 하고, 다음 분기의 기관등급은 아래의 기준에 따라 산정함.\n   - 입원 환자수는 개설 당일부터 해당 분기의 마지막 월 14일까지의 입원환자를 평균하여 산정함.\n   - 간호인력은 개설 당일부터 해당 분기 마지막 월 14일까지의 재직일수를 평균하여 산정함.\n○ 분기 마지막 월 15일 이후 개설기관의 해당분기 및 다음 분기의 기관등급은 기본 등급으로 함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 237쪽',237,8,139);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0140','PDF_QNA','PDF_QNA_11','PDF','QA','환자지원팀 구성원 중 ‘기타 환자지원에 필요한 인력’은 어떤 인력인지?','환자지원팀 구성원 중 ‘기타 환자지원에 필요한 인력’은 어떤 인력인지?','환자지원팀 구성원 환자지원 필요한 인력 어떤 치매 인지기능 MMSE 인지 약사 약사인력 재직일수 영양 경관영양 섭취 수분','○ 요양병원에 상근하는 인력으로 환자지원에 필요한 구성원을 말함.\n   <예> 약사, 영양사, 물리치료사, 작업치료사, 언어치료사 등','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 238쪽',238,8,140);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0141','PDF_QNA','PDF_QNA_11','PDF','QA','환자지원팀을 구성한 경우, 별도로 신고 해야 하는지?','환자지원팀을 구성한 경우, 별도로 신고 해야 하는지?','환자지원팀 구성한 별도 신고 해야 하는지 간호인력 간호사 간호조무사 간호등급','○ 환자지원팀의 필수인력인 의사, 간호사, 사회복지사는 상근이어야 하며 건강보험심사 평가원에 환자지원팀으로 신고 해야 함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 238쪽',238,8,141);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0142','PDF_QNA','PDF_QNA_11','PDF','QA','입원환자 간호업무 전담 간호사도 환자지원팀 업무를 할 수 있는지?','입원환자 간호업무 전담 간호사도 환자지원팀 업무를 할 수 있는지?','입원환자 간호업무 전담 간호사 환자지원팀 업무 있는지 간호인력 간호조무사 간호등급','○ 중복가능. ‘간호인력 확보수준에 따른 요양병원 입원료 차등제’ 산정 대상에 포함하여 적용 가능. 다만, 지역연계를 위한 연계 기관 방문업무는 불가능함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 238쪽',238,8,142);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0143','PDF_QNA','PDF_QNA_11','PDF','QA','‘필요인력 확보에 따른 별도 보상제’ 적용을 받는 사회복지사도 환자지원팀 업무를 할 수 있는지?','‘필요인력 확보에 따른 별도 보상제’ 적용을 받는 사회복지사도 환자지원팀 업무를…','필요인력 확보 보상제 적용 사회복지사 환자지원팀 업무 있는지 ','○ 상근하는 사회복지사가 원내 치료과정 참여 등 사회복지 업무를 수행하는 경우 환자 지원팀 업무를 겸직가능하며, ‘필요인력 확보에 따른 별도 보상제’의 산정 대상 인력에도 포함하여 적용 가능함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 238쪽',238,8,143);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0144','PDF_QNA','PDF_QNA_11','PDF','QA','‘요양병원 지역사회 연계료’는 입원 120일 이내에 퇴원하는 경우에도 산정 가능한지?','‘요양병원 지역사회 연계료’는 입원 120일 이내에 퇴원하는 경우에도 산정 가능…','요양병원 지역사회 연계료 입원 120일 이내 퇴원하 경우에 퇴원지원 복귀 장기입원 체감제 입원기간','○ ‘요양병원 지역사회 연계료’는 장기입원으로 인해 지역사회와 단절된 환자들의 원활한 지역사회 복귀를 돕는 활동에 대한 수가이므로 120일이 경과한 후 퇴원 예정인 환자를 대상으로 하며, 120일 이내에 퇴원한 경우 산정 불가함.\n   ※ 120일 경과는 입원일로부터 121일째를 의미','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 239쪽',239,8,144);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0145','PDF_QNA','PDF_QNA_11','PDF','QA','퇴원 후 재 입원시 ‘요양병원 지역사회 연계료’를 산정할 수 있는 기산점은 언제인지?','퇴원 후 재 입원시 ‘요양병원 지역사회 연계료’를 산정할 수 있는 기산점은 언제…','퇴원 입원시 요양병원 지역사회 연계료 산정할 기산점 언제 치매 인지기능 MMSE 인지 퇴원지원 복귀','○ 재입원 일을 기산점으로 하여 입원 120일이 경과 후 퇴원이 예정되어 있는 경우 산정 가능함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 239쪽',239,8,145);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0146','PDF_QNA','PDF_QNA_11','PDF','QA','환자지원팀 필수인력(기존, 신규) 교육이수 방법은 어떻게 되는지?','환자지원팀 필수인력(기존, 신규) 교육이수 방법은 어떻게 되는지?','환자지원팀 필수인력 기존 신규 교육이수 어떻게 되는지 간호인력 간호사 간호조무사 간호등급','○ 환자지원팀의 필수인력(의사, 간호사, 사회복지사)중 1인 이상은 매년 1회 이상 국민 건강보험공단에서 실시하는 요양병원 퇴원환자지원 기본교육을 이수하여야 함.\n   * 교육 관련 내용은 공단 정보시스템(요양기관정보마당)을 통해 안내(교육 관련 문의：\n      1577-1000)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 239쪽',239,8,146);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0147','PDF_QNA','PDF_QNA_11','PDF','QA','교육을 이수한 환자지원팀 필수인력(기존, 신규)의 교육 이수 신고 방법?','교육을 이수한 환자지원팀 필수인력(기존, 신규)의 교육 이수 신고 방법?','교육 이수한 환자지원팀 필수인력 기존 신규 이수 신고 지역사회 연계료 퇴원지원 복귀','- 기존：청구기관은 ’20.12.31. 전까지 신고\n   - 신규：요양병원 지역사회 연계료 최초청구 전까지 신고','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 239쪽',239,8,147);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0148','PDF_QNA','PDF_QNA_11','PDF','QA','요양병원 지역사회 연계료는 교육 이수일과 신고일 중 어느 날부터 적용되나요?','요양병원 지역사회 연계료는 교육 이수일과 신고일 중 어느 날부터 적용되나요?','요양병원 지역사회 연계료 교육 이수일 신고일 어느 적용되 퇴원지원 복귀','이수일부터 산정 가능.\n요양병원 지역사회 연계 평가료(관련 상담 활동 포함) 및 관리료 Ⅰ, Ⅱ','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 239쪽',239,8,148);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0149','PDF_QNA','PDF_QNA_11','PDF','QA','‘요양병원 지역사회 연계 평가료’ 산정을 위한 환자지원 심층평가는 누가 실시해야 하는지?','‘요양병원 지역사회 연계 평가료’ 산정을 위한 환자지원 심층평가는 누가 실시해야…','요양병원 지역사회 연계 평가료 환자지원 심층평가 실시해야 하는지 간호인력 간호사 간호조무사 간호등급 연계료 퇴원지원 복귀','○ 환자지원팀에 속한 의사, 간호사, 사회복지사가 실시하여야 함. 심층평가는 환자의 사회경제환경을 파악하기 위하여 환자(또는 보호자)를 대상으로 30분 이상 상담을 하고 평가하는 것을 원칙으로 함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 240쪽',240,8,149);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0150','PDF_QNA','PDF_QNA_11','PDF','QA','‘요양병원 지역사회 연계 관리료 Ⅰ, Ⅱ’를 산정하기 위한 연계활동은 무엇인지?','‘요양병원 지역사회 연계 관리료 Ⅰ, Ⅱ’를 산정하기 위한 연계활동은 무엇인지?','요양병원 지역사회 연계 관리료 산정하기 연계활동 무엇 치매 인지기능 MMSE 인지 연계료 퇴원지원 복귀','○ 지역사회 연계활동이란, 환자별 건강상태 및 사회경제환경을 바탕으로 환자지원팀이 회의를 통해 환자 맞춤형 퇴원지원 표준계획을 수립하고, 환자에게 필요한 지역사회 자원을 섭외하여 연계 및 조정 하는 활동을 말함.\n○ 시군구내의 사회복지기관, 보건소, 치매안심센터, ‘지역사회 통합 돌봄 계획’에 따라 설치된 지자체의 케어안내창구, ‘복지로’에 등록된 민간서비스단체 등을 통해 환자에게 직접 제공되는 서비스(일자리, 주거, 일상생활, 신체건강 및 보건의료, 정신건강 및 심리정서, 보호 및 돌봄, 요양, 안전 및 권익보장 등)를 연계하는 활동이며,\n   - ‘연계 안내서’를 환자(또는 보호자)에게 제공해야함.\n    ※ 공단 요양기관정보마당에서 출력\n○ 다만, 노인장기요양보험 대리 신청 및 급여 연계, 국민건강보험공단의 만성질환관리 프로그램연계, 타 의료기관 연계, 본인부담상한제 대리 신청, 재난적 의료비 신청만 이루어진 경우에는 수가 산정이 불가능함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 240쪽',240,8,150);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0151','PDF_QNA','PDF_QNA_11','PDF','QA','‘요양병원 지역사회 연계 관리료Ⅰ’은 연계여부와 관계없이 퇴원지원 표준계획만 시행해도 수가산정이 가능한지?','‘요양병원 지역사회 연계 관리료Ⅰ’은 연계여부와 관계없이 퇴원지원 표준계획만 시…','요양병원 지역사회 연계 관리료 연계여부 관계없 퇴원지원 표준계획 시행해 수가산정 연계료 복귀','○ 퇴원지원 표준계획서를 작성하고 퇴원 시 해당 계획서에 따라 필요한 지역사회 자원과 연계한 경우 산정 가능함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 240쪽',240,8,151);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0152','PDF_QNA','PDF_QNA_11','PDF','QA','퇴원지원 표준계획은 요양병원에 입원한 모든 환자를 대상으로 작성해야 하는지?','퇴원지원 표준계획은 요양병원에 입원한 모든 환자를 대상으로 작성해야 하는지?','퇴원지원 표준계획 요양병원 입원한 모든 환자 대상 작성해야 하는지 지역사회 연계료 복귀','○ 지역연계가 필요한 환자를 대상으로 함.\n○ 다만, 입원 120일이 경과하여 환자지원 심층평가를 시행 하고 나서 퇴원지원표준계획을 작성하여야 함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 241쪽',241,8,152);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0153','PDF_QNA','PDF_QNA_11','PDF','QA','두 가지 이상의 지역사회 자원을 연계한 경우 ‘지역사회 연계 관리료’를 각각 산정할 수 있는지?','두 가지 이상의 지역사회 자원을 연계한 경우 ‘지역사회 연계 관리료’를 각각 산…','가지 지역사회 자원 연계한 연계 관리료 산정할 있는지 연계료 퇴원지원 복귀','○ 여러 가지 지역사회 자원을 연계하더라도 ‘지역사회 연계 관리료’는 퇴원 시 1회만 산정할 수 있음.\n    지역사회 연계 시, 두 가지 연계 방법(유선 또는 팩스 이용, 직접 방문)을 모두 시행한 경우 ‘요양병원 지역사회 연계 관리료Ⅰ,Ⅱ’를 각각 산정할 수 있는지?\n○ 여러 가지 방법을 통해 지역사회 연계를 하였더라도 ‘요양병원 지역사회 연계료 Ⅰ, Ⅱ’를 동시에 산정할 수 없으며 주된 항목의 소정점수만 산정 가능함.\n[붙임]\n요양병원 지역사회 연계료 관련 신고방법 안내 고시 제2019-182,183(2019.8.22.) ‘요양병원 지역사회연계료’ 관련 ‘환자지원교육’ 신고\n■ 차등제 운영병상 및 인력 등 신고방법\n\n■ 환자지원교육 신고방법','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 241쪽',241,8,153);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0154','PDF_QNA','PDF_QNA_12','PDF','QA','요양병원 입원환자 안전관리료는 모든 요양병원에서 산정할 수 있는지?','요양병원 입원환자 안전관리료는 모든 요양병원에서 산정할 수 있는지?','요양병원 입원환자 안전관리료 모든 산정할 있는지 환자안전 전담인력 인증 의료기관인증 인증조사 가산','○ 의료법 제3조제2항제3호에 의한 요양병원(단, 「장애인복지법」 제58조제1항제4호에 따른 의료재활시설은 제외*)중 「환자안전법」 제11조･제12조를 준수하고 「의료법」\n   제58조･제58조의3에 따라 의료기관평가인증원에서 실시하는 의료기관 인증결과 ‘인증’ 또는 ‘조건부인증’ 등급을 받은 200병상 이상 요양병원에서 산정할 수 있음.\n   - 이때, 병상 수는 의료법령에 따른 허가병상 수 기준이며, 「국민건강보험법」 제43조에 * 의료법(법률 제17069호, 2021.2.5. 시행) 개정에 따른 문구 수정 입원환자 안전관리료 청구 시 항, 목 구분은 어떻게 되는지?\n○ 입원환자 안전관리료는 1항 03목으로 청구함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 245쪽',245,8,154);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0155','PDF_QNA','PDF_QNA_12','PDF','QA','입원환자 안전관리료는 입원일수별로 산정할 수 있는지?','입원환자 안전관리료는 입원일수별로 산정할 수 있는지?','입원환자 안전관리료 입원일수별 산정할 있는지 환자안전 전담인력','○ 입원환자 안전관리료는 환자 당 입원일수별로 산정할 수 있음. 다만, 외박 시에는 산정할 수 없음.\n   <예시> 4박 5일 입원한 경우 5회 산정\n   <예시> 4박 5일 입원 중 1일 외박한 경우 4회 산정','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 245쪽',245,8,155);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0156','PDF_QNA','PDF_QNA_12','PDF','QA','0~6시 사이에 입원하거나, 18~24시 사이에 퇴원하여 입원료의 50%를 별도 산정한 경우 입원환자 안전관리료 산정이 가능한지?','0~6시 사이에 입원하거나, 18~24시 사이에 퇴원하여 입원료의 50%를 별도…','6시 사이 입원하거나 18 24시 퇴원하여 입원료 50 산정한 입원환자 안전관리료 환자안전 전담인력','○ 입원환자 안전관리료는 입원 1일당 1회 산정하는 수가로 입원료의 50%가 별도 산정된 경우에는 산정할 수 없음.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 246쪽',246,8,156);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0157','PDF_QNA','PDF_QNA_12','PDF','QA','퇴원 당일 재입원한 경우 입원환자 안전관리료 산정방법은 어떻게 되는지?','퇴원 당일 재입원한 경우 입원환자 안전관리료 산정방법은 어떻게 되는지?','퇴원 당일 재입원한 입원환자 안전관리료 산정방법 어떻게 되는지 환자안전 전담인력','○ 퇴원 후 당일 재입원한 경우에는 계속 입원 중 이었던 환자로 간주하여 1일 1회 산정함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 246쪽',246,8,157);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0158','PDF_QNA','PDF_QNA_12','PDF','QA','요양병원 입원환자 안전관리료를 산정하는 요양병원의 환자안전 활동 시행 확인 방법은?','요양병원 입원환자 안전관리료를 산정하는 요양병원의 환자안전 활동 시행 확인 방법은?','요양병원 입원환자 안전관리료 산정하 환자안전 활동 시행 확인 전담인력 인증 의료기관인증 인증조사 가산','○ 「환자안전법」 제11조·제12조를 준수하고 「의료법」 제58조‧제58조의3에 따라 ‘인증’\n   또는 ‘조건부인증’ 등급을 받은 200병상 이상 요양병원으로 전담인력 배치, 환자안전 위원회를 설치·운영하는 기관은 매년 1월 31일까지 전년도 환자안전위원회 운영계획 및 활동증빙서류를 의료기관평가인증원 환자안전 보고학습시스템(환자안전 서비스 포털)을 통해 제출하여야함\n   - 미제출 시 해당년도 2월 1일부터 다음 연도 1월 31일까지 요양병원 입원환자 안전 관리료를 산정할 수 없음\n      * (단, 제출기간 이후 제출 시 최종제출일 이후 산정가능)\n○ 신설 또는 요양병원 입원환자 안전관리료를 최초 청구하는 요양병원은 해당년도 환자 안전위원회 운영계획을 의료기관평가인증원에 제출한 후 수가를 적용하여야 하고,\n   - 다음 연도 1월 31일까지 전년도 환자안전위원회 운영계획 및 활동 증빙서류를 제출 하여야 함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 246쪽',246,8,158);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0159','PDF_QNA','PDF_QNA_12','PDF','QA','환자안전 전담인력으로 배치하는 경우 입원료 차등제 인력과 중복 적용 할 수 있는지?','환자안전 전담인력으로 배치하는 경우 입원료 차등제 인력과 중복 적용 할 수 있는지?','환자안전 전담인력 배치하 입원료 차등제 인력 중복 적용 있는지 ','○ 중복 적용할 수 없음. 환자안전 전담인력으로 배치된 인력은 입원료 차등제 산정 대상에서 제외하여야 함.\n   전담인력 기준','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 247쪽',247,8,159);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0160','PDF_QNA','PDF_QNA_12','PDF','QA','전담인력 및 환자안전위원회 현황 신고방법은 어떻게 되는지?','전담인력 및 환자안전위원회 현황 신고방법은 어떻게 되는지?','전담인력 환자안전위원회 현황 신고방법 어떻게 되는지 인증 의료기관인증 인증조사 가산','○ 전담인력 배치현황 및 환자안전위원회 설치현황을 「환자안전법」시행규칙 제9조5항에 따라 의료기관평가인증원에 신고*하여야 하며, 현황 변경 시(신규배치·해지 등) 지체 없이 변경신고 하여야함.\n   * 의료기관평가인증원의 환자안전 보고학습시스템(환자안전 서비스포털)을 통해 신고\n○ 또한, 인증원에 신고 된 전담인력은 심평원에 신고 되어 있는 요양기관현황(인력 등)에도 신고가 되어 있어야 함.\n   ※ 신규 및 기존인력 중 미 신고 또는 변경사항이 있는 경우 (변경)신고 필수','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 247쪽',247,8,160);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0161','PDF_QNA','PDF_QNA_12','PDF','QA','전담인력 배치현황이 변경되어 배치기준을 충족하지 않는 경우 수가 산정 방법은 어떻게 되는지?','전담인력 배치현황이 변경되어 배치기준을 충족하지 않는 경우 수가 산정 방법은 어…','전담인력 배치현황 변경되어 배치기준 충족하지 어떻게 되는지 인증 의료기관인증 인증조사 가산','○ 배치현황 변경 시 지체 없이 의료기관평가인증원에 변경 신고를 하여야 하며, 배치 기준을 만족하지 못하는 날부터 수가 산정은 불가능함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 247쪽',247,8,161);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0162','PDF_QNA','PDF_QNA_12','PDF','QA','전담인력이 환자안전과 관련된 업무만 시행하여야 하는지?','전담인력이 환자안전과 관련된 업무만 시행하여야 하는지?','전담인력 환자안전 관련된 업무 시행하여야 하는지 ','○ 전담인력은 환자안전 업무를 위해 배치된 인력으로 환자안전법에 따른 업무만 시행 하여야 함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 248쪽',248,8,162);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0163','PDF_QNA','PDF_QNA_12','PDF','QA','전담인력(기존, 신규) 교육이수 방법은 어떻게 되는지?','전담인력(기존, 신규) 교육이수 방법은 어떻게 되는지?','전담인력 기존 신규 교육이수 어떻게 되는지 ','○ 「환자안전법」 제13조, 동법 시행규칙 제10조 및 제11조에 따름.\n   산정방법','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 248쪽',248,8,163);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0164','PDF_QNA','PDF_QNA_12','PDF','QA','요양병원 입원환자 안전관리료 산정 시, 줄번호 특정내역기재 방법은?','요양병원 입원환자 안전관리료 산정 시, 줄번호 특정내역기재 방법은?','요양병원 입원환자 안전관리료 줄번호 특정내역기재 환자안전 전담인력 9인이상 병실 감산','○ ’22년 1월 1일 진료분부터 ‘요양병원 입원환자 안전관리료’ 산정 시, 6인 이하 병실에 입원한 환자의 경우 줄번호 특정내역 JT029를 기재하여 청구함.\n      < 특정내역 JT029 작성요령 >\n    ▶ 기재요령: (6인 이하 병실) From/To\n    ▶ 기재형식: ccyymmdd/ccyymmdd\n    ▶ 기재예시\n      - 2022년 1월 1일에 A요양병원 7인실로 입원 한 환자가 1월 15일 6인실로 전실 후 1월 30일에 퇴원 한 경우 특정내역 구분코드 특정내역 JT029 20220115/20220130','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 248쪽',248,8,164);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0165','PDF_QNA','PDF_QNA_12','PDF','QA','계속 입원중인 환자의 명세서 청구 시, 요양병원 입원환자 안전관리료 산정을 위한 줄번호 특정내역 기재 방법은?','계속 입원중인 환자의 명세서 청구 시, 요양병원 입원환자 안전관리료 산정을 위한…','계속 입원중인 환자 명세서 청구 요양병원 입원환자 안전관리료 줄번호 특정내역 환자안전 전담인력 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 9인이상 병실 감산','○ 명세서마다 ‘요양병원 입원환자 안전관리료’ 줄번호에 특정내역 JT029를 기재하며, 해당 명세서의 요양개시일자 및 마지막날짜를 입실일/퇴실일로 간주하여 특정내역을 작성함.\n   ▶ (예시) 2022년 1월 1일에 A요양병원 6인실에 입원한 환자가 2022년 2월 13일에 퇴원 한 경우\n      ☞ (1월명세서) JT029 20220101/20220131 (2월명세서) JT029 20220201/20220213\n      ※ 명세서를 분리청구 해야 하는 경우(ex. 정액수가 기간 중 특정기간이 발생하는 등)에도 동일 적용함.\n      7인 이상 병실에 입원 해 있던 환자가 6인 이하 병실로 전실되는 경우, 전실하는','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 249쪽',249,8,165);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0166','PDF_QNA','PDF_QNA_12','PDF','QA','날의 입원환자 안전관리료는?','날의 입원환자 안전관리료는?','입원환자 안전관리료 환자안전 전담인력 9인이상 병실 감산','○ 7인 이상 병실에서 6인 이하 병실로 전실하는 경우, 전실하는 당일 수진자가 더 오랫 동안 체류한 쪽 병실의 기준에 따라 산정함.\n- 6인 이하 병실에 더 오랫동안 체류한 경우 요양병원 입원환자 안전관리료는 산정 가능 함.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 249쪽',249,8,166);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0167','PDF_QNA','PDF_QNA_13','PDF','QA','“정당한 사유 없이 인증조사에 협조하지 않은 경우”에서 정당한 사유란?','“정당한 사유 없이 인증조사에 협조하지 않은 경우”에서 정당한 사유란?','정당한 사유 인증조사 협조하지 사유란 인증 의료기관인증 가산','○ 재해로 인한 의료기관 시설의 멸실, 영업정지, 폐업, 휴업 등으로 인증조사 시행의 의미가 없어진 경우를 말함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 250쪽',250,8,167);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0168','PDF_QNA','PDF_QNA_13','PDF','QA','개정되는 요양병원 인증조사에 따른 가산 배제가 적용되는 시점은?','개정되는 요양병원 인증조사에 따른 가산 배제가 적용되는 시점은?','개정되 요양병원 인증조사 가산 배제 적용되 시점 인증 의료기관인증','○ ’21년 10월 07일 이후 인증조사를 신청 또는 재신청하는 요양병원을 대상으로 함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 250쪽',250,8,168);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0169','PDF_QNA','PDF_QNA_13','PDF','QA','가산배제 해당기관으로 수회 통보된 경우 배제 횟수는 어떻게 적용되는지?','가산배제 해당기관으로 수회 통보된 경우 배제 횟수는 어떻게 적용되는지?','가산배제 해당기관 수회 통보된 배제 횟수 어떻게 적용되는지 안전관리료 환자안전 전담인력','○ 가산 배제 해당기관으로 통보될 때 마다 통보 시점이 속한 분기의 직후 1분기 동안 입원료 (인력) 가산 및 필요인력 확보에 따른 별도 보상을 배제함\n참고 상급종합병원·종합병원 등에 적용하는 입원환자 안전관리료 급여 기준 등\n      제1장 기본진료료\n가29 입원환자 입원환자 안전관리료는 아래와 같은 조건을 모두 갖춘 요양 입원환자 안전관리료 기관의 경우, 입원환자 입원 1일당 1회 산정함\n안전관리료 산정기준 -아 래-\n      가. 대상기관\n      1) 상급종합병원, 종합병원, 200병상 이상 병원･정신병원 가) ｢환자안전법｣ 제11조･제12조 및 동법 시행규칙 제5조･\n      제9조제1항에 해당하는 의료기관으로 전담인력을 배치 하고, 환자안전위원회를 설치･운영하는 기관 나) 「의료법 시행규칙」 제39조의6에 해당하는 의료기관으로 보안장비 설치, 보안인력 배치 등 기준을 충족하는 기관\n      2) 100병상 이상~200병상 미만 병원･정신병원\n      「의료법 시행규칙」 제39조의6에 해당하는 의료 기관으로 보안장비 설치, 보안인력 배치 등 기준을 충족하는 기관\n      3) 200병상 이상 한방병원\n      ｢환자안전법｣ 제11조･제12조 및 동법 시행규칙 제5조･제9 조제1항에 해당하는 의료기관으로 전담인력을 배치하고, 환자안전위원회를 설치･운영하는 기관\n      나. 위 ‘가’ 1)에 해당하는 기관은 다음 1)~4)의 기준을 모두 충족하여야 하며, 위 ‘가’ 2)에 해당하는 기관은 다음 4)의 기준을 충족해야 하며, 위 ‘가’ 3)에 해당하는 기관은 1)~3)의 기준을 충족해야함\n      1) 환자안전위원회는 「환자안전법」 제11조제3항 및 동법 시행 규칙 제8조에 명시된 업무를 시행하여야 하며, 위원회 구성은 동법 시행규칙 제6조를 따름\n      2) 전담인력은 「환자안전법」 제12조제3항 및 동법 시행규칙\n      제9조제5항에 따른 업무를 시행하여야 하며, 환자안전활동에 대한 연간 계획을 수립하고 관리하여야 함\n3) 「환자안전법」 제9조 및 동법 시행령 제6조에 따른 환자안전 기준 준수를 위해 아래의 가), 나)를 포함한 체계적인 활동을 시행하여야 함\n      가) 입원환자 병문안 관리 규정을 자체적으로 수립하고 이를 시행하여야 함\n      나) 입원기간 동안 낙상, 욕창 예방 및 관리 등을 시행하여야 함\n      4) 보안관리 기준은 「의료법 시행규칙」 제39조의6에 따라 가), 나) 를 충족해야 함\n      가) 의료인 및 환자에 대한 폭력행위를 관할 경찰관서에 신고할 수 있는 비상경보장치를 설치･운영해야 함\n      나) 보안 전담인력을 요양기관별 1인 이상 배치하여야 함\n      다) 입원환자 안전관리료를 산정하는 요양기관은 별지 제26호 서식에 의한 보안인력 현황신고서를 최초 수가 청구전까지 제출하여야 하며, 최초 신고 이후 변경이 있는 경우 지체없이 변경 내용을 신고하여야 함\n      (고시 제2021-88호, 2021.3.24. 시행)\n      입원환자 입원환자 안전관리료 산정을 위한 전담인력기준은 아래와 같이함\n      안전관리료 -아 래-\n      인력기준 가. 전담인력은 「환자안전법」 시행규칙 제9조제2항에 따라 다음\n      각 호중 하나에 해당하는 자격을 갖추어야 함.\n      1) 의사･치과의사 또는 한의사 면허를 취득한 후 3년 이상 보건의료기관에서 근무한 사람\n      2) 「의료법」 제77조에 따른 전문의 자격이 있는 사람\n      3) 간호사 면허를 취득한 후 3년 이상 보건의료기관에서 근무한 사람\n      나. 전담인력은 「환자안전법」 제13조 및 동법 시행규칙 제10조에 따라 환자안전 활동에 관한 교육을 매년12시간 이상 정기적으로 받아야 함. 다만, 새로 배치된 경우에는 6개월 이내에 24시간 이상 이수하여야 함.\n다. 대상기관은 「환자안전법 시행규칙」 제9조제3항에 따라 위의 ‘가’ 및 ‘나’항을 모두 만족한 전담인력을 해당기관에 배치 하여야 함.\n      1) 500병상 이상 종합병원급：2명 이상\n      2) 100병상 이상~ 500병상 미만 종합병원급：1명 이상\n      3) 200병상 이상 병원급：1명 이상\n      라. 현황신고\n      1) 「환자안전법」 제11조 및 12조에 따른 환자안전위원회 구성･ 운영 및 전담인력 배치현황은 의료기관평가인증원에 신고 하여야 함\n      2) 「환자안전법」 시행규칙 제9조4항에 따라 전담인력 현황변경 시 (신규배치･해지 등) 의료기관평가인증원에 지체없이 신고 하여야 함\n      (고시 제2020-330호, 2021.1.1. 시행)\n    입원환자 입원환자 안전관리료 산정을 위한 병문안 관리기준은 다음과 안전관리료 같이 함.\n    병문안\n      -다 음-\n    관리기준\n      1. 입원환자 안전관리료 산정을 위한 병문안 관리기준을 충족 하기 위해서는 ‘병문안 관리 규정’ 및 ‘병문안 관리방법’을\n      2. ‘병문안 관리 규정’(이하 규정)은 아래 기준을 모두 충족해야 함.\n      -아 래-\n      가. 의료기관에서 자체적으로 수립하고 기관장 결재를 마친 규정이어야 함\n      나. 규정에는 다음 5가지 내용이 모두 포함되어야 함\n      1) 병문안 허용시간대\n      2) 병문안 제한 대상\n      3) 병문안객 관리대장 양식 및 운영방법\n      4) 반입금지 물품 목록\n5) 병문안 관리 방법\n      다. 기관장 직인이 포함된 규정 전문을 첨부파일로 제출해야 함\n      3. ‘병문안 관리 방법’은 아래 기준을 모두 충족해야 함.\n      -아 래-\n      가. 병문안객 관리를 위한 ‘시설’, ‘인력’, ‘기타’ 중 하나 이상의 방법을 운영하고 있어야 함\n      1) ‘시설’은 ID카드 등을 이용하여 허용된 사람에 한해 개폐가 가능한 고정 시설물을 의미하며, 건물별로 1개 이상 설치되어 있어야 함.\n      2) ‘인력’은 규정에 정해진 시간 동안 병문안객 관리를 전담하는 사람을 의미하며, 외부 보안관리 전문기관 과의 계약에 따라 배치된 사람은 포함되나 단순 안내 요원 및 자원봉사자, 사회복무요원 등은 제외함. 기관 별로 1명 이상이 배치되어 있어야 하며, 인력 배치 현황(인력수, 근무시간, 장소) 및 근무대장을 관리･ 작성하여야 함.\n      3) ‘기타’는 위 1) 또는 2)에 해당하지 않지만 병문안객 관리가 가능한 방법을 의미함\n      나. ‘가’항에 따른 운영현황을 증빙할 수 있는 자료(‘시설’의 경우 도면, 사진 등, ‘인력’의 경우 근로계약서, 근무대장 등)를 첨부파일로 제출해야 함.\n      4. 입원환자 안전관리료를 산정하는 요양기관은 별지 제 14호 서식에 의한 입원환자 병문안 관리 현황신고서를 최초 수가 청구 전까지 (단, 기존 산정기관은 ’18.7월말까지) 건강보험 심사평가원에 제출하여야 하며, 최초 신고 이후 변경이 있는 경우 지체없이 변경 내용을 신고해야 함.\n      (고시 제2018-114호, 2018.8.1. 시행)\n[별지 제14호 서식] (앞면)\n      입원환자 병문안 관리 현황 신고서 1. 신규 ※\n      2. 변경\n요양기관명 요양기관기호\n소 재 지 담당자 성명 전화번호\n      [입원환자 병문안 관리 현황]\n병문안 관리 병문안 허용시간대 병문안 제한 대상 병문안객 관리대장 규정 (포함여부) ※ 1. 포함 2. 미포함 ※ 1. 포함 2. 미포함 ※ 1. 포함 2. 미포함 ※ 1. 포함 2. 미포함\n병문안 관리 시설 인력\n    방법 ※ 1. 해당 2. 미해당 ※ 1. 해당 2. 미해당 ※ 1. 해당 2. 미해당\n      [입원환자 병문안 시설 현황]\n      시설종류 설치장소 설치개수 적용일자\n설치시설\n      [입원환자 병문안 인력 현황]\n운영현황 ※ (1：전속 2：위탁 3：병행)\n      업 소 명 칭 대표자\n위탁운영\n      사업자등록번호 전화번호\n      [입원환자 병문안 인력별 세부현황]\n      근무현황\n      위탁여부 근무형태\n연번 성명 주민등록번호 ※1：전속 ※1：전담 2：위탁 2：겸임 최초근무일자 최종근무일자 입원환자 병문안 관리 인력：총 명 입원환자 병문안 관리 현황을 제출합니다.\n[증빙자료 목록]\n      년 월 일\n      개설자(대표자) (서명 또는 인)\n      작성자 (서명 또는 인)\n주) 세부작성요령은 뒷면을 참조하여 작성하시기 바라며, ※란은 반드시 해당 번호를 기재하여야 합니다.\n[별지 제14호 서식]\n      (뒷면)\n      입원환자 병문안 관리 현황 신고서 작성요령\n[입원환자 병문안 관리 현황]\n○ 병문안 관리 규정에 ~의 내용이 포함되어 있으면 ‘1. 포함’, 포함되지 않으면 ‘2. 미포함’으로 표시\n○ 병문안 관리 방법은 ~의 방법으로 관리 중이면 ‘1. 해당’, 해당하지 않으면 ‘2. 미해당’으로 표시\n- 병문안 관리 방법별 세부 내용은 이하 세부 내용 참조\n[입원환자 병문안 시설 현황]\n○ 설치시설은 허용된 사람에 한해 개폐가 가능한 고정식 시설로, 건물별로 최소 1개 이상 설치되어 있어야 함.\n   단순 터치에 의해 개폐되는 자동 도어와 정신과폐쇄병동에 설치된 시설은 해당하지 않음.\n○ 시설종류는 바코드인식 시스템, RFID 인식 시스템, 스크린도어 등으로 구분하여 작성함\n○ 설치장소는 주출입구, 엘리베이터, 일반병동 등으로 구분하여 작성함. 간호간병포괄서비스병동, 응급실, 중환자실에 설치된 경우는 제외함.\n○ 설치개수는 설치장소별로 구분하여 작성함\n○ 적용일자는 설치를 기준으로 하여 8자리(YYYYMMDD)로 작성함.\n[입원환자 병문안 인력 현황]\n○ 운영현황은 해당 의료기관 소속인 경우 ‘1. 전속’, 위탁운영인 경우 ‘2. 위탁’, 1과 2를 병행하는 경우 ‘3. 병행’으로 표시\n○ 위탁운영 내용은 운영현황이 ‘2. 위탁’ 또는 ‘3. 병행’인 경우에 한해 작성\n[입원환자 병문안 인력별 세부현황]\n○ 병문안 관리 인력은 해당 의료기관에서 주 40시간 이상 병문안객 관리를 담당하는 인력을 의미하며, 단순 안내요원, 자원봉사자, 사회복무요원 등은 해당하지 않음.\n○ 정규직이 아닌 경우 「기간제 및 단시간근로자보호 등에 관한 법률」 제17조(근로조건의 서면명시)를 준수하고, 4대 사회보험에 가입 및 고용계약을 체결한 경우에만 해당됨\n○ 병문안 관리 인력은 내부 규정에 따른 근무시간에 해당 근무장소에 근무해야 하며, 근무대장을 작성･관리･ 보관해야 함.\n○ 위탁여부는 해당 의료기관에 전속된 경우 ‘1. 전속’, 위탁계약에 따라 근무하는 경우 ‘2. 위탁’으로 표시\n○ 근무형태는 해당 의료기관에서 주 40시간 이상 병문안 관리 인력으로 근무하면 ‘1. 전담’, 주 20시간 이상 40시간 미만을 근무하면 ‘2. 겸임’으로 표시. 겸임의 경우 근무시간과 인력수를 고려하여 주 40시간 이상 병문안 관리가 가능한 경우에만 병문안 관리 인력으로 인정함\n○ 최초근무일자 및 최종근무일자는 병문안 관리 인력으로 근무한 최초근무일자 및 최종근무일자 기준으로 하며 8자리(YYYYMMDD)로 작성함\n[증빙자료]\n○ 병문안 관리 규정은 의료기관장의 직인이 날인된 전문을 첨부파일(PDF, HWP 등) 형태로 제출\n○ 시설은 설치 도면 또는 사진을 첨부파일(PDF, JPG 등)로 제출하되, 건물별 1개 이상 제출\n○ 인력은 의료기관 소속인 경우 근로계약서와 재직증명서 중 1종류와 근무대장(최근 15일 이내), 위탁계약인 경우 위탁운영계약서와 근무대장(최근 15일 이내)을 첨부파일(PDF, JPG 등)로 제출\n○ 병문안 관리 방법이 기타인 경우 객관적 증빙이 가능한 자료를 첨부파일 형태로 제출\n[제출시기]\n○ 신규：입원환자 안전관리료 최초 청구시 제출\n○ 기존：’18.7.31.까지 제출\n○ 변경：입원환자 병문안 관리 현황 변경 발생 즉시 제출 주) 세부작성요령은 뒷면을 참조하여 작성하시기 바라며, ※란은 반드시 해당 번호를 기재하여야 합니다.\n입원환자 안전관리료 질의응답\n      (보험급여과-6429호, ’22.1.1.)\n 입원환자 안전관리료 산정기준\n▣ 산정기준','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 250쪽',250,8,169);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0170','PDF_QNA','PDF_QNA_13','PDF','QA','입원환자 안전관리료를 산정하는 의료기관의 환자안전 활동 시행 확인 방법은?','입원환자 안전관리료를 산정하는 의료기관의 환자안전 활동 시행 확인 방법은?','입원환자 안전관리료 산정하 의료기관 환자안전 활동 시행 확인 전담인력 인증 의료기관인증 인증조사 가산','○ 「환자안전법」 제11조·제12조 및 동법 시행규칙 제5조·제9조제1항에 해당하는 의료 기관으로 전담인력 배치, 환자안전위원회를 설치·운영하는 기관은 계획서와 활동증빙 서류를 의료기관평가인증원 환자안전 보고학습시스템(환자안전 서비스포털)을 통해 제출하여야함\n- 신설 또는 입원환자 안전관리료를 최초 청구하는 의료기관은 해당년도 환자안전위원회 운영계획을 의료기관평가인증원에 제출한 후 수가를 적용하여야 함\n   * 요양기관 종별 및 개설자 변경으로 인한 요양기호 변경 시에도 해당\n- 매년 1월 31일까지 전년도 환자안전위원회 운영계획 및 활동 증빙서류를 의료기관 평가인증원에 제출하여야하며, 미제출시 해당년도 2월 1일부터 다음 연도 1월 31일 까지 입원환자 안전관리료를 산정할 수 없음\n   * (단, 제출기간 이후 제출 시 최종제출일 이후 산정가능)\n   입원환자 안전관리료는 모든 의료기관에서 산정할 수 있나요?\n○ 대상기관은 「환자안전법」 제11조, 제12조에 명시된 보건복지부령으로 정하는 일정 규모 이상의 병원급 의료기관 및 의료법 시행규칙 제39조의6에 따른 의료기관으로 상급종합병원, 종합병원, 100병상 이상의 병원·정신병원 및 200병상 이상의 한방 병원을 의미합니다.\n   여기서 병상 수는 의료법령에 따른 허가병상 수 기준이며, 「국민건강보험법」 제43조에','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 257쪽',257,8,170);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0171','PDF_QNA','PDF_QNA_13','PDF','QA','신규개설기관 또는 입원환자 안전관리료 최초 청구기관 산정기준은?','신규개설기관 또는 입원환자 안전관리료 최초 청구기관 산정기준은?','신규개설기관 입원환자 안전관리료 최초 청구기관 산정기준 환자안전 전담인력','○ 상급종합병원, 종합병원, 200병상 이상 병원·정신병원 및 200병상 이상 한방병원은\n   「요양급여의 적용기준 및 방법에 관한 세부사항」 입원환자 안전관리료 산정기준(고시 제2021-88호), 입원환자 안전관리료 인력기준(고시 제2020-330호), 입원환자 안전 관리료 병문안 관리기준(고시 제2018-114호) 모두 충족해야 함\n○ 100병상 이상 200병상 미만 병원·정신병원은 「요양급여의 적용기준 및 방법에 관한 세부사항」입원환자 안전관리료 산정기준(고시 제2021-88호)을 충족하여야 함\n   * 정신병원은 2021년 3월 4일까지는 ‘요양병원(정신건강복지법 제3조제5호에 따른 정신의료기관 중 정신병원인 요양병원만 해당)’임','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 258쪽',258,8,171);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0172','PDF_QNA','PDF_QNA_13','PDF','QA','입원환자 안전관리료는 입원일수별로 산정할 수 있나요?','입원환자 안전관리료는 입원일수별로 산정할 수 있나요?','입원환자 안전관리료 입원일수별 산정할 환자안전 전담인력','○ 네, 입원환자 안전관리료는 환자 당 입원일수별로 산정할 수 있습니다. 다만 외박 시에는 산정이 불가능 합니다.\n   (예시) 4박 5일 입원한 경우 5회 산정','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 258쪽',258,8,172);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0173','PDF_QNA','PDF_QNA_13','PDF','QA','0~6시 사이에 입원하거나, 18~24시 사이에 퇴원하여 입원료의 50%를 별도 산정한 경우 입원환자 안전관리료 산정이 가능한가요?','0~6시 사이에 입원하거나, 18~24시 사이에 퇴원하여 입원료의 50%를 별도…','6시 사이 입원하거나 18 24시 퇴원하여 입원료 50 산정한 입원환자 안전관리료 가능한가요 환자안전 전담인력','○ 입원환자 안전관리료는 입원1일당 1회 산정하는 수가로 입원료의 50%가 별도 산정된 경우에는 산정이 불가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 258쪽',258,8,173);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0174','PDF_QNA','PDF_QNA_13','PDF','QA','퇴원 당일 재입원한 경우 입원환자 안전관리료 산정방법은 어떻게 되나요?','퇴원 당일 재입원한 경우 입원환자 안전관리료 산정방법은 어떻게 되나요?','퇴원 당일 재입원한 입원환자 안전관리료 산정방법 어떻게 환자안전 전담인력','○ 퇴원한 후 당일 재입원한 경우에는 계속 입원 중 이었던 환자로 간주하여 1일 1회 산정합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 259쪽',259,8,174);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0175','PDF_QNA','PDF_QNA_13','PDF','QA','낮병동 입원료를 산정하는 경우 입원환자 안전관리료를 산정할 수 있나요?','낮병동 입원료를 산정하는 경우 입원환자 안전관리료를 산정할 수 있나요?','낮병동 입원료 산정하 입원환자 안전관리료 산정할 환자안전 전담인력','○ 낮병동 입원료를 산정하는 경우에는 수가 산정이 불가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 259쪽',259,8,175);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0176','PDF_QNA','PDF_QNA_13','PDF','QA','응급의료센터의 입원환자 본인부담률 적용 환자의 경우 입원환자 안전관리료 산정이 가능한가요?','응급의료센터의 입원환자 본인부담률 적용 환자의 경우 입원환자 안전관리료 산정이 …','응급의료센터 입원환자 본인부담률 적용 환자 안전관리료 가능한가요 환자안전 전담인력','○ 입원환자 본인부담률 적용 환자라도 수가 산정이 불가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 259쪽',259,8,176);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0177','PDF_QNA','PDF_QNA_13','PDF','QA','간호･간병통합서비스 병동에 입원한 환자도 입원환자 안전관리료 산정이 가능한가요?','간호･간병통합서비스 병동에 입원한 환자도 입원환자 안전관리료 산정이 가능한가요?','간호 간병통합서비스 병동 입원한 환자 입원환자 안전관리료 가능한가요 환자안전 전담인력','○ 네, 입원환자 안전관리료 산정기준 및 인력기준이 충족된 기관의 간호･간병통합서비스 병동 환자의 경우 산정이 가능합니다.\n      호스피스 병동에 입원한 환자도 입원환자 안전관리료 산정이 가능한가요?\n○ 네, 건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수 제4편 3부 호스피스 급여 별도산정 목록･상대가치점수 및 산정지침에 따라 산정 가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 259쪽',259,8,177);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0178','PDF_QNA','PDF_QNA_13','PDF','QA','의료기관 인증을 받은 기관만 수가를 산정할 수 있나요?','의료기관 인증을 받은 기관만 수가를 산정할 수 있나요?','의료기관 인증 기관 수가 산정할 의료기관인증 인증조사 가산','○ 의료기관 인증을 받지 않아도 기준 충족 시 수가를 산정할 수 있습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 259쪽',259,8,178);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0179','PDF_QNA','PDF_QNA_13','PDF','QA','2020.6.30.(진료분) 이전에 입원환자 안전관리료를 산정한 기관 중 보안관리 기준 미충족시 수가 산정 방법은?','2020.6.30.(진료분) 이전에 입원환자 안전관리료를 산정한 기관 중 보안관…','2020 30 진료분 이전 입원환자 안전관리료 산정한 기관 보안관리 기준 미충족시 환자안전 전담인력','○ 2020.6.30.(진료분) 이전에 입원환자 안전관리료를 산정한 상급종합병원, 종합병원, 200병상 이상 병원은 「요양급여의 적용기준 및 방법에 관한 세부사항」가29 입원환자 안전관리료 입원환자 안전관리료 산정기준 나. 4) 기준 미충족시 아래 수가코드를 2020.10.23.까지 산정할 수 있음\n      코드 상대가치점수\n      상급종합병원 AC410(16410) 24.20 500병상이상 AC421(16421) 26.83 종합병원 100병상이상~ AC422(16422) 28.35 500병상미만 병원 AC430(16430) 31.40 (고시 제2017-167호)\n▣ 보안인력 산정기준','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 260쪽',260,8,179);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0180','PDF_QNA','PDF_QNA_13','PDF','QA','보안관리 기준(인력) 현황 신고 기한은?','보안관리 기준(인력) 현황 신고 기한은?','보안관리 기준 인력 현황 신고 기한 안전관리료 환자안전 전담인력','○ 입원환자 안전관리료를 산정하고자 하는 경우. 보안인력 현황을 수가 청구 전까지 변경 내용을 신고해야 함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 260쪽',260,8,180);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0181','PDF_QNA','PDF_QNA_13','PDF','QA','보안관리 기준(인력) 현황신고 방법은?','보안관리 기준(인력) 현황신고 방법은?','보안관리 기준 인력 현황신고 ','○ 보안인력 현황은 보건의료자원신고포털에 현황신고 하고 이를 증빙할 수 있는 자료 (배치신고서 등)를 첨부하여 제출하여야 함\n   * 신고방법\n   - 보건의료자원신고포털(www.hurb.or.kr)>현황신고‧변경>인력현황\n   - 인력신고 방법은 보건의료자원통합신고포털 공지사항에 게시할 예정','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 260쪽',260,8,181);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0182','PDF_QNA','PDF_QNA_13','PDF','QA','보안 전담인력은 1인만 배치하면 되는지?','보안 전담인력은 1인만 배치하면 되는지?','보안 전담인력 1인 배치하면 되는지 ','○ 주 40시간 이상 근무자는 1인,\n      주 20시간 이상~30시간 미만 근무자는 0.5인으로 2인 이상 배치해야함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 261쪽',261,8,182);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0183','PDF_QNA','PDF_QNA_13','PDF','QA','보안인력이 휴가(병가)등 부재 시 인력산정 방법은?','보안인력이 휴가(병가)등 부재 시 인력산정 방법은?','보안인력 부재 인력산정 ','○ 연속적 부재기간이 16일 이상인 경우 인력 산정에서 제외됨. 다만, 대체인력이 있는 경우 대체인력을 신고한 이후 수가 산정 가능함','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 261쪽',261,8,183);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0184','PDF_QNA','PDF_QNA_13','PDF','QA','비상경보장치란?','비상경보장치란?','비상경보장치란 안전관리료 환자안전 전담인력','○ 붙임* 참조\n* [붙임]\n      「의료법 시행규칙」 개정에 따른 보안인력, 시설기준 적용기준 (적용대상) 100개 이상의 병상을 갖춘 병원․정신병원 또는 종합병원에 대해 보안인력 및 시설 기준 등 개정 내용 적용 → 요양병원, 치과병원, 한방병원은 적용 제외 입원환자 안전관리료 인력기준 ▣ 전담인력','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 261쪽',261,8,184);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0185','PDF_QNA','PDF_QNA_13','PDF','QA','전담인력 현황 신고 방법은 어떻게 되나요?','전담인력 현황 신고 방법은 어떻게 되나요?','전담인력 현황 신고 어떻게 인증 의료기관인증 인증조사 가산','○ 「환자안전법」 시행규칙 제9조5항에 따라 의료기관평가인증원에 전담인력 배치현황을 신고하여야 하며, 현황 변경 시(신규배치·해지 등) 지체 없이 변경신고 하여야 합니다.\n   또한, 인증원에 신고된 전담인력은 심평원에 신고되어 있는 요양기관현황(인력 등)에도 신고가 되어 있어야 합니다.\n   * 신규 및 기존인력 중 미신고·변경사항이 있는 경우 (변경)신고 필수','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 262쪽',262,8,185);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0186','PDF_QNA','PDF_QNA_13','PDF','QA','전담인력 배치현황이 변경되어 배치기준을 충족하지 않는 경우 수가 산정방법은 어떻게 되나요?','전담인력 배치현황이 변경되어 배치기준을 충족하지 않는 경우 수가 산정방법은 어떻…','전담인력 배치현황 변경되어 배치기준 충족하지 산정방법 어떻게 인증 의료기관인증 인증조사 가산','○ 배치현황 변경 시 지체없이 의료기관평가인증원에 변경 신고를 하여야 하며, 배치 기준을 만족하지 못하는 날부터 수가 산정은 불가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 262쪽',262,8,186);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0187','PDF_QNA','PDF_QNA_13','PDF','QA','전담인력이 환자안전과 관련된 업무만 시행하여야 하나요?','전담인력이 환자안전과 관련된 업무만 시행하여야 하나요?','전담인력 환자안전 관련된 업무 시행하여야 ','○ 전담인력은 환자안전 업무를 위해 배치된 인력으로 전담인력 업무범위는 「환자안전법」\n   제12조제2항을 따르며 환자안전활동에 대한 연간 계획을 수립하고 관리하여야 합니다.\n   또한 동법 시행규칙 제9조제4항제4호에 따라 의료질 향상을 위하여 보건복지부장관이 특히 필요하다고 인정하는 사항을 시행할 수 있습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 262쪽',262,8,187);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0188','PDF_QNA','PDF_QNA_13','PDF','QA','전담인력(기존,신규) 교육이수 방법은 어떻게 되나요?','전담인력(기존,신규) 교육이수 방법은 어떻게 되나요?','전담인력 기존 신규 교육이수 어떻게 ','○ 「환자안전법」 제13조 및 동법 시행규칙 제10조에 따라 정해진 교육시간을 이수 하여야 하며, 보건복지부 고시 제2016-142호에 따른 위탁기관(대한병원협회)에서 주관하는 교육을 이수하여야 합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 262쪽',262,8,188);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0189','PDF_QNA','PDF_QNA_13','PDF','QA','전담인력이 매년 12시간이상 교육을 받지 않는 경우 어떻게 되나요?','전담인력이 매년 12시간이상 교육을 받지 않는 경우 어떻게 되나요?','전담인력 매년 12시간이상 교육 받지 어떻게 안전관리료 환자안전','○ 전담인력은 「환자안전법」 제13조 및 동법 시행규칙 제10조에 따라 정해진 교육 시간을 이수하여야 합니다. 따라서 당해연도 교육에 대한 이수증을 매년 12월 말까지 제출하지 않은 경우, 익일부터 전담인력으로 인정되지 않습니다.\n   (단, 이수증 제출일로부터는 전담인력 인정 가능)\n   예시) ’21년12월31일까지 교육 이수증을 제출하지 않은 경우 다음 교육 이수증 제출일 전까지 전담인력 불인정 입원환자 안전관리료 병문안 관리기준 ▣ 산정 기준','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 263쪽',263,8,189);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0190','PDF_QNA','PDF_QNA_13','PDF','QA','입원환자 병문안 관리 규정은 어떤 내용을 포함하여야 하나요?','입원환자 병문안 관리 규정은 어떤 내용을 포함하여야 하나요?','입원환자 병문안 관리 규정 어떤 내용 포함하여야 ','○ 감염예방 등 안전한 입원환경 조성을 위해 병문안 시간 설정 및 안내, 대장관리, 시설 또는 인력 등을 배치하여 방문객관리 등을 시행하여야 합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 263쪽',263,8,190);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0191','PDF_QNA','PDF_QNA_13','PDF','QA','병문안 관리기준을 충족하지 못하는 경우 ‘입원환자 안전관리료’를 산정할 수 있나요?','병문안 관리기준을 충족하지 못하는 경우 ‘입원환자 안전관리료’를 산정할 수 있나요?','병문안 관리기준 충족하지 못하 입원환자 안전관리료 산정할 환자안전 전담인력','○ 상급종합병원, 종합병원, 200병상 이상 병원(‘18.8.1. 진료분부터), 정신병원(‘20.7.1.\n   진료분부터), 한방병원(‘21.3.29. 진료분부터)은 병문안 관리기준을 충족하지 못하는 경우 ’입원환자 안전관리료‘를 산정할 수 없습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 263쪽',263,8,191);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0192','PDF_QNA','PDF_QNA_13','PDF','QA','모든 병동 출입구나 엘리베이터에 병문안 관리 시설을 설치한 경우에도 병문안 관리 인력을 배치하여야 하나요?','모든 병동 출입구나 엘리베이터에 병문안 관리 시설을 설치한 경우에도 병문안 관리…','모든 병동 출입구나 엘리베이터 병문안 관리 시설 설치한 경우에 인력 배치하여야 ','○ 시설을 이용하여 병문안 관리가 잘 이루어지고 있다면 병문안 관리 인력을 반드시 배치할 필요는 없습니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 263쪽',263,8,192);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0193','PDF_QNA','PDF_QNA_13','PDF','QA','2개 이상의 건물 중 1개 건물에만 ID카드 등을 이용한 스크린도어가 설치되어 있는 경우 나머지 건물은 인력을 반드시 배치하여야 하나요?','2개 이상의 건물 중 1개 건물에만 ID카드 등을 이용한 스크린도어가 설치되어 …','2개 건물 1개 건물에 ID카드 이용한 스크린도어 설치되어 나머지 인력 반드시 배치하여야 ','○ ‘시설’의 경우 ‘건물별’로 병문안객 관리가 이루어져야 하므로, ‘시설’로 관리되지 않는 건물의 경우 ‘인력’ 또는 ‘기타’ 중 하나 이상의 방법으로 관리되어야 합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 264쪽',264,8,193);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0194','PDF_QNA','PDF_QNA_13','PDF','QA','병문안 관리 규정 중 ‘반입금지 물품 목록’에는 어떤 것들이 있나요?','병문안 관리 규정 중 ‘반입금지 물품 목록’에는 어떤 것들이 있나요?','병문안 관리 규정 반입금지 물품 목록 어떤 것들 ','○ 해당 요양기관의 특성을 고려하여 자율적으로 규정하실 수 있습니다.\n   예시) 화분, 꽃, 애완동물 등 감염, 환자 안정, 화재 등에 영향을 줄 수 있는 물품','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 264쪽',264,8,194);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0195','PDF_QNA','PDF_QNA_13','PDF','QA','병문안객 관리를 위한 ‘시설’, ‘인력’, ‘기타’의 방법을 동시에 운영하여야 하나요?','병문안객 관리를 위한 ‘시설’, ‘인력’, ‘기타’의 방법을 동시에 운영하여야 …','병문안객 관리 시설 인력 동시 운영하여야 ','○ 병문안객 관리를 위한 ‘시설’, ‘인력’, ‘기타’ 중 하나 이상의 방법으로 운영하시면 됩니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 264쪽',264,8,195);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0196','PDF_QNA','PDF_QNA_13','PDF','QA','병문안객 관리대장의 작성대상자는 누구인가요?','병문안객 관리대장의 작성대상자는 누구인가요?','병문안객 관리대장 작성대상자 누구 ','○ 병문안객 관리대장은 병동에 출입하는 병문안객을 대상으로 작성하시면 됩니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 264쪽',264,8,196);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0197','PDF_QNA','PDF_QNA_13','PDF','QA','병문안 관리기준은 상급종합병원 지정･평가 ‘병문안객 통제 시설 및 인력’ 기준과 동일하게 설정하여야 하나요?','병문안 관리기준은 상급종합병원 지정･평가 ‘병문안객 통제 시설 및 인력’ 기준과…','병문안 관리기준 상급종합병원 지정 병문안객 통제 시설 인력 기준 동일하게 설정하여야 안전관리료 환자안전 전담인력','○ 아닙니다. 질의하신 기준은 상급종합병원 지정･평가를 위한 기준으로 상급종합병원 외에도 산정할 수 있는 ‘입원환자 안전관리료 병문안 관리기준’과 동일하지 않습니다.\n▣ 시설 기준\n   병문안 관리 시설을 설치할 예정이나 설치가 완료되지 않은 경우는 어떻게 하나요?\n○ 시설이 설치･운영되기 전까지 ‘인력’ 또는 ‘기타’의 방법으로 병문안 관리가 이루어져야 수가 산정이 가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 264쪽',264,8,197);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0198','PDF_QNA','PDF_QNA_13','PDF','QA','병문안 관리 시설을 일반병동 출입구가 아닌 장소에 설치하는 경우도 시설로 인정되나요?','병문안 관리 시설을 일반병동 출입구가 아닌 장소에 설치하는 경우도 시설로 인정되…','병문안 관리 시설 일반병동 출입구 아닌 장소 설치하 인정되 ','○ 각 병동별 출입구에 병문안 관리 시설을 설치하는 것을 권장하나, 시설 설치에 소요\n   되는 시간‧비용 등을 고려하여 병문안객이 주로 이용하는 동선별 주요 장소(1층 엘리 베이터, 병원 주 출입구 등) 중 최소 1곳 이상에 설치한 경우 인정됩니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 265쪽',265,8,198);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0199','PDF_QNA','PDF_QNA_13','PDF','QA','간호‧간병통합서비스 병동 출입구에 설치된 슬라이딩 도어도 병문안 관리 시설로 인정되나요?','간호‧간병통합서비스 병동 출입구에 설치된 슬라이딩 도어도 병문안 관리 시설로 인…','간호 간병통합서비스 병동 출입구 설치된 슬라이딩 도어 병문안 관리 시설 인정되 ','○ 해당 요양기관 전체 병문안 관리를 목적으로 하는 시설이어야 하며, 간호‧간병통합서비스 병동 등 일부 장소에 국한된 시설은 제외합니다.\n   중환자실, 응급실, 수술실, 정신과 폐쇄병동 등의 출입구에 설치된 시설도 병문안 관리 시설로 인정되나요?\n○ 병문안 관리를 목적으로 하는 시설이어야 하므로, 병문안 관리가 주 목적이 아닌 시설은 제외합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 265쪽',265,8,199);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0200','PDF_QNA','PDF_QNA_13','PDF','QA','주 출입구가 여러 군데인 경우 1곳만 개폐시설이 설치되어 있어도 인정되나요?','주 출입구가 여러 군데인 경우 1곳만 개폐시설이 설치되어 있어도 인정되나요?','출입구 여러 군데인 1곳 개폐시설 설치되어 있어 인정되 ','○ ID카드 등을 이용하여 허용된 사람에 한해 개폐가 가능한 고정 시설물을 의미하며, 건물별로 1개 이상 설치된 경우 인정됩니다.\n▣ 인력 기준','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 265쪽',265,8,200);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0201','PDF_QNA','PDF_QNA_13','PDF','QA','병문안 관리 인력만 운영하는 경우 24시간 배치하여야 하나요?','병문안 관리 인력만 운영하는 경우 24시간 배치하여야 하나요?','병문안 관리 인력 운영하 24시간 배치하여야 ','○ 병문안 관리 ‘시설’을 설치하지 않은 경우 24시간 배치가 원칙이지만, 인력 확보 어려움을 고려하여 최소 주 40시간 이상 ‘인력’에 의한 병문안 관리가 이루어지는 경우 인정 가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 266쪽',266,8,201);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0202','PDF_QNA','PDF_QNA_13','PDF','QA','병문안 관리 인력을 병문안 허용시간 또는 병문안객 관리 인력 근무 시간(주40시 간)에만 배치하는 경우에도 인정되나요?','병문안 관리 인력을 병문안 허용시간 또는 병문안객 관리 인력 근무 시간(주40시…','병문안 관리 인력 허용시간 병문안객 근무 시간 주40시 배치하 경우에 인정되 ','○ 최소 주 40시간 이상 ‘인력’에 의한 병문안 관리가 이루어지는 경우 인정 가능합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 266쪽',266,8,202);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0203','PDF_QNA','PDF_QNA_13','PDF','QA','주 20시간 미만 병문안 관리를 담당하는 경우도 병문안 관리 ‘인력’으로 인정되나요?','주 20시간 미만 병문안 관리를 담당하는 경우도 병문안 관리 ‘인력’으로 인정되…','20시간 병문안 관리 담당하 인력 인정되 ','○ 근무시간과 인력수를 고려하여 주 40시간 이상 병문안 관리를 하는 경우 인정 가능 합니다.\n   예시) 28시간 근무자 × 1명 = 총 28시간 → 불인정 20시간 근무자 × 2명 = 총 40시간 → 인정','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 266쪽',266,8,203);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0204','PDF_QNA','PDF_QNA_13','PDF','QA','위탁운영의 경우 근무자가 정해지지 않는 경우는 어떡해야 하나요?','위탁운영의 경우 근무자가 정해지지 않는 경우는 어떡해야 하나요?','위탁운영 근무자 정해지지 어떡해야 ','○ 위탁운영의 경우에도 근무대장 작성･관리가 이루어져야 합니다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 266쪽',266,8,204);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0205','PDF_QNA','PDF_QNA_13','PDF','QA','중환자실, 응급실, 수술실, 정신과폐쇄병동 등의 출입구에 인력이 배치된 경우 병문안 관리 인력으로 인정되나요?','중환자실, 응급실, 수술실, 정신과폐쇄병동 등의 출입구에 인력이 배치된 경우 병…','중환자실 응급실 수술실 정신과폐쇄병동 출입구 인력 배치된 병문안 관리 인정되 간호인력 간호사 간호조무사 간호등급 인증 의료기관인증 인증조사 가산','○ 입원환자 병문안 관리가 주 목적이 아닌 인력은 제외합니다.\n▣ 기타 기준\n   병문안 관리 방법 중 ‘기타’는 어떤 방법인가요?\n○ ‘시설’ 또는 ‘인력’이 아닌 다른 방법으로 입원환자 병문안 관리가 이루어지는 경우를 의미합니다. 건물밖에 별도의 면회실을 설치하는 경우 등이 해당하며, 이 경우 객관적인 증빙이 가능한 자료(면회실 사진 등)를 첨부하여 제출하여야 합니다.\n   병문안 관리 방법 중 ‘기타’로 병동 간호사실에서 병문안객 관리대장 관리, 배너 설치, 안내문 배부 등만 하는 경우도 포함이 되나요?\n○ ‘시설’ 또는 ‘인력’없이 병동 간호사실에서 병문안객 관리대장 관리, 배너 설치, 안내문 배부만 하는 경우는 해당되지 않습니다.\n[붙임 1]\n      의료기관평가인증원 신고방법\n      - 환자안전위원회 및 환자안전활동 관련 -\n□ 조사내용 및 방법\n○ 환자안전위원회 현황신고\n   (신고방법) 매년 1월 31일까지 의료기관평가인증원의 환자안전 보고학습시스템 (www.kops.or.kr)에 제출 (제출내용) 환자안전위원회 설치 현황* [표 1]의 내용 * 운영형태, 위원회명칭, 설치일자, 해체일자, 인력구성\n○ 환자안전활동\n   (신고방법) 환자안전위원회 개최 및 환자안전활동 관련 정보를 수집하고 관련 근거자료*를 확인 * 환자안전위원회 개최 현황, 회의록, 환자안전활동 연간 활동계획 및 결과보고, 성과보고 등 (제출자료) 환자안전위원회 연간 운영계획 및 활동 증빙서류 첨부 (제출시기) 매년 1월 31일까지 인증원에 관련 자료 제출\n      「환자안전법」에 따른 환자안전위원회 업무\n      · 환자안전사고의 예방 및 재발 방지를 위한 계획수립 및 시행\n      · 환자안전 전담인력의 선임 및 배치\n      · 보건의료기관의 의료 질 향상 활동 및 환자안전체게 구축･운영\n      · 환자안전사고 보고자 및 보고내용의 보호\n      · 환자와 환자 보호자의 한자안전활동 참여를 위한 계획 수립 및 시행\n      · 환자안전기준의 준수에 관한 사항\n      · 환자안전지표의 운영에 관한 사항\n      · 환자안전사고의 보고 활성화에 관한 사항\n      · 환자안전활동의 교육에 관한 사항\n[표 1] 환자안전위원회 설치현황 조사내용\n      □ 단독위원회 운영 □ 유사위원회 통합운영 운영형태 (통합운영 위원회 명칭 기재)\n      □ 미운영\n   위원회 명칭\n   최초설치일자 해체일자\n※ 설치일자는 환자안전법 시행일(’16. 7. 29)부터 기재 단독위원회 운영의 경우 최초설치일자를 기재하며, 유사위원회 통합운영의 경우 환자안전법\n   제11조의 환자안전위원회 설치 요건을 충족하여 운영하기 시작한 일자를 기재 성명 연락처 담당자(전담인력) 부서 직위 이메일 위원 구성 성명 구분 직종 소속부서 직책 역할 중복위원회 활동 여부 활동시작일/ (소속기관) (중복위원회 명칭) 활동종료일 의료기 Y YY.MM.DD/ 가위원 사내 의사 예방의학과 위원장 관장 (의료사고예방위원회) YY.MM.DD 나위원 외부 의사 감염내과 과장 위원 N YY.MM.DD/ (oo 병원) YY.MM.DD 총 인원수 (명)\n[붙임 2]\n      환자안전 전담인력의 심평원 인력신고 방법\n※ 인증원 전담인력 현황신고와 별개로, 해당인력의 심평원 인력신고 필요\n   (신규인력 및 기존인력 중 변경사항이 있는 경우 (변경)신고 필요)\n   → ‘입원환자 안전관리료’ 수가 적용을 위한 전담인력 인원수 현황은 심평원에 등록(신고)된 정보를 기준으로 산정되기에, 인증원에 전담인력으로 현황신고 된 인력이 심평원에도 인력신고가 되어있어야 전담인력 인원으로 연계･반영 됩니다.\n□ 신고방법\n① 보건의료자원통합신고포털( ) ▶ 현황신고･변경 ▶ 인력현황\n   ▶ 간호인력 신고\n② 신규신고 버튼 클릭\n③ 기존에 신고된 인력을 변경하고자 하는 경우에는 해당 인력정보 우측의\n   「변경」 클릭, 신규인력인 경우 하단의 「신규입사」 클릭\n④ 기본정보 탭 ▶\n   (신규인력) 면허종별, 세부종별(일반간호사), 입사일자, 성명, 주민번호, 근무 병동, 직책, 직종, 간호등급 적용여부(미적용으로 표기), 근무시간 정보를 필수 입력 (기존인력) 변경 사항이 있는 경우(근무병동, 세부종별, 간호등급 적용여부, 근무시간 등) 해당항목 변경 입력\n   ▶ 임시저장 ▶ 최종제출\n※ 근무병동 선택방법\n   ① 근무병동 란의 「병동찾기」 버튼 클릭\n   ② 요양기관에서 신고한 병동현황 중 「환자안전전담」 병동 선택\n※ 병동찾기 버튼 클릭 후 해당 병동이 없는 경우\n   ① 보건의료자원통합신고포털 ▶ 현황신고･변경 ▶ 시설현황 ▶ 차등제 운영병상 신고\n   ② 「신규신고」 클릭 ▶ 「신규병동」 클릭 ▶ 병동구분, 적용일자, 병동명 입력 ▶ 임시저장 ▶ 최종제출\n      - 병동구분：기타 / 적용일자：전담인력의 최초배치일 / 병동명：환자안전전담\n※ 전담인력이 의사인 경우도 위와 동일한 방법으로 신고함\n   (경로：보건의료자원통합신고포털 ▶ 현황신고･변경 ▶ 인력현황 ▶ 의(약/조산)사 신고)\n[붙임 3]\n      병문안 관리규정 신고방법 안내\n1. 경로\n○ 보건의료자원통합신고포털( ) ▶ 현황신고･변경 ▶ 특수운영현황\n▶ 특수운영현황 신고 ▶ 병문안 관리규정 신고\n2. 관리규정 신고\n○ (신규 등록기관) 화면 오른쪽 하단의 「신규등록」 버튼 클릭\n○ (기존 등록기관) 입원환자 병문안 관리 현황 우측의 「변경」 버튼 클릭\n1) 적용일자 입력\n※ 적용시작일자는 병문안 관리규정과 병문안 관리방법을 모두 갖추고 운영하는 날을 기재 예) 관리규정은 2019.9.1.부터 갖추고, 관리방법 중 인력을 배치하여 2019.9.15.부터 운영하는 경우 적용시작일자는 2019.9.15.로 기재\n2) 병문안 관리규정 신고\n- 4개의 항목에 대하여 「포함」 또는 「미포함」으로 신고\n- 4개 항목이 모두 「포함」인 경우에만 병문안 관리규정 신고기관으로 등록 가능\n3) 병문안 관리방법 신고\n- 시설, 인력, 기타 중 병문안 관리를 위하여 운영하고 있는 항목에 대하여\n   「해당」으로 신고\n- 시설, 인력, 기타 중 「해당」 항목이 1개 이상인 경우 병문안 관리규정 신고기관 으로 등록 가능\n4) 임시저장 클릭\n※ 관리방법 중 「인력」을 선택하는 경우 → 인력운영과 인력상세 신고 관리방법 중 「시설」을 선택하는 경우 → 시설 신고 관리방법 중 「기타」를 선택하는 경우 → 최종제출시 증빙자료(첨부파일) 제출\n3. 인력운영 신고\n○ (신규 등록기관) 화면 오른쪽 하단의 「신규등록」 버튼 클릭\n○ (기존 등록기관) 운영현황 우측 「변경」 버튼 클릭\n1) 적용일자 입력\n2) 운영현황 입력(전속, 위탁, 병행 중 선택)\n3) 위탁운영 정보 입력(업소명칭, 대표자, 사업자등록번호, 전화번호)\n    ※ 위탁운영 정보는 운영현황이 위탁 또는 병행인 경우만 입력\n4) 임시저장 클릭\n4. 인력상세 신고\n○ (신규 등록인력) 화면 오른쪽 하단의 「신규등록」 버튼 클릭\n○ (기존 등록인력) 현재 인력현황 항목의 우측 「변경」 버튼 클릭(퇴사의 경우\n      「퇴사」 버튼 클릭)\n1) 근무일자 입력(병문안 관리업무를 담당하는 인력으로 최초 배치된 날짜)\n2) 성명 입력\n3) 주민등록번호 입력\n4) 위탁여부 입력(전속, 위탁 중 선택)\n5) 근무형태 입력(전담, 겸임 중 선택)\n6) 임시저장 클릭\n5. 시설 신고\n○ (신규 등록시설) 화면 오른쪽 하단의 「신규등록」 버튼 클릭\n○ (기존 등록시설) 입원환자 병문안 시설현황 항목 우측의 「변경」 버튼 클릭\n1) 적용일자 입력\n2) 시설종류 코드의 「코드 조회」 버튼 클릭\n3) 해당되는 시설종류 코드를 선택. 시설종류 코드가 없는 경우 하단의 「신규 코드 생성」 버튼 클릭 후 시설종류 명칭, 설치장소, 설치개수를 입력하여 신규 코드를 생성한 후 선택\n    ※ 시설종류 명칭은 제출 후 수정이 불가합니다. 정확한 명칭을 입력하여 주시기 바랍니다.\n    ※ 시설은 건물별로 구분하여 신고하여 주시기 바랍니다.\n    (같은 시설종류도 설치장소가 다른 경우에는 시설종류코드를 추가로 신설하셔야 합니다.)\n    예시)\n      시설종류코드 시설종류명칭 설치장소 설치개수 001 스크린도어 본관 10 002 스크린도어 별관 7 003 RFID 본관 20 004 RFID 신관 5\n4) 임시저장 클릭\n6. 최종제출\n1) 관리규정 및 관리방법 입력 후 상단의 「최종제출」 버튼 클릭\n2) 우편발송여부에서 「파일첨부」 클릭\n3) 「파일추가」 버튼 클릭\n4) 증빙서류(첨부파일) 선택\n    ※ 신고항목에 따라 아래의 자료를 첨부하여 주시기 바랍니다.\n      - 관리규정：의료기관장의 직인이 날인된 전문\n      - 시설：설치 도면 또는 사진(건물별 1개 이상)\n      - 인력：근로계약서, 재직증명서 중 1종류와 근무대장 (위탁인 경우 위탁운영계약서와 근무대장)\n      - 기타：객관적 증빙이 가능한 자료\n5) 작성자 정보(성명, 연락처) 입력7\n6) 하단의 최종제출 클릭','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 266쪽',266,8,205);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0206','PDF_SUGA','PDF_SUGA_01','PDF','ITEM','치과 입원환자','치과 입원환자','입원환자 ','라. 치과 입원환자\n3. 장기환자가 입원기간 중 다음에 해당하는 경우 동 기간(이하 “특정기간”이라 한다) 동안에는 제3부에 의하여 산정할 수 있다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 11쪽',11,7,206);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0207','PDF_SUGA','PDF_SUGA_01','PDF','ITEM','외과적 수술 및 동 수술에 따른 관련된 치료기간','외과적 수술 및 동 수술에 따른 관련된 치료기간','외과적 수술 관련된 치료기간 ','바. 외과적 수술 및 동 수술에 따른 관련된 치료기간\n4. 요양급여비용 산정과 각종 가감률에 의하여 산출된 금액에 대하여는 제1편\n    제1부Ⅰ. 일반기준 1. 및 2.에 의한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 11쪽',11,7,207);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0208','PDF_SUGA','PDF_SUGA_02','PDF','ITEM','제1편 제1부 Ⅱ. 요양기관 종별 가산율의 금액, 제2부 각 장에서 분류된','제1편 제1부 Ⅱ. 요양기관 종별 가산율의 금액, 제2부 각 장에서 분류된','제1편 제1부 요양기관 종별 가산율 금액 제2부 분류된 ','가. 제1편 제1부 Ⅱ. 요양기관 종별 가산율의 금액, 제2부 각 장에서 분류된 분류항목의 점수와 각종 가산제도에 의해 가산한 금액 및 제3편 요-51 요양병원입원료','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 12쪽',12,7,208);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0209','PDF_SUGA','PDF_SUGA_02','PDF','ITEM','국민건강보험 요양급여의 기준에 관한 규칙(이하 “요양급여기준”이라 한다)','국민건강보험 요양급여의 기준에 관한 규칙(이하 “요양급여기준”이라 한다)','국민건강보험 요양급여 기준 관한 규칙 요양급여기준 이라 한다 ','나. 국민건강보험 요양급여의 기준에 관한 규칙(이하 “요양급여기준”이라 한다)\n      제8조제2항의 규정에 의하여 고시된 약제･치료재료 급여목록에 해당하는 약제 및 치료재료','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 12쪽',12,7,209);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0210','PDF_SUGA','PDF_SUGA_02','PDF','ITEM','다음 항목 중 위 가목 및 나목에 해당하는 경우','다음 항목 중 위 가목 및 나목에 해당하는 경우','항목 가목 나목 해당하 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','다. 다음 항목 중 위 가목 및 나목에 해당하는 경우\n      (1) 요양급여기준 [별표 1] 제1호마목 단서규정에 의하여 장관이 정하는 바에 따라 다른 기관에 검사를 위탁하거나 당해 요양기관에 소속되지 아니한 전문성이 뛰어난 의료인을 초빙하거나, 또는 다른 요양기관에서 보유하고 있는 양질의 시설･인력 및 장비를 공동 사용하는 경우 소요\n      되는 행위･약제 및 치료재료\n      (2) 입･퇴원 당일에 발생한 행위･약제 및 치료재료로서 외래진료 및 퇴원 약제 등. 다만, 입원이 결정되지 않은 상태에서 입원 당일 외래 진료를 받은 경우의 원외처방 약제비는 제외\n      (3) 요양기관의 요구에 의하여 가입자 등이 외부에서 직접 구입한 약제 및 치료재료\n3. 위 2.에 불구하고 정액수가를 적용하는 기간(이하 “정액수가기간”이라 한다) 동안 의학적으로 필요한 경우 다음의 분류항목은 별도 산정 할 수 있다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 12쪽',12,7,210);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0211','PDF_SUGA','PDF_SUGA_02','PDF','ITEM','정액수가에 포함되지 않는 다음의 항목(이하 “특정항목”이라 한다)은 제1편','정액수가에 포함되지 않는 다음의 항목(이하 “특정항목”이라 한다)은 제1편','정액수가 포함되지 항목 특정항목 이라 한다 제1편 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','가. 정액수가에 포함되지 않는 다음의 항목(이하 “특정항목”이라 한다)은 제1편','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 13쪽',13,7,211);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0212','PDF_SUGA','PDF_SUGA_03','PDF','ITEM','다음에 분류된 항목의 산정기준 등은 제3부에서 정한 바에 따른다.','다음에 분류된 항목의 산정기준 등은 제3부에서 정한 바에 따른다.','분류된 항목 산정기준 제3부 정한 따른다 안전관리료 환자안전 전담인력 지역사회 연계료 퇴원지원 복귀 적정성평가 질지원금 우수기관 향상기관','나. 다음에 분류된 항목의 산정기준 등은 제3부에서 정한 바에 따른다.\n      (1) 요양병원 입원환자 안전관리료 (요-55)\n      (2) 요양병원 지역사회 연계료 (요-56)\n      (3) 요양병원 입원급여 적정성 평가 연계 질지원금(’23.7.1. 시행)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 13쪽',13,7,212);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0213','PDF_SUGA','PDF_SUGA_03','PDF','ITEM','환자를 진료하는 중에 당해 요양기관에 인력·시설·장비가 갖추어져 있지','환자를 진료하는 중에 당해 요양기관에 인력·시설·장비가 갖추어져 있지','환자 진료하 당해 요양기관 인력 시설 장비 갖추어져 있지 ','다. 환자를 진료하는 중에 당해 요양기관에 인력·시설·장비가 갖추어져 있지 아니하거나 기타 부득이한 사유로 해당 진료가 가능한 다른 요양기관으로 적정하게 의뢰한 경우 또는 입원 중인 환자의 특별한 문제에 대한 평가 및 관리를 위하여 그 주치의가 아닌 동일기관 내 치과의사·한의사의 견해나 조언을 얻는 경우 발생한 행위·약제 및 치료재료','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 13쪽',13,7,213);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0214','PDF_SUGA','PDF_SUGA_03','PDF','ITEM','연명의료중단등결정은 건강보험 행위 급여·비급여 목록표 및 급여 상대가치','연명의료중단등결정은 건강보험 행위 급여·비급여 목록표 및 급여 상대가치','연명의료중단등결정 건강보험 행위 급여 비급여 목록표 상대가치 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','라. 연명의료중단등결정은 건강보험 행위 급여·비급여 목록표 및 급여 상대가치 점수 제4편 제5부에 의하여 산정한다.\n4. 정액수가는 1일당으로 다음과 같이 산정한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 14쪽',14,7,214);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0215','PDF_SUGA','PDF_SUGA_03','PDF','ITEM','1일이라 함은 12시(정오)부터 다음 날 12시(정오)까지를 의미한다.','1일이라 함은 12시(정오)부터 다음 날 12시(정오)까지를 의미한다.','1일이라 12시 정오 까지 의미한다 ','가. 1일이라 함은 12시(정오)부터 다음 날 12시(정오)까지를 의미한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 14쪽',14,7,215);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0216','PDF_SUGA','PDF_SUGA_03','PDF','ITEM','0~6시 사이에 입원하거나(산정코드 첫 번째 자리에 1로 기재), 18~24시','0~6시 사이에 입원하거나(산정코드 첫 번째 자리에 1로 기재), 18~24시','6시 사이 입원하거나 산정코드 번째 자리 18 24시 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','나. 0~6시 사이에 입원하거나(산정코드 첫 번째 자리에 1로 기재), 18~24시 사이에 퇴원한 경우(산정코드 첫 번째 자리에 2로 기재)에는 정액수가 소정 점수의 50%를 별도 산정한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 14쪽',14,7,216);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0217','PDF_SUGA','PDF_SUGA_03','PDF','ITEM','6~12시 사이에 입원하거나, 12~18시 사이에 퇴원한 경우에는 동 기간의','6~12시 사이에 입원하거나, 12~18시 사이에 퇴원한 경우에는 동 기간의','12시 사이 입원하거나 12 18시 퇴원한 경우에 기간 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','다. 6~12시 사이에 입원하거나, 12~18시 사이에 퇴원한 경우에는 동 기간의 정액수가는 별도 산정하지 아니한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 14쪽',14,7,217);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0218','PDF_SUGA','PDF_SUGA_03','PDF','ITEM','정액수가 입원료는 입원기간에 따라 다음과 같이 산정한다.','정액수가 입원료는 입원기간에 따라 다음과 같이 산정한다.','정액수 입원료 입원기간 따라 산정한다 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','라. 정액수가 입원료는 입원기간에 따라 다음과 같이 산정한다.\n      (1) 입원 181일째부터 270일째까지는 정액수가 소정점수에서 요양병원 입원료 소정점수의 5%를 감산하여 산정한다(산정코드 첫 번째 자리에 3으로 기재).\n      (2) 입원 271일째부터 360일째까지는 정액수가 소정점수에서 요양병원 입원료 소정점수의 10%를 감산하여 산정한다(산정코드 첫 번째 자리에 4로 기재).\n      (3) 입원 361일째부터는 정액수가 소정점수에서 요양병원입원료 소정점수의 15%를 감산하여 산정한다(산정코드 첫 번째 자리에 5로 기재).\n      (4) 퇴원 후 90일 이내 재입원 하는 경우에는 입원기간에 이전 요양병원 입원기간을 합산하여 적용한다.(다만, 2020년 12월 31일까지는 동일 요양병원에 재입원 하는 경우에만 적용한다.)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 14쪽',14,7,218);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0219','PDF_SUGA','PDF_SUGA_03','PDF','ITEM','9인 이상 병실에 입원한 경우 정액수가 소정점수에서 요양병원 입원료','9인 이상 병실에 입원한 경우 정액수가 소정점수에서 요양병원 입원료','9인 병실 입원한 정액수 소정점수 요양병원 입원료 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 9인이상 감산','마. 9인 이상 병실에 입원한 경우 정액수가 소정점수에서 요양병원 입원료 소정점수의 30%를 감산하여 산정한다.(산정코드 두 번째 자리에 9로 기재, ’22.1.1.부터 적용)\n5. 정액수가는 제3부 4호 마목 및 바목의 의사 및 간호 인력확보수준에 따른 입원료 차등제를 적용하여 산정한다.\n6. 「의료법」 제3조의5에 따라 전문병원으로 지정받은 요양병원은 「의료질평가 지원금 등 산정을 위한 기준」의 평가결과에 따라 제1편의 전문병원(병원･요양 병원･한방병원) 의료질평가지원금(가-24-1)을 산정한다. 다만, 입원료 중 외박 수가를 산정하는 경우에는 제외한다.\n7. 입원 중인 환자가 주치의의 허가를 받은 후 연속해서 24시간을 초과하여 외박한 경우에는 외박수가를 산정한다.\n8. 정액수가 환자군은 「요양급여의 적용기준 및 방법에 관한 세부사항」 Ⅰ. 행위 환자평가표[별지 제25호 서식]를 사실에 근거하여 작성한 후 결정하되, 환자 평가표의 각 항목별 세부인정사항은 ｢요양급여의 적용기준 및 방법에 관한 세부사항｣에서 정한 바에 따른다.\n분류 코 드 분 류 행위 약제･치료재료\n번호 점수 금액(원)\n요­1 의료최고도\n     A1100 가. 입원환자군 690.15 13,000\n     A1900 나. 외박 143.07 6,390\n요­2 의료고도\n     A2100 가. 입원환자군 634.48 7,980\n     A2900 나. 외박 142.97 4,730\n요­3 의료중도\n     A3000 주 : 의사의 판단하에 환자의 상태에 따라 적합한 “일상생활수행능력 향상 활동”을 1일 4회 이상 실시하고 진료기록부 등에 활동내용 및 개선경과를 기록한 경우에 51.70점 (1일당)을 별도 산정한다.\n     A3100 가. 입원환자군 516.96 6,630\n     A3900 나. 외박 143.15 4,910\n요­6 의료경도\n     A6100 가. 입원환자군 509.01 5,170\n     A6900 나. 외박 143.10 3,750\n요­7 선택입원군\n     A7100 가. 입원환자군 329.07 4,270\n     A7900 나. 외박 143.10 3,750','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 14쪽',14,7,219);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0220','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','혈액 내 균 혹은 균 독소가 증명된 경우 또는 감염으로 인한 전신염증반응','혈액 내 균 혹은 균 독소가 증명된 경우 또는 감염으로 인한 전신염증반응','혈액 독소 증명된 감염 인한 전신염증반응 ','나. 혈액 내 균 혹은 균 독소가 증명된 경우 또는 감염으로 인한 전신염증반응 으로서 다음 중 2가지 이상에 해당되어 패혈증으로 확진된 경우(별표2 참조)\n      (1) 체온이 38°C 초과되거나 36°C 미만인 경우\n      (2) 심박동수가 90회(/분)를 초과한 경우\n      (3) 호흡수가 24회(/분)를 초과하거나 이산화탄소분압이 32mmHg 미만인 경우\n      (4) 백혈구수가 12,000/㎣ 초과되거나 4,000/㎣ 미만인 경우, 미성숙 호중성구\n      [Immature(band) Neutrophils] 수가 10% 초과된 경우 위･장관계','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 17쪽',17,7,220);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0221','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','임상적으로 문제가 되는 체내출혈 소견(기관지 출혈, 출혈, 비뇨','임상적으로 문제가 되는 체내출혈 소견(기관지 출혈, 출혈, 비뇨','임상적 문제 체내출혈 소견 기관지 출혈 비뇨 ','다. 임상적으로 문제가 되는 체내출혈 소견(기관지 출혈, 출혈, 비뇨 ･생식기계 출혈 등)이 있으면서 지혈을 위한 처치 또는 수술을 시행한 경우 (별표3 참조)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 17쪽',17,7,221);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0222','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','격리실 입원치료가 필요한 경우 격리실 입원료 산정에 따른 격리기간','격리실 입원치료가 필요한 경우 격리실 입원료 산정에 따른 격리기간','격리실 입원치료 필요한 입원료 격리기간 격리','마. 격리실 입원치료가 필요한 경우 격리실 입원료 산정에 따른 격리기간','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 18쪽',18,7,222);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0223','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','입원 기간 중 (별표4)에 해당하는 외과적 수술을 시행한 날부터 외과적','입원 기간 중 (별표4)에 해당하는 외과적 수술을 시행한 날부터 외과적','입원 기간 별표4 해당하 외과적 수술 시행한 ','바. 입원 기간 중 (별표4)에 해당하는 외과적 수술을 시행한 날부터 외과적 수술과 관련한 치료가 완료된 기간','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 18쪽',18,7,223);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0224','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','위 “가” 및 “나”의 기준에 적합한 경우 진단일로부터 특정기간으로 적용한다.','위 “가” 및 “나”의 기준에 적합한 경우 진단일로부터 특정기간으로 적용한다.','기준 적합한 진단일로 특정기간 적용한다 ','사. 위 “가” 및 “나”의 기준에 적합한 경우 진단일로부터 특정기간으로 적용한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 18쪽',18,7,224);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0225','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','위 “다”의 기준에 적합한 경우 시행일로부터 특정기간으로 적용한다.','위 “다”의 기준에 적합한 경우 시행일로부터 특정기간으로 적용한다.','기준 적합한 시행일로 특정기간 적용한다 격리실 격리 입원료','아. 위 “다”의 기준에 적합한 경우 시행일로부터 특정기간으로 적용한다.\n4. 제외환자 및 특정기간에 산정 가능한 입원료는 요양병원입원료･낮병동입원료･ 중환자실입원료･격리실입원료에 한하며 다음 기준에 의한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 18쪽',18,7,225);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0226','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','입원료 등의 소정점수에는 다음의 세부항목이 포함되어 있다.','입원료 등의 소정점수에는 다음의 세부항목이 포함되어 있다.','입원료 소정점수에 세부항목 포함되어 있다 격리실 격리','가. 입원료 등의 소정점수에는 다음의 세부항목이 포함되어 있다.\n      (1) 요양병원입원료, 낮병동입원료, 격리실입원료 요양병원입원료, 낮병동입원료, 격리실입원료의 소정점수에는 입원환자 의학관리료(소정점수의 31%), 입원환자 간호관리료(소정점수의 16%), 입원환자 병원관리료(소정점수의 53%)가 포함되어 있다.\n      (2) 중환자실입원료\n      중환자실입원료의 소정점수에는 입원환자 의학관리료(소정점수의 40%), 입원환자 간호관리료(소정점수의 25%), 입원환자 병원관리료(소정점수의 35%)가 포함되어 있다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 18쪽',18,7,226);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0227','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','입원료 등을 산정하기 위해서는 국민건강보험법 제43조 및 동법 시행규칙','입원료 등을 산정하기 위해서는 국민건강보험법 제43조 및 동법 시행규칙','입원료 산정하기 위해서 국민건강보험법 제43조 동법 시행규칙 9인이상 병실 감산','나. 입원료 등을 산정하기 위해서는 국민건강보험법 제43조 및 동법 시행규칙\n      제12조에 따라 요양기관의 병실 및 병상현황을 신고하여야 한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 18쪽',18,7,227);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0228','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','낮병동입원료, 중환자실입원료, 격리실입원료를 산정할 수 있는 경우는 다음과','낮병동입원료, 중환자실입원료, 격리실입원료를 산정할 수 있는 경우는 다음과','낮병동입원료 중환자실입원료 격리실입원료 산정할 격리실 격리 입원료','다. 낮병동입원료, 중환자실입원료, 격리실입원료를 산정할 수 있는 경우는 다음과 같으며 이때 입원료 등을 중복산정하지 아니한다.\n      (1) 낮병동 입원료\n      (가) 다음 각 호의 1에 해당하는 경우\n      1) 분만 후 당일 귀가 또는 이송하여 입원료를 산정하지 아니한 경우\n      2) 응급실, 수술실 등에서 처치･수술 등을 받고 연속하여 6시간 이상 관찰 후 귀가 또는 이송하여 입원료를 산정하지 아니한 경우\n      3) 정신건강의학과의 “낮병동”에서 6시간 이상 진료를 받고 당일 귀가한 경우 (나) 낮병동 입원료를 산정 하는 당일 외래 또는 응급실에서 진찰을 행한 경우에는 진찰료를 함께 산정할 수 있다. 다만, 예정된 외래 수술을 위해 내원하는 경우 또는 정신건강의학과의 “낮병동”에서 매일 또는 반복하여 진료를 받는 경우에는 진찰료를 산정하지 아니한다.\n      (다) 낮병동 입원료를 산정하는 당일의 본인일부부담금은 입원진료 본인 일부부담률에 따라 산정한다.\n    (2) 중환자실 입원료：｢의료법｣ 시행규칙 제34조 [별표4]에서 정한 중환자실의 시설･장비를 갖춘 중환자실(ICU)이 설치된 요양병원에서 지극히 심각한 질환이나 손상을 입어 집중적인 치료 및 간호가 필요한 환자를 중환자실에서 진료한 경우\n    (3) 격리실 입원료：다음 각 호의 1에 해당하는 경우 (가) 면역이 억제된 환자를 보호하기 위하여 일반 환자와 격리하여 치료한 경우 (나) 일반 환자를 보호하기 위하여 전염력이 강한 전염성 환자를 일반 환자와 격리하여 치료한 경우 (다) 기타 보건복지부장관이 반드시 격리가 필요하다고 인정하여 고시하는 경우 입원료 등(요양병원입원료･중환자실입원료･격리실입원료)은 1일당으로 다음과 라.\n    같이 산정한다.\n    (1) 1일이라 함은 12시(정오)부터 다음 날 12시(정오)까지를 의미한다.\n    (2) 0~6시 사이에 입원하거나(산정코드 첫 번째 자리에 1로 기재), 18~24시 사이에 퇴원한 경우(산정코드 첫 번째 자리에 2로 기재)에는 입원료 소정점수의 50%를 별도 산정한다.\n    (3) 6~12시 사이에 입원하거나, 12~18시 사이에 퇴원한 경우에는 동기간의 입원료 등은 별도 산정하지 아니한다.\n    (4) 입원과 퇴원이 24시간 이내에 이루어진 경우에는 전체 입원 시간이 6시간 이상인 경우에 한하여 1일의 입원료 등을 산정한다.\n    (5) 요양병원 입원료는 입원기간에 따라 다음과 같이 산정한다.\n      (가) 입원 181일째부터 270일째까지는 해당점수의 95%를 산정한다(산정 코드 첫 번째 자리에 3로 기재).\n(나) 입원 271일째부터 360일째까지는 해당점수의 90%를 산정한다(산정 코드 첫 번째 자리에 4로 기재).\n      (다) 입원 361일째부터는 해당점수의 85%를 산정한다(산정코드 첫 번째 자리에 5로 기재).\n      (라) 퇴원 후 90일 이내 재입원 하는 경우에는 입원기간에 이전 요양병원 입원기간을 합산하여 적용한다.(다만, 2020년 12월 31일까지는 동일 요양병원에 재입원 하는 경우에만 적용한다.)\n      (6) 중환자실 입원료, 격리실 입원료는 입원 16일째부터 30일째까지는 해당 점수의 90%를 산정하고(산정코드 첫 번째 자리에 8로 기재), 입원 31 일째부터는 해당점수의 85%를 산정한다.(산정코드 첫 번째 자리에 9로 기재)\n      (7) 요양병원입원료는 9인 이상 병실에 입원한 경우 해당점수의 70%를 산정한다.(산정코드 두 번째 자리에 9로 기재, ’22.1.1.부터 적용)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 18쪽',18,7,228);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0229','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','의사인력확보수준에 따른 입원료 차등제','의사인력확보수준에 따른 입원료 차등제','의사인력확보수준 입원료 차등제 의사인력 의사수 의사등급 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','마. 의사인력확보수준에 따른 입원료 차등제\n      (1) 요양병원입원료, 낮병동 입원료, 정액수가 산정시 적용한다.\n      (2) 직전 분기 평균 환자 수 대비 당해 요양기관에 상근하는 의사 수(환자 수 대 의사 수의 비)와 「전문의의 수련 및 자격 인정 등에 관한 규정」\n      제3조에 따른 전문과목의 전문의 비율이 50% 이상인 경우와 50% 미만인 경우에 따라 의사인력확보수준을 다음 각 호의 1과 같이 1등급 내지 4등급으로 구분한다.\n      (가) 1등급 - 35:1 이하이면서 전문의 비율이 50% 이상인 경우 (나) 2등급 - 35:1 이하이면서 전문의 비율이 50% 미만인 경우 (다) 3등급 - 35:1 초과 40:1 이하인 경우 (라) 4등급 - 40:1 초과인 경우 (마) 다만, (가) 및 (나)의 규정은 당해 요양기관에 상근하는 의사 1인 이상을 포함하여 의사 수가 2인(소수점은 반올림) 이상인 요양병원에 적용한다.\n      (3) 환자 수는 낮병동 입원환자를 포함한 요양병원 입원환자 전체를 말하며, 다만, 중환자실 입원환자, 별도의 병동으로 구분 운영하는 격리실 입원 환자는 제외한다.\n(4) 의사인력확보수준에 따른 요양병원입원료 등은 등급별로 다음과 같이 가감한다.\n      (가) 1등급：요양병원입원료 소정점수의 18% 가산(기본코드 네 번째 자리에 9로 기재)\n      (나) 2등급：요양병원입원료 소정점수의 10% 가산(기본코드 네 번째 자리에 1로 기재)\n      (다) 3등급：요양병원입원료 소정점수로 산정(기본코드 네 번째 자리에 0으로 기재)\n      (라) 4등급：요양병원입원료 소정점수의 50% 감산(기본코드 네 번째 자리에 5로 기재)\n      (마) 다만, (가) 및 (나)의 규정은 당해 요양기관에 상근하는 의사 1인 이상을 포함하여 의사 수가 2인(소수점은 반올림) 이상인 요양병원에 적용 한다.\n    ※ 보건복지부 고시 제2021-59호, ’23.7.1. 시행\n    (4) 의사인력확보수준에 따른 요양병원입원료 등은 등급별로 다음과 같이 가감한다.\n      (가) 1등급：요양병원입원료 소정점수의 13% 가산(기본코드 네 번째 자리에 9로 기재)\n      (나) 2등급：요양병원입원료 소정점수의 5% 가산(기본코드 네 번째 자리에 1로 기재)\n      (다) 3등급：요양병원입원료 소정점수로 산정(기본코드 네 번째 자리에 0으로 기재)\n      (라) 4등급：요양병원입원료 소정점수의 50% 감산(기본코드 네 번째 자리에 5로 기재)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 20쪽',20,7,229);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0230','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','간호인력확보수준에 따른 입원료 차등제','간호인력확보수준에 따른 입원료 차등제','간호인력확보수준 입원료 차등제 간호인력 간호사 간호조무사 간호등급 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','바. 간호인력확보수준에 따른 입원료 차등제\n    (1) 요양병원입원료, 낮병동 입원료, 정액수가 산정시 적용한다.\n    (2) 직전 분기 평균 환자 수 대비 간호업무에 종사하는 직전 분기 평균 간호 인력(간호사 및 간호조무사) 수(환자 수 대 간호인력 수의 비)에 따라 간호인력확보수준을 다음 각 호의 1과 같이 1등급 내지 6등급으로 구분 한다.\n     (가) 1등급 - 4.5:1 미만인 경우\n     (나) 2등급 - 4.5:1 이상 5:1 미만인 경우 (다) 3등급 - 5:1 이상 5.5:1 미만인 경우 (라) 4등급 - 5.5:1 이상 6:1 미만인 경우 (마) 5등급 - 6:1 이상 6.5:1 미만인 경우 (바) 6등급 - 6.5:1 이상인 경우\n(3) 환자 수는 낮병동 입원환자를 포함한 요양병원 입원환자 전체를 말하며, 다만, 중환자실 입원환자, 별도의 병동으로 구분 운영하는 격리실 입원 환자는 제외한다.\n(4) 간호인력확보수준에 따른 요양병원입원료 등은 등급별로 다음과 같이 가감 한다.\n     (가) 1등급：요양병원입원료 소정점수의 60% 가산(기본코드 다섯 번째 자리에 1로 기재)\n     (나) 2등급：요양병원입원료 소정점수의 50% 가산(기본코드 다섯 번째 자리에 2로 기재)\n     (다) 3등급：요양병원입원료 소정점수의 35% 가산(기본코드 다섯 번째 자리에 3으로 기재)\n     (라) 4등급：요양병원입원료 소정점수의 20% 가산(기본코드 다섯 번째 자리에 4로 기재)\n     (마) 5등급：요양병원입원료 소정점수로 산정(기본코드 다섯 번째 자리에 0으로 기재)\n     (바) 6등급：요양병원입원료 소정점수의 50% 감산(기본코드 다섯 번째 자리에 8로 기재)\n     (사) 다만, 환자 수 대 간호사 수의 비가 18:1을 초과하는 경우 1등급 내지 5등급에 해당하는 요양병원은 요양병원 입원료 소정점수의 15%를 감산한 점수로 산정한다. (기본코드 세 번째 자리 6으로 기재. 다만, 정액수가(외박제외)에 대해서는 기본코드 세 번째 자리를 5로 기재)\n(5) 1등급 내지 5등급에 해당하는 요양병원 중 간호사 비율이 간호인력의 3분의2 이상인 경우는 1일당 2,000원을 별도 산정한다.\n      (코드는 의･치과 AB001, 한의과 15001)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 21쪽',21,7,230);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0231','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','간호인력확보수준에 따른 중환자실 입원환자 간호관리료 차등제','간호인력확보수준에 따른 중환자실 입원환자 간호관리료 차등제','간호인력확보수준 중환자실 입원환자 간호관리료 차등제 간호인력 간호사 간호조무사 간호등급','사. 간호인력확보수준에 따른 중환자실 입원환자 간호관리료 차등제\n    제1편 제2부 제1장 기본진료료 [산정지침] 2. 입원료 등 ‘바. 간호인력 확보 수준에 따른 일반 중환자실 입원환자 간호관리료 차등제’의 (1)의 (나)항, (2)의 (나)항의 등급별 산정방법에 따른다.\n    [코드는 1등급：AJ510, 19510, 2등급：AJ520, 19520, 3등급：AJ530,\n    19530, 4등급：AJ540, 19540, 5등급：AJ550, 19550, 6등급：AJ560,\n    19560, 7등급 : AJ500, 19500, 8등급：AJ580, 19580, 9등급：AJ590,\n    19590 사용]','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 23쪽',23,7,231);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0232','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','필요인력 확보에 따른 별도 보상제','필요인력 확보에 따른 별도 보상제','필요인력 확보 보상제 약사 약사인력 재직일수','아. 필요인력 확보에 따른 별도 보상제\n    (1) 직전 분기 당해 요양기관에 약사가 상근하고, 의무기록사, 방사선사, 임상병리사, 물리치료사, 사회복지사 중 상근자가 1명 이상인 직종이 4개 이상인 경우, 일당 1,710원을 별도 산정한다. 다만, 약사는 환자 수가 200명 미만인 경우, 약사가 주 16시간 이상 근무한 경우에도 산정할 수 있다. (코드는 의･치과 AB002, 한의과 15002)\n    (2) 필요인력의 경우, 해당 치료를 실시할 수 있는 일정한 면적의 물리치료실, 임상병리실, 방사선실을 갖추고 실제 사용할 수 있는 해당 장비를 보유하고 있는 요양기관에 한하여 산정할 수 있다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 23쪽',23,7,232);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0233','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','요양병원 입원급여 적정성 평가결과 환류','요양병원 입원급여 적정성 평가결과 환류','요양병원 입원급여 적정성 평가결 환류 적정성평가 질지원금 우수기관 향상기관','자. 요양병원 입원급여 적정성 평가결과 환류 위 ‘마~아’의 규정에도 불구하고 ‘요양병원 입원급여 적정성 평가’결과 평가 영역이 전체 하위 20% 이하에 해당하는 요양병원은 평가결과 발표 직후 2분기 동안 위 ‘마’ 및 ‘바’의 입원료 가산과 ‘아’의 필요인력 확보에 따른 별도 보상을 적용하지 아니한다. (단, 동규정은 2011년 평가결과 발표 분부터 적용한다.)\n※ 보건복지부 고시 제2021-59호, ’23.7.1. 시행','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 23쪽',23,7,233);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0234','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','요양병원 입원급여 적정성 평가를 연계한 질지원금 및 환류는 다음 기준에','요양병원 입원급여 적정성 평가를 연계한 질지원금 및 환류는 다음 기준에','요양병원 입원급여 적정성 평가 연계한 질지원금 환류 기준 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 적정성평가 우수기관 향상기관','자. 요양병원 입원급여 적정성 평가를 연계한 질지원금 및 환류는 다음 기준에 의한다.\n    (1) 요양병원 입원급여 적정성 평가 연계 질지원금 (가) 요양병원입원료, 낮병동 입원료, 정액수가 산정 시 적용한다.\n      (나) 요양병원 입원급여 적정성 평가 연계 질지원금은 위 ‘(가)’의 산정 횟수와 동일하게 산정한다. 다만, 입원료 중 병원관리료만을 산정하는 경우, 외박수가를 산정하는 경우, 0~6시 사이에 입원하거나 18~24시 사이에 퇴원하는 경우에는 별도 산정하지 아니한다.\n      (다) ‘요양병원 입원급여 적정성 평가’ 결과 종합점수 상위 10% 이하인 경우는 요양병원입원료 소정점수의 20%를 별도 산정한다.(코드는 의･치과 AB003, 한의과 15003)\n      (라) ‘요양병원 입원급여 적정성 평가’결과 종합점수 상위 10% 초과하고, 상위 30% 이하인 경우는 요양병원입원료 소정점수의 10%를 별도 산정한다.(코드는 의･치과 AB004, 한의과 15004)\n      (마) ‘요양병원 입원급여 적정성 평가’결과 4등급 이상 이면서, 종합점수가 직전 평가 대비 5점 이상 향상된 경우에는 요양병원입원료 소정점수의 5%를 별도 산정한다.(코드는 의･치과 AB005, 한의과 15005)\n      (바) 요양병원 입원급여 적정성 평가 연계 질지원금은 (다)~(마)에 해당하는 경우 적정성 평가결과 발표 익월부터 다음 평가 결과 발표 월까지 산정하되 의료법 제58조･제58조의3에 따라 의료기관평가인증원에서 실시하는 의료기관 인증결과 ‘인증’ 또는 ‘조건부인증’ 등급이 유효한 기관에 한하여 산정한다.\n    (2) 요양병원 입원급여 적정성 평가결과 환류 위 ‘마~자(1)’의 규정에도 불구하고, ‘요양병원 입원급여 적정성 평가’ 결과 종합점수가 하위 5% 이하에 해당하는 요양병원은 평가결과 발표 직후 2분기 동안 위 ‘마’ 및 ‘바’의 입원료 가산과 ‘아’의 필요인력 확보에 따른 별도 보상, ‘자(1)’의 적정성 평가 연계 질지원금을 적용하지 아니한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 24쪽',24,7,234);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0235','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','요양병원 인증조사에 따른 가산 배제','요양병원 인증조사에 따른 가산 배제','요양병원 인증조사 가산 배제 인증 의료기관인증','차. 요양병원 인증조사에 따른 가산 배제\n      의료법 제58조의4에 따른 인증을 정해진 기간 내 신청하지 아니한 인증조사 미신청기관 및 인증조사 신청 후 정당한 사유 없이 인증비용 미납 등 인증 조사에 협조하지 않거나 인증조사결과 전체 조사항목 평균점수가 5점 미만인 요양병원은 통보 시점이 속한 분기의 직후 1분기 동안 위 ‘마~아’의 규정에도 불구하고 ‘마’ 및 ‘바’의 입원료 가산과 ‘아’의 필요인력 확보에 따른 별도 보상을 적용하지 아니한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 25쪽',25,7,235);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0236','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','「의료법」 제3조의5에 따라 전문병원으로 지정받은 요양병원은 「의료질평가','「의료법」 제3조의5에 따라 전문병원으로 지정받은 요양병원은 「의료질평가','의료법 제3조의5 따라 전문병원 지정받 요양병원 의료질평 지역사회 연계료 퇴원지원 복귀','카. 「의료법」 제3조의5에 따라 전문병원으로 지정받은 요양병원은 「의료질평가 지원금 등 산정을 위한 기준」의 평가결과에 따라 제1편의 전문병원(병원･ 요양병원･한방병원) 의료질평가지원금(가-24-1)을 산정한다. 다만, 입원료 중 병원관리료만을 산정하는 경우에는 제외한다.\n5. 의약품관리료\n    의약품관리료는 특정기간 중 투약한 경우 특정기간이 종료되는 시점마다 투약 일수에 따라 제1편 제2부 제1장 가-11 의약품관리료 나-(3)의 수가를 산정한다.\n6. 요양병원 지역사회 연계 관리료Ⅱ를 산정한 경우 교통비는 소요시간, 방문지역 등에 불문하고 1회 방문당 108.30점(코드는 의･치과 AW004, 한의과 16004)을 환자 본인이 100분의 100을 부담한다.\n7. 연명의료중단등결정은 건강보험 행위 급여·비급여 목록표 및 급여 상대가치점수\n    제4편 제5부에 의하여 산정한다.\n분류 코드 분 류 점수\n번호\n요-51 AB500 요양병원 입원료 Inpatient Care 270.04 (15500) 주：내과질환자, 정신질환자, 만8세 미만의 소아환자에 대하여는 소정점수의 30%를 가산(산정코드 세 번째 자리에 4로 기재)한다.\n요-52 AF500 낮병동 입원료 Day Care 270.04 (18500)\n요-53 중환자실 입원료 ICU Patient Care AJ002 주：중환자실에 전담의를 두는 경우에는 136.03점을 별도 (19002) 산정한다.\n      AJ500 (1) 요양병원 의･치과 1,077.71\n      19500 (2) 요양병원 한의과 1,072.42\n요-54 격리실 입원료 Isolation Room Patient Care 주：다인용의 경우 6인 이하의 격리병실을 이용한 경우에 산정한다.\n      AK500 (1) 1인용 1,574.16\n      AK501 (2) 2인용 1,049.41\n      AK502 (3) 다인용 881.55\n요-55 AC500 요양병원 입원환자 안전관리료(1일당) 19.35 (16500) 주：환자의 안전을 위하여 움직임을 제한하는 등의 경우에는 의료법 시행규칙 별표4의2를 준수하여야 한다.\n요-56 요양병원 지역사회 연계료\n      주：1. 환자지원팀(상근하는 의사, 간호사, 사회복지사 각 1인 및 기타 환자지원에 필요한 인력으로 구성)을 설치하여 운영하는 경우에 산정한다.\n      2. 「가」는 입원기간 중 1회 산정하되, 환자 상태의 급격한 변화 등 불가피한 경우 진료기록부에 이를 기록하고 추가 1회 산정한다.\n      3. 「나」, 「다」는 퇴원 시 1회 산정하되 동시에 실시하는 경우에는 주된 항목의 소정점수만 산정한다.\n      AW001 가. 요양병원 지역사회 연계 평가료 (관련 상담 활동 포함) 233.27 (16001)\n      AW002 나. 요양병원 지역사회 연계 관리료 Ⅰ 295.76 (16002)\n      AW003 다. 요양병원 지역사회 연계 관리료 Ⅱ 631.72 (16003)\n(별표 1)\n      특정항목\n1. 식대\n    - 제1편 제2부 제17장 입원환자 식대\n2. CT 및 MRI\n    - 제1편 제2부 제3장 제2절 방사선 특수영상진단료 중 다-245 전산화단층영상 진단(CT) 및 다-246 자기공명영상진단(MRI)\n    - CT 및 MRI 촬영에 소요된 필름(또는 FULL PACS)･조영제\n3. 전문재활치료\n    - 제1편 제2부 제7장 이학요법료 중 제2절의 사116 운동치료와 제3절 전문재활 치료료\n4. 혈액투석 및 투석액\n    - 제1편 제2부 제9장 처치 및 수술료 중 자702 혈액투석(O7020, O7021)\n    - 혈액투석에 사용된 투석액\n    - 복막투석에 사용된 투석액\n5. 전문의약품\n    가. Erythropoietin 주사제(품명：에포론주 등), Darbepoetin Alpha 주사제 (품명 : 네스프프리필드주 등), Methoxy polyethylene glycol-epoetin β 주사제(품명∶미쎄라프리필드주)\n    나. Recombinant Human Epidermal Growth Factor(품명：이지에프외용액)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 25쪽',25,7,236);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0237','PDF_SUGA','PDF_SUGA_04','PDF','ITEM','Interferon β - 1a(품명：레비프프리필드주 등)','Interferon β - 1a(품명：레비프프리필드주 등)','Interferon 1a 품명 레비프프리필드주 ','라. Interferon β - 1a(품명：레비프프리필드주 등)\n6. 전혈 및 혈액성분제제\n    - 제1편 제2부 제16장 전혈 및 혈액성분제제료 중 파1 전혈과 파2 혈액성분제제\n7. 제1편 제3부 행위 비급여 목록과 치료재료 급여･비급여 목록 및 급여 상한 금액표의 비급여 목록 중 ’19년 1월 이후 급여로 변경 고시된 항목\n8. 「선별급여 지정 및 실시 등에 관한 기준」 제3조제2항의 규정에 의한 행위･치료재료 (별표 2)\n      폐렴 및 패혈증 점검표 및 인정상병\n      폐렴 환자에 대한 점검표\n      환 자 명：\n      진 단 일： 년 월 일\n      ‘폐렴’으로 청구할 수 있는 폐렴의 진단기준은 다음 1의 소견이 있으면서 2~6의 항목 중에서 2가지 이상이 있는 경우로 한다.\n      - 다 음 -\n      1. 흉부방사선 상 신규 또는 진행성 폐 침윤(new or progressive infiltration) 등의 소견：유 □ 무□\n      2. 체온 > 38°C(다른 원인에 의한 것이 아닌)：유 □ 무□\n      3. 백혈구수 > 12,000/㎣ 또는 < 4,000/㎣：유 □ 무□\n      4. 새로 발생한 화농성 객담 또는 객담양상의 변화, 또는 새로 발생하거나 악화된 기침：유 □ 무□\n      5. 흉부 진찰 소견 상 Rale(Crackle)：유 □ 무□\n      6. 혈액가스 이상(PaO2 < 60mmHg 등)：유 □ 무□ 평가자 □ 의사\n      ------------------------- (서명)\n      □ 간호사\n❏ 폐렴 인정 상병\n      상병코드 상 병 명\n      A420 폐 방선균증\n      A430 폐 노카르디아증\n      B583 폐 톡소포자충증\n      B664 폐흡충증\n      J120 아데노바이러스 폐렴\n      J121 호흡기세포융합바이러스 폐렴\n      J122 파라인플루엔자바이러스 폐렴\n      J128 기타바이러스 폐렴\n      J1280 사람보카바이러스 폐렴\n      J1288 기타바이러스 폐렴\n      J129 상세불명의 바이러스 폐렴\n      J13 폐렴연쇄알균에 의한 폐렴\n      J14 인플루엔자균에 의한 폐렴\n      J150 폐렴막대균에 의한 폐렴\n      J151 슈도모나스에 의한 폐렴\n      J152 포도알균에 의한 폐렴\n      J153 연쇄알균B군에 의한 폐렴\n      J154 기타 연쇄알균에 의한 폐렴\n      J155 대장균에 의한 폐렴\n      J156 그람음성균에 의한 폐렴\n      J157 폐렴마이코플라스마에 의한 폐렴 J158 기타 세균폐렴 J159 상세불명의 세균폐렴 J160 클라미디아폐렴 J168 기타 명시된 감염성병원체에 의한 폐렴 J170 달리 분류된 세균질환에서의 폐렴 J171 달리 분류된 바이러스질환에서의 폐렴 J173 기생충질환에서의 폐렴 J178 달리 분류된 기타 질환에서의 폐렴 J180 상세불명의 기관지 폐렴 J181 상세불명의 대엽성 폐렴 J188 상세불명 병원체의 기타 폐렴 J189 상세불명의 폐렴 J690 음식 또는 구토물에 의한 폐렴 J691 기름 및 엣센스제에 의한 폐렴 J698 기타 고체 및 액체에 의한 폐렴 J853 종격의 농양 패혈증 환자에 대한 점검표 환 자 명：\n      진 단 일： 년 월 일\n‘패혈증’으로 청구할 수 있는 패혈증의 진단기준은 다음 1 또는 2에 해당하는 경우로 한다.\n      -다 음-\n1. 혈액 내 균 혹은 균 독소가 증명된 경우：유 □ 무□\n2. 감염으로 인한 전신염증반응으로서 다음 (1)~(4)의 항목 중에서 2가지 이상이 있는 경우\n(1) 체온 > 38°C 또는 < 36°C：유 □ 무□\n(2) 심박동수 > 90/분：유 □ 무□\n(3) 호흡수 > 24회/분 또는 이산화탄소분압 < 32mmHg ：유 □ 무□\n(4) 백혈구수 > 12,000/㎣ 또는 < 4,000/㎣ 또는 immature(band) neutrophils > 10%：유 □ 무□ 평가자 □ 의사\n      ------------------------- (서명)\n      □ 간호사\n❏ 패혈증 인정 상병\n      상병코드 상 병 명\n      A021 살모넬라 패혈증\n      A327 리스테리아 패혈증\n      A391 워터하우스-프리데릭센 증후군 A392 급성 수막알균혈증 A393 만성 수막알균혈증 A394 상세불명의 수막알균혈증 A398 기타 수막알균감염 A399 상세불명의 수막알균감염 A400 연쇄알균A군에 의한 패혈증 A401 연쇄알균B군에 의한 패혈증 A402 연쇄알균D군 및 장알균에 의한 패혈증 A4020 장알균에 의한 패혈증 A4021 연쇄알균D군에 의한 패혈증 A403 폐렴연쇄알균에 의한 패혈증 A408 기타 연쇄알균패혈증 A409 상세불명의 연쇄알균패혈증 A411 기타 명시된 포도알균에 의한 패혈증 A412 상세불명의 포도알균에 의한 패혈증 A413 인플루엔자균에 의한 패혈증 A414 무산소균에 의한 패혈증 A418 기타 명시된 패혈증 A419 상세불명의 패혈증 A427 방선균 패혈증 A483 독성 쇼크증후군 R578 기타 쇼크 ❏ 폐렴･패혈증 점검표 작성요령\n   - 폐렴/패혈증을 확정 진단한 날에 점검표를 작성한다.\n   - 점검표는 발생 기간별로 1회 작성한다(동일 월에 하나 이상의 특정기간이 발생한 경우에는 기간별로 각각 작성한다).\n   - 점검표는 원칙적으로 환자를 치료한 의사 또는 간호사가 기재하며, 의무기록에 근거하여 작성하여 제출한다.\n(별표 3)\n      체내출혈 점검표\n      체내출혈 환자에 대한 점검표\n      환 자 명：\n      시 행 일： 년 월 일\n   ‘체내출혈’로 청구할 수 있는 기준은 다음 1의 소견이 있으면서 2 또는 3을 시행한 경우로 한다.\n      -다 음-\n   1. 임상적으로 문제가 되는 체내출혈 소견：유 □ 무□\n      (1) 기관지 출혈 (객혈 등)\n      (2) 위･장관계 출혈 (토혈 또는 혈변 등)\n      (3) 비뇨･생식기계 출혈 (혈뇨 등)\n      (4) 기타부위 출혈(경미한 출혈 제외)\n   2. 지혈을 위한 처치(수혈 등)：유 □ 무□\n   3. 지혈을 위한 수술(시술 포함)：유 □ 무□ 평가자 □ 의사\n      ------------------------------ (서명)\n      □ 간호사\n❏ 체내출혈 점검표 작성요령\n- 체내출혈에 대한 처치 또는 수술을 시행한 날에 점검표를 작성한다.\n- 점검표는 발생 기간별로 1회 작성한다(동일 월에 하나 이상의 특정기간이 발생한 경우에는 기간별로 각각 작성한다).\n- 점검표는 원칙적으로 환자를 치료한 의사 또는 간호사가 기재하며, 의무기록에 근거하여 작성하여 제출한다.\n(별표 4)\n      외과적 수술코드\n코 드 명 칭\nC8514 침생검(심부)-심낭 [EKG비용포함]\nC8515 침생검(심부)-척수\nC8532 절개생검(표재성)-기타부위 C8533 절개생검(심부[장기절개생검])-개흉에 의한 것\nC8534 절개생검(심부[장기절개생검])-개복에 의한 것\nC8535 절개생검(표재성)-근육 및 연부조직 C8552 전립선생검-관혈적 C8562 고환, 부고환생검-관혈적 C8572 자궁내막조직생검-구획소파생검 C8574 자궁내막조직생검-단순소파생검 C8575 자궁내막조직생검-자궁경내소파술 C8582 골생검(절개생검)-척추골 C8583 골생검(절개생검)-기타부위 C8592 갑상선생검-관혈적생검 C8601 관절절개생검술-견관절, 고관절, 천장관절 C8602 관절절개생검술-주관절, 슬관절 C8603 관절절개생검술-완관절 및 족관절 C8604 관절절개생검술-기타부위 C8610 신경생검술 C8642 유방생검 [편측]-절개생검 E6551 이식형 사건 기록기 삽입술 E6552 이식형 사건 기록기 제거술 E7500 관절경검사 E7501 관절경검사-고관절부위를실시한경우 E7593 기관지경검사(경기관지폐생검)\nE7600 흉강경검사\nE7605 종격동검사\nE7690 복강경검사\nE7691 후복강경검사\nHD081 밀봉소선원치료-강내치료(고선량률분할치료, 1치료기간당, 5~15회 실시기준)\nHD082 밀봉소선원치료-강내치료(고선량률분할치료, 치료중단시, 1회당)\nHD083 밀봉소선원치료-강내치료(저선량률치료, 방사성선원 삽입 당일)\nHD085 밀봉소선원치료-조직내치료, 관내치료(고선량률분할치료, 1치료기간당, 3회 이상 실시기준)\nHD086 밀봉소선원치료-조직내치료, 관내치료(고선량률분할치료, 치료중단시, 1회당)\nHD087 밀봉소선원치료-조직내치료, 관내치료(저선량률치료, 방사성선원삽입당일)\nHD089 밀봉소선원치료-방사성입자의 자입치료 [본수불문 1회당]','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 27쪽',27,7,237);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0238','PDF_CLAIM','PDF_CLAIM_01','PDF','ITEM','심사청구서 및 명세서 등 구분방법','심사청구서 및 명세서 등 구분방법','심사청구서 명세서 구분방법 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','1. 심사청구서 및 명세서 등 구분방법\n가. 장기환자･ □ 요양병원에 입원한 환자의 경우 건강보험 행위 급여･비급여 목록표 제외환자 및 급여 상대가치점수(이하 “상대가치점수표”라 한다) 제3편제1부 요양병원 급여 일반원칙에 따라 장기환자와 제외환자로 명세서를 분리하여 청구서를 각각 작성한다.\n      □ 요양병원에 입원한 장기환자의 요양급여비용은 요양급여비용 청구 방법, 심사청구서･명세서서식 및 작성요령(이하 “고시”라 한다) 제1편\n      제2장제9조제9항에 따라 반드시 월단위로 구분하여 진료월 다음달 초일부터 월별로 청구한다.\n나. 정액기간･ □ 요양병원에 입원한 장기환자는 고시 제1편제2장제8조제1항1호에 특정기간 따라 요양병원형 수가 중 정액수가를 적용받는 기간과 특정기간인 행위별수가를 적용받는 기간으로 요양급여내역을 각각 분리하여 명세서를 작성한다.\n      □ 상기 내역에 따라 명세서를 분리할 경우 정액수가 적용기간의 요양 급여비용은 정액･정률 구분란에 “1”을 기재하여 작성(서면의 경우 별지 제10-1호서식)하고, 특정기간인 행위별수가 적용기간의 요양 급여비용은 정액･정률 구분란에 “2”로 기재하여 작성한다.(서면의 경우 별지 제10호서식)\n다. 타보험 □ 자동차보험이나 산재보험 적용 환자가 입원중에 건강보험 적용 질환 기왕증 (기왕증)에 대해 진료를 받는 경우 해당 내역만 별도의 명세서에 진료 작성하여 “제외환자”로 청구한다.\n라. 심사청구서 환자구분 장 기 환 자 제외환자 및 명세서 청구구분 특정기간 구분방법 (정액수가) (행위별수가) (행위별수가)\n    (입원환자) 청구서 진료형태 A：요양병원 장기환자 입원(의과) 1：의과입원 정보 서식번호 H120：건강보험 의과 입원 H020：건강보험 의과 입원 통신 명세서 요양급여비용 명세서 요양급여비용 명세서 망 정액･정률 1：정액수가 적용 2：행위별수가 적용 9：정률 구분 전산 청구서 진료형태 A：요양병원 장기환자 입원(의과) 1：의과입원 매체 명세서 정액･정률 1：정액수가 적용 2：행위별수가 적용 9：정률 구분 서면 청구서 별지 제9-3호서식 별지 제9-3호서식 명세서 별지 제10-1호서식 별지 제10호서식 별지 제10호서식','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 156쪽',156,6,238);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0239','PDF_CLAIM','PDF_CLAIM_01','PDF','ITEM','명세서 일반내역','명세서 일반내역','명세서 일반내역 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','2. 명세서 일반내역\n가. 청구구분 □ 고시 제1편제2장제8조제1항1호에 따라 장기환자가 동일 월에 정액수가 적용기간과 행위별수가 적용기간(특정기간) 등 여러 개의 명세서로 분리되는 경우 청구구분의 코드는 분리청구에 해당하는 구분코드 ‘3’을 기재한다.\n      ※ 접수번호, 명세서일련번호에 대한 기재방법\n      ○ 최초 입원인 경우\n      - 최초 입원이면서 당월에 명세서가 분리된 경우 최초 입원일이 속한 명세서는 원청구로 작성한다.\n      - 그 다음 명세서는 분리청구 명세서이므로 당초 청구한 명세서의 접수 번호, 명세서일련번호는 각각 ‘9999999’, ‘99999’로 기재한다.\n      ○ 계속 입원인 경우\n      - 당초 청구한 명세서(전월 명세서)의 접수번호, 명세서일련번호를 당월에 분리된 모든 명세서에 동일하게 기재하되, 당초 청구한 명세서가 여러 개로 분리된 경우 명세서일련번호는 마지막 명세서의 일련번호를 기재 한다.\n      (예시) 2022년 1월 5일 최초 입원한 경우 진료월 1월 1월 2월 2월 2월 접수번호 AAAAAAA AAAAAAA BBBBBBB BBBBBBB BBBBBBB\n      명세서일련번호 1 2 15 16 17\n      청구구분 3 3 3 3\n      접수번호 9999999 AAAAAAA AAAAAAA AAAAAAA\n      명세서일련번호 99999 2 2 2\n      최초입원개시일 20220105 20220105 20220105 20220105\n나. 본인일부 □ 요양병원 입원환자의 본인일부부담금은 “요양급여비용 심사청구서･명세서 부담금 세부작성요령 Ⅲ. 요양급여비용 명세서 작성요령 1. 일반(공통)사항 가. 명세서 일반내역”의 7) 본인일부부담금과 같다.\n      □ 단, ｢국민건강보험법 시행령｣ 제19조제1항 [별표 2] 제1호 가목2)의 규정을 적용받는 보건복지부장관이 정하여 고시하는 환자군에 해당하는 경우 본인 일부부담률은 100분의 40으로 한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 157쪽',157,6,239);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0240','PDF_CLAIM','PDF_CLAIM_01','PDF','ITEM','명세서 진료내역','명세서 진료내역','명세서 진료내역 의사인력 의사수 의사등급 차등제 간호인력 간호사 간호조무사 간호등급 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','3. 명세서 진료내역\n가. 요양병원 □ 상대가치점수표 제3편제2부 [산정지침] 1.에 따라 산정하되, 그 금액을 정액수가 “L항 01목”에 기재한다.\n      (예시) 의료고도 환자군에 해당하는 환자가 의사인력확보수준에 따른 입원료 차등 3등급과 간호인력 확보수준에 따른 입원료 차등 5등급인 요양병원에 계속 입원한 경우의 2022.7월분 명세서\n      ▸ 정보통신망 또는 전산매체로 청구하는 경우 항 목 줄 코드구분 코드 단가 일투 총투 금액\n      L 01 0001 1 A2100 57,720 1 31 1,789,320\n      ▸ 서면으로 청구하는 경우\n      입원일수 31 일 (Ⅰ) (Ⅱ) 코드 분 류 단가 일투 총투 금액 구 분\n      L.요양병원 ① 31일 1,789,320원 A2100 의료고도 57,720 1 31 1,789,320\n      정액\n나. 특정항목 □ 상대가치점수표 제3편제2부 [산정지침] 3.에 따라 장기환자에게 정액수가를 적용하는 기간 동안 정액수가에 포함되지 않는 특정항목은 각 해당 항목에 기재한다.\n      (예시) 의사인력 확보수준에 따른 입원료 차등 3등급과 간호인력 확보수준에 따른 입원료 차등 5등급인 요양병원에 입원중인 의료고도 환자군에 해당하는 환자에게 일반식을 제공하고 재활기능치료-보행치료를 실시한 경우 2022.7월분 명세서\n      ▸ 정보통신망 또는 전산매체로 청구하는 경우 줄 항 목 코드구분 코드 단가 일투 총투 금액\n      0001 02 10 1 Y2300 4,520 3 31 420,360\n      0002 02 11 1 Z0010 580 3 31 53,940\n      0003 06 01 1 MM302 13,910 1 21 292,110\n      0004 L 01 1 A2100 57,720 1 31 1,789,320\n▸ 서면으로 청구하는 경우\n      구 분 (Ⅰ) (Ⅱ) 코드 분 류 단가 일투 총투 금액\n      2. 입원료 ⑦ 420,360원 Y2300 일반식 4,520 3 31 420,360\n      기본식대\n      ⑧ 53,940원 Z0010 일반식(영양사) 580 3 31 53,940\n      가산식대\n      6. 이학 ① 1종 원 292,110원 MM302 재활기능치료 13,910 1 21 292,110\n      요법료 -보행치료\n      L. ① 31일 1,789,320원 A2100 의료고도 57,720 1 31 1,789,320\n      요양병\n      원\n      정액\n다. 입원환자 □ 상대가치점수표 제3편제3부 [산정지침] 5.에 따라 입원환자 의약품관리료는 의약품 투약한 일수에 따라 특정기간이 종료되는 시점마다 각각 산정하여 “1항 관리료 03목”에 기재한다.\n      (예시) 2022.4.10일에 처음 입원한 장기환자가 2022.6.20일부터 7.14일 까지 폐렴에 대한 치료로 매일 투약하고 행위별수가로 청구하는 경우 입원환자 의약품관리료는 특정기간 동안의 투약일수를 합산하여 7월 명세서에 작성\n      ▸ 정보통신망 또는 전산매체로 청구하는 경우(2022.7월 명세서)\n      줄 항 목 코드구분 코드 단가 일투 총투 금액\n      0001 01 03 1 AL786 8,190 1 1 8,190\n      ▸ 서면으로 청구하는 경우(2022.7월 명세서)\n      입원일수 14 일 (Ⅰ) (Ⅱ) 코드 분 류 단가 일투 총투 금액 구 분\n      1. 진찰료 ③ 의약품 8,190원 AL786 입원환자 8,190 1 1 8,190\n      관리료 의약품관리료\n      (16일~30일분)\n라. 행위별 □ 상대가치점수표 제3편제2부 [산정지침] 2.에 따른 정액수가를 적용하는 진료내역 명세서에는 정액수가에 포함된 실제 행위별 진료내역을 “L항 81목 진찰료 부터 94목 기타”란에 구분하여 해당 각 목에 기재하며 요양급여비용에는 산입하지 아니한다.\n(예시) 의사인력 확보수준에 따른 입원료 차등 3등급과 간호인력 확보수준에 따른 입원료 차등 5등급인 요양병원에서 2022.7.1일부터 2022.7.9일 까지 의료고도로 입원한 환자에게 기본식사(완제품경관유동식- 완제품)를 제공하고, 영풍파모티딘정20mg(정액수가 포함항목)을 하루 2회씩 계속 복용 및 체위변경처치[1일당], 비강영양[1일당], 경피적 혈액산소포화도측정[1일당]을 매일 실시한 경우 ‣정보통신망 또는 전산매체로 청구하는 경우 줄 항 목 코드 코드 단가 1회 일투 총투 금액 구분 투약량\n      0001 02 10 1 Y7001 4,830 1 3 9 130,410\n      0002 L 01 1 A2100 57,720 1 1 8 461,760\n      0003 L 82 1 AB500 21,170 1 1 8 169,360\n      0004 L 83 3 661901320 58 1 2 9 1,044\n      0005 L 88 1 M0143 7,520 1 1 9 67,680\n      0006 L 88 1 Q2660 9,290 1 1 9 83,610\n      0007 L 89 1 E7230 7,280 1 1 9 65,520','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 158쪽',158,6,240);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0241','PDF_CLAIM','PDF_CLAIM_01','PDF','ITEM','특정내역 구분코드 작성요령','특정내역 구분코드 작성요령','특정내역 구분코드 작성요령 ','4. 특정내역 구분코드 작성요령\n가. 명일련단위 □ MT010(폐렴 정보)\n    작성 ○ 요양병원의 장기환자에게 폐렴이 발생되어 행위별수가를 적용하는 경우 특정내역 ‘폐렴 환자에 대한 점검표’ 6항목의 해당유무(각 사항에 해당하면 “Y”, 항목 그렇지 않으면 “N”)와 진단일을 순서대로 기재한다.\n      - 기재형식：X(1)/X(1)/X(1)/X(1)/X(1)/X(1)/ccyymmdd\n      (예시) 흉부방사선상 신규의 폐침윤이 있고, 체온이 38.5℃이며, 백혈구 수 15,000/㎣, 새로 발생한 화농성 객담이 있고, 흉부 진찰소견 상 Rale 없고, PaO2 50mmHg로 2022.7.10일에 폐렴으로 진단한 경우\n      ▸ 정보통신망 또는 전산매체로 청구하는 경우 특정내역기재란 발생단위구분 줄번호 특정내역구분 특정내역 1 MT010 Y/Y/Y/Y/N/Y/20220710\n▸ 서면으로 청구하는 경우\n      특정내역 폐렴 정보, Y/Y/Y/Y/N/Y/20220710\n      □ MT011(패혈증 정보)\n      ○ 요양병원의 장기환자에게 패혈증이 발생되어 행위별수가를 적용하는 경우 ‘패혈증 환자에 대한 점검표’ 5항목의 해당유무(각 사항에 해당하면 “Y”, 그렇지 않으면 “N”)와 진단일을 순서대로 기재한다.\n      - 기재형식：X(1)/X(1)/X(1)/X(1)/X(1)/ccyymmdd\n      (예시) pseudomonas aeruginosa 배양(+), 38.5℃, 심박동수 98회, 호흡수 30회, 백혈구수 12,000/㎣로 2022.7.21일에 패혈증으로 진단한 경우\n      ▸ 정보통신망 또는 전산매체로 청구하는 경우 특정내역기재란 발생단위구분 줄번호 특정내역구분 특정내역 1 MT011 Y/Y/Y/Y/N/20220721\n      ▸ 서면으로 청구하는 경우\n      특정내역 패혈증 정보, Y/Y/Y/Y/N/20220721\n      □ MT058(체내출혈 정보) (2019.11.1.진료분부터 적용)\n      ○ 요양병원의 장기환자에게 체내출혈이 발생되어 행위별수가를 적용하는 경우 ‘체내출혈 환자에 대한 점검표’ 3항목의 해당유무(각 사항에 해당 하면 “Y”, 그렇지 않으면 “N”)와 시행일을 순서대로 기재한다.\n      - 기재형식：X(1)/X(1)/X(1)/ccyymmdd\n      (예시) 위장관 출혈로 혈변을 보여 혈액검사 후 2022년 7월 25일 수혈을 시행한 경우\n      ▸ 정보통신망 또는 전산매체로 청구하는 경우 특정내역기재란 발생단위구분 줄번호 특정내역구분 특정내역 1 MT058 Y/Y/N/20220725\n▸ 서면으로 청구하는 경우\n      특정내역 체내출혈 정보, Y/Y/N/20220725\n      □ MT063(요양병원 입원 중 진료의뢰)\n      ○ 「요양급여의 적용기준 및 방법에 관한 세부사항」에 따라 요양병원 입원 중인 산정특례 대상자를 「본인일부부담금 산정특례에 관한 기준」[별표 3], [별표4] 및 [별표4의2]에 따른 산정특례 대상 상병명으로 다른 요양 기관에 진료 의뢰한 경우 요양기관기호(의뢰한 요양병원은 의뢰받은 요양 기관의 기관기호, 의뢰받은 요양기관은 의뢰한 요양병원의 기관기호)와 의뢰일자를 기재한다.\n      - 기재형식：9(8)/ccyymmdd\n      (예시) A요양병원(12345678)에 입원 중인 등록 암환자(V193, 등록번호 0123456789)를 2022년 1월 5일 해당 암 상병 관련으로 B병원 (23456789)으로 진료 의뢰한 경우 구분 특정내역기재란 발생단위구분 줄번호 특정내역구분 특정내역\n      A 요양병원 1 MT063 23456789/20220105\n      B 병원 1 MT063 12345678/20220105\n나. 줄번호단위 □ JT007(치매검사결과)\n      작성 ○ 치매치료제 중 Acetylcholinesterase inhibitor제제(예：아리셉트정, 특정내역 엑셀론정 등)나 memantine제제(예：에빅사정 등)를 투여하거나 신경 항목 인지기능검사를 시행한 경우 MMSE 검사결과/검사실시일/CDR 검사결과 /검사실시일/GDS 검사결과/검사실시일 순서대로 기재한다.\n      - 기재형식：9(2)/ccyymmdd/9(1).V9(1)/ccyymmdd/9(1)/ccyymmdd\n      (예시 1) 2022.4.20일에 실시한 MMSE 검사결과가 16이고, 2022.3.11 일에 실시한 GDS 검사결과가 3인 경우\n      ▸ 정보통신망 또는 전산매체로 청구하는 경우 항 목 줄번호 코드구분 코드 단가 1회투약량 일투 총투 금액\n      L 83 0001 3 652105760 1,902 1 1 31 58,962\n      특정내역기재란\n      발생단위구분 줄번호 특정내역구분 특정내역\n      2 0001 JT007 16/20220420///3/20220311\n      ▸ 서면으로 청구하는 경우\n      코드 분 류 단가 1회투약량 일투 총투 금액\n      652105760 아리셉트정 1,902 1 1 31 58,962\n      특정내역 652105760 아리셉트정, MMSE 16(2022.04.20), GDS 3(2022.03.11)\n      (예시 2) 2022.1.20일에 실시한 MMSE 검사결과가 16이고, 2022.5.1일에 실시한 CDR 검사결과가 2인 경우\n      ▸ 정보통신망 또는 전산매체로 청구하는 경우 항 목 줄번호 코드구분 코드 단가 1회투약량 일투 총투 금액\n      L 83 0001 3 652105760 1,902 1 1 31 58,962\n      특정내역기재란\n      발생단위구분 줄번호 특정내역구분 특정내역\n      2 0001 JT007 16/20220120/2.0/20220501//\n      ▸\n      서면으로 청구하는 경우\n      코드 분 류 단가 1회투약량 일투 총투 금액\n      652105760 아리셉트정 1,902 1 1 31 58,962\n      특정내역 652105760 아리셉트정, MMSE 16(2022.01.20), CDR 2(2022.05.01)','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 160쪽',160,6,241);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0242','PDF_CLAIM','PDF_CLAIM_01','PDF','ITEM','환자평가표 제출','환자평가표 제출','환자평가표 제출 평가표 작성','5. 환자평가표 제출\n가. 정액 □ 정액명세서에는 반드시 환자평가표를 제출해야 한다.\n명세서당 ○ 원청구 및 보완청구 명세서 동일 적용 환자평가표 ○ 적용예외 제출 - 추가청구 명세서\n      - 부득이하게 환자평가표를 미작성하여 선택입원군 수가를 적용하는 경우(2019.10.31.까지는 신체기능저하군의 수가를 적용하는 경우에 해당)\n      □ 동월에 정액명세서를 2건 이상으로 분리 작성하는 경우\n      ○ 월초(또는 특정기간 이후)에 작성된 환자평가표를 각각 제출하며, 이때 환자평가표 내역 중 요양개시일은 각각 기재한다.\n      □ 월말 입원으로 환자평가표가 익월에 작성된 경우\n      ○ 익월에 작성된 환자평가표를 각각 제출하며, 이 때 환자평가표 내역 중 요양개시일은 각각 기재한다.\n      □ 환자평가표 작성일로부터 그 달 말일까지의 잔여일수가 7일 이하로 익월의 환자평가표를 생략한 경우\n      ○ 당월의 환자평가표를 익월에도 동일하게 제출하며, 이 때 환자 평가표 내역 중 요양개시일은 익월의 요양개시일을, 평가구분은 ‘3’으로 기재한다.\n      * 평가구분 3：‘이전 환자평가표를 적용하는 경우’를 의미\n6. 기타\n가. 산정특례 □ 산정특례대상자 진료분 청구방법 대상의 ｢본인일부부담금 산정특례에 관한 기준｣ 제4조에 따라 중증질환 타상병 산정특례 대상자 및 제5조에 따른 희귀질환 및 중증난치질환 산정 발생시 특례 대상자가 요양병원에 입원하여 장기환자에 해당하는 경우 청구 청구방법 방법\n      ○ 산정특례 대상 상병 및 관련 합병증에 대한 진료는 산정특례대상 (중증질환자 5%, 희귀질환 및 중증난치질환자 10% 본인부담)임\n      ○ 산정특례 대상과 전혀 관련 없는 타상병(기왕증 포함)의 진료는 산정특례대상이 아니므로 행위별 수가를 적용하여 제외환자로 분리청구 한다.\n      - 다만, 동일 진료과목 의사에게 진료를 받은 경우는 산정특례대상 이므로 “장기환자”로 청구한다.\n      ※ 분리청구 시 「요양급여비용 청구방법, 심사청구서･명세서서식 작성 요령」 제1편 행위 요양급여비용 제4장 심사청구서 및 명세서 작성요령 제24조의1. 상해외인에 해당하는 코드를 기재하여 청구함\n나. 보훈국비 □ 보훈위탁진료 요양기관 보훈국비환자 진료분 청구방법 환자 ○ 보훈환자 중 보훈국비환자(상이처, 무자격자) 진료분으로서 보험자 청구방법 구분 ‘7’을 적용하는 경우 행위별수가를 적용하여 “제외환자”로 청구한다.\n      ○ 보훈환자 중 건강보험이거나 국비질환 이외의 일반질환에 해당 하여 보험자구분 ‘4’를 적용하는 경우 요양병원형 수가를 적용하여 “장기환자”로 청구한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 164쪽',164,6,242);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0243','PDF_ADM','PDF_ADM_01','PDF','QA','필요인력 별도보상 기준 (예시) 약사가 상근하고 필요 인력 5개 직종이 상근하되, 이중 2개 직종의 인력이 퇴사 후 입사까지 4일의 공백기간 (공백기간이 서로 겹치지 않음)이 있는 경우 필요인력 별도보상 산정 여부','필요인력 별도보상 기준 (예시) 약사가 상근하고 필요 인력 5개 직종이 상근하되…','필요인력 별도보상 기준 예시 약사 상근하고 필요 인력 5개 직종 상근하되 이중 2개 퇴사 입사 4일 공백기간 겹치지 않음 약사인력 재직일수','○ 요양기관에 약사가 상근하고, 5개 직종 중 상근자가 1명 이상인 직종이 매일 4개 이상인 경우에 해당 하므로 필요인력에 따른 인센티브 산정이 가능함.\n(단, 협회에서 예시한 직종 모두 상근인력이어야 함)\n\n[출처] 보험급여과-389호,’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 172쪽',172,6,243);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0244','PDF_ADM','PDF_ADM_01','PDF','QA','필요인력 유급휴가 중 대체 고용인력 인정여부','필요인력 유급휴가 중 대체 고용인력 인정여부','필요인력 유급휴 대체 고용인력 인정여부 ','○ 16일 이상 장기유급 휴가 시 인력 산정대상에서 제외됨. 다만 장기유급휴가자를 대체하는 상근자가 있는 경우 “요양병원 입원료 차등제 산정현황 통보서” 신고 후 인정 가능함.\n\n[출처] 보험급여과-389호,’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 172쪽',172,6,244);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0245','PDF_ADM','PDF_ADM_01','PDF','QA','필요인력의 퇴직 마지막 기간을 연차 휴가 시 인력 산정 여부','필요인력의 퇴직 마지막 기간을 연차 휴가 시 인력 산정 여부','필요인력 퇴직 마지막 기간 연차 인력 약사 약사인력 재직일수','○ 필요인력(상근하는 약사, 의무기록사, 방사선사, 임상병리사, 사회복지사, 물리치료사)은 요양병원 입원료 차등제 산정현황 통보서 상의 상근자를 의미하며, 타 의료인력의 기준과 같이 16일 이상 장기 유급 휴가의 경우에는 산정대상에서 제외함.\n\n[출처] 보험급여과-389호,’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 172쪽',172,6,245);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0246','PDF_ADM','PDF_ADM_01','PDF','QA','필요인력 확보에 따른 별도 보상금액(1,710원)에 2010년 점수당 단가(환산지수) 적용 가능 여부','필요인력 확보에 따른 별도 보상금액(1,710원)에 2010년 점수당 단가(환산…','필요인력 확보 보상금액 710원 2010년 점수당 환산지수 적용 ','○ 필요인력 확보에 따른 별도 보상인 ‘일당 1,710원’은 상대가치점수가 아닌 금액 고시(보건복지가족부 고시 제2009- 216호, ’09.11.30.)이므로 점수당 단가를 적용할 수 없음.\n\n[출처] 보험급여과-389호,’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 172쪽',172,6,246);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0247','PDF_ADM','PDF_ADM_01','PDF','QA','필요인력 확보에 따른 별도 보상 산정 방법','필요인력 확보에 따른 별도 보상 산정 방법','필요인력 확보 보상 ','○ 필요인력 확보에 따른 별도 보상제는 필요인력의 조건이 충족되었을 때 입원 1일당 1,710원을 별도 산정함.\n\n[출처] 보험급여과-389호, ’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 172쪽',172,6,247);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0248','PDF_ADM','PDF_ADM_01','PDF','QA','환자수 200명 미만에서 주당 16시간 이상 근무 약사를 고용한 경우 근로기준법상 연차 인정 여부','환자수 200명 미만에서 주당 16시간 이상 근무 약사를 고용한 경우 근로기준법…','환자수 200명 주당 16시간 근무 약사 고용한 근로기준법상 연차 인정 약사인력 재직일수','○ 필요인력 확보에 따른 별도 보상제 관련 환자수 200명 미만에서, 약사가 주 16시간 이상 근무한 경우 근로기준법령에 따른 휴가 인정 가능함.\n\n[출처] 보험급여과-389호,’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 172쪽',172,6,248);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0249','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 관련 산정기준 질의','요양병원 관련 산정기준 질의','요양병원 산정기준 ','○ 필요인력 확보에 따른 별도 산정 관련\n(1) 필요인력 확보에 따른 보상은 일당 1,710원을 별도 산정한다고 규정하고 있는데, 외박 환자 에게도 적용되는지?\n(2) 필요인력 확보에 따른 별도 보상이 입원료의 일당 개념으로 1,710원을 보상한다면, 중환자 실입원료에 대하여도 적용되는지?\n(3) 요양병원에서 폐렴, 패혈증 치료기간으로 정액 수가가 아닌 별도의 행위별 수가를 산정하는 경우에도 필요 인력 확보에 따른 일당 1,710 원 원을 보상하는지?\n⇒ 필요인력 확보에 따른 별도 보상제는 필요\n인력을 확보한 경우 입원료의 일당 개념으로 1,710원을 보상하는 것으로 - 외래 환자 및 입원 환자 중 외박 수가 산정 시에는 별도 산정할 수 없음.\n- 필요인력 확보가 된 해당 기관의 중환자실 입원료에 산정 가능하며 또한, 요양병원의 폐렴 및 패혈증 치료기간 중 산정하는 ‘요양 병원 입원료(AB500)’에도 산정 가능함.\n○ 신규개설기관 관련\n’10. 6. 10일 개설 신고를 한 요양병원이 개설 당일부터 의사 등 해당 인력은 갖춘 상태로 실제 입원 환자를 ’10. 6. 17.부터 시행한 경우, 입원료 차등제 적용 관련 환자 수 산정기준은 ?\n⇒ 분기 마지막 월 14일 이전 개설기관의 다음 환 분기의 기관 등급은 신규개설 요양병원 입원료 차등제 산정기준(보험급여과-74호, ’10.1.8)에 작 따라, 입원 환자 수는 개설 당일부터 해당 분기의 마지막 월 14일까지의 입원환자를 평균하여 산정하여야 함.\n- 다만, 동 사례와 같이 ’10.6.10~6.14까지의 현황을 기준으로 적용 시 개설은 분기 마지막 월 14일(6.14) 전에 하였으나, 실제 입원환자의 진료는 6.17.부터 실시하여 해당 기간 동안 평균할 환자 수가 없는 경우(환자수가 ‘0’인 기간)에는 ‘기본등급’을 산정함.\n\n[출처] 보험급여과-284호,’10.4.13.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 173쪽',173,6,249);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0250','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원의 필요인력 확보에','요양병원의 필요인력 확보에','요양병원 필요인력 확보 약사 약사인력 재직일수','가. 따른 별도 보상제 관련 질의에 대한 회신 나. 다. 요양병원의 ‘필요인력 확보에 따른 별도 보상제’는 요양병원의 의료서비스의 질향상을 위하여 도입한 인력 확보에 따른 인센티브 제도로써 직전분기 당해 요양기관에 약사가 상근하고 의무기록사, 방사선사, 임상병리사, 물리치료사, 사회복지사 중 상근자가 1명 이상인 직종이 4개 이상인 경우 일당 1,710원을 별도 산정하도록 한 것임 한편, 현행 「요양급여의 적용기준 및 방법에 관한 세부사항」의 “요양기관의 시설･인력 및 장비 등의 공동이용시 요양급여비용 청구에 관한 사항”에 의하면 물리치료, 검체검사 및 FULL PACS 등과 같이 「건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수」 등에서 별도로 시설, 장비 및 인력에 대한 기준을 규정하고 있는 항목에 대하여는 우선원칙에 따라 타 요양기관과 시설, 장비 및 인력의 공동이용을 인정하지 않고 있음\n이에, 요양병원의 ‘필요인력 확보에 따른 별도 보상제’ 도입 취지 및 해당 인력(보상을 받고 있는 인력)에 대한 비용보상 기준을 「건강보험 행위 급여･비급여 목록표 및 급여 상대가치점 수」에서 별도로 정하고 있는 점을 감안할 때, 동 필요인력 확보에 따른 별도 보상제 규정을 우선 적용하는 것이 원칙으로 타 요양기관과 시설･ 장비 인력의 공동이용은 인정하지 않는 것이 기존 행정해석이었음\n라. 따라서, 귀 원에서 질의한 필요인력이 상근하고 시설･장비를 보유한 요양병원이 필요인력이 상근 하나 시설･장비를 보유하지 않는 타 요양병원과 시설･장비를 공동이용하는 경우는 공동이용으로 인정하지 않는 것이 타당하며, 이에 따라 시설･ 장비를 보유하지 않는 요양병원의 경우 필요\n인력이 상근하더라도 ‘필요인력 확보에 따른 별도 보상제’의 일당 비용을 산정할 수 없을 것임.\n마. 다만, 필요인력이 상근하고 시설･장비를 보유한 요양병원이 관련 규정에 따라 적합한 인력･시설･ 장비를 보유하고 해당 서비스가 적정하게 제공 되었을 경우에는 관련 규정에 따라 ‘필요인력 확보에 따른 별도 보상제’의 일당 비용을 산정 고 할 수 있을 것임.\n\n[출처] 보험급여과-753호,’13.2.22.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 174쪽',174,6,250);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0251','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 필요인력 확보에 따른 별도 보상제 관련 기준에 대한 질의 회신','요양병원 필요인력 확보에 따른 별도 보상제 관련 기준에 대한 질의 회신','요양병원 필요인력 확보 보상제 기준 회신 ','○ 질의 내용\n- 요양병원에 ‘상근자’로 신고되어 있는 사회 Ⅲ 복지사가 임신으로 「근로기준법」 제74조제7항에 따라 하루 2시간씩 단축 근무하여 하루 6시간 근무를 할 경우 상근자 인정 여부\n○ 회신 내용\n- 「건강보험 행위 급여･비급여 목록표 및 급여 상대가치점수」 제3편 제3부에 따른 「요양급여의 적용기준 및 방법에 관한 세부사항」 Ⅵ.요양병원\n제3부 중 ‘필요인력 확보에 따른 별도 보상제 관련 기준’에서는 요양병원의 입원환자에게 질 높은 의료 서비스를 제공토록 하기 위해 가 시행하는 필요인력 확보에 따른 별도 보상제에서 사회복지사 필요인력은 요양병원 입원료 차등제 산정현황 통보서상의 상근자를 의미한다고 규정 하고 있습니다.\n- 또한, 「근로기준법」 제74조(임산부의 보호)는 “⑦ 사용자는 임신 후 12주 이내 또는 36주 이후에 있는 여성 근로자가 1일 2시간의 근로 시간 단축을 신청하는 경우 이를 허용하여야 한다.\n⑧ 사용자는 제7항에 따른 근로시간 단축을 이유로 해당 근로자의 임금을 삭감하여서는 아니된다.” 라고 규정하고 있습니다.\n- 따라서, 임산부 보호를 위한 제도취지와 관련 규정 등을 종합적으로 고려할 때, 관련 법령 등에 따라 상근자로 인정되고 있었던 사회 복지사가, 상근자의 다른 조건은 충족하나, 근로 시간에 대하여 근로기준법 제74조제7항에 따라 임신 후 12주 이내 또는 36주 이후에 1일 2 시간의 근로시간 단축을 허용받은 경우에는 요양병원 필요인력 확보에 따른 별도보상제에서 상근자로 인정할 수 있을 것으로 판단됩니다.\n- 다만, 적정 의료서비스 제공 및 질적 수준 제고 등 필요인력 확보에 따른 별도 보상제 및 상근 제도를 운영하는 취지에 부합될 수 있도록 해당 요양기관에서는 의료의 질 관리와 서비스 제공에 더욱 만전을 기하여야 할 것입니다.\n\n[출처] 보험급여과-4243호, ’15.7.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 175쪽',175,6,251);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0252','PDF_ADM','PDF_ADM_01','PDF','QA','징병전담의사 수련기간중 차 등수가 등 인력산정에 대한 기준 통보','징병전담의사 수련기간중 차 등수가 등 인력산정에 대한 기준 통보','징병전담의사 수련기간중 등수 인력산정 기준 통보 의사인력 의사수 의사등급 차등제','○ 요양병원에서 징병전담의사를 의사등급에 포함시킬 수 있는지 여부에 대한 민원이 제기되어 검토한 결과를 알리고자 하오니 업무에 착오 없으시기 바랍니다.\n○ 징병전담의사는 병역법 제34조의3 제2항에 의거 징병검사를 실시하지 아니하는 기간 중 3월의 범위안에서 군병원등에서 직무와 관련된 수련을 실시할 수 있도록 되어 있습니다.\n○ 그러나 이 경우 진찰료 차등수가 및 의사인력확보 수준에 따른 입원료 차등제 등급 산정시 징병전담 의사의 포함여부는 요양급여의 적용기준 및 방법에 관한 세부사항에 의하여야 하며, 동 적용기준에 의거 징병전담의사는 기간의 정함이 있는 기간제 (계약직)의사에 해당되며, 기간제 의사는 3개월 요\n이상 고용계약을 체결하고 실제 근무기간도 3개월 이상이어야 1인으로 산정할 수 있습니다.\n○ 다만, 차등수가 산정시 3개월미만 수련허가를 받은 징병전담의사를 포함하여야 한다는 병무청의 문서가 이미 시달되어 있고, 일선 요양기관이 기 시달된 병무청의 문서로 차등수가 및 의사등급 산정에 3개월미만 수련허가를 받은 징병전담의사를 이미 적용하여 혼란이 있었던 점 등을 감안하여, 차등수가는 ’07.12월~’08.1/4분기, 의사등급은 ’08년 1/4분기 진료분에 한하여 3개월미만 수련 허가를 받은 징병전담의사를 포함하여 적용하고 ’08년 2/4분기 진료분부터는 차등수가 및 의사등급 (1/4분기 의사수)에서 제외함을 알려드립니다.\n\n[출처] 보험급여과-1159호,’08.6.30.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 176쪽',176,6,252);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0253','PDF_ADM','PDF_ADM_01','PDF','QA','공익근무요원의 요양병원 의사인력확보수준에 따른 입원료 가산제 적용에 대한 질의','공익근무요원의 요양병원 의사인력확보수준에 따른 입원료 가산제 적용에 대한 질의','공익근무요원 요양병원 의사인력확보수준 입원료 가산제 적용 의사인력 의사수 의사등급 차등제','가. 「병역법」 제33조 및 「공익근무요원 복무관리규정」 제28조의 규정에서 공익근무요원은 복무기관의 장의 허가를 받아 다른 직무를 겸할 수 있음.\n나. 요양병원의 의사인력확보수준에 따른 입원료 차등제에서 의사 수는 요양병원 입원료 차등제 산정현황통보서 상의 상근자를 의미하므로 당직 의사가 상근자인 경우에 포함되며, 의사확보수준에 따라 수가를 차등 적용하는 취지 및 상대가치 점수 산출 배경 등을 감안하여 주 5일 이상 근무 하면서 주 40시간 이상 근무하는 의사를 1인으로 산정하도록 정하고, 주 3일 이상이면서 주 20시간 이상 근무한 경우에는 0.5인으로 인정함.\n다. 따라서 해당 복무기관의 장으로부터 겸직근무 허가를 받은 공익근무요원인 의사가 요양병원에서 당직 의사로서 주 5일이상이면서 주 40시간 이상 근무하거나 주 3일 이상이면서 주 20시간이상 근무하는 경우 요양병원 의사인력확보수준에 따른 입원료 차등제 적용이 가능함\n\n[출처] 보험급여과-341호,’12.2.3.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 177쪽',177,6,253);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0254','PDF_ADM','PDF_ADM_01','PDF','QA','신규(’07.12.15이후) 개설 기관의 의사 및 간호인력 확보수준에 따른 등급 산정 기준','신규(’07.12.15이후) 개설 기관의 의사 및 간호인력 확보수준에 따른 등급…','신규 07 12 15이후 개설 기관 의사 간호인력 확보수준 등급 기준 의사인력 의사수 의사등급 차등제 간호사 간호조무사 간호등급','○ 신규개설기관(’07.12.15이후 개설)의 당해 분기 및 차기 분기의 의사 및 간호인력 확보수준에 따른 등급 산정기준\n- 개설 당해 분기：개설 당일을 기준으로 산정한 등급 적용\n- 분기 시작월 15일 이후 개설한 경우의 개설 차기 분기 ∙ 간호등급 : 개설 당일과 당해 분기 잔여기간을 평균(15일 기준)하여 산정한 등급 적용 ∙ 의사등급 : 개설당일부터 당해 분기의 마지막 월 14일까지의 재직일수를 기준 으로 산정한 등급 적용 ∙ 평균할 잔여기간이 없는 경우(예：3월 20일 개설)에는 개설 당일을 기준으로 산정한 등급 적용\n○ 요양기관 폐업 후 동일 장소에 다른 요양기관이 개설된 경우 개설자, 의료기관명칭 및 관리의사가 변경되었다 하더라도 진료와 관련된 진료기록 일체를 개설 요양기관이 인수한 경우에는 입원 환자 및 외래환자 모두를 계속 진료로 보아야 하므로, 이와 같은 경우는 신규개설기관에 적용 하는 등급 산정방법을 적용하지 아니함.\n○ 이 때 요양급여비용 청구는 폐업 전･후 진료분에 대하여 각각 분리 청구하되, 환자평가표는 개설한 월에 기 작성된 환자평가표가 있을 경우 동 환자 평가표를 사용할 수 있음.\n\n[출처] 보험급여팀-204호,’08.1.24.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 178쪽',178,6,254);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0255','PDF_ADM','PDF_ADM_01','PDF','QA','의사 및 기타 인력의 ‘상근’의 개념과 기준 ‘상근’의 개념에 주당 근무일수 산정 시점','의사 및 기타 인력의 ‘상근’의 개념과 기준 ‘상근’의 개념에 주당 근무일수 산…','의사 인력 상근 개념 기준 주당 근무일수 시점 ','○ 상근하는 의료 인력에 대하여 차등된 수가를 인정하는 것은 적절한 의료행위를 할 수 있을 요\n정도의 충분한 시간동안 근무하는 것을 전제로 국민건강보험 가입자에 대한 의료서비스의 질적 향상을 도모하는 것이 근본취지임\n○ 이에 비전속진료허용 등에 따른 수가적용기준(보 험급여과-76호, 2010. 1. 8)에서도 의사확보수 준에 따라 수가를 차등지급하는 경우 의사수 산정은 의사확보 수준에 따라 수가를 차등 적용 병 하는 취지 및 상대가치점수 산출 배경 등을 감안 하여 주5일 이상 근무하면서 주40시간 이상 근무하는 의사를 1인으로 산정토록 하고 있음.\n○ 아울러, 상근과 관련한 당해 근로자의 근무수준은 해당 사업장 내 다른 근로자나 동종 또는 유사 등 업종에 근무하는 다른 근로자의 근무조건(근무 시간, 근무일수 등)에 비추어 판단해야 할 것임.\n\n[출처] 보험급여과-389호,’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 179쪽',179,6,255);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0256','PDF_ADM','PDF_ADM_01','PDF','QA','의사인력, 간호인력 차등제 가산은 총재원일수 기준인지, 입원료 산정 기준인지','의사인력, 간호인력 차등제 가산은 총재원일수 기준인지, 입원료 산정 기준인지','의사인력 간호인력 차등제 가산 총재원일수 기준 입원료 치매 인지기능 MMSE 인지 의사수 의사등급 간호사 간호조무사 간호등급','○ 보건복지가족부 고시 제2009-216호, 제2009- 병 214호(’09.11.30) 및 「요양병원입원료 차등제 개정관련 기준송부(보험급여과-4556호, ’09.12.24)」 행 내용과 동일함\n○ 즉, 환자수는 전전분기 마지막 월 15일부터 전분기 마지막 월 14일까지의 3개월 평균 환자수 (총 재원일수의 합을 대상기간 입원일수의 합으로 나눈 값)로 산정 ∙ 입원환자수 = 3개월 간 입원환자수의 합/ 3 환 개월간 일수의 합(소수점 3째자리에서 반올림)\n∙ 입원환자수에는 낮병동, 타법령 입원환자수 포함\n- 단, 입원과 퇴원이 같은 날에 이루어진 경우에만 1인으로 적용\n\n[출처] 보험급여과-389호,’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 179쪽',179,6,256);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0257','PDF_ADM','PDF_ADM_01','PDF','QA','환자 100명 입원 시, 당일 10명이 오전에 퇴원하고 당일 오후에 10명이 입원한 경우 환자수 산정은?','환자 100명 입원 시, 당일 10명이 오전에 퇴원하고 당일 오후에 10명이 입…','환자 100명 입원 당일 10명 오전 퇴원하고 오후 입원한 환자수 ','○ 환자수 산정의 원칙은 위 1번의 기준과 동일함.\n- 따라서 동 질의의 경우 환자수는 100명으로 적용\n\n[출처] 보험급여과-389호,’10.2.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 180쪽',180,6,257);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0258','PDF_ADM','PDF_ADM_01','PDF','QA','의사인력확보수준에 따른 입원료 차등제 산정시 환자수 대 의사수가 35:1 이하이면서, 해당분기동안 전문의 총 재직일수가 전체 의사 총 재직일수의 절반인 경우 (예: 전체의사 재직일수 390일에 전문의 재직일수 195일) 등급적용 방법은?','의사인력확보수준에 따른 입원료 차등제 산정시 환자수 대 의사수가 35:1 이하이…','의사인력확보수준 입원료 차등제 산정시 환자수 의사수 35 이하이면서 해당분기동안 전문 재직일수 전체 의사 절반인 전체의사 390일 195일 등급적용 의사인력 의사등급','○ 「요양병원 입원료 차등제 산정현황 통보서 작성 요령」에 따르면, 의사수 및 전문의수는 전전분기 마지막 월 15일부터 전분기 마지막 월 14일까지의 재직일수의 합을 해당분기 일수로 나누어 3개월 평균을 산출하여 기재(소수점 3자리에서 반올림)하며, 전문의수 대 의사수는 소수점 3자리 이하 절사하여 기재함\n○ 다만, 해당분기 전문의 총 재직일수가 전체 의사 총 재직일수의 절반인 경우는 전문의 비율이 50%에 해당하므로 의사인력확보수준에 따른 입원료 차등제의 1등급으로 적용함\n\n[출처] 보험급여과-85호,’22.1.6.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 180쪽',180,6,258);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0259','PDF_ADM','PDF_ADM_01','PDF','QA','물리치료사 1인당 1일 실시인원 (30명)에 일당 정액수가를 적용받는 환자(장기환자)도 포함 되는지 여부','물리치료사 1인당 1일 실시인원 (30명)에 일당 정액수가를 적용받는 환자(장기…','물리치료사 1인당 1일 실시인원 30명 일당 정액수가 적용받 환자 장기환자 포함 되는지 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 요양병원에 대해 별도로 규정하지 않은 급여 기준은 행위, 약제, 치료재료의 모든 기준을 “요양급여의 적용기준 및 방법에 관한 세부사항”\n에서 정한 대로 따라야 함.\n○ 따라서, 장기환자에게 물리치료를 실시할 경우 실시 인력 및 장비, 시설 기준 등 모든 기준은 행위별 수가를 적용받는 환자와 동일하게 적용 받는 것임.\n\n[출처] 보험급여팀-4048호,’07.12.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 180쪽',180,6,259);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0260','PDF_ADM','PDF_ADM_01','PDF','QA','재활의학과 전문의가 장기 부재시 전문재활치료료 산정 여부에 대한 민원회신 통보 수 있는 장비를 보유하고 재활의학과전문의가 상근하고, 전공의의 처방에 따라 상근하는 물리치료사 또 해당분야 전문치료사가 실시하고 그 결과를 진 기록부에 기록한 경우에 산정토록 하고 있습니 재활의학과 전문의가 상근하는 기관에서만 전문 재활치료…','재활의학과 전문의가 장기 부재시 전문재활치료료 산정 여부에 대한 민원회신 통보 …','재활의학 전문의 장기 부재시 전문재활치료료 민원회신 통보 장비 보유하고 재활의학과전문의 상근하고 전공의 처방 따라 상근하 물리치료사 해당분야 전문치료사 실시하고 결과 기록부 기록한 산정토록 하고 있습니 기관에서 전문 재활치료 특성 전문성 환자에게 하지 않는다 할지라 감독 환자 상태 주도면밀하게 하여 적절한 하기 위함입니다 또한 요양병원 시행중인 의사인력 확보수 입원료 차등제 적용 기관 현황통보서상 휴가자 16일 경우에 산정대상 제외토록 있습니다 따라서 장기휴가시 의사인력확보수준 입원 치료 감안하여 휴가중 발생한 전문재활치료 초일 불가함 알려드립니다 아울러 의학과전문의 휴가중에 산정하지 않음 원칙이므 재활전문의 휴가일수 관계 산정할 없으며 내용 2008 1일 진료분 드립니다 의사수 의사등급 재활 물리치료','[질의] 재활의학과 전문의가 장기 부재시 전문재활치료료 산정 여부에 대한 민원회신 통보 수 있는 장비를 보유하고 재활의학과전문의가 상근하고, 전공의의 처방에 따라 상근하는 물리치료사 또 해당분야 전문치료사가 실시하고 그 결과를 진 기록부에 기록한 경우에 산정토록 하고 있습니 재활의학과 전문의가 상근하는 기관에서만 전문 재활치료를 산정토록 특성 및 전문성 등을 전문의가 처방 후 환자에게 하지 않는다 할지라도 지도･감독 및 환자 상태 등을 주도면밀하게 하여 환자에게 적절한 재활치료가 될 수 있도 하기 위함입니다. 또한, 요양병원에서 시행중인 의사인력 확보수 따른 입원료 차등제 적용 기관 현황통보서상의 휴가자(16일 이상 장기 경우에는 산정대상에서 제외토록 하고 있습니다 따라서 요양병원에서 이상 장기휴가시 의사인력확보수준에 따른 입원 차등제 산정대상에서 치료의 특성 등을 감안하여 재활의학과 전문의 휴가중에 발생한 전문재활치료는 휴가 초일부터 별도 산정이 불가함을 알려드립니다. 아울러, 전문재활치료의 의학과전문의의 휴가중에는 산정하지 않음이 원칙이므로 재활전문의의 휴가 중에 발생한 전문재활치료료는 휴가일수에 관계 없이 휴가 초일부터 별도 산정할 수 없으며, 내용은 2008. 6. 1일 진료분부터 적용 드립니다.\n\n○ 건강보험 요양급여 행위 급여･비급여 목록표 및 급여 상대가치점수 제2부 제7장 이학요법료는 난이도 및 전문성 등에 따라 인력기준을 구분하여 정하고 있으며, 이중 제3절은 전문적인 재활치료 항목으로서 해당 항목의 물리치료를 실시할 수 있는 일정한 면적의 해당 치료실과 실제 사용할 있는 요양기관에서 해당전문의 또는 요\n는\n료\n다.\n한 것은 전문재활치료의\n감안할 때 재활의학과\n직접 재활치료를\n처방에 따른 각 행위의\n관찰\n록\n준에\n기준 중 의사는 요양\n상근자를 의미하며, 분만 Ⅲ\n유급 휴가자 포함)의\n.\n재활의학과 전문의가 16일 행\n료\n제외되는 점 및 전문재활\n가\n특성을 감안할 때 재활 병\n전문재활치료료를\n동\n됨을 알려\n\n[출처] 보험급여과-588호,’08.5.6.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 180쪽',180,6,260);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0261','PDF_ADM','PDF_ADM_01','PDF','QA','의사 1인, 한의사 2인이 근무 하는 요양병원에서 의사가 해외 출국으로 부재중이고, 한의사만 근무한 기간에 대한 의과 입원환자 요양급여비용 인정 여부','의사 1인, 한의사 2인이 근무 하는 요양병원에서 의사가 해외 출국으로 부재중이…','의사 1인 한의사 2인 근무 요양병원 해외 출국 부재중이고 근무한 기간 입원환자 요양급여비용 인정 ','○ 「의료법」 제2조 및 제27조에 의거 의사는 의료와 보건지도를, 한의사는 한방의료와 한방 보건지도를 임무로 하며, 의료인은 면허된 것 이외의 의료 행위를 할 수 없도록 규정하고 있음.\n○ 따라서, 의사 부재 중 의과 입원환자에 대한 의과 진료를 한의사가 대신 할 수 없으므로 기본적인 의사의 진료행위가 없는 상태에서 발생한 입원료, 식대 등 의과요양급여비용은 인정하기 곤란하며, 단, 동 상황에서 시행한 한의사의 한방 의료행위는 해당 내역에 한해 인정할 수 있음.\n\n[출처] 보험급여과-513호,’09.2.12.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 182쪽',182,6,261);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0262','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 신종인플루엔자 A(H1N1) 확진검사 등에 대한 급여기준 개선 관련','요양병원 신종인플루엔자 A(H1N1) 확진검사 등에 대한 급여기준 개선 관련','요양병원 신종인플루엔자 H1N1 확진검사 급여기준 개선 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 요양병원은 다른 요양기관 종별과는 달리 입원 환자에 대한 일당정액수가제를 적용함에 따라, 현행 급여기준상 별도 산정토록 명시되어 있는 일부 행위 및 약제를 제외하고는 일당 정액수가에 포함되어 별도 산정할 수 없음. 다만, 요양병원에 ‘신종인플루엔자 고위험군’이 다수 입원하고 있는 점을 감안, 신종 인플루엔자 확산에 신속하게 대처하고 확진환자를 조기에 치료하기 위하여 다음과 같이 한시적으로 별도 산정할 수 있음.\n-다 음-\n○ 당해 요양기관내에서 신종인플루엔자 A(H1N1)\n의심환자에게 확진검사를 실시한 경우, 일당정 액수가에 포함되어 있으므로 별도 산정할 수 없으나, 검체 검사를 다른 요양기관에 위탁하는 경우는 행위별로 별도 산정 가능\n○ 적용기간：[재난 및 안전관리기본법]에 따라 보건 복지가족부가 작성한 [전염병 위기 대응 실무 메뉴얼]상 위기 경보수준이 경계･심각 단계에 한시 적용\n※ 대상환자(적응증), 검사종류, 적용수가 등은 Ⅰ 신종인플루엔자 A(H1N1)의 의심환자 확진 요\n검사법 급여기준 확대 변경 안내[보험급여과\n-3139호, ’09.8.17]와 동일함.\n아울러, 요양병원 입원환자에게 항바이러스제 (타미플루캅셀 등)를 투여하고자 하나 병원 내 항바이러스제를 확보하지 못한 경우, 항바이러스제에 대해서만 원외 처방할 수 있음.\n\n[출처] 보험급여과-3494호,’09.9.15.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 182쪽',182,6,262);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0263','PDF_ADM','PDF_ADM_01','PDF','QA','신종인플루엔자 국가위기단계 전염병 조정에 따른 급여기준 변경 추세 안내 위기단 급여기 현장에 3.1','신종인플루엔자 국가위기단계 전염병 조정에 따른 급여기준 변경 추세 안내 위기단 …','신종인플루엔자 국가위기단계 전염병 조정 급여기준 변경 추세 안내 위기단 급여기 현장 지역사회 연계료 퇴원지원 복귀','가. 1) 위기평가회의에서 신종인플루엔자의 발생 원 등을 고려하여 그간 경계단계로 운영되던 국가 계가 주의 단계로 조정됨에 따라 다음과 같이 준을 변경합니다. 다만, 금번 변경적용은 진료 서의 국민혼란을 방지하기 위하여 2010. 5. (월)진료분부터 적용할 예정임을 알려드립니다.\n신종인플루엔자A(H1N1)의 확진검사법의 급여 Ⅲ 기준 변경 전 (보험급여과-3147호, 2009. 8.18)\n○ Real-time RT-PCR, Conventional RT-PCR, Multiplex RT-PCR 검사 중 1종을 건강보험으로 인정\n○ 적응증\n급성 열성 호흡기 질환이 있으면서\n- 입원중인환자(응급실 환자포함)\n- 신종인플루엔자 고위험군 환자\n- 신종인플루엔자A(H1N1) 진단기준의 의심사례, 추정환자 또는 지역사회 감염이 의심되는 경우 등 의사가 검사 필요성을 인정한 경우\n※ 급여기준 이외 시행하는 경우의 검사비용은 전액을 환자가 부담\n2) 변경 후\n단계하향에 따라 신종인플루엔자A(H1N1)의 의심 환자 확진검사 시 검사비용은 전액을 환자가 부담 (비급여)\n나. 요양병원의 신종인플루엔자A(H1N1)의 확진 검사법의 급여기준\n1) 변경 전(보험급여과-3494호, 2009. 9.15)\n○ 당해 요양기관내에서 신종인플루엔자 A(H1N1)\n의심환자에게 확진검사를 실시시 일당정액 수가에 포함되어 있으므로 별도 산정불가, 타 요양기관에 위탁시 별도 산정 가능\n2) 변경 후\n단계하향에 따라 신종인플루엔자A(H1N1)의 의심 환자 확진 검사시 검사비용은 전액을 환자가 부담 (비급여)\n다. 신종인플루엔자 거점병원의 감염전문관리료 적용\n1) 변경 전(보험급여과-3226호, 2009. 8.25)\n신종인플루엔자 환자가 신종인플루엔자 거점병원에 입원하여 치료받는 경우 감염전문관리료(가8 협의진찰료, 코드 AH400)를 입원기간 중 30일에 1회 산정\n2) 변경 후：동일하게 적용\n\n[출처] 보험급여과-612호,’10.3.5.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 183쪽',183,6,263);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0264','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원의 중환자실이 시설 기준 등 충족하지 못하는 경우 진료비 산정방법 통보','요양병원의 중환자실이 시설 기준 등 충족하지 못하는 경우 진료비 산정방법 통보','요양병원 중환자실 시설 기준 충족하지 못하 진료비 산정방법 통보 ','○ 2008.7.1.부터 중환자실 입원료는 의료법시행규칙\n제34조 [별표4]에서 정한 중환자실의 시설･장비를 갖춘 중환자실이 설치된 종합전문요양기관, 종합 병원, 병원, 요양병원에서 지극히 심각한 질환이나 손상을 입어 집중적인 치료 및 간호가 필요한 성인 또는 소아환자 또는 신생아를 중환자실에서 진료한 경우 산정할 수 있습니다.\n○ 이에 따라 중환자실을 운영하는 요양기관은 중환 자실 입원환자 간호관리료 차등제 산정현황[신규, 분기말 20일까지 제출하여야 하며, 미제출기관 및 의료법시행규칙 제34조 [별표4]에서 정한 중 환자실의 시설･장비를 갖추지 못한 경우는 중환자실 입원료를 산정할 수 없습니다.\n○ 따라서 요양병원 중 요양기관현황 신고시 중환자실을 보유하였다고 신고한 기관이 「중환자실 입원환자 간호관리료 차등제 산정현황 통보서」를 제출하지 못하였거나, 의료법시행규칙 제34조 [별표4]에서 정한 중환자실의 시설･장비 등 기준을 충족하지 못하는 경우는, 요양기관 현황통보서상의 중환자 실에 입원한 환자에 대해 중환자실입원료를 산정할 수 없으므로 특정기간에 해당되지 않음을 알려 드립니다.\n○ 아울러, 해당 요양기관은 기준에 미달된 중환자실에 대하여 요양기관현황을 조속히 변경･신고하여, 병상수, 의사등급, 간호등급 등이 정확히 산정될 수 있도록 조치하여 주시기 바랍니다.\n\n[출처] 보험급여과-1691호,’08.8.20.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 184쪽',184,6,264);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0265','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 중환자실에서의 진료 내역이 인공호흡기 치료와 기본적 처치가 주로서 적극적 치료이기보다 생명유지 및 연장의 진료로 판단되는 경우 중환자실 진료내역을 특정 기간이 아닌 정액수가로 인정 할 수 있는지 여부','요양병원 중환자실에서의 진료 내역이 인공호흡기 치료와 기본적 처치가 주로서 적극…','요양병원 중환자실에서 진료 내역 인공호흡기 치료 기본적 처치 주로서 적극적 치료이기보다 생명유지 연장 판단되 중환자실 진료내역 특정 기간 아닌 정액수가 인정 있는지 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군 9인이상 병실 감산','○ 요양병원에서 중환자실 입원료는 지극히 심각한 질환이나 손상을 입어 집중적인 치료 및 간호가 필요한 환자를 중환자실에서 진료한 경우에 산정 할 수 있으며, 이 경우 ‘특정기간’으로 분류하여 일당정액이 아닌 행위별 수가를 적용하고 있음.\n○ 질의에서와 같이 중환자실 입원환자에 대하여 집중적인 치료행위가 아닌 생명유지 및 연장을 위한 기본적 처치만 한 경우라면 중환자실 입원이 필요한 환자(심각한 질환이나 손상을 입어 집중적인 치료 및 간호가 필요한 환자)로 보기 곤란할 뿐만 아니라 일반 병실에 입원한 동일 환자군과의 형평성 문제가 발생할 소지가 크다고 판단됨.\n○ 따라서, 요양병원 중환자실에서 인공호흡기 치료와 기본적 처치만으로 생명유지 진료만 한 경우라면 ‘특정기간’으로 분류하여 행위별 수가를 적용하기 보다는 동일한 환자군(의료최고도)의 일당정액 수가를 적용함이 타당하다고 판단되며,\n○ 향후 중환자실 입원료 산정이 부적절한 경우 발생 시 일당정액 적용 환자분류군에 대해서는 적용 기준, 환자상태 등을 고려하여 사례별로 적절히 적용하시기 바람.\n\n[출처] 보험급여과-513호,’09.2.12.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 185쪽',185,6,265);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0266','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 적정성 평가결과 환류 관련 질의 3. 간호인력 가산 중 경우에 요양병원 되는지?','요양병원 적정성 평가결과 환류 관련 질의 3. 간호인력 가산 중 경우에 요양병원…','요양병원 적정성 평가결 환류 간호인력 가산 되는지 간호사 간호조무사 간호등급 적정성평가 질지원금 우수기관 향상기관','→ 간호 1 환 ☞ 고시 제 삭제 1. ‘「요양병원 입원급여 적정성 평가결과」 평가영역이 전체 하위 20%에 해당하는 요양병원’에서 전체 하위 20% 이하의 기준을 적용받는 기관이란?\n→ 구조와 진료부문 모두 종합순위 하위 20% 이하인 기관을 의미함\n2. ‘평가결과 발표 직후 2분기 동안’의 적용 기준은?\n→ 평가대상 기간 및 결과 발표 시기를 고려하여, 평가결과 발표연도의 4/4분기(10월~12월)\n및 익년 1/4분기(1월~3월) 진료분에 적용함\n- 평가결과 발표 직후 청구실적이 없거나 지연 되는 경우에도 동일하게 진료분 기준으로 적용 되며, 관리 기간은 청구소멸시효를 감안하여 3년으로 함.\n[ 2011년 평가결과 발표(3차년도 평가)]\n∙ 평가대상 기간：2010년 10월 ~ 12월 진료분 ∙ 결과적용 시기：2011년 10월 ~ 2012년 3월 진료분 확보수준에 따른 입원료 차등제의 입원료 ‘간호사 비율이 간호인력의 3분의2 이상인 1일당 2,000원을 별도 산정’하는 규정도 적정성 평가결과 환류 적용 범주에 포함\n사비율이 간호인력이 3분의2 이상인 경우에 일당 2,000원을 별도 산정’도 적정성평가 결과 류의 적용을 받는 입원료 가산의 범주에 포함됨.\n2021-59호(2023.7.1.시행)에 의거 ’23.7.1.\n\n[출처] 보험급여과-1804호,’10.8.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 186쪽',186,6,266);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0267','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 적정성 평가결과 1. 요양병원 환류 변경하거 경우 평 - 요양 후 면 2. 요양병원 이루어진 연계)를 능한지 - 타 기 개 평 실 평 - 다 이 입원급여 적정성 평가 이후 설립구분을 나 공동대표자 중 주개설자가 변경된','요양병원 적정성 평가결과 1. 요양병원 환류 변경하거 경우 평 - 요양 후 면 …','요양병원 적정성 평가결 환류 변경하거 요양 이루어진 연계 입원급여 이후 설립구분 공동대표자 주개설자 변경된 적정성평가 질지원금 우수기관 향상기관','가결과 연계가 가능한지 여부\n기관의 설립구분만 변경되었을 뿐 변경 전･ 가 실질적으로 동일(시설, 인력, 운영 등)하다\n평가결과 연계\n입원급여 적정성 평가 이후, 양도･양수가 경우 양수한 요양병원의 평가 결과(수가 양수받은 대표자의 요양병원에 연계가 가 여부 요양병원을 양도･양수받아 재개설한 경우 부 관의 대표자의 변경이 있었을 뿐 신규로 설한 기관이 아니므로 양수받은 요양병원이 가대상 요양병원이고, 대표자 변경 전･후가 질적으로 동일(시설, 인력, 운영 등)하다면 가결과 연계 만, 평가결과를 통보받은 이후에 양도･양수가 루어진 경우에 적용 가능\n\n[출처] 보험급여과-3100호,’11.9.22.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 187쪽',187,6,267);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0268','PDF_ADM','PDF_ADM_01','PDF','QA','환자평가표 작성을 위한 의무 기록의 작성 여부 등','환자평가표 작성을 위한 의무 기록의 작성 여부 등','환자평가표 작성 의무 기록 간호인력 간호사 간호조무사 간호등급 평가표 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 의료인은 의료법 제22조 및 동법 시행규칙 제17조,\n제18조에 의거 각각 진료기록부, 조산기록부, 간호기록부, 그 밖의 진료에 관한 기록(이하 “진료 기록부 등”이라 한다)을 갖추어 두고 그 의료행위에 관한 사항과 의견을 상세히 기록하고 서명하여야 하며, 진료기록부등에는 주된 증상, 치료내용, 투약, 처치 및 간호 등에 관한 기록을 하여 보건복지부령 으로 정하는 바에 따라 보존하여야 함.\n○ 건강보험 행위 급여･비급여 목록표 및 상대가치 점수 제3편에서 요양병원은 입원중인 환자의 환자군별 상대가치점수 결정을 위하여 매월 환자 평가표를 작성하여야 하며, 환자평가표는 당해 환자를 담당하는 간호사가 의무기록을 근거로 작성하여 의무기록에 비치토록 하고 있음.\n○ 따라서, 요양병원은 환자의 의무기록(진료기록부, 간호기록부 등)에 의거 환자평가표를 작성함이 원칙임.\n○ 환자평가표 작성을 용이하게 하기 위하여 별도의 check list 등을 만들어 사용하는 것은 무관하나, 이 경우에도 문제행동 등 의무기록에 근거하여 작성토록 되어 있는 모든 문항은 반드시 진료 기록부 등에 증상 등이 기재되어 있어야 함.\n○ 아울러, 의무기록에 기록이 없이 환자평가표만 작성되어 환자평가표의 사실여부 확인이 불가능할 경우는 의무기록으로 확인된 사항을 적용하여 환자군을 적용함.\n\n[출처] 보험급여팀-204호,’08.1.24.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 188쪽',188,6,268);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0269','PDF_ADM','PDF_ADM_01','PDF','QA','탈수로 인하여 생리식염수에 Kcl등 전해질을 mix하여 투여한 경우 ‘정맥주사에 의한 투약’으로 적용할 수 있는지','탈수로 인하여 생리식염수에 Kcl등 전해질을 mix하여 투여한 경우 ‘정맥주사에…','탈수 인하여 생리식염수 Kcl등 전해질 mix하여 투여한 정맥주사 의한 투약 적용할 있는지 영양 경관영양 섭취 수분','○ 탈수환자에게 생리식염수에 전해질을 mix하여 투여하고 ‘정맥주사에 의한 투약’으로 적용할 수 있는 탈수의 기준은 아래 중 2가지 이상에 해당 하는 경우(①, ③은 I/O sheet에 근거해야 함)에 적용함.\n① 하루에 섭취하는 수분량이 1500㎖ 미만인 경우\n② 탈수의 임상적 증상이 있음\n예：새로 발병된 또는 악화된 혼돈(confusion), 비정상적인 임상결과(헤모글로빈, 헤마토 크리트, 칼륨, 혈액요소질소, 요비중 증가 등)\n③ 구토, 열, 설사 등으로 섭취한 수분량보다 수분 소실량이 많은 경우\n\n[출처] 보험급여과-502호,’08.4.29.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 188쪽',188,6,269);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0270','PDF_ADM','PDF_ADM_01','PDF','QA','의료최고도 조건인 ‘중심 정맥관을 통하여 영양물질을 공급한 경우’란 어떤 경우를 말하는지','의료최고도 조건인 ‘중심 정맥관을 통하여 영양물질을 공급한 경우’란 어떤 경우를…','의료최고 조건인 중심 정맥관 통하여 영양물질 공급한 어떤 말하는지 영양 경관영양 섭취 수분','○ 중심정맥관을 통하여 일반적인 수액제(5% 또는 양 10% D/W 등)를 투여한 경우에는 말초정맥을 통하여 수액제를 투여하여야 하나 route확보 등이 어려워 말초정맥투여를 하지 못하는 경우에 해당 하므로 말초정맥영양을 실시한 것으로 보아야 하며, 중심정맥영양의 경우는 반드시 중심정맥관을 통하여 TPN요법을 실시한 경우에만 해당됨.\n\n[출처] 보험급여과-502호,’08.4.29.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 189쪽',189,6,270);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0271','PDF_ADM','PDF_ADM_01','PDF','QA','퇴원약 별도 산정여부','퇴원약 별도 산정여부','퇴원약 산정여부 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 요양병원의 장기환자에게 적용하는 일당 정액수가 에는 퇴원약이 포함(평균 10일 정도)되어 있으므로, 퇴원약 비용은 별도 산정할 수 없음.\n○ 퇴원약이 필요한 환자에게 퇴원시 약을 처방하지 않고 수일내 외래로 내원케하여 약을 처방하는 것은 정액수가에 포함되어 있는 퇴원약에 대한 비용을 이중으로 청구하게 되므로 요양병원에서는 이와 같은 행위를 지양하기 바람.\n\n[출처] 보험급여팀-4048호,’07.12.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 189쪽',189,6,271);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0272','PDF_ADM','PDF_ADM_01','PDF','QA','의약품관리료 산정방법','의약품관리료 산정방법','의약품관리료 산정방법 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 입원환자 의약품관리료는 일당 정액수가에 포함 원 되어 있으므로 별도 산정할 수 없음.\n○ 특정기간 중 투약한 경우는 특정기간이 종료되는 시점마다 투약일수에 따라 제1편 제2부 제1장 작 가-11 의약품관리료 나-(3)의 수가를 산정함.\n○ 다만, 2008.1.1이전부터 계속 입원환자\n- 2008.1.1부터 일당 정액수가 적용환자：2007.\n12.31까지의 입원기간 중 투약한 일수에 따라 의약품관리료 산정\n- 2008.1.1 이후부터 특정기간 해당환자：특정 기간이 종료되는 시점에 입원기간 중 투약한 일수에 따라 의약품관리료 산정\n○ 위 모든 경우의 의약품관리료는 입원 당시 상대 가치점수 및 환산지수를 적용하여 산정함.\n\n[출처] 보험급여팀-4048호,’07.12.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 189쪽',189,6,272);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0273','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 입원이 부적절한 환자','요양병원 입원이 부적절한 환자','요양병원 입원 부적절한 환자 치매 인지기능 MMSE 인지','○ 의료법시행규칙 제28조의4에 의거 정신질환자 (노인성치매환자 제외) 및 전염성질환자는 입원 대상이 아니므로 입원 진료비용은 인정하지 아니함.\n\n[출처] 보험급여팀-4048호,’07.12.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 190쪽',190,6,273);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0274','PDF_ADM','PDF_ADM_01','PDF','QA','장기입원에 따른 입원료 체감제 적용시 기산점','장기입원에 따른 입원료 체감제 적용시 기산점','장기입원 입원료 체감제 적용시 기산점 입원기간','○ 요양병원 입원환자의 장기입원에 따른 요양병원 입원료 체감제 적용 기산점은 최초 입원일부터 기산하여 적용함.\n\n[출처] 보험급여팀-4048호,’07.12.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 190쪽',190,6,274);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0275','PDF_ADM','PDF_ADM_01','PDF','QA','(제도개편) 요양병원도 상급 병실료 제도개편에 따른 4･ 5인실 입원료수가 등이 적용 되는지?','(제도개편) 요양병원도 상급 병실료 제도개편에 따른 4･ 5인실 입원료수가 등이…','제도개편 요양병원 상급 병실료 5인실 입원료수 적용 되는지 9인이상 병실 감산','요양병원은 「국민건강보험 요양급여의 기준에 관한 규칙」 별표2 제4호 나목의 규정에 따라 기존대로 5인 이하 입원 병상에 상급병실료(고시한 입원료 외에 추가로 부담하는 입원실 이용 비용)를 부과할 수 있음.\n또한, 요양병원은 「건강보험 행위 급여･비급여 목록 및 급여 상대가치점수 고시」 제3편이 적용되기 때문에,\n제1편의 개정 규정(4인실 및 5인실 입원료 신설 등)은 적용되지 아니함.\n\n[출처] 보험급여과-3093호,’14.9.1.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 190쪽',190,6,275);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0276','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원에서 외과적 수술이 가능한지 여부','요양병원에서 외과적 수술이 가능한지 여부','요양병원 외과적 수술 ','○ 의료법시행규칙 제28조의4에 의거 요양병원의 입원대상은 노인성질환자･만성질환자 및 외과적 수술 후 또는 상해후의 회복기간에 있는 자로서 주로 요양을 필요로 하는 자임.\n○ 따라서, 요양병원에 입원중인 장기환자에게 외과적 수술이 필요한 질환이 발생하여 수술을 실시한 경우는 제3편 제1부 일반원칙 3.에 의거 외과적 수술 및 동 수술에 따른 치료기간은 제3부에 의한 행위별로 비용을 산정할 수 있음.\n○ 그러나, 요양병원에서 장기환자가 아닌 급성 관 기질환자에게 외과적 수술을 시행하고 입원치료를 하는 것은 의료법시행규칙에서 정한 요양병원 입원대상에 부합된다고 할 수 없으므로 응급 수술을 제외한 여타의 수술을 목적으로 한 입원은 인정하지 아니함.\n\n[출처] 보험급여팀-4048호,’07.12.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 190쪽',190,6,276);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0277','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원에서 수술이 가능한 응급수술의 범위 및 비응급 수술 관련 진료비 등 불인정 시점','요양병원에서 수술이 가능한 응급수술의 범위 및 비응급 수술 관련 진료비 등 불인…','요양병원 수술 가능한 응급수술 범위 비응급 진료비 불인정 시점 ','○ 요양병원에서 진료비용을 산정할 수 있는 응급 수술이라 함은 응급의료에 관한 법률 제2조에 의거 보건복지부장관이 별도로 정한 응급증상으로 내원한 환자에게 응급증상의 개선을 위해 수술을 실시한 경우를 말함.\n○ 비응급환자의 외과적수술이 2007.12월 말에도 발생한 점을 감안하여 비응급수술환자의 진료비용 불인정 시점은 2008.2.1이후 수술받은 환자의 입원초일부터임.\n(예시：’08.2.1 치핵상병으로 수술받은 환자의 최초입원일이 ’08.1.30인 경우 ’08.1.30 입원일부터 퇴원일까지의 진료비용 불인정)\n\n[출처] 보험급여팀-204호,’08.1.24.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 191쪽',191,6,277);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0278','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 특정기간 적용 대상 인 「패혈증」 관련 등 질의 1. 요양병원 입원료의 특정기간으로 적용할 수 있는 패혈증 기준 관련, 상기도감염 등의 경우에서 패혈증 진단의 2가지 이상 항목(체온 및 심박동수 상승 등)에 해당 시 특정기간(행위별 수가로 청구) 으로 적용 가능한지?','요양병원 특정기간 적용 대상 인 「패혈증」 관련 등 질의 1. 요양병원 입원료의…','요양병원 특정기간 적용 대상 패혈증 입원료 적용할 기준 상기도감염 진단 2가지 항목 체온 심박동수 상승 행위별 수가 청구 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 요양병원 입원료는 환자군별로 소요되는 행위, 표 약제, 치료재료 각 항목을 반영하여 1일당 정 작 액수가로 운영이 되고 있으며, 동 수가에 포함될 수 없는 특정기간(패혈증 등)을 일부 예외적으로 인정하고 있음.\n○ 위 기준 중 ‘감염으로 인한 전신염증 반응으로서 2가지 이상의 항목에 해당되어 패혈증으로 확진된 경우’에도 특정기간으로 적용할 수 있으며, 다만 일부 요양병원에서 단순 바이러스 감염 (상기도감염 등)에서 패혈증진단의 2가지 이상 항목(별첨)에 해당된다 하여 특정기간으로 적용 하여 행위별수가로 청구하는 것은 질병 진단 및 기준 적용상의 착오 사례로 판단됨.\n○ 따라서 일선 요양병원에서는 동 기준 적용에 착오가 발생되지 않도록 협조를 부탁드리며, 진료비 심사를 담당하는 기관에서는 관련 진료비 심사에 만전을 기울여 주시기 바람.\n<별첨 - 패혈증 확진 기준>\n：혈액 내 균 혹은 균 독소가 증명된 경우 또는 감염 으로 인한 전신염증반응으로서 다음 중 2가지 이상에 해당되어 패혈증으로 확진된 경우 ⑴ 체온이 38°C 초과되거나 36°C 미만인 경우 ⑵ 심박동수가 90회(/분)를 초과한 경우 ⑶ 호흡수가 24회(/분)를 초과하거나 이산화탄 소분압이 32mmHg 미만인 경우 ⑷ 백혈구수가 12,000/㎣ 초과되거나 4,000/㎣ 미만인 경우, 미성숙 호중성구 [immature(band)\nneutrophils] 수가 10% 초과된 경우\n\n[출처] 보험급여과-1799호,’10.8.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 191쪽',191,6,278);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0279','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원에 입원중인 환자에게 원외처방전 발행시 수가산정 방법','요양병원에 입원중인 환자에게 원외처방전 발행시 수가산정 방법','요양병원 입원중인 환자에게 원외처방전 발행시 수가산정 정액수가 환자군 분류체계 의료최고도 의료고도 의료중도 의료경도 선택입원군','○ 요양병원형 일당 정액수가에는 별도로 산정하도록 정해진 약제를 제외한 경구 및 비경구 약제비용이 모두 포함되어 있음.\n○ 국민건강보험 요양급여의 기준에 관한 규칙 제5조 제1항 관련 [별표1] 요양급여의 적용기준 및 방법 1.요양급여의 일반원칙 중 바.항에서 요양기관은 별도로 정한 경우 이외에는 요양급여에 필요한 약제･치료재료를 직접 구입하여 가입자등에게 지급하도록 하고 있음.\n○ 또한, 입원은 외래에서의 통원치료로는 충분한 치료효과를 기대하기 어려운 경우 입원을 통해 련 의료진의 지속적인 감시 및 치료가 필요하다는 판단하에 이루어지게 되므로 요양병원 입원환자 에게 필요한 의약품은 요양병원에서 구입하여 환자상태에 즉각적인 투약이 가능하도록 하여야 할 것임.\n○ 따라서, 요양병원에 입원중인 환자에게 별도 산정 토록 정해진 약제를 제외한 나머지 약제에 대하여 원외처방전을 발행하는 것은 인정하지 아니함.\n○ 다만, 요양병원에서 위 내용에도 불구하고 불가 고 피하게 원외처방하는 경우는 동 내역을 청구명세 서에 명기할 경우 심사시 이를 고려하여 심사･ 조정할 것임.\n\n[출처] 보험급여팀-4048호,’07.12.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 192쪽',192,6,279);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0280','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원 입원환자를 다른 요양기관에 진료의뢰시 수가 산정방법 등 (JS00 연월일을 특정내역란 시기관기호 청구함. ㅇ 진료비 의함.','요양병원 입원환자를 다른 요양기관에 진료의뢰시 수가 산정방법 등 (JS00 연월…','요양병원 입원환자 다른 요양기관 진료의뢰시 산정방법 JS00 연월일 특정내역란 시기관기호 청구함 진료비 의함 ','나. 본인일부부담 요양병원 다. 진찰료 입원 진료 전문과에 한하여 소 라. 요양병원( 요양병원( 의뢰시 ㅇ 동일 구내 환자가 특 담당의사의 위해 의과 입원환자 의사가 직 “협의진찰 ㅇ 이 경우 요양기관에 하여 청구 비용총액에 의해 청구\n○ 요양병원에 입원 진료중인 환자를 치료하는 과정 에서 시설･장비 또는 인력이 갖추어져 있지 원 아니하여 부득이하게 해당 진료가 가능한 요양 행 기관으로 환자를 의뢰하여 처치 및 수술, 방사선 치료 등을 받도록 할 경우 수가산정방법은 아래와 같이 함.\n-아 래-\n가. 진료비청구 및 정산\nㅇ 진료를 의뢰한 요양병원에서 의뢰한 진료내역을 포함하여 청구하되, 의뢰한 진료내역은 실제 평 진료한 요양기관의 종별가산율을 적용하여 (Ⅰ)란으로 청구함.\nㅇ 이때 의뢰한 진료내역은 EDI청구기관은 특정 내역 기재란에 위탁진료임을 표시하는 구분코드 8), 위탁진료실시기관기호, 위탁진료실시 기재하여 청구하고, 서면청구기관은 에 해당 진료항목, “T”, 위탁진료실 및 위탁진료실시연월일을 기재하여 정산은 해당 요양기관간 상호 협의에 금 입원환자의 본인일부부담률을 적용함.\n중인 해당 진료전문과이외의 다른 진료\n다른 상병의 진료를 의뢰한 경우에\n정 진찰료를 별도 산정함.\n의과)에서 타 요양기관(한방)으로 또는 한방)에서 타 요양기관(의과)으로 진료 에 있는 한방(의과)요양병원에 입원중인 별한 문제에 대한 평가 및 관리를 위하여 지시에 따라 의과(한방)진료를 받기 (한방) 요양기관의 외래를 방문하거나 진료를 위해 의과(한방)요양기관의 접 방문한 경우에는 진찰료가 아닌 료”로 산정하여야 함.\n요양급여비용은 실제 협의진찰을 실시한\n서 외래요양급여비용명세서에 작성\n하되, 협의진찰료를 포함한 요양급여\n대한 외래본인부담액산정방법에\n하여야 함.\n\n[출처] 보험급여팀-4048호,’07.12.31.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 193쪽',193,6,280);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0281','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원에 입원중인 환자를 타 요양기관으로 진료의뢰하여 의뢰받은 요양기관에서 진료 후 발생한 약제비 산정방법','요양병원에 입원중인 환자를 타 요양기관으로 진료의뢰하여 의뢰받은 요양기관에서 진…','요양병원 입원중인 환자 요양기관 진료의뢰하여 의뢰받 진료 발생한 약제비 산정방법 ','○ 요양병원의 일당정액 수가에는 별도로 산정하도록 정해진 약제를 제외한 경구 및 비경구 약제비용이 모두 포함되어 있으므로, 요양병원에 입원중인 환자에게 별도 산정토록 정해진 약제를 제외한 나머지 약제에 대하여 원외처방전을 발행하는 것은 인정하지 아니하나, 요양병원에서 위 내용에도 불구하고 불가피하게 원외처방하는 경우는 동 내역을 청구명세서에 명기할 경우 심사시 이를 Ⅱ 고려하여 심사･조정할 것임을 기 통보한 바 있음.\n○ 따라서, 요양병원에 입원 진료중인 환자를 치료 하는 과정에서 시설･장비 또는 인력이 갖추어져 있지 아니하여 부득이하게 해당 진료가 가능한 요양기관으로 환자를 의뢰하여 처치 및 수술, 방사선치료 등을 받도록 할 경우 의뢰받은 요양 기관에서 처방한 약제는 요양병원에 입원중인 환자에 대한 처방이므로 의뢰받은 요양기관에서 원내처방 하여야 하며, 환자에게 처방한 약제를 포함한 진료내역은 의뢰한 요양병원에서 일괄 요\n청구하여야 함.\n○ 다만, 의뢰받은 요양기관에서 원내처방 약제를 구비하지 아니하여 부득이하게 원내처방 할 수 석 없을 경우는, 처방내역을 의뢰한 요양병원에 통보 하여 요양병원에서 원내처방토록 하고, 이 경우 요양병원에서 원내처방 한 약제는 별도 비용을 산정할 수 없음.\n\n[출처] 보험급여팀-204호,’08.1.24.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 195쪽',195,6,281);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0282','PDF_ADM','PDF_ADM_01','PDF','QA','요양병원에 입원중인 환자를 타 요양기관에 진료의뢰하여 물리치료 실시시 비용 산정 방법','요양병원에 입원중인 환자를 타 요양기관에 진료의뢰하여 물리치료 실시시 비용 산정…','요양병원 입원중인 환자 요양기관 진료의뢰하여 물리치료 실시시 비용 전문재활치료 재활','○ 물리치료는 해당 물리치료를 실시할 수 있는 원 일정한 면적의 해당 치료실과 실제 사용할 수 환 있는 장비를 보유하고 있는 요양기관에서 건강 가 보험 행위 급여･비급여 목록표 및 급여 상대가치 점수에서 별도로 정한 의사의 처방에 따라 상근 하는 물리치료사가 실시하고 그 결과를 진료 얼 기록부에 기록한 경우에 산정토록 하고 있음.\n○ 또한, 「국민건강보험 요양급여의 기준에 관한 규칙」\n- [별표1] 1-라 및 마에 의거 요양기관은 가입자 등의 요양급여에 필요한 적정한 인력･시설 및 장비를 유지하도록 정하여져 있는 바, 요양병원의 입원대상자가 주로 노인성･만성질환자로 물리 치료의 적응증이 되는 대상이 많으므로, 물리치료를 실시할 수 있는 인력･시설 및 장비를 갖춤이 바람직함.\n○ 한편, 전문재활치료는 그 특성상 일시적인 제공 으로 의학적 효과를 기대하기 곤란하며 지속적인 관찰 및 치료를 요하는 고도의 전문치료로, 장기 요양을 목적으로 요양병원에 입원한 환자에게 인근병원에 의뢰하여 물리치료를 실시하는 것은 요양병원 입원환자의 특성을 고려할 때 바람직 하지 아니함.\n○ 따라서, 요양병원 입원환자를 타 요양기관에 의뢰하여 물리치료를 받도록 하고 별도로 비용을 산정하는 것은 인정하지 아니하며, 환자등급 산정시도 적용하지 아니함.\n\n[출처] 보험급여팀-204호,’08.1.24.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 195쪽',195,6,282);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0283','PDF_LAW','PDF_LAW_01','PDF','ITEM','제21조 (계약의 내용 등)','제21조 (계약의 내용 등)','제21조 계약 내용 ','제21조(계약의 내용 등)\n① 법 제45조제1항에 따른 계약은 공단의 이사장과 제20조 각 호에 따른 사람이 유형별 요양기관을 대표하여 체결하며, 계약의 내용은 요양급여의 각 항목에 대한 상대가치점수의 점수당 단가를 정하는 것으로 한다.\n② 제1항에 따른 요양급여 각 항목에 대한 상대가치점수는 요양급여에 드는 시간･ 노력 등 업무량, 인력･시설･장비 등 자원의 양, 요양급여의 위험도 및 요양 급여에 따른 사회적 편익 등을 고려하여 산정한 요양급여의 가치를 각 항목 사이에 상대적인 점수로 나타낸 것으로 하며, 보건복지부장관이 심의 위원회의 심의･의결을 거쳐 보건복지부령으로 정하는 바에 따라 고시한다.\n③ 제2항에도 불구하고 다음 각 호의 경우에는 다음 각 호의 구분에 따른 방법으로 요양급여의 상대가치점수를 산정할 수 있다.\n1. 「의료법」 제3조제2항제3호라목에 따른 요양병원에서 입원진료를 받는 경우:\n    해당 진료에 필요한 요양급여 각 항목의 점수와 약제･치료재료의 비용을 합산하여 증세의 경중도(輕重度)의 구분에 따른 1일당 상대가치점수로 산정\n2. 「의료법」 제3조제2항제1호가목에 따른 의원, 같은 항 제3호가목 및 라목 부터 바목까지의 규정에 따른 병원·요양병원·정신병원·종합병원, 같은 법\n    제3조의4에 따른 상급종합병원 또는 「지역보건법」 제12조에 따른 보건 의료원에서 보건복지부장관이 정하여 고시하는 질병군[진단명, 시술명, 중증도, 나이 등을 기준으로 분류한 환자집단을 말한다]에 대하여 입원진료를 받는 경우 : 해당 진료에 필요한 요양급여 각 항목의 점수와 약제･치료재료의 비용을 포괄하여 입원 건당 하나의 상대가치점수로 산정\n[별표 2] 본인일부부담금의 부담률 및 부담액(제19조제1항 관련)\n   1. 가입자 또는 피부양자는 요양급여비용 중 다음 각 목의 어느 하나에 해당하는 금액(100원 미만은 제외한다)을 부담한다. 다만, 입원진료의 경우에는 100원 미만의 금액도 부담한다.\n      가. 입원진료(나목의 표 중 보건복지부장관이 정하는 의료장비를 이용한 진료의 경우는 제외한다) 및 보건복지부장관이 정하는 요양급여를 받은 경우(약국 또는 한국희귀･필수의약품센터인 요양기관에서 처방전에 따라 의약품을 조제받는 경우를 포함한다)는 다음의 구분에 따라 계산한 금액\n      1) 요양급여비용 총액(보건복지부장관이 정하여 고시하는 식대와 장애인 치과 진료에 대한 가산금액은 제외한다)의 100분의 20에 입원기간 중 식대\n      [입원환자의 식사의 질과 서비스에 영향을 미치는 부가적 요소에 드는 비용에 해당하는 가산금액(이하 “식대가산금액”이라 한다)을 포함한다. 이하 이 호, 제2호 및 제3호가목･나목･아목에서 같다]의 100분의 50을 더한 금액.\n      (중략)\n      2) 「의료법」 제3조제2항제3호라목에 따른 요양병원(「장애인복지법」 제58조 제1항제4호에 따른 장애인 의료재활시설로서 「의료법」 제3조의2의 요건을 갖춘 의료기관인 요양병원은 제외한다)에서 입원진료를 받는 사람 중 입원 치료보다는 요양시설이나 외래진료를 받는 것이 적합한 환자로서 보건 복지부장관이 정하여 고시하는 환자군에 해당하는 경우에는 요양급여비용 총액의 100분의 40에 입원기간 중 식대의 100분의 50을 더한 금액','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 3쪽',3,4,283);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0284','PDF_LAW','PDF_LAW_02','PDF','ITEM','제3조의2 (요양병원 입원진료 현황의 고지)','제3조의2 (요양병원 입원진료 현황의 고지)','제3조의2 요양병원 입원진료 현황 고지 ','제3조의2(요양병원 입원진료 현황의 고지)\n   ① 보건복지부 장관은 「의료법」 제3조제2항제3호라목에 따른 요양병원 「장애인 복지법」 제58조제1항제4호에 따른 의료재활시설로서 「의료법」 제3조의2의 요건을 갖춘 의료기관인 요양병원은 제외한다. 이하 이 조에서 같다)의 장에게 해당 요양병원에서 입원진료를 받는 가입자등의 입원･퇴원 일시 등 입원진료 현황을 공단에 알리도록 요구할 수 있다. <2021.3.26. 개정>\n   ② 제1항에 따른 입원진료 현황의 내용, 고지 방법 및 절차 등에 관한 구체적인 사항은 보건복지부장관이 정하여 고시한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 6쪽',6,4,284);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0285','PDF_LAW','PDF_LAW_02','PDF','ITEM','제6조 (요양급여의 의뢰 및 가입자등의 회송 등)','제6조 (요양급여의 의뢰 및 가입자등의 회송 등)','제6조 요양급여 의뢰 가입자등 회송 ','제6조(요양급여의 의뢰 및 가입자등의 회송 등)\n   ① 요양기관은 가입자등에게 적절한 요양급여를 행하기 위하여 필요한 경우에는 다른 요양기관에게 요양급여를 의뢰할 수 있다.\n   ③ 요양기관이 제1항에 따라 요양급여를 의뢰하는 경우에는 별지 제4호서식에 의한 요양급여의뢰서를, 제2항에 따라 가입자등을 회송하는 경우에는 별지 제5호서식에 따른 요양급여회송서를 가입자등에게 발급하여야 한다. 이 경우 요양급여를 의뢰하거나 가입자등을 회송하는 요양기관은 가입자등의 동의를 받아 진료기록의 사본 등 요양병원에 관한 자료를 요양급여를 의뢰받거나 가입자등을 회송받는 요양기관에 제공하여야 한다. <2020.6.29. 개정>','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 6쪽',6,4,285);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0286','PDF_LAW','PDF_LAW_02','PDF','ITEM','제8조 (요양급여대상의 고시)','제8조 (요양급여대상의 고시)','제8조 요양급여대상 고시 ','제8조 (요양급여대상의 고시)\n   ④ 보건복지부장관은 제2항에도 불구하고 영 제21조제3항제1호에 따른 요양병원의 입원진료나 같은 항 제3호에 따른 호스피스･완화의료의 입원진료의 경우에는 제2항의 행위･약제 및 치료재료를 묶어 1일당 행위로 정하여 고시할 수 있다.\n      이 경우 1일당 행위에서 제외되는 항목은 보건복지부장관이 정하여 고시할 수 있다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 6쪽',6,4,286);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0287','PDF_LAW','PDF_LAW_03','PDF','ITEM','제4조 (요양병원 입원진료 현황의 고지)','제4조 (요양병원 입원진료 현황의 고지)','제4조 요양병원 입원진료 현황 고지 ','제4조 (요양병원 입원진료 현황의 고지)\n① 보건복지부장관은 「의료법」 제3조제2항제3호라목에 따른 요양병원(「장애인 복지법」 제58조제1항제4호에 따른 의료재활시설로서 「의료법」 제3조의2의 요건을 갖춘 의료기관인 요양병원은 제외한다. 이하 이 조에서 같다)의 장에게 해당 요양병원에서 입원진료를 받는 수급권자의 입원･퇴원 일시 등 입원진료 현황을 공단에 알리도록 요구할 수 있다.\n② 제1항에 따른 입원진료 현황의 내용, 고지 방법 및 절차 등에 관한 구체적인 사항은 보건복지부장관이 정하여 고시한다.','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 7쪽',7,4,287);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,SORT_NO) VALUES ('pdf-0288','PDF_LAW','PDF_LAW_03','PDF','ITEM','제8조 (의료급여의 범위 등)','제8조 (의료급여의 범위 등)','제8조 의료급여 범위 ','제8조 (의료급여의 범위 등)\n② 「국민건강보험 요양급여의 기준에 관한 규칙」 제8조제2항 및 제4항은 의료 급여대상에 관하여 이를 준용한다.\n별표1의2\n1. 수급권자가 급여비용을 부담하는 경우 또는 항목의 비용\n자. 「의료법」 제3조제2항제3호라목의 요양병원 중 「장애인복지법」 제58조 제1항제4호의 장애인 의료재활시설을 제외한 요양병원에서 입원진료를 받은 수급권자가 제3조제3항에 따른 의료급여의뢰서 없이 다른 의료급여기관에서 진료를 받는 경우에 소요된 비용의 총액\n2. 본인부담률：제1호에 해당하는 비용의 100분의 100','','','2022 요양병원 수가 실무교육자료(건강보험심사평가원) 7쪽',7,4,288);
